// Autosave slot. Namespaced by industry in case this pattern gets reused for other slices later.
// ============================== PERSISTENCE ==============================
// Every stored record carries a schema version and passes through a migration ladder when read.
// This is what makes a long-lived project survivable: without it, any schema change silently
// breaks every save written before it. To make a change: bump SCHEMA_VERSION, then add one entry
// per affected record type to MIGRATIONS. Old saves upgrade themselves on load.
//
// STORE_NS is a *generation* marker, deliberately separate from SCHEMA_VERSION. Bumping
// SCHEMA_VERSION migrates data in place. Changing STORE_NS abandons a generation wholesale —
// reserved for a break so fundamental that migration isn't worth writing.

const STORE_NS = 'es:v1';
const SCHEMA_VERSION = 1;

const K = {
  prefs: `${STORE_NS}:prefs`,
  active: `${STORE_NS}:save:active`,
  profile: `${STORE_NS}:profile`,
  mastery: `${STORE_NS}:mastery`,
  runsIndex: `${STORE_NS}:runs:index`,
  companies: `${STORE_NS}:entities:companies`,
  investors: `${STORE_NS}:entities:investors`,
  founders: `${STORE_NS}:entities:founders`,
  chronicle: (id) => `${STORE_NS}:runs:${id}`,
};

// Pre-namespace keys from earlier builds. Adopted on first boot, never deleted — if the new
// schema ever needs to be rolled back, the originals are still sitting there intact.
const LEGACY_KEYS = {
  active: 'hospitality-run',
  sound: 'sound-enabled',
  language: 'language',
  metaFull: 'meta-full',
  metaScenario: 'meta-scenario',
};

const PHILOSOPHY_AXES = [
  'growthVsSustainability', 'innovationVsExecution', 'peopleVsProfit',
  'riskVsStability', 'premiumVsMass', 'centralizedVsDelegated',
];
const emptyPhilosophy = () => Object.fromEntries(PHILOSOPHY_AXES.map(a => [a, 0]));

const RUNS_INDEX_CAP = 200;      // full chronicles live in their own keys; this stays scannable
const CHRONICLE_TIMELINE_CAP = 60;

const EMPTY_RECORD = {
  prefs: () => ({ v: SCHEMA_VERSION, language: 'en', sound: true }),
  profile: () => ({
    v: SCHEMA_VERSION, createdAt: Date.now(), lastPlayedAt: Date.now(),
    totals: { runs: 0, wins: 0, losses: 0, byBucket: {}, byIndustry: {}, byOutcome: {} },
    philosophy: emptyPhilosophy(),
    unlocks: { scenarios: [], founders: [], industries: ['hospitality'], businessModels: [], strategicOptions: [], knowledge: [] },
  }),
  mastery: () => ({ v: SCHEMA_VERSION, industries: {} }),
  runsIndex: () => ({ v: SCHEMA_VERSION, archivedCount: 0, runs: [] }),
  companies: () => ({ v: SCHEMA_VERSION, companies: {} }),
  investors: () => ({ v: SCHEMA_VERSION, investors: {} }),
  // The player's own founder, the roster's accumulated experience, and the career record the
  // unlock markers read. One save file, one custom founder (locked decision).
  founders: () => ({
    v: SCHEMA_VERSION,
    custom: null,              // null until the player creates one
    roster: {},                // leaderId -> { xp, allocated: {stat: n}, runsWith, wins }
    career: {},                // accumulateCareer() shape — drives evaluateUnlocks
    unlocked: [],              // cached unlock ids; always recomputed, never trusted as input
  }),
  active: () => null,
};

// Migration ladders, one per record type, keyed by the version being migrated *to*.
// Example for a future v2 that adds a field to profile:
//   profile: { 2: (doc) => ({ ...doc, totals: { ...doc.totals, byFounder: {} } }) }
// A missing entry means that record type needs no reshaping for that version.
const MIGRATIONS = {
  prefs: {}, profile: {}, mastery: {}, runsIndex: {},
  companies: {}, investors: {}, chronicle: {}, active: {}, founders: {},
};

function migrateDoc(type, doc) {
  if (!doc || typeof doc !== 'object') return null;
  let from = doc.v || 0;
  // Written by a newer build than this one. Refuse rather than corrupt — the caller falls back
  // to a default, and the newer data stays untouched on disk for when that build returns.
  if (from > SCHEMA_VERSION) return null;
  let cur = doc;
  while (from < SCHEMA_VERSION) {
    const to = from + 1;
    const fn = (MIGRATIONS[type] || {})[to];
    cur = { ...(fn ? fn(cur) : cur), v: to };
    from = to;
  }
  return cur;
}

const Store = {
  async readDoc(type, key, fallback) {
    try {
      const res = await window.storage.get(key, false);
      if (!res || res.value == null) return fallback;
      const migrated = migrateDoc(type, JSON.parse(res.value));
      return migrated || fallback;
    } catch (e) {
      return fallback; // absent key or storage unavailable — callers get a usable default
    }
  },

  async writeDoc(key, doc) {
    try {
      await window.storage.set(key, JSON.stringify({ ...doc, v: SCHEMA_VERSION }), false);
      return true;
    } catch (e) {
      return false; // never let a failed write break play
    }
  },

  // One-time adoption of pre-namespace keys. Idempotent: a profile existing means done.
  async migrateLegacy() {
    try {
      const existing = await window.storage.get(K.profile, false);
      if (existing && existing.value) return false;
    } catch (e) { /* no profile yet, continue */ }

    const raw = {};
    for (const [name, key] of Object.entries(LEGACY_KEYS)) {
      try {
        const r = await window.storage.get(key, false);
        if (r && r.value != null) raw[name] = r.value;
      } catch (e) { /* absent */ }
    }
    if (Object.keys(raw).length === 0) return false; // fresh install, nothing to adopt

    const parse = (s, d) => { try { return s ? JSON.parse(s) : d; } catch (e) { return d; } };
    const full = parse(raw.metaFull, null);
    const scen = parse(raw.metaScenario, null);

    const prefs = EMPTY_RECORD.prefs();
    if (raw.language) prefs.language = raw.language;
    if (raw.sound != null) prefs.sound = raw.sound !== 'off';

    const profile = EMPTY_RECORD.profile();
    const bucket = {};
    if (full) bucket.full = { runs: full.runs || 0, wins: full.wins || 0, bestValuation: full.bestValuation || 0 };
    if (scen) bucket.scenario = { runs: scen.runs || 0, wins: scen.wins || 0, bestValuation: scen.bestValuation || 0 };
    profile.totals.byBucket = bucket;
    profile.totals.runs = (bucket.full?.runs || 0) + (bucket.scenario?.runs || 0);
    profile.totals.wins = (bucket.full?.wins || 0) + (bucket.scenario?.wins || 0);
    profile.totals.losses = profile.totals.runs - profile.totals.wins;
    profile.totals.byIndustry = { hospitality: { runs: profile.totals.runs, wins: profile.totals.wins } };

    const mastery = EMPTY_RECORD.mastery();
    mastery.industries.hospitality = {
      runs: profile.totals.runs, wins: profile.totals.wins,
      bestValuation: Math.max(bucket.full?.bestValuation || 0, bucket.scenario?.bestValuation || 0),
      totalMonthsPlayed: 0, stagesReached: {}, exitsAchieved: {}, level: 0,
    };

    await this.writeDoc(K.prefs, prefs);
    await this.writeDoc(K.profile, profile);
    await this.writeDoc(K.mastery, mastery);

    if (raw.active) {
      const game = parse(raw.active, null);
      if (game) await this.writeDoc(K.active, { industry: 'hospitality', game });
    }
    return true;
  },

  // Single boot read. Everything cold loads here; the hot path never touches these again.
  // Deliberately NOT migrateDoc. An in-progress run finishes on the schema it started on —
  // see GAME_FIELD_DEFAULTS / hydrateResumedGame for how the engine tolerates the gap instead.
  // Passing this through the cold-record migration ladder would silently relabel a save's
  // version without actually reshaping its nested `game` object, corrupting future migrations
  // that assume a record's declared version matches its real shape.
  async readActiveRaw() {
    try {
      const res = await window.storage.get(K.active, false);
      if (!res || res.value == null) return null;
      const doc = JSON.parse(res.value);
      return doc && doc.game ? doc : null;
    } catch (e) {
      return null;
    }
  },

  async boot() {
    await this.migrateLegacy();
    const [prefs, profile, mastery, runsIndex, activeDoc] = await Promise.all([
      this.readDoc('prefs', K.prefs, EMPTY_RECORD.prefs()),
      this.readDoc('profile', K.profile, EMPTY_RECORD.profile()),
      this.readDoc('mastery', K.mastery, EMPTY_RECORD.mastery()),
      this.readDoc('runsIndex', K.runsIndex, EMPTY_RECORD.runsIndex()),
      this.readActiveRaw(),
    ]);
    return { prefs, profile, mastery, runsIndex, active: activeDoc ? hydrateResumedGame(activeDoc.game) : null };
  },

  // Hot path: one key, one write, on every player action.
  async saveActive(game, industry = 'hospitality') {
    return this.writeDoc(K.active, { industry, game });
  },

  async clearActive() {
    try { await window.storage.delete(K.active, false); } catch (e) { /* ignore */ }
  },

  async savePrefs(prefs) { return this.writeDoc(K.prefs, prefs); },

  // Cold path: batched, once at run end.
  async commitRun({ game, industry = 'hospitality', bucket = 'full', outcome, won, headline }) {
    const profile = await this.readDoc('profile', K.profile, EMPTY_RECORD.profile());
    const mastery = await this.readDoc('mastery', K.mastery, EMPTY_RECORD.mastery());
    const index = await this.readDoc('runsIndex', K.runsIndex, EMPTY_RECORD.runsIndex());

    const bump = (obj, key, w) => {
      const cur = obj[key] || { runs: 0, wins: 0, bestValuation: 0 };
      obj[key] = {
        runs: cur.runs + 1,
        wins: cur.wins + (w ? 1 : 0),
        bestValuation: Math.max(cur.bestValuation || 0, game.companyValuation || 0),
      };
    };
    profile.totals.runs += 1;
    profile.totals.wins += won ? 1 : 0;
    profile.totals.losses = profile.totals.runs - profile.totals.wins;
    bump(profile.totals.byBucket, bucket, won);
    bump(profile.totals.byIndustry, industry, won);
    profile.totals.byOutcome[outcome] = (profile.totals.byOutcome[outcome] || 0) + 1;
    profile.lastPlayedAt = Date.now();
    PHILOSOPHY_AXES.forEach(a => {
      profile.philosophy[a] = clamp((profile.philosophy[a] || 0) + ((game.philosophy && game.philosophy[a]) || 0), -100, 100);
    });

    const m = mastery.industries[industry] || {
      runs: 0, wins: 0, bestValuation: 0, totalMonthsPlayed: 0, stagesReached: {}, exitsAchieved: {}, level: 0,
    };
    m.runs += 1;
    m.wins += won ? 1 : 0;
    m.bestValuation = Math.max(m.bestValuation, game.companyValuation || 0);
    m.totalMonthsPlayed += game.month || 0;
    const indForMastery = getIndustry(industry);
    const reached = stageOf(Math.min(game.month, game.endMonth || indForMastery.runEnd), indForMastery.stages).id;
    m.stagesReached[reached] = (m.stagesReached[reached] || 0) + 1;
    if (won) m.exitsAchieved[outcome] = (m.exitsAchieved[outcome] || 0) + 1;
    mastery.industries[industry] = m;

    const runId = `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
    index.runs.unshift({
      id: runId, industry, scenarioId: game.scenarioId || 'fullRun',
      endedAt: Date.now(), months: game.month || 0,
      outcome, won, valuation: game.companyValuation || 0, headline: headline || '',
    });
    if (index.runs.length > RUNS_INDEX_CAP) {
      index.archivedCount += index.runs.length - RUNS_INDEX_CAP;
      index.runs = index.runs.slice(0, RUNS_INDEX_CAP);
    }

    await this.writeDoc(K.profile, profile);
    await this.writeDoc(K.mastery, mastery);
    await this.writeDoc(K.runsIndex, index);
    await this.writeDoc(K.chronicle(runId), {
      id: runId, industry, scenarioId: game.scenarioId || 'fullRun',
      team: game.team ? { name: game.team.name, leaders: game.team.leaders.map(l => l.name) } : null,
      timeline: (game.log || []).slice(0, CHRONICLE_TIMELINE_CAP).map(tk => ({
        month: tk.month, kind: tk.kind, title: tk.title, detail: tk.body,
      })),
      finalState: {
        capital: game.capital, revenue: game.revenuePerMonth, reputation: game.reputation,
        morale: game.morale, boardConfidence: game.boardConfidence,
        valuation: game.companyValuation, stats: game.stats,
      },
      philosophyAtEnd: game.philosophy || emptyPhilosophy(),
    });
    await this.upsertCompaniesFromRun(game.competitors, industry, runId);
    // Settled from who actually backed this run and how it ended. Absolute values, not deltas —
    // settleInvestorStandings folds the run's outcome onto the standings already hydrated into
    // game state at start, so this is idempotent across repeated commits.
    const settledStandings = settleInvestorStandings(game, won, outcome);
    await this.commitInvestorStandings(settledStandings, runId);
    // Founder career: XP for everyone who was on the team, plus a fresh unlock evaluation.
    const founders = await this.commitFounderRun({ game, industry, won, outcome, investorStandings: settledStandings });

    return { profile, mastery, index, runId, founders };
  },

  // Every name ever used for this industry, not just the current run's — this is what makes
  // name collisions actually rare over years of play rather than just within one sitting.
  async getAllCompanyNames(industry) {
    const cos = await this.getCompaniesForIndustry(industry);
    return cos.map(c => c.name);
  },

  async getChronicle(runId) {
    return this.readDoc('chronicle', K.chronicle(runId), null);
  },

  // Companies are industry-scoped (7.2): filtered here, at read time, rather than partitioned
  // into per-industry keys — one flat store, industry is just a field every record carries.
  async getCompaniesForIndustry(industry) {
    const doc = await this.readDoc('companies', K.companies, EMPTY_RECORD.companies());
    return Object.entries(doc.companies)
      .filter(([, c]) => c.industry === industry)
      .map(([id, c]) => ({ id, ...c }));
  },

  // Folds every rival encountered in a finished run into the persistent Nemesis store. Matched
  // by seedId (7.2/2), not name — two companies coincidentally sharing a name are still
  // recognized as distinct if their seedIds differ, and a genuine recurrence correctly merges
  // into one entity's history even if the display name changed along the way.
  async upsertCompaniesFromRun(competitors, industry, runId) {
    if (!competitors || competitors.length === 0) return;
    const doc = await this.readDoc('companies', K.companies, EMPTY_RECORD.companies());
    competitors.forEach(comp => {
      const key = comp.seedId || comp.id; // falls back gracefully for any pre-existing save without seedId
      const existingId = Object.keys(doc.companies).find(
        id => doc.companies[id].industry === industry && doc.companies[id].seedId === key);
      const id = existingId || `co-${industry}-${Math.random().toString(36).slice(2, 8)}`;
      const prior = doc.companies[id];
      // The in-run competitor is already the merged, cumulative record by run end — its
      // `encounters` and `pastLeaders` were built by carrying prior.* forward at spawn time (see
      // makeCompetitor's knownRival branch) and accumulating live via recordNemesisEvent. So this
      // replaces rather than adds — summing here on top of an already-cumulative field would
      // double it, the same class of bug just fixed in deriveDisposition.
      const cur = makeCompanyEntity(comp, industry);
      cur.firstSeenRun = (prior && prior.firstSeenRun) || runId;
      cur.lastSeenRun = runId;
      cur.encounterCount = ((prior && prior.encounterCount) || 0) + 1;
      cur.history = [{ runId, event: comp.returning ? 're-encountered' : 'first-encountered', detail: `Posture ${cur.posture}, Disposition ${cur.disposition}, Strength ${comp.strength}` }, ...((prior && prior.history) || [])].slice(0, 20);
      doc.companies[id] = cur;
    });
    await this.writeDoc(K.companies, doc);
  },

  // ---- Founder identity, roster experience, and career unlocks ----
  async getFounders() {
    const doc = await this.readDoc('founders', K.founders, EMPTY_RECORD.founders());
    return migrateFounderDoc(doc);
  },

  async saveCustomFounder(founder) {
    const doc = await this.readDoc('founders', K.founders, EMPTY_RECORD.founders());
    doc.custom = { ...founder, createdAt: founder.createdAt || Date.now() };
    await this.writeDoc(K.founders, doc);
    return doc;
  },

  // Player-directed allocation of points a roster founder earned through experience. Their
  // authored statBonus, bio, portrait and trait are NOT touched — locked decision.
  async allocateRosterPoints(leaderId, allocated) {
    const doc = await this.readDoc('founders', K.founders, EMPTY_RECORD.founders());
    const rec = doc.roster[leaderId] || { xp: 0, allocated: {}, runsWith: 0, wins: 0 };
    const cap = founderEarnedPoints(rec.xp);
    const spent = Object.values(allocated || {}).reduce((a, b) => a + (b || 0), 0);
    if (spent > cap) return doc; // refuse over-allocation rather than silently clamping
    rec.allocated = { ...allocated };
    doc.roster[leaderId] = rec;
    await this.writeDoc(K.founders, doc);
    return doc;
  },

  // Folds a finished run into the career record, awards XP to everyone who was on the team, and
  // recomputes unlocks. Unlocks are RECOMPUTED from the career record every time rather than
  // incrementally appended — an incrementally-maintained list drifts and cannot be repaired,
  // the same reasoning behind deriveDisposition being a pure recompute.
  async commitFounderRun({ game, industry, won, outcome, investorStandings }) {
    const doc = await this.readDoc('founders', K.founders, EMPTY_RECORD.founders());
    const months = game.month || 0;
    const rivalDefeats = (game.competitors || [])
      .reduce((a, c) => a + ((c.encounters || {}).defeatedByPlayer || 0), 0);
    const alliesFormed = (game.competitors || [])
      .filter(c => dispositionBand(deriveDisposition(c)).id === 'ally').length;

    // Per-class career tracking drives the signature MASTERY gates. classId comes off the
    // custom founder on the team, so Quickplay/Blitz (no custom founder) contribute nothing —
    // consistent with the existing rule that they don't feed career progression at all.
    const customLeader = ((game.team && game.team.leaders) || []).find(l => l.id === CUSTOM_FOUNDER_ID);
    const ind = getIndustry(industry);
    const stageOrder = (ind && ind.stageOrder) || [];
    const finalStageId = ind ? stageOf(game.month || 1, ind.stages).id : null;
    // Fraction rather than index: the two industries have different stage counts AND different
    // stage names, so a raw index or a named stage would not compare across them.
    const stageFraction = (finalStageId && stageOrder.length > 1)
      ? Math.max(0, stageOrder.indexOf(finalStageId)) / (stageOrder.length - 1)
      : 0;

    // Leader-unlock metrics, measured on the run as it actually ended.
    const friendly = countFriendlyRelationships(game, investorStandings);

    doc.career = accumulateCareer(doc.career, {
      months, won, outcome, industry,
      totalRaised: game.totalRaised || 0,
      rivalDefeats, alliesFormed,
      investorStandings: investorStandings || game.investorStandings || {},
      // Buyer relationships earned this run, and any buyers made permanent by completing a term.
      buyerStandings: game.buyerStandings || {},
      unlockedBuyers: game.unlockedBuyers || [],
      classId: customLeader ? customLeader.classId : null,
      stageFraction,
      successfulChoices: game.successfulChoices || 0,
      friendlyInvestors: friendly.friendlyInvestors,
      friendlyCompanies: friendly.friendlyCompanies,
    });

    // What this run looked like, from the perspective of anyone who was in the room for it.
    // Recorded per-founder rather than globally so each founder's archive is genuinely THEIR
    // history — two founders who joined at different times have different stories.
    const runRecord = {
      at: Date.now(), industry, months, won,
      outcome: outcome || 'unknown',
      company: (game.team && game.team.name) || '',
      valuation: Math.round(game.companyValuation || 0),
      raised: game.totalRaised || 0,
      headline: (game.gameOver && game.gameOver.headline) || '',
    };
    const backers = Object.keys(game.investorBackers || {});
    const rivalsFaced = (game.competitors || []).map(c => ({
      seedId: c.seedId, name: c.name,
      disposition: deriveDisposition(c),
      band: dispositionBand(deriveDisposition(c)).id,
    }));

    // Natural Mentor multiplies what everyone who rode along learns from the run.
    const mentorMult = founderFx(game).rosterXpMult;
    const xp = Math.round(founderRunXp({ months, won, outcome }) * mentorMult);
    (game.team && game.team.leaders ? game.team.leaders : []).forEach(l => {
      if (l.id === CUSTOM_FOUNDER_ID) return; // the custom founder levels via career unlocks, not XP
      const rec = doc.roster[l.id] || {
        xp: 0, allocated: {}, runsWith: 0, wins: 0,
        philosophy: emptyPhilosophy(), history: [], investorsBacked: {}, rivalsFaced: {},
      };
      rec.xp += xp;
      rec.runsWith += 1;
      if (won) rec.wins += 1;

      // Philosophy accumulates from the runs this founder was actually present for, so a founder
      // who was only there for the ruthless years reads differently from one who lived the
      // sustainable ones. Averaged rather than summed so long-serving founders don't pin every
      // axis at the clamp.
      rec.philosophy = rec.philosophy || emptyPhilosophy();
      const runPhil = game.philosophy || emptyPhilosophy();
      PHILOSOPHY_AXES.forEach(a => {
        const prior = rec.philosophy[a] || 0;
        const n = rec.runsWith;
        rec.philosophy[a] = clamp(Math.round((prior * (n - 1) + (runPhil[a] || 0)) / n), -100, 100);
      });

      rec.history = [runRecord, ...(rec.history || [])].slice(0, 30);
      rec.investorsBacked = { ...(rec.investorsBacked || {}) };
      backers.forEach(id => { rec.investorsBacked[id] = (rec.investorsBacked[id] || 0) + 1; });
      rec.rivalsFaced = { ...(rec.rivalsFaced || {}) };
      rivalsFaced.forEach(r => {
        const prior = rec.rivalsFaced[r.seedId] || { name: r.name, times: 0 };
        rec.rivalsFaced[r.seedId] = { name: r.name, times: prior.times + 1, band: r.band, disposition: r.disposition };
      });

      doc.roster[l.id] = rec;
    });

    doc.unlocked = evaluateUnlocks(doc.career);
    await this.writeDoc(K.founders, doc);
    return doc;
  },

  // Global (7.2): no industry filter. A VC who backed a Hospitality run takes the call on a
  // Manufacturing one — the relationship is with the player, not with an industry.
  async getInvestors() {
    const doc = await this.readDoc('investors', K.investors, EMPTY_RECORD.investors());
    return Object.entries(doc.investors).map(([id, inv]) => ({ id, ...inv }));
  },

  // Standing per investor character id, -100..100, global across industries. Returned as a plain
  // map because that's exactly the shape game.investorStandings wants — no adapter at the call
  // site, which is what keeps the gating logic readable.
  async getInvestorStandings() {
    const doc = await this.readDoc('investors', K.investors, EMPTY_RECORD.investors());
    const out = {};
    Object.entries(doc.investors).forEach(([id, inv]) => {
      if (typeof inv.standing === 'number') out[id] = inv.standing;
    });
    return out;
  },

  // Merges a finished run's standings deltas into the persistent record. Stores the ABSOLUTE
  // settled value rather than a delta, for the same reason deriveDisposition is a pure
  // recompute: a stored value that gets re-incremented on every commit drifts without bound.
  async commitInvestorStandings(standings, runId) {
    if (!standings || Object.keys(standings).length === 0) return;
    const doc = await this.readDoc('investors', K.investors, EMPTY_RECORD.investors());
    Object.entries(standings).forEach(([id, standing]) => {
      const prior = doc.investors[id] || {};
      doc.investors[id] = {
        ...prior, id,
        name: (INVESTOR_BY_ID[id] && INVESTOR_BY_ID[id].name) || prior.name || id,
        standing,
        runsBacked: (prior.runsBacked || 0) + 1,
        lastRun: runId,
      };
    });
    await this.writeDoc(K.investors, doc);
  },

  async upsertInvestor(investor) {
    const doc = await this.readDoc('investors', K.investors, EMPTY_RECORD.investors());
    const id = investor.id || `inv-${Math.random().toString(36).slice(2, 8)}`;
    doc.investors[id] = { ...investor, id };
    await this.writeDoc(K.investors, doc);
    return id;
  },
};

// Two dominant axes -> an archetype label. Philosophy biases (7.3), never gates — this label is
// purely descriptive, shown at Game Over and rolled into the lifetime profile, and never used to
// unlock or restrict content in v1.
// The scale labels themselves — distinct from ARCHETYPE_LABELS below, which names a *headline*
// once one axis leans hard enough. These describe the live, ongoing position on each axis.
const PHILOSOPHY_POLE_LABELS = {
  growthVsSustainability: { neg: { en: 'Sustainability', es: 'Sostenibilidad' }, pos: { en: 'Growth', es: 'Crecimiento' } },
  innovationVsExecution: { neg: { en: 'Operational Excellence', es: 'Excelencia Operativa' }, pos: { en: 'Innovation', es: 'Innovación' } },
  peopleVsProfit: { neg: { en: 'Profit', es: 'Ganancia' }, pos: { en: 'People', es: 'Personas' } },
  riskVsStability: { neg: { en: 'Stability', es: 'Estabilidad' }, pos: { en: 'Risk', es: 'Riesgo' } },
  premiumVsMass: { neg: { en: 'Mass Market', es: 'Mercado Masivo' }, pos: { en: 'Premium', es: 'Premium' } },
  centralizedVsDelegated: { neg: { en: 'Delegated', es: 'Delegado' }, pos: { en: 'Centralized', es: 'Centralizado' } },
};

const ARCHETYPE_LABELS = {
  growthVsSustainability: { pos: { en: 'The Empire Builder', es: 'El Constructor de Imperios' }, neg: { en: 'The Steward', es: 'El Guardián' } },
  innovationVsExecution: { pos: { en: 'The Visionary', es: 'El Visionario' }, neg: { en: 'The Operator', es: 'El Operador' } },
  peopleVsProfit: { pos: { en: 'The People\u2019s Founder', es: 'El Fundador del Pueblo' }, neg: { en: 'The Bottom-Liner', es: 'El Pragmático' } },
  riskVsStability: { pos: { en: 'The Gambler', es: 'El Apostador' }, neg: { en: 'The Fortress-Builder', es: 'El Constructor de Fortalezas' } },
  premiumVsMass: { pos: { en: 'The Tastemaker', es: 'El Referente de Estilo' }, neg: { en: 'The Populist', es: 'El Popular' } },
  centralizedVsDelegated: { pos: { en: 'The Hands-On Founder', es: 'El Fundador Presente' }, neg: { en: 'The Architect', es: 'El Arquitecto' } },
};
function computeArchetype(philosophy, lang) {
  if (!philosophy) return null;
  const ranked = PHILOSOPHY_AXES
    .map(a => ({ axis: a, val: philosophy[a] || 0 }))
    .filter(a => Math.abs(a.val) >= 5) // too close to neutral isn't a real lean
    .sort((a, b) => Math.abs(b.val) - Math.abs(a.val));
  if (ranked.length === 0) return null;
  const top = ranked[0];
  const label = ARCHETYPE_LABELS[top.axis][top.val > 0 ? 'pos' : 'neg'];
  return { name: lang === 'es' ? label.es : label.en, axis: top.axis, value: top.val };
}

