// Overlays Spanish text onto a leader for display, without touching stat bonuses, deltas, or the
// English `trait` value used elsewhere as a game-logic key (leader-unlocked traits, choice-event
// traitCheck matching). A separate `traitDisplay` field carries the localized trait name instead.
function localizeLeader(leader, lang) {
  if (lang !== 'es') return { ...leader, traitDisplay: leader.trait, operateLabelDisplay: leader.operate.label, operateDescDisplay: leader.operate.desc };
  const tr = LEADERS_ES[leader.id];
  if (!tr) return { ...leader, traitDisplay: leader.trait, operateLabelDisplay: leader.operate.label, operateDescDisplay: leader.operate.desc };
  return { ...leader, role: tr.role, traitDesc: tr.traitDesc, bio: tr.bio, traitDisplay: tr.trait, operateLabelDisplay: tr.operateLabel, operateDescDisplay: tr.operateDesc };
}

