// Tag → business system. Each industry names its projects in its own vocabulary, so the mapping
// is per-industry rather than global. Hospitality's tags were the original proto-system list;
// Manufacturing's eleven tags are mapped here from its real project distribution.
//
// This was previously a single Hospitality-only table, which meant systemAudit() counted ZERO
// across every system for Manufacturing — the audit did not merely ignore its industry, it had
// no vocabulary for any industry but the first.
const TAG_TO_SYSTEM_BY_INDUSTRY = {
  hospitality: {
    Expansion: 'strategy', Growth: 'sales', Operations: 'operations', People: 'hr',
    Experience: 'marketing', Reputation: 'marketing', Compliance: 'legal', Security: 'legal',
    Development: 'rnd',
  },
  manufacturing: {
    // Making things: the plant, the line, and the tooling that runs on them.
    Plant: 'production', Line: 'production', Tooling: 'production',
    // Getting materials in and goods out.
    Sourcing: 'supplyChain', Logistics: 'supplyChain',
    // Designing what gets made, and proving it holds up.
    Prototype: 'rnd', Quality: 'operations',
    // Selling it, funding it, staffing it, and staying legal.
    Channel: 'sales', Capital: 'finance', Team: 'hr', Certification: 'legal',
  },
};
// Kept for any caller still using the flat table; Hospitality remains its content.
const TAG_TO_SYSTEM = TAG_TO_SYSTEM_BY_INDUSTRY.hospitality;

function systemAudit(industryId) {
  const id = industryId || 'hospitality';
  const counts = {};
  SYSTEMS.forEach(s => { counts[s] = 0; });
  const mapping = TAG_TO_SYSTEM_BY_INDUSTRY[id] || TAG_TO_SYSTEM_BY_INDUSTRY.hospitality;
  // Resolved lazily: INDUSTRIES is declared far below this point, so touching it at module
  // scope would be a temporal-dead-zone error. Runtime-only access keeps that impossible.
  const registry = (typeof INDUSTRIES !== 'undefined') ? INDUSTRIES : null;
  const projects = (registry && registry[id] && registry[id].content && registry[id].content.projects) || PROJECTS;
  projects.forEach(p => { const sys = mapping[p.tag]; if (sys) counts[sys] += 1; });
  return counts;
}

// Which systems an industry actually leans on, derived from the audit rather than asserted.
// dormant = 0 projects, standard = 1-9, core = 10+.
function systemProfile(industryId) {
  const counts = systemAudit(industryId);
  const profile = {};
  Object.entries(counts).forEach(([sys, n]) => {
    profile[sys] = n === 0 ? 'dormant' : n < 10 ? 'standard' : 'core';
  });
  return profile;
}

// Any project tag with no system mapping is invisible to the audit — worth being able to catch
// that directly rather than discovering it as a silently-zero count later.
function unmappedTags(industryId) {
  const id = industryId || 'hospitality';
  const mapping = TAG_TO_SYSTEM_BY_INDUSTRY[id] || {};
  const registry = (typeof INDUSTRIES !== 'undefined') ? INDUSTRIES : null;
  const projects = (registry && registry[id] && registry[id].content && registry[id].content.projects) || [];
  return [...new Set(projects.map(p => p.tag).filter(tag => !mapping[tag]))];
}

