function localizeProject(proj, lang) {
  if (lang !== 'es') return proj;
  const tr = PROJECTS_ES[proj.id];
  if (!tr) return proj;
  return { ...proj, name: tr.name, desc: tr.desc, tag: PROJECT_TAGS_ES[proj.tag] || proj.tag };
}
function localizeEvent(ev, lang) {
  if (lang !== 'es') return ev;
  const tr = EVENTS_ES[ev.id];
  if (!tr) return ev;
  return { ...ev, title: tr.title, body: tr.body };
}
function localizeChoiceEvent(event, lang) {
  if (lang !== 'es') return event;
  const tr = CHOICE_EVENTS_ES[event.id];
  if (!tr) return event;
  return {
    ...event,
    title: tr.title,
    body: tr.body,
    options: event.options.map((opt, i) => {
      const o = tr.options[i];
      if (!o) return opt;
      return {
        ...opt,
        label: o.label,
        good: { ...opt.good, text: o.good },
        bad: { ...opt.bad, text: o.bad },
      };
    }),
  };
}

// The class bonus is a MAJORITY rule, not a unanimous one: two leaders sharing a class is
// enough. That matters now that a full run fields three leaders — requiring all three to match
// would make the bonus nearly unreachable and would flatten the roster into one class per run.
// For the older two-leader scenarios the behaviour is unchanged, since two-of-two is both a
// majority and unanimous. Ties (impossible at 3, possible at 4+) resolve to no bonus rather
// than arbitrarily picking one, since "which class is the team" would have no honest answer.
function computeTeam(leaders) {
  const counts = {};
  leaders.forEach(l => { if (l.style) counts[l.style] = (counts[l.style] || 0) + 1; });
  const ranked = Object.entries(counts).sort((a, b) => b[1] - a[1]);
  const top = ranked[0];
  const tied = ranked.length > 1 && ranked[1][1] === top[1];
  const style = (top && top[1] >= 2 && !tied) ? top[0] : null;
  const name = style ? `${style} Leadership` : 'Independent Leadership';
  return { name, style, leaders };
}

function statBonusText(statBonus, lang) {
  return Object.entries(statBonus).map(([k, v]) => `+${v} ${statLabel(k, lang)}`).join(', ');
}

