// ---------------------------------------------------------------- byproduct resolution
// A launched line throws off scrap in proportion to what it actually produces. What that costs —
// or earns — is entirely down to the policy the player set and whether they built the line that
// eats it.
function byproductVolume(inst, product, game) {
  if (!product.byproduct || inst.phase !== 'launched') return 0;
  // Actual production (tracked by the finished-goods system), not raw nameplate capacity — a
  // line running under capacity throws off proportionally less scrap, not a fixed amount.
  const produced = inst.lastProducedUnits != null ? inst.lastProducedUnits : productCapacityContribution(inst, product, game);
  return produced * product.byproduct.ratePerUnit;
}

// Is the "feed your own line" option actually available? Only if the consuming line exists AND is
// launched — this is the payoff for having seen the opportunity and built for it.
function reuseAvailable(game, byproductId) {
  const bp = BYPRODUCTS[byproductId];
  if (!bp || !bp.consumedBy) return false;
  const consumer = (game.products || {})[bp.consumedBy];
  return !!consumer && consumer.phase === 'launched';
}

function effectiveByproductPolicy(game, byproductId) {
  const chosen = (game.byproductPolicies || {})[byproductId] || 'dispose';
  // Falling back rather than silently doing nothing: a player who set 'reuse' and then retired
  // the consuming line should pay disposal, not get free handling.
  if (chosen === 'reuse' && !reuseAvailable(game, byproductId)) return 'dispose';
  return chosen;
}

// The monthly cash and burn consequence of everything the company throws off. Returns a breakdown
// rather than one number, so the UI can show WHERE the money is going.
// ---------------------------------------------------------------- spoilage -> byproduct (step 5)
// Below the quality floor, stock stops being sellable product and becomes a byproduct instead —
// SAME stream, SAME policy the player already set for that material (direction's Q6). 1:1
// conversion (Q4): the value collapse between a product and its byproduct is already enormous
// (a product worth 24 converts to scrap worth ~0.5 — about 2% of face value), so a lossy ratio
// on top would be punishing an already-catastrophic mistake twice. Automatic, not player-
// triggered (Q5): there is no real decision to make once stock has crossed the floor, only a
// loss to report honestly.
function resolveSpoilage(game, industry, month) {
  const result = { lines: [], totalUnitsLost: 0 };
  if (!industry || !industry.productCatalog) return result;
  Object.keys(game.products || {}).forEach(pid => {
    const inst = game.products[pid];
    if (inst.phase !== 'launched') return;
    const def = PRODUCT_BY_ID[pid];
    if (!def) return;
    const lots = lotsOf(inst);
    const keep = [];
    let spoiledUnits = 0;
    lots.forEach(lot => {
      const q = lotQualityNow(lot, pid, month, game);
      if (q != null && q < SPOILAGE_QUALITY_FLOOR) {
        spoiledUnits += lot.units;
      } else {
        keep.push(lot);
      }
    });
    if (spoiledUnits <= 0) return;
    result.lines.push({ productId: pid, units: spoiledUnits, keptLots: keep });
    result.totalUnitsLost += spoiledUnits;
  });
  return result;
}

// Applies a spoilage line's units into the SAME byproduct resolution a product's own production
// waste already flows through — same BYPRODUCTS entry, same effectiveByproductPolicy — and
// returns the cash/reputation effect so the caller can fold it into the same monthly totals.
function applySpoilageToByproducts(draft, line, def) {
  if (!def.byproduct) {
    // Nowhere for it to go: a straight write-off. Honest rather than inventing a sink.
    return { cash: 0, wroteOff: true };
  }
  const bp = BYPRODUCTS[def.byproduct.id];
  if (!bp) return { cash: 0, wroteOff: true };
  const policy = effectiveByproductPolicy(draft, bp.id);
  const volume = line.units; // 1:1, per direction
  if (policy === 'dispose') {
    const cost = Math.round(volume * bp.disposalCost * 10) / 10;
    draft.capital -= cost;
    return { cash: -cost, policy, byproductId: bp.id, volume };
  }
  if (policy === 'sell') {
    const revenue = Math.round(volume * bp.wholesaleValue * 10) / 10;
    draft.capital += revenue;
    return { cash: revenue, policy, byproductId: bp.id, volume };
  }
  if (policy === 'burn') {
    // Energy relief reduces THIS month's burn already computed elsewhere; credit it as cash-
    // equivalent here since spoilage resolves after that figure is locked in.
    const relief = Math.round(volume * bp.energyValue * 10) / 10;
    draft.capital += relief;
    return { cash: relief, policy, byproductId: bp.id, volume };
  }
  if (policy === 'reuse' && reuseAvailable(draft, bp.id)) {
    // Feeds the consuming line for free, same as production-sourced scrap on 'reuse'.
    return { cash: 0, policy, byproductId: bp.id, volume, reusedInto: bp.consumedBy };
  }
  const cost = Math.round(volume * bp.disposalCost * 10) / 10;
  draft.capital -= cost;
  return { cash: -cost, policy: 'dispose', byproductId: bp.id, volume };
}

function resolveByproducts(game, industry) {
  const result = { disposalCost: 0, wholesaleRevenue: 0, energyRelief: 0, reusedInto: [], lines: [] };
  if (!industry || !industry.productCatalog) return result;
  Object.values(game.products || {}).forEach(inst => {
    const def = PRODUCT_BY_ID[inst.productId];
    if (!def || !def.byproduct) return;
    const volume = byproductVolume(inst, def, game);
    if (volume <= 0) return;
    const bp = BYPRODUCTS[def.byproduct.id];
    if (!bp) return;
    const policy = effectiveByproductPolicy(game, bp.id);
    const line = { byproductId: bp.id, volume: Math.round(volume * 10) / 10, policy };
    if (policy === 'dispose') {
      line.cost = Math.round(volume * bp.disposalCost * 10) / 10;
      result.disposalCost += line.cost;
    } else if (policy === 'sell') {
      line.revenue = Math.round(volume * bp.wholesaleValue * 10) / 10;
      result.wholesaleRevenue += line.revenue;
    } else if (policy === 'burn') {
      line.relief = Math.round(volume * bp.energyValue * 10) / 10;
      result.energyRelief += line.relief;
    } else if (policy === 'reuse') {
      // Feeding your own line: no disposal cost AND the consuming line's material cost drops,
      // because you are buying less of its input. The compounding reward for having built it.
      line.reusedInto = bp.consumedBy;
      result.reusedInto.push({ from: bp.id, into: bp.consumedBy, volume: line.volume });
    }
    result.lines.push(line);
  });
  result.disposalCost = Math.round(result.disposalCost * 10) / 10;
  result.wholesaleRevenue = Math.round(result.wholesaleRevenue * 10) / 10;
  result.energyRelief = Math.round(result.energyRelief * 10) / 10;
  return result;
}

// Material cost relief on a line that is being fed by its own upstream scrap.
const REUSE_MATERIAL_RELIEF = 0.25;
function reuseMaterialRelief(game, productId) {
  const feeding = Object.values(BYPRODUCTS).some(bp =>
    bp.consumedBy === productId && effectiveByproductPolicy(game, bp.id) === 'reuse');
  return feeding ? REUSE_MATERIAL_RELIEF : 0;
}

// Kept as an alias so nothing downstream needs to know the catalogue was replaced.
const FURNITURE_PRODUCTS = BASE_PRODUCTS;

// Lazy, because the live catalogue is adapter-generated and defined further down the file.
// Resolving on first use rather than at declaration keeps declaration order from mattering —
// the same hazard that produced the TDZ class of bugs earlier in this project.
let _productById = null;
function productById() {
  if (!_productById) {
    _productById = {};
    (typeof MANUFACTURING_CATALOG !== 'undefined' ? MANUFACTURING_CATALOG : FURNITURE_PRODUCTS)
      .forEach(p => { _productById[p.id] = p; });
  }
  return _productById;
}
const PRODUCT_BY_ID = new Proxy({}, {
  get: (_, k) => productById()[k],
  has: (_, k) => k in productById(),
  ownKeys: () => Reflect.ownKeys(productById()),
  getOwnPropertyDescriptor: (_, k) => ({ value: productById()[k], enumerable: true, configurable: true }),
});

