// ---------------------------------------------------------------- adjacency
// Weights favour what costs CAPITAL AND TIME to acquire (equipment, materials) over what can be
// trained or built (skills, channels) — see Bible §A.5.2.
const ADJACENCY_WEIGHTS = { materials: 0.30, capabilities: 0.30, skills: 0.20, channels: 0.20 };

const ADJACENCY_BANDS = [
  { min: 0.75, id: 'lineExtension', label: { en: 'Line Extension', es: 'Extensión de Línea' } },
  { min: 0.45, id: 'adjacent', label: { en: 'Adjacent', es: 'Adyacente' } },
  { min: 0.20, id: 'stretch', label: { en: 'Stretch', es: 'Estiramiento' } },
  { min: -1, id: 'unrelated', label: { en: 'Unrelated', es: 'No Relacionado' } },
];
function adjacencyBand(score) {
  return ADJACENCY_BANDS.find(b => score >= b.min) || ADJACENCY_BANDS[ADJACENCY_BANDS.length - 1];
}

// Fraction of `required` already present in `owned`. 1.0 when the product needs nothing (a
// degenerate but harmless case — an empty requirement is trivially satisfied).
function tagOverlap(required, owned) {
  if (!required || required.length === 0) return 1;
  const ownedSet = owned instanceof Set ? owned : new Set(owned || []);
  const hit = required.filter(r => ownedSet.has(r)).length;
  return hit / required.length;
}

