// Two Tooling/Line/Plant projects stay process/organisational rather than a new machine —
// spawning THEM as equipment would be a fiction. Instead they buff the maintenance system
// directly, which is what they are actually about.
//   mfgCapacityExpansion ("Second Shift")     -> running EXISTING equipment longer, not a new
//                                                 machine: read directly by handleAdvanceProduct's
//                                                 laborFactor via draft.completed, unchanged.
//   mfgPredictiveMaintenance                  -> a passive decay-rate reduction across ALL owned
//                                                 equipment (see EQUIPMENT_DECAY_REDUCTION below).

function isEquipmentProject(projectId) { return !!EQUIPMENT_CATALOG[projectId]; }

// Builds a fresh equipment instance the month its project completes. corrective is the default
// stance — the one a player ends up on if they never touch the dial, per Bible §B.2's table.
function instantiateEquipment(projectId) {
  const def = EQUIPMENT_CATALOG[projectId];
  if (!def) return null;
  return {
    id: projectId, originTag: def.originTag, type: def.type,
    condition: 100, automationLevel: def.automationLevel,
    stance: 'corrective', downtimeMonthsLeft: 0, installedMonth: null,
  };
}

// ---------------------------------------------------------------- maintenance stances
// Three ongoing stances (a recurring monthly choice). Replacement and automation upgrades are
// separate one-time ACTIONS (handleReplaceEquipment / handleUpgradeAutomation) rather than
// stances — they're capital events, not standing policy, and are not mutually exclusive with
// whichever stance is active.
const MAINTENANCE_STANCES = {
  preventive: { decayPerMonth: 1.2, costMult: 1.6, failureSeverity: 0.35,
    label: { en: 'Preventive', es: 'Preventivo' } },
  corrective: { decayPerMonth: 2.6, costMult: 1.0, failureSeverity: 1.0,
    label: { en: 'Corrective', es: 'Correctivo' } },
  neglect: { decayPerMonth: 5.5, costMult: 0, failureSeverity: 2.2,
    label: { en: 'Neglect', es: 'Abandono' } },
};
function maintenanceStance(id) { return MAINTENANCE_STANCES[id] || MAINTENANCE_STANCES.corrective; }

// mfgPredictiveMaintenance's effect: slows decay on every owned machine, regardless of that
// machine's own stance — a company-wide capability, not a per-machine dial.
const EQUIPMENT_DECAY_REDUCTION = 0.7; // multiplies decayPerMonth when the program is completed

// ---------------------------------------------------------------- decay, cost, failure
function equipmentDecayThisMonth(equipment, hasPredictiveMaintenance, managerRelief) {
  const stance = maintenanceStance(equipment.stance);
  const mult = hasPredictiveMaintenance ? EQUIPMENT_DECAY_REDUCTION : 1;
  // A maintenance-discipline manager slows wear on every machine they oversee.
  return stance.decayPerMonth * mult * (1 - (managerRelief || 0));
}
function equipmentMonthlyCost(equipment) {
  const def = EQUIPMENT_CATALOG[equipment.id];
  const stance = maintenanceStance(equipment.stance);
  return Math.round((def ? def.maintenanceCost : 1) * stance.costMult * 10) / 10;
}

// Failure probability rises as condition falls, amplified by how aggressively the stance accepts
// risk (Bible §B.2: "tempting during cash shortages but dangerous" — neglect is cheap AND its
// decay is faster AND its severity multiplier is highest, so risk compounds three ways at once,
// not one). Fresh equipment (condition 100) essentially never fails regardless of stance.
const FAILURE_BASE_RATE = 0.5;
function equipmentFailureChance(equipment) {
  if (equipment.downtimeMonthsLeft > 0) return 0; // already down; can't fail further this month
  const stance = maintenanceStance(equipment.stance);
  const conditionRisk = clamp((100 - equipment.condition) / 100, 0, 1);
  return clamp(conditionRisk * stance.failureSeverity * FAILURE_BASE_RATE, 0, 0.9);
}

// ---------------------------------------------------------------- company equipment lookups
// The "weakest link" rule from §B.4 applies to equipment exactly the way it applies to quality:
// a product needing BOTH Tooling and Quality is only as good as the worse of the two, not their
// average. Picks the single BEST owned instance per required tag (a company with two Tooling
// projects completed uses whichever one is actually working this month).
function bestEquipmentForTag(game, tag) {
  const owned = Object.values(game.equipment || {}).filter(eq => eq.originTag === tag);
  if (!owned.length) return null;
  return owned.reduce((best, eq) => {
    const score = equipmentEffectiveCapacity(eq);
    const bestScore = best ? equipmentEffectiveCapacity(best) : -1;
    return score > bestScore ? eq : best;
  }, null);
}
function equipmentAutomationFactor(automationLevel) { return 1 + (automationLevel || 0) * 0.15; }
function equipmentEffectiveCapacity(eq) {
  if (eq.downtimeMonthsLeft > 0) return 0; // Bible §0.2's "− maintenanceDowntime" term
  const def = EQUIPMENT_CATALOG[eq.id];
  if (!def) return 0;
  return def.capacityContribution * (eq.condition / 100) * equipmentAutomationFactor(eq.automationLevel);
}
// EQUIPMENT_CATALOG stores precision on the original 1-10 authoring scale; it is exposed here on
// the shared 0-100 quality scale so it can be compared against product ceilings directly.
function equipmentPrecision(eq) {
  const def = EQUIPMENT_CATALOG[eq.id];
  const raw = def ? def.precision : 5;
  return raw * 10;
}

// The two derived floors a product's required equipment tags impose. Returns a NEUTRAL value
// (1 for capacity, 10 for precision — i.e. "no constraint") when a tag has no owned equipment,
// since callers only reach here after missingEquipmentTags has already gated entry to
// Production; this is a defensive default, not a path that should be reachable in play.
// Capability-based versions of the equipment factors. Same weakest-link rule, new vocabulary:
// a product is only as capable as the WORST machine among those providing what it needs.
function equipmentProvidingCapability(game, capability) {
  const owned = Object.values(game.equipment || {})
    .filter(eq => (EQUIPMENT_CAPABILITIES[eq.id] || []).includes(capability));
  if (!owned.length) return null;
  return owned.reduce((best, eq) =>
    equipmentEffectiveCapacity(eq) > (best ? equipmentEffectiveCapacity(best) : -1) ? eq : best, null);
}
function capabilityCapacityFactor(game, requiredCaps) {
  if (!requiredCaps || !requiredCaps.length) return 1;
  const factors = requiredCaps.map(cap => {
    const eq = equipmentProvidingCapability(game, cap);
    // Neutral (1), not zero: the REAL gate against missing capabilities is
    // missingEquipmentTags at Production entry — a launched product should never actually reach
    // this branch. Same defensive-default philosophy the original equipmentCapacityFactor used.
    return eq ? equipmentEffectiveCapacity(eq) : 1;
  });
  return Math.min(...factors);
}
function capabilityPrecisionFloor(game, requiredCaps) {
  if (!requiredCaps || !requiredCaps.length) return 10;
  const precisions = requiredCaps.map(cap => {
    const eq = equipmentProvidingCapability(game, cap);
    return eq ? equipmentPrecision(eq) : QUALITY_MAX;
  });
  return Math.min(...precisions);
}

function equipmentCapacityFactor(game, requiredTags) {
  if (!requiredTags || !requiredTags.length) return 1;
  const factors = requiredTags.map(tag => {
    const eq = bestEquipmentForTag(game, tag);
    return eq ? equipmentEffectiveCapacity(eq) : 1;
  });
  return Math.min(...factors);
}
function equipmentPrecisionFloor(game, requiredTags) {
  if (!requiredTags || !requiredTags.length) return 10;
  const precisions = requiredTags.map(tag => {
    const eq = bestEquipmentForTag(game, tag);
    return eq ? equipmentPrecision(eq) : QUALITY_MAX;
  });
  return Math.min(...precisions);
}

