// Effective magnitude for a given manager. One place, so tier scaling can never drift per-perk.
function managerPerkMagnitude(manager) {
  const perk = MANAGER_PERKS[manager.perkId];
  if (!perk) return 0;
  return perk.base * managerTier(manager.tier).mult;
}
function managerPerkPercent(manager) { return Math.round(managerPerkMagnitude(manager) * 100); }

