const MANAGER_BY_ID = MANAGER_ROSTER.reduce((a, m) => { a[m.id] = m; return a; }, {});

// New unlock markers this roster needs beyond the ten that already exist.
const MANAGER_UNLOCKS = {
  veteranIndustrialist: {
    id: 'veteranIndustrialist',
    name: { en: 'Veteran Industrialist', es: 'Industrial Veterana' },
    requirement: { en: 'Win 2 runs in Manufacturing.', es: 'Gana 2 partidas en Manufactura.' },
    check: (career) => ((career.winsByIndustry || {}).manufacturing || 0) >= 2,
    progress: (career) => ({ have: (career.winsByIndustry || {}).manufacturing || 0, need: 2 }),
  },
  scaleOperator: {
    id: 'scaleOperator',
    name: { en: 'Scale Operator', es: 'Operadora de Escala' },
    requirement: { en: 'Accumulate 500 months as a founder.', es: 'Acumula 500 meses como fundador.' },
    check: (career) => (career.totalMonths || 0) >= 500,
    progress: (career) => ({ have: career.totalMonths || 0, need: 500 }),
  },
  peoplePerson: {
    id: 'peoplePerson',
    name: { en: 'People Person', es: 'Persona de Gente' },
    requirement: { en: 'Finish a run with 3 allied rival companies.', es: 'Termina una partida con 3 empresas rivales aliadas.' },
    check: (career) => (career.alliesFormed || 0) >= 3,
    progress: (career) => ({ have: career.alliesFormed || 0, need: 3 }),
  },
};

// A manager with no `unlockedBy` is hireable from the first run — all ten C-Tier are. Everything
// above C is earned. Gates resolve against BOTH the manager-specific markers above and the ten
// existing LEADER/UNLOCK markers, since several A/B-Tier managers reuse those.
function managerUnlocked(manager, career, unlockedIds) {
  if (!manager.unlockedBy) return true;
  const own = MANAGER_UNLOCKS[manager.unlockedBy];
  if (own) { try { return !!own.check(career || {}); } catch (e) { return false; } }
  return (unlockedIds || []).includes(manager.unlockedBy); // one of the ten existing markers
}
function availableManagers(career, unlockedIds) {
  return MANAGER_ROSTER.filter(m => managerUnlocked(m, career, unlockedIds));
}

// ---------------------------------------------------------------- assignment & aggregation
// Locations are the slot mechanic: one manager per location. A hired-but-unassigned manager is on
// the bench — still paid, contributing nothing. That's deliberate: it makes location count the
// real constraint on how much manager power a company can actually field.
// KNOWN GAP (flagged, not silently patched): Manufacturing currently has ZERO projects flagged
// isLocation, so `locations` never rises above 0 there — which means slot limit is 0 and no
// manager can ever be assigned in the industry this system was designed for. Hospitality has
// seven such projects and works as intended. Closing this needs either location-flagged
// Manufacturing projects (Second Facility / Third Facility / Overseas Facility are the obvious
// candidates, and already exist as Plant-tagged equipment projects) or a different slot source
// for Manufacturing. That is a content/design decision, not a bug fix, so it is left for
// direction rather than guessed at here.
function managerSlotLimit(game) { return game.locations || 0; }
function assignedManagers(game) {
  return Object.values(game.managers || {}).filter(m => m.assignedLocation != null);
}
function benchedManagers(game) {
  return Object.values(game.managers || {}).filter(m => m.assignedLocation == null);
}
function unmanagedLocationCount(game) {
  return Math.max(0, (game.locations || 0) - assignedManagers(game).length);
}

// The aggregator, same pattern as founderFx/activeTermEffects: one pure function returning a
// neutral-default object, so call sites read a named key and never know managers exist.
// Same-perk stacking is ADDITIVE across assigned managers (two throughput managers are better
// than one), but every multiplier is clamped so a stack can never invert a mechanic.
function managerFx(game) {
  const fx = {
    smallBatchQuality: 0, defectReduction: 0, throughput: 0, maintenanceDiscipline: 0,
    disruptionBuffer: 0, supplierSwitchRelief: 0, complianceShield: 0,
    talentAnchor: 0, prototypeSpeed: 0, channelReach: 0,
  };
  assignedManagers(game).forEach(inst => {
    const def = MANAGER_BY_ID[inst.managerId];
    if (!def) return;
    const perk = MANAGER_PERKS[def.perkId];
    if (!perk) return;
    fx[perk.id] += managerPerkMagnitude(def);
  });
  // Clamped: reductions can never exceed 80% (nothing becomes free), bonuses cap at +150%.
  Object.keys(fx).forEach(k => { fx[k] = clamp(fx[k], 0, 1.5); });
  ['defectReduction', 'maintenanceDiscipline', 'disruptionBuffer', 'supplierSwitchRelief',
    'talentAnchor', 'prototypeSpeed'].forEach(k => { fx[k] = Math.min(fx[k], 0.8); });
  return fx;
}

// Monthly salary for everyone on payroll, assigned or benched — a bench costs real money, which
// is what stops a player from simply hoarding every manager they unlock.
function managerPayroll(game) {
  return Object.values(game.managers || {}).reduce((sum, inst) => {
    const def = MANAGER_BY_ID[inst.managerId];
    return sum + (def ? managerTier(def.tier).salary : 0);
  }, 0);
}

// An unmanaged location runs at reduced effectiveness. This is what makes managers REQUIRED for
// expansion rather than a nice-to-have: adding locations without people to run them buys burn
// and overhead without buying the output that justifies it.
const UNMANAGED_LOCATION_CAPACITY_PENALTY = 0.15; // per unmanaged location, capped below
function unmanagedLocationDrag(game) {
  return clamp(unmanagedLocationCount(game) * UNMANAGED_LOCATION_CAPACITY_PENALTY, 0, 0.6);
}

// ============================== WORKING CAPITAL & FINANCE ==============================
// Bible §F, build order item 5. The missing pressure: until now a company's cash was capital in,
// burn out, revenue in — nothing was ever TIED UP. Every system built in items 1-4 consumes cash
// on a timeline the engine didn't represent: you pay suppliers on contract, hold inventory, and
// build products for months, then got paid instantly and in full. A profitable company could not
// die of a cash gap, which is the most characteristically manufacturing way to die.

// ---------------------------------------------------------------- receivables
// B2B sells on terms, B2C collects at the till. This makes the launch fork built in item 1 a
// CASH decision as well as a margin one: B2C is lower volume but immediate, B2B is higher volume
// but you finance the gap yourself until it clears.
const RECEIVABLE_TERMS_MONTHS = 2;   // net-60, the B2B default
const FACTORING_DISCOUNT = 0.18;     // what you surrender to get paid today instead

// What fraction of this month's revenue is sold on terms rather than collected immediately.
// Weighted by each launched product's actual demand contribution, so a company whose B2B line is
// most of its volume genuinely carries most of its revenue as paper.
function b2bRevenueShare(game, industry) {
  if (!industry || !industry.productCatalog) return 0;
  let b2b = 0, total = 0;
  Object.values(game.products || {}).forEach(inst => {
    if (inst.phase !== 'launched') return;
    const def = PRODUCT_BY_ID[inst.productId];
    if (!def) return;
    const contribution = productDemandContribution(inst, def, game);
    total += contribution;
    if (inst.launchType === 'b2b') b2b += contribution;
  });
  return total > 0 ? b2b / total : 0;
}

// Receivables are an aging queue, not a single number — that's what lets a player see money
// arriving in two months and decide whether they can wait for it.
function totalReceivables(game) {
  return (game.receivables || []).reduce((sum, r) => sum + r.amount, 0);
}
function receivablesDueIn(game, months) {
  return (game.receivables || []).filter(r => r.monthsLeft <= months).reduce((sum, r) => sum + r.amount, 0);
}

// ---------------------------------------------------------------- payables (trade credit)
// Trade credit is a supplier RELATIONSHIP paying off in cash rather than reliability — the
// counterpart to the reliability benefit item 3 already gave. A trusted supplier lets you pay
// later, which is a free working-capital loan from someone who likes you.
const TRADE_CREDIT_RELATIONSHIP_THRESHOLD = 15; // 'reliable' band or better
const TRADE_CREDIT_DEFERRAL_MONTHS = 1;

function tradeCreditEligible(game) {
  return Object.entries(game.supplierContracts || {}).some(([id, c]) => {
    if (c.active === false) return false;
    return (c.relationship || 0) >= TRADE_CREDIT_RELATIONSHIP_THRESHOLD;
  });
}
function totalPayables(game) {
  return (game.payables || []).reduce((sum, p) => sum + p.amount, 0);
}

// ---------------------------------------------------------------- inventory value
// Stock on hand is cash the company has already spent and cannot spend again. Derived from the
// inventory strategy and active contracts rather than tracked per-unit — same level of
// abstraction the rest of the supply system uses.
function inventoryValue(game) {
  const activeContracts = Object.entries(game.supplierContracts || {})
    .filter(([, c]) => c.active !== false);
  if (!activeContracts.length) return 0;
  const strat = inventoryStrategy(game.inventoryStrategy);
  return Math.round(activeContracts.reduce((sum, [id]) => {
    const supplier = resolveSupplier(game, id);
    return sum + (supplier ? supplier.minimumOrder * supplier.priceIndex : 0);
  }, 0) * strat.workingCapitalMult);
}

// The headline number, Bible §F.1. Finished goods join raw materials and receivables — stock
// built on Build to Stock is cash the company converted into inventory, and it should show up
// here exactly like any other form of capital tied up.
function workingCapital(game) {
  return Math.round(totalReceivables(game) + inventoryValue(game) + finishedGoodsValue(game) - totalPayables(game));
}

// ---------------------------------------------------------------- debt
// Cash now, fixed repayment with interest, fatal if left unserviced. Deliberately distinct from
// the equity instruments that already exist: no dilution, but it does not care how the month went.
const DEBT_INSTRUMENTS = {
  bankLoan: {
    id: 'bankLoan', interestRate: 0.06, termMonths: 24,
    name: { en: 'Bank Term Loan', es: 'Préstamo Bancario a Plazo' },
    blurb: {
      en: 'The cheapest money available, and the hardest to qualify for. The bank wants a company that already looks like it does not need the loan.',
      es: 'El dinero más barato disponible, y el más difícil de conseguir. El banco quiere una empresa que ya parezca no necesitar el préstamo.',
    },
    requires: { boardConfidence: 55, reputation: 50, revenuePerMonth: 20 },
    amountOf: (game) => Math.round(clamp((game.revenuePerMonth || 0) * 6, 40, 400)),
  },
  investorNote: {
    id: 'investorNote', interestRate: 0.11, termMonths: 18,
    name: { en: 'Investor Bridge Note', es: 'Nota Puente de Inversionista' },
    blurb: {
      en: 'An investor who already backed you will lend against the next round. Faster than a bank and more expensive, and they will remember the ask.',
      es: 'Un inversionista que ya te respaldó prestará contra la siguiente ronda. Más rápido que un banco y más caro, y recordará que se lo pediste.',
    },
    requires: { backers: 1 },
    amountOf: (game) => Math.round(clamp((game.revenuePerMonth || 0) * 4 + 30, 30, 250)),
  },
  merchantAdvance: {
    id: 'merchantAdvance', interestRate: 0.22, termMonths: 12,
    name: { en: 'Merchant Advance', es: 'Adelanto Comercial' },
    blurb: {
      en: 'Money against next quarter\u2019s receipts at a rate nobody defends. Available to almost anyone, which is exactly the problem with it.',
      es: 'Dinero contra los ingresos del próximo trimestre a una tasa que nadie defiende. Disponible para casi cualquiera, que es exactamente su problema.',
    },
    requires: {},
    amountOf: (game) => Math.round(clamp((game.revenuePerMonth || 0) * 2 + 15, 20, 120)),
  },
};

// Straight amortisation: every debt costs the same each month until it's gone. Simple on purpose —
// the player needs to be able to hold "what do I owe every month" in their head.
function debtMonthlyPayment(principal, interestRate, termMonths) {
  const total = principal * (1 + interestRate);
  return Math.round((total / termMonths) * 10) / 10;
}
function totalDebtOutstanding(game) {
  return Math.round((game.debts || []).reduce((sum, d) => sum + d.remaining, 0));
}
function totalMonthlyDebtService(game) {
  return Math.round((game.debts || []).reduce((sum, d) => sum + d.monthlyPayment, 0) * 10) / 10;
}
function debtInstrumentAvailable(instrumentId, game) {
  const inst = DEBT_INSTRUMENTS[instrumentId];
  if (!inst) return { open: false, reason: 'unknown' };
  const req = inst.requires || {};
  if (req.boardConfidence != null && (game.boardConfidence || 0) < req.boardConfidence) {
    return { open: false, reason: 'boardConfidence', need: req.boardConfidence };
  }
  if (req.reputation != null && (game.reputation || 0) < req.reputation) {
    return { open: false, reason: 'reputation', need: req.reputation };
  }
  if (req.revenuePerMonth != null && (game.revenuePerMonth || 0) < req.revenuePerMonth) {
    return { open: false, reason: 'revenue', need: req.revenuePerMonth };
  }
  if (req.backers != null && Object.keys(game.investorBackers || {}).length < req.backers) {
    return { open: false, reason: 'backers', need: req.backers };
  }
  return { open: true };
}

// Missing payments escalates. The Bible's "fatal if left unserviced" is implemented as a counter
// rather than an instant kill, so a player gets a visible, actionable warning first — the same
// hysteresis principle the ousting rule uses.
const DEBT_DEFAULT_MISSES = 3;

// ---------------------------------------------------------------- emergency financing
// Q2's answer: expensive and avoidable, not fatal. When cash would go negative, the company
// reaches for whatever is nearest — and each option costs something different, so even the
// rescue teaches which relationship the founder has been neglecting.
function emergencyFinancingOption(game) {
  // Cheapest first: a warm investor, then the bank, then dilution as the last resort.
  const warmBackers = Object.entries(game.investorStandings || {})
    .filter(([, v]) => (v || 0) >= 15).length;
  if (warmBackers > 0) return 'investorRescue';
  if ((game.boardConfidence || 0) >= 45 && (game.reputation || 0) >= 40) return 'bankOverdraft';
  return 'emergencyEquity';
}
const EMERGENCY_FINANCING = {
  investorRescue: {
    id: 'investorRescue', costMultiplier: 1.15,
    deltas: { boardConfidence: -4, reputation: -2 },
    name: { en: 'Investor Rescue', es: 'Rescate de Inversionista' },
    body: {
      en: 'An investor who already believes in you wires enough to cover the gap. They do not make it a scene, and they do not forget.',
      es: 'Un inversionista que ya cree en ti transfiere lo suficiente para cubrir el hueco. No hace una escena, y no lo olvida.',
    },
  },
  bankOverdraft: {
    id: 'bankOverdraft', costMultiplier: 1.3,
    deltas: { boardConfidence: -7, reputation: -3 },
    name: { en: 'Bank Overdraft', es: 'Sobregiro Bancario' },
    body: {
      en: 'The bank covers the shortfall at overdraft rates and schedules a meeting you would rather not have.',
      es: 'El banco cubre el faltante a tasas de sobregiro y agenda una reunión que preferirías no tener.',
    },
  },
  emergencyEquity: {
    id: 'emergencyEquity', costMultiplier: 1.0, dilutes: true,
    deltas: { boardConfidence: -12, reputation: -6, morale: -5 },
    name: { en: 'Emergency Equity', es: 'Capital de Emergencia' },
    body: {
      en: 'With nobody left to call, the company sells shares into its own crisis at whatever price it can get. Everyone notices.',
      es: 'Sin nadie a quien llamar, la empresa vende acciones en plena crisis al precio que consiga. Todos lo notan.',
    },
  },
};

// ---------------------------------------------------------------- forecasting (Analyst tie-in)
// Q5's answer: everyone sees one derived meter; the Analyst sees the breakdown AND a projected
// gap. This makes the Analyst class the natural counter to the whole working-capital system,
// which is the kind of design economy worth taking when it's available.
function projectedCashGap(game, burnEstimate, monthsAhead) {
  const horizon = monthsAhead || 3;
  let cash = game.capital || 0;
  let worstMonth = null;
  for (let m = 1; m <= horizon; m++) {
    const collecting = (game.receivables || []).filter(r => r.monthsLeft === m)
      .reduce((s, r) => s + r.amount, 0);
    const paying = (game.payables || []).filter(p => p.monthsLeft === m)
      .reduce((s, p) => s + p.amount, 0);
    cash = cash - burnEstimate - totalMonthlyDebtService(game) + collecting - paying;
    if (cash < 0 && worstMonth === null) worstMonth = m;
  }
  return { endingCash: Math.round(cash), gapInMonths: worstMonth };
}

// ============================== COMPETITOR LIFECYCLE ==============================
// Bible §G.2, build order item 6. Until now the market was a set of health bars that only moved
// up: rivals grew, attacked, and remembered you, but no rival had ever gone under, bought another
// rival, or become anything other than a competitor. This is what makes the market evolve without
// the player — the brief's explicit goal.
//
// Pacing rule, from direction: significant events must NEVER become noise. One lifecycle event
// fires per check, checks are 18-24 months apart, and the most consequential applicable event
// wins. Over an 84-month Manufacturing run that is roughly 3-4 events — each one memorable.

// ---------------------------------------------------------------- strategic archetypes
// Bible §G.1. Distinct from `posture` (which is BEHAVIOURAL — how they fight you) and from
// `philosophy` (which is VALUES). Archetype is STRATEGY: what kind of company they are trying to
// be, and therefore how they die and who they buy. Every archetype has an explicit weakness, and
// that weakness is what feeds failure risk — so a company's death is legible from its identity.
const RIVAL_ARCHETYPES = {
  costLeader: {
    id: 'costLeader',
    name: { en: 'Cost Leader', es: 'Líder en Costos' },
    focus: { en: 'Automation, scale, low prices, high volume.', es: 'Automatización, escala, precios bajos, alto volumen.' },
    weakness: { en: 'Vulnerable to premium competition and brittle in a downturn.', es: 'Vulnerable a la competencia premium y frágil en una recesión.' },
    // How this archetype dies. Read by rivalFailureScore.
    failsWhen: 'lowMarketPosition',
    failureNarrative: {
      en: 'undercut on price by someone with deeper pockets, and with no premium line to retreat to',
      es: 'superada en precio por alguien con más recursos, y sin línea premium a la cual replegarse',
    },
    acquisitiveness: 0.8, // relative appetite for buying a struggling rival
  },
  qualityHouse: {
    id: 'qualityHouse',
    name: { en: 'Quality House', es: 'Casa de Calidad' },
    focus: { en: 'Craftsmanship, quality, premium customers.', es: 'Artesanía, calidad, clientes premium.' },
    weakness: { en: 'High costs and cannot scale.', es: 'Costos altos y no puede escalar.' },
    failsWhen: 'lowStrength',
    failureNarrative: {
      en: 'unable to scale past a boutique volume while its costs kept climbing',
      es: 'incapaz de escalar más allá de un volumen boutique mientras sus costos seguían subiendo',
    },
    acquisitiveness: 0.3,
  },
  innovator: {
    id: 'innovator',
    name: { en: 'Innovator', es: 'Innovadora' },
    focus: { en: 'R&D, product development, new materials and designs.', es: 'I+D, desarrollo de producto, nuevos materiales y diseños.' },
    weakness: { en: 'High R&D spending and operational instability.', es: 'Alto gasto en I+D e inestabilidad operativa.' },
    failsWhen: 'burnRate',
    failureNarrative: {
      en: 'having spent its way through three funding rounds without a product that paid for itself',
      es: 'tras gastarse tres rondas de financiamiento sin un producto que se pagara solo',
    },
    acquisitiveness: 0.4,
  },
  verticalIntegrator: {
    id: 'verticalIntegrator',
    name: { en: 'Vertical Integrator', es: 'Integradora Vertical' },
    focus: { en: 'Owning the supply chain end to end.', es: 'Poseer la cadena de suministro de punta a punta.' },
    weakness: { en: 'Capital intensive and complex to run.', es: 'Intensiva en capital y compleja de operar.' },
    failsWhen: 'capitalIntensity',
    failureNarrative: {
      en: 'crushed under the fixed costs of a supply chain it had bought but could not keep loaded',
      es: 'aplastada por los costos fijos de una cadena de suministro que compró pero no pudo mantener ocupada',
    },
    acquisitiveness: 0.9, // buying upstream is the whole strategy
  },
  outsourcingSpecialist: {
    id: 'outsourcingSpecialist',
    name: { en: 'Outsourcing Specialist', es: 'Especialista en Tercerización' },
    focus: { en: 'Minimal fixed assets, contract manufacturing, capital efficiency.', es: 'Mínimos activos fijos, manufactura por contrato, eficiencia de capital.' },
    weakness: { en: 'Dependent on suppliers it does not control.', es: 'Dependiente de proveedores que no controla.' },
    failsWhen: 'supplierDependency',
    failureNarrative: {
      en: 'when the contract manufacturer it depended on raised prices and it had no plant of its own to fall back on',
      es: 'cuando el fabricante por contrato del que dependía subió precios y no tenía planta propia a la cual recurrir',
    },
    acquisitiveness: 0.5,
  },
  conglomerate: {
    id: 'conglomerate',
    name: { en: 'Conglomerate', es: 'Conglomerado' },
    focus: { en: 'Acquisitions, multiple products, market dominance.', es: 'Adquisiciones, múltiples productos, dominio del mercado.' },
    weakness: { en: 'Debt, complexity, and integration failure.', es: 'Deuda, complejidad y fracaso de integración.' },
    failsWhen: 'overextension',
    failureNarrative: {
      en: 'having bought more companies than it could integrate, and servicing debt on all of them',
      es: 'tras comprar más empresas de las que podía integrar, y pagando deuda por todas ellas',
    },
    acquisitiveness: 1.0, // the defining behaviour
  },
};
function rivalArchetype(id) { return RIVAL_ARCHETYPES[id] || RIVAL_ARCHETYPES.costLeader; }

// Assignment for the 12 authored companies — two per archetype, derived from each company's
// existing authored philosophy rather than bolted on arbitrarily. A company whose mission is
// about relentless efficiency IS a cost leader; one that hands its brand to local operators IS an
// outsourcing specialist. Keeping these consistent is what makes "who buys whom" readable.
const AUTHORED_ARCHETYPES = {
  // Hospitality
  hearthstone: 'outsourcingSpecialist',   // community-run, delegated, local operators
  vantagePoint: 'conglomerate',           // scale, acquisition-minded, centralised
  lanternHouse: 'qualityHouse',           // premium boutique, preserves character
  commonTable: 'costLeader',              // standardise relentlessly, lowest price
  meridianRooms: 'outsourcingSpecialist', // franchise: hands the brand to others
  saltCedar: 'innovator',                 // experimental, funds ideas that shouldn't work
  // Manufacturing
  northRiver: 'verticalIntegrator',       // responsible end-to-end manufacture
  atlasFoundry: 'conglomerate',           // empire, relentless growth, eliminates inefficiency
  kestrelDynamics: 'innovator',           // R&D, breakthrough to market
  halversonPrecision: 'qualityHouse',     // tightest tolerance, refuses to chase markets
  oreliaSystems: 'costLeader',            // automate, centralise, undercut
  bellwetherMill: 'verticalIntegrator',   // cooperative that owns itself
};

// Procedural rivals get an archetype too, chosen from their rolled philosophy so the same
// mission/identity logic applies to them as to the authored twelve.
function archetypeFromPhilosophy(philosophy) {
  const p = philosophy || {};
  if ((p.premiumVsMass || 0) >= 45) return 'qualityHouse';
  if ((p.innovationVsExecution || 0) >= 45) return 'innovator';
  if ((p.centralizedVsDelegated || 0) <= -45) return 'outsourcingSpecialist';
  if ((p.growthVsSustainability || 0) >= 60 && (p.centralizedVsDelegated || 0) >= 30) return 'conglomerate';
  if ((p.growthVsSustainability || 0) <= -40) return 'verticalIntegrator';
  return 'costLeader';
}

// ---------------------------------------------------------------- failure scoring
// Direction's answer to Q5 was (c): baseline probability, sharply raised by having lost fights.
// "Putting a competitor out of business is an accomplishment" — so the player's own successful
// attacks are the single heaviest term here, and the failure ticket names them explicitly.
const LIFECYCLE_CHECK_MIN_MONTHS = 18;
const LIFECYCLE_CHECK_MAX_MONTHS = 24;
const FAILURE_THRESHOLD = 45; // score a rival must clear to be eligible to collapse

function rivalFailureScore(rival, allRivals) {
  const enc = rival.encounters || {};
  const arch = rivalArchetype(rival.archetype);
  let score = 0;

  // Baseline frailty: how weak they actually are relative to the field.
  const avgStrength = allRivals.length
    ? allRivals.reduce((s, r) => s + r.strength, 0) / allRivals.length : rival.strength;
  if (rival.strength < avgStrength * 0.7) score += 20;
  if (rival.marketPosition < 20) score += 15;

  // The player's own pressure — deliberately the heaviest single term.
  score += (enc.defeatedByPlayer || 0) * 12;
  score += (enc.attackedByPlayer || 0) * 3;

  // Archetype weakness: each one dies its own way.
  switch (arch.failsWhen) {
    case 'lowMarketPosition': if (rival.marketPosition < 30) score += 18; break;
    case 'lowStrength':       if (rival.strength < 25) score += 18; break;
    case 'burnRate':          score += 10; break; // innovators are structurally fragile
    case 'capitalIntensity':  if (rival.marketPosition < 35) score += 15; break;
    case 'supplierDependency':if (rival.strength < 30) score += 15; break;
    case 'overextension':     score += (rival.acquisitionsMade || 0) * 14; break;
    default: break;
  }

  // An allied or trading partner is propped up — relationships keep companies alive.
  if ((rival.allianceWith || []).length) score -= 15;
  return Math.max(0, Math.round(score));
}

// Who, if anyone, is going under. Returns the single most-distressed eligible rival.
function failureCandidate(rivals) {
  const scored = rivals
    .map(r => ({ rival: r, score: rivalFailureScore(r, rivals) }))
    .filter(x => x.score >= FAILURE_THRESHOLD)
    .sort((a, b) => b.score - a.score);
  return scored.length ? scored[0] : null;
}

// ---------------------------------------------------------------- acquisition & alliance
// A struggling rival is a prime acquisition target. Acquirers are chosen by archetype appetite
// AND relative strength — a conglomerate with muscle buys; a boutique quality house does not.
const ACQUISITION_STRENGTH_RATIO = 1.4; // acquirer must be this much stronger than the target

function acquisitionPair(rivals) {
  const distressed = rivals
    .map(r => ({ rival: r, score: rivalFailureScore(r, rivals) }))
    .filter(x => x.score >= FAILURE_THRESHOLD * 0.6) // struggling, not necessarily dying
    .sort((a, b) => b.score - a.score);
  if (!distressed.length) return null;
  for (const target of distressed) {
    const buyers = rivals
      .filter(r => r.seedId !== target.rival.seedId)
      .filter(r => r.strength >= target.rival.strength * ACQUISITION_STRENGTH_RATIO)
      .map(r => ({ rival: r, appetite: rivalArchetype(r.archetype).acquisitiveness * r.strength }))
      .sort((a, b) => b.appetite - a.appetite);
    if (buyers.length) return { buyer: buyers[0].rival, target: target.rival };
  }
  return null;
}

// Two healthy rivals partnering to gain market control. Deliberately requires both to be doing
// WELL — an alliance of the weak is just two companies about to fail together, which isn't the
// pressure this event exists to create.
function alliancePair(rivals) {
  const healthy = rivals
    .filter(r => !(r.allianceWith || []).length)
    .filter(r => r.marketPosition >= 30)
    .sort((a, b) => b.strength - a.strength);
  if (healthy.length < 2) return null;
  return { a: healthy[0], b: healthy[1] };
}

// ---------------------------------------------------------------- talent scatter
// Direction: "Leaders and Managers will scatter in the event of a collapse or acquisition (some
// may choose to join the team)." A dying company's people are the part the player remembers.
function scatterTalent(rival, month) {
  const leaders = rival.leaders || [];
  if (!leaders.length) return null;
  const one = leaders[Math.floor(Math.random() * leaders.length)];
  return {
    name: one.name, role: one.role, trait: one.trait,
    fromCompany: rival.name, fromSeedId: rival.seedId, availableFromMonth: month,
  };
}

// ---------------------------------------------------------------- rival as supplier
// Direction on Q3: slot it in FULLY. A rival at ally disposition can become a real, contractable
// supplier — same contract types, same disruption model, same relationship track, same
// acquisition path as the ten authored suppliers. That makes diplomacy pay in something concrete
// rather than only in burn relief.
const RIVAL_SUPPLIER_DISPOSITION = 60; // 'ally' band

// Builds a supplier record from a rival. Derived rather than authored: a strong rival makes a
// reliable, expensive supplier; a weak one is cheap and shaky — their company is the product.
function rivalAsSupplier(rival, material) {
  const strengthFactor = clamp(rival.strength / 100, 0.2, 1);
  return {
    id: `rival-${rival.seedId}`,
    name: rival.name,
    material,
    origin: 'domestic',
    isRival: true,
    rivalSeedId: rival.seedId,
    portrait: { hue: (rival.logo && rival.logo.hue) || 200 },
    bio: {
      en: `${rival.name} competes with you and supplies you at the same time. Both of those are true at once, and both parties are aware of it.`,
      es: `${rival.name} compite contigo y te abastece al mismo tiempo. Ambas cosas son ciertas a la vez, y ambas partes lo saben.`,
    },
    reliability: clamp(0.62 + strengthFactor * 0.3, 0.6, 0.94),
    leadTimeMonths: 0,
    priceIndex: clamp(1.35 - strengthFactor * 0.35, 0.9, 1.35),
    qualityGrade: Math.round(clamp(4 + strengthFactor * 5, 4, 9)),
    minimumOrder: 8,
    tell: {
      en: 'A competitor on the other side of the invoice.',
      es: 'Un competidor al otro lado de la factura.',
    },
  };
}

// The single resolver every supplier lookup goes through, so a rival-supplier is genuinely
// first-class rather than a special case bolted onto each call site.
function resolveSupplier(game, supplierId) {
  if (SUPPLIER_BY_ID[supplierId]) return SUPPLIER_BY_ID[supplierId];
  return (game && game.rivalSuppliers && game.rivalSuppliers[supplierId]) || null;
}
function allAvailableSuppliers(game) {
  return [...allSuppliers(), ...Object.values((game && game.rivalSuppliers) || {})];
}

// Which allied rivals could be turned into suppliers, and for which material. Offers a material
// the company doesn't already have a strong source for, so the offer is actually attractive.
function rivalSupplierCandidates(game) {
  const existing = new Set(Object.keys(game.rivalSuppliers || {}));
  return (game.competitors || [])
    .filter(c => deriveDisposition(c) >= RIVAL_SUPPLIER_DISPOSITION)
    .filter(c => !existing.has(`rival-${c.seedId}`));
}

// ============================== VERTICAL INTEGRATION (7a) ==============================
// Bible §C.6/§10, build order item 7a. Two systems that share one idea: owning more of the chain
// is powerful and slow, and every new capability arrives attached to a new obligation.
//
// SCOPE: this is the BACKWARD half plus player acquisitions. Forward integration (Warehousing →
// Distribution → Retail) is item 7b — it touches margin and demand, which items 1-6 left largely
// alone, and it deserves the same care the supply side got rather than being crammed in here.

// ---------------------------------------------------------------- the chain
// The Bible's seven tiers. Backward tiers are live in 7a; forward tiers are DEFINED here (so the
// ladder is visible and the data model is settled) but not yet buildable — see forwardTier below.
const CHAIN_TIERS = {
  rawMaterials: {
    id: 'rawMaterials', order: 0, direction: 'backward',
    name: { en: 'Forestry & Timber', es: 'Silvicultura y Madera' },
    desc: {
      en: 'Standing timber and the right to cut it. The furthest upstream anyone in this industry can go.',
      es: 'Madera en pie y el derecho a cortarla. Lo más arriba que alguien en esta industria puede llegar.',
    },
    // Obligation-with-capability: every tier carries a permanent monthly overhead.
    monthlyOverhead: 6,
    buildCost: 180,
    // What owning it actually does.
    materialCostReduction: 0.20,
    disruptionImmunity: true,
    requiresTier: 'processing', // you cannot buy the forest before you own the mill
  },
  processing: {
    id: 'processing', order: 1, direction: 'backward',
    name: { en: 'Lumber Processing', es: 'Procesamiento de Madera' },
    desc: {
      en: 'Mills that turn logs into graded, dimensioned stock. The first step most manufacturers ever take upstream.',
      es: 'Aserraderos que convierten troncos en madera clasificada y dimensionada. El primer paso río arriba que da la mayoría.',
    },
    monthlyOverhead: 4,
    buildCost: 110,
    materialCostReduction: 0.15,
    disruptionImmunity: true,
    requiresTier: null, // reachable by acquiring a supplier, or built directly
  },
  components: {
    id: 'components', order: 2, direction: 'backward',
    name: { en: 'Component Manufacturing', es: 'Manufactura de Componentes' },
    desc: {
      en: 'Hardware, fittings, foam and textile — the parts that are not the frame but decide whether it works.',
      es: 'Herrajes, accesorios, espuma y textil — las partes que no son el armazón pero deciden si funciona.',
    },
    monthlyOverhead: 4,
    buildCost: 100,
    materialCostReduction: 0.15,
    disruptionImmunity: true,
    requiresTier: null,
  },
  // The player's own position, always owned and never purchasable — it is where every run starts.
  // Present in the data model so the chain is complete and the UI can render the full ladder with
  // the player's own place in it, rather than a gap between components and warehousing.
  manufacturing: {
    id: 'manufacturing', order: 3, direction: 'own', alwaysOwned: true,
    name: { en: 'Furniture Manufacturing', es: 'Manufactura de Muebles' },
    desc: {
      en: 'Where you already stand. Every run begins here, and everything else is a step up or down the chain from it.',
      es: 'Donde ya estás. Cada partida empieza aquí, y todo lo demás es un paso arriba o abajo en la cadena.',
    },
    monthlyOverhead: 0, buildCost: 0,
  },
  // ---- Item 7b territory. Defined so the ladder and data model are settled; not buildable yet.
  // ---- Forward tiers (7b). Each stands alone: the backward chain is genuinely sequential in a
  // way "warehouse -> truck -> shop" is not. Retail is the exception, and it is not gated so much
  // as PRICED — see retailDistributionCost.
  warehousing: {
    id: 'warehousing', order: 4, direction: 'forward',
    name: { en: 'Warehousing', es: 'Almacenamiento' },
    desc: {
      en: 'Your own storage, on your own terms. More stock, held cheaper — and stock that can go stale on your books rather than someone else\u2019s.',
      es: 'Tu propio almacenamiento, en tus propios términos. Más existencias, a menor costo — y existencias que pueden caducar en tus libros y no en los de otro.',
    },
    monthlyOverhead: 3, buildCost: 90, requiresTier: null,
  },
  distribution: {
    id: 'distribution', order: 5, direction: 'forward',
    name: { en: 'Distribution', es: 'Distribución' },
    desc: {
      en: 'Cut out the middleman between the plant and the buyer. You keep their cut, and you deliver directly — so you get paid sooner.',
      es: 'Elimina al intermediario entre la planta y el comprador. Te quedas con su margen y entregas directo — así te pagan más pronto.',
    },
    monthlyOverhead: 5, buildCost: 150, requiresTier: null,
  },
  retail: {
    id: 'retail', order: 6, direction: 'forward',
    name: { en: 'Retail', es: 'Menudeo' },
    desc: {
      en: 'Your own storefront: the highest margin, the heaviest overhead, and a shelf for anything you make. Something still has to move goods from the plant to the shop.',
      es: 'Tu propia tienda: el mayor margen, el mayor gasto fijo, y un estante para todo lo que fabricas. Algo todavía tiene que llevar el producto de la planta a la tienda.',
    },
    monthlyOverhead: 8, buildCost: 220, requiresTier: null,
  },
};
const BACKWARD_TIERS = Object.values(CHAIN_TIERS).filter(t => t.direction === 'backward').sort((a, b) => a.order - b.order);
function chainTier(id) { return CHAIN_TIERS[id] || null; }
function tierIsLive(id) { const t = chainTier(id); return !!t && !t.deferred; }

// Which tier a material sits in — this is what makes "acquiring a supplier grants its tier"
// (direction's option C) work without a second ownership concept.
const MATERIAL_TIER = {
  // Timber and sand are extracted then processed; metals, fibers and petrochemicals arrive as
  // refined inputs, which puts them a step further down the chain.
  timber: 'processing',
  sand: 'processing',
  metals: 'components',
  fibers: 'components',
  petrochemicals: 'components',
};
function tierForMaterial(material) { return MATERIAL_TIER[material] || 'components'; }

// ---------------------------------------------------------------- ownership
// Two routes in, per direction's option C: acquire a supplier (grants that supplier's tier), or
// build the tier directly once you hold the one below it.
function ownedTiers(game) {
  const owned = new Set(Object.keys(game.ownedTiers || {}));
  // Acquiring a supplier grants its material's tier — the on-ramp that reuses everything item 3
  // already built rather than standing up a parallel purchase flow.
  Object.keys(game.acquiredSuppliers || {}).forEach(id => {
    const sp = resolveSupplier(game, id);
    if (sp) owned.add(tierForMaterial(sp.material));
  });
  return owned;
}
function ownsTier(game, tierId) { return ownedTiers(game).has(tierId); }

function tierBuildable(game, tierId) {
  const tier = chainTier(tierId);
  if (!tier || tier.deferred) return { open: false, reason: 'deferred' };
  if (tier.alwaysOwned) return { open: false, reason: 'alwaysOwned' };
  if (ownsTier(game, tierId)) return { open: false, reason: 'owned' };
  if (tier.requiresTier && !ownsTier(game, tier.requiresTier)) {
    return { open: false, reason: 'needsTier', need: tier.requiresTier };
  }
  return { open: true };
}

// The obligation half of obligation-with-capability: every owned tier bills every month, forever.
function tierMothballed(game, tierId) {
  const rec = (game.ownedTiers || {})[tierId];
  return !!(rec && rec.mothballed);
}
// A tier that is warming up after reopening is not yet contributing either.
function tierProductive(game, tierId) {
  const rec = (game.ownedTiers || {})[tierId];
  if (!rec) return ownsTier(game, tierId); // granted via supplier acquisition: always live
  return !rec.mothballed && !(rec.warmupMonthsLeft > 0);
}
function tierMonthlyOverhead(game) {
  let total = 0;
  ownedTiers(game).forEach(id => {
    const tier = chainTier(id);
    // A closed plant costs nothing to hold — that is the entire point of closing it.
    if (tier && !tierMothballed(game, id)) total += tier.monthlyOverhead;
  });
  return total;
}

// The capability half: materials from a tier you own cost less and cannot be disrupted.
function tierMaterialRelief(game, material) {
  const tierId = tierForMaterial(material);
  // Closed or still warming up = no capability. You cannot save on materials from a plant that
  // is not running, which is the cost side of the mothballing decision.
  if (!ownsTier(game, tierId) || !tierProductive(game, tierId)) return { costReduction: 0, immune: false };
  const tier = chainTier(tierId);
  return { costReduction: tier.materialCostReduction || 0, immune: !!tier.disruptionImmunity };
}

// ---------------------------------------------------------------- integration periods
// Direction's answer to Q4: N months of underperformance, slightly eased by Agility. Legible and
// felt, and it makes the TIMING of an acquisition a real decision — don't buy right before you
// need the capacity.
const INTEGRATION_BASE_MONTHS = 4;
const INTEGRATION_DRAG = 0.25; // capacity penalty while integrating

function integrationMonthsFor(game) {
  // Agility shortens it, but never to nothing — integration is work, not a stat check.
  const agility = (game.stats && game.stats.agility) || 0;
  return Math.max(2, INTEGRATION_BASE_MONTHS - Math.floor(agility / 3));
}
function activeIntegrations(game) {
  return (game.integrations || []).filter(i => i.monthsLeft > 0);
}
function integrationDrag(game) {
  return activeIntegrations(game).length ? INTEGRATION_DRAG : 0;
}

// ---------------------------------------------------------------- rival acquisition
// Bible §10: an acquisition must fundamentally change the company, not add 10% revenue. Direction
// was explicit about what transfers — supply chain, products, people, market position, AND their
// debts and obligations, with the option to sell assets if you cannot carry all of it.
const RIVAL_ACQUISITION_DISPOSITION_MAX = 20; // a rival that hates you will not sell at any price

function rivalAcquisitionCost(rival) {
  // Priced off what they're actually worth, same shape as the valuation shown in the Companies tab.
  return Math.round((rival.strength * 4 + rival.marketPosition * 6) * (1 + (rival.runsSeen || 1) * 0.05));
}

function rivalAcquirable(game, rival) {
  if (!rival) return { open: false, reason: 'unknown' };
  if (!ownsAnyBackwardTier(game) && !(game.completed && game.completed.mfgBackwardIntegration)) {
    return { open: false, reason: 'needsIntegrationCapability' };
  }
  if (deriveDisposition(rival) < -RIVAL_ACQUISITION_DISPOSITION_MAX) {
    return { open: false, reason: 'hostile' };
  }
  // You cannot buy someone bigger than you — market position is the proxy for "can you swallow it".
  if (rival.marketPosition > (game.marketPosition || 0) * 1.2) {
    return { open: false, reason: 'tooBig' };
  }
  return { open: true, cost: rivalAcquisitionCost(rival) };
}
function ownsAnyBackwardTier(game) {
  return BACKWARD_TIERS.some(t => ownsTier(game, t.id));
}

// What the player inherits. Products specifically: acquiring a rival is the LEGITIMATE route past
// an adjacency block (Bible §A.5.3 names acquisition as one of only two ways in), which closes a
// loop opened all the way back in item 1.
function inheritedProductFrom(rival, game, industry) {
  if (!industry || !industry.productCatalog) return null;
  const owned = new Set(Object.keys(game.products || {}));
  const profile = companyResourceProfile(game, industry);
  // Prefer something the company could NOT have built for itself — that is the point of buying.
  const blocked = industry.productCatalog
    .filter(p => !owned.has(p.id))
    .filter(p => productAdjacency(p, profile).band.id === 'unrelated');
  if (blocked.length) return blocked[Math.floor(Math.random() * blocked.length)];
  const any = industry.productCatalog.filter(p => !owned.has(p.id));
  return any.length ? any[Math.floor(Math.random() * any.length)] : null;
}

// Their obligations come with them. A rival carries an implied debt load scaled to their size —
// buying a company means buying what it owes.
function inheritedDebtFrom(rival) {
  const principal = Math.round(rival.strength * 1.5 + rival.marketPosition * 2);
  if (principal < 15) return null;
  return {
    instrumentId: 'bankLoan',
    principal,
    remaining: Math.round(principal * 1.08 * 10) / 10,
    monthlyPayment: debtMonthlyPayment(principal, 0.08, 18),
    monthsLeft: 18,
    inherited: true,
  };
}

// Sell-off: the escape valve when the obligations turn out to be more than the company can carry.
// Deliberately lossy — a forced sale never recovers what the asset was worth.
const ASSET_SELLOFF_RECOVERY = 0.55;
function selloffValue(game, tierId) {
  const tier = chainTier(tierId);
  return tier ? Math.round(tier.buildCost * ASSET_SELLOFF_RECOVERY) : 0;
}

// ============================== FORWARD INTEGRATION (7b) ==============================
// Bible §C.1 downstream half, build order item 7b. The backward chain (7a) was about capacity,
// cost and risk. This half is about MARGIN and DEMAND — the two things items 1-6 deliberately
// left alone — so each tier lands on a different system rather than being three sizes of the
// same dial.
//
//   Warehousing  → hold more, cheaper        (inventory strategy, item 3)
//   Distribution → cut the middleman, get paid sooner (margin + receivable terms, item 5)
//   Retail       → sell direct, to anyone     (margin + the channel gate itself, item 1)

// ---------------------------------------------------------------- warehousing
// Owning storage changes the inventory trade rather than sidestepping it: more buffer AND less
// holding cost, because you are not renting the space. The obligation is obsolescence — stock you
// own can go stale, which a renter never had to care about.
const WAREHOUSE_BUFFER_BONUS = 1;        // extra months of disruption absorbed
const WAREHOUSE_HOLDING_RELIEF = 0.35;   // holding cost reduction
const OBSOLESCENCE_RISK_PER_MONTH = 0.06; // chance stock goes stale when nothing needs it

function warehouseBufferBonus(game) { return ownsTier(game, 'warehousing') ? WAREHOUSE_BUFFER_BONUS : 0; }
function warehouseHoldingRelief(game) { return ownsTier(game, 'warehousing') ? WAREHOUSE_HOLDING_RELIEF : 0; }

// ---------------------------------------------------------------- distribution
// Two benefits, both real: you keep the distributor's cut, and you deliver directly so you get
// paid sooner. The second is why a B2B-heavy company gets far more from this tier than a B2C one
// — B2B is where the receivables actually live.
const DISTRIBUTION_MARGIN_MULT = 1.15;
const DISTRIBUTION_TERMS_MONTHS = 1; // net-30 instead of the net-60 default

// ---------------------------------------------------------------- retail
// The headline: your own storefront. Highest margin, heaviest overhead, and it can sell a product
// that has no other open channel — the forward mirror of how acquisition bypasses adjacency.
const RETAIL_MARGIN_MULT = 1.30;
const RETAIL_COLOCATED_MARGIN_MULT = 1.18; // a shop attached to the plant reaches fewer people
const RETAIL_CHANNEL = 'ownRetail';
// Deliberately MODEST and uniform. Every product becomes viable through your own shop, but none
// becomes optimal that way — so a stranded product is rescued without flattening appealSegments,
// which is the whole segment design from item 1.
const RETAIL_CHANNEL_APPEAL = 0.35;

// Something has to move product from the plant to the shop. Owning Distribution covers it; being
// CO-LOCATED with production makes it nearly free; otherwise you pay a third party every month.
const THIRD_PARTY_DISTRIBUTION_FEE = 7;
const COLOCATED_DISTRIBUTION_FEE = 1;

function retailMode(game) {
  const owned = (game.ownedTiers || {}).retail;
  return owned && owned.colocated ? 'colocated' : 'standalone';
}
// The recurring cost of getting goods to your own shelves.
function retailDistributionCost(game) {
  if (!ownsTier(game, 'retail')) return 0;
  if (ownsTier(game, 'distribution')) return 0;       // you own the trucks
  if (retailMode(game) === 'colocated') return COLOCATED_DISTRIBUTION_FEE; // walk it across the yard
  return THIRD_PARTY_DISTRIBUTION_FEE;                 // somebody else's trucks, every month
}

// ---------------------------------------------------------------- composition
// Multiplier chain rather than a replaced constant — the same discipline that kept capacity and
// demand intact when products landed in item 1. marginPerUnit stays the industry constant it was.
function forwardMarginMultiplier(game) {
  let mult = 1;
  if (ownsTier(game, 'distribution')) mult *= DISTRIBUTION_MARGIN_MULT;
  if (ownsTier(game, 'retail')) {
    mult *= retailMode(game) === 'colocated' ? RETAIL_COLOCATED_MARGIN_MULT : RETAIL_MARGIN_MULT;
  }
  return mult;
}

// Receivable terms shorten when you deliver your own goods.
function receivableTermsFor(game) {
  return ownsTier(game, 'distribution') ? DISTRIBUTION_TERMS_MONTHS : RECEIVABLE_TERMS_MONTHS;
}

// Whether a product can reach your own shelves, and how much appeal it has there.
function retailChannelAppeal(game, product) {
  if (!ownsTier(game, 'retail')) return 0;
  // Uniform across the catalogue on purpose — your shop will stock anything you make.
  return RETAIL_CHANNEL_APPEAL;
}

// Direction on Q1: retail is selling directly to consumers, so it settles as CASH, distinct from
// B2B accounts receivable. This returns the share of demand flowing through your own shelves,
// which the cash/receivable split in endMonth treats as immediate.
function retailCashShare(game, industry) {
  if (!ownsTier(game, 'retail') || !industry || !industry.productCatalog) return 0;
  let retail = 0, total = 0;
  Object.values(game.products || {}).forEach(inst => {
    if (inst.phase !== 'launched') return;
    const def = PRODUCT_BY_ID[inst.productId];
    if (!def) return;
    const contribution = productDemandContribution(inst, def, game);
    total += contribution;
    // The retail slice of THIS product's demand, proportional to retail appeal against its other
    // open channels.
    const otherAppeal = (inst.channelsOpened || [])
      .reduce((sum, seg) => sum + (def.appealSegments[seg] || 0), 0);
    const retailAppeal = retailChannelAppeal(game, def);
    if (retailAppeal > 0) retail += contribution * (retailAppeal / Math.max(0.01, otherAppeal + retailAppeal));
  });
  return total > 0 ? clamp(retail / total, 0, 1) : 0;
}

// ---------------------------------------------------------------- obligations
// Retail is consumer-facing, so quality problems reach customers directly rather than through a
// B2B buyer who absorbs them. This makes the quality chain built in items 2-3 matter much more
// once you own shelves — a late-game tightening rather than a new system.
const RETAIL_REPUTATION_EXPOSURE = 1.6;
function reputationExposureMultiplier(game) {
  return ownsTier(game, 'retail') ? RETAIL_REPUTATION_EXPOSURE : 1;
}

// Warehousing's obligation: stock you own can go stale when nothing needs it.
function obsolescenceRisk(game) {
  if (!ownsTier(game, 'warehousing')) return 0;
  const strat = inventoryStrategy(game.inventoryStrategy);
  return OBSOLESCENCE_RISK_PER_MONTH * strat.workingCapitalMult;
}

