// Tag → category. A project whose tag isn't claimed by anyone falls into Short-Term, since that
// section is the "everything else you can do now" bucket by design.
const TAG_TO_CATEGORY = (() => {
  const map = {};
  Object.values(PROJECT_CATEGORIES).forEach(cat => cat.tags.forEach(tag => { map[tag] = cat.id; }));
  return map;
})();
function projectCategory(project) {
  return TAG_TO_CATEGORY[project.tag] || 'shortTerm';
}

