// ---------------------------------------------------------------- product families (§10)
// Families let hundreds of products share one economic backbone rather than each being its own
// tree. A family declares what its members hold in common; individual products vary within it.
const PRODUCT_FAMILIES = {
  furniture: {
    id: 'furniture', name: { en: 'Furniture', es: 'Muebles' },
    sharedCapabilities: ['assembly', 'finishing'],
    sharedChannels: ['independentRetailers', 'nationalRetailChains', 'hospitalityCommercial'],
  },
  tools: {
    id: 'tools', name: { en: 'Tools', es: 'Herramientas' },
    sharedCapabilities: ['machining', 'assembly', 'qualityTesting'],
    sharedChannels: ['independentRetailers', 'developers', 'nationalRetailChains'],
  },
  electronics: {
    id: 'electronics', name: { en: 'Electronics', es: 'Electrónica' },
    sharedCapabilities: ['electronicsAssembly', 'qualityTesting'],
    sharedChannels: ['nationalRetailChains', 'independentRetailers'],
  },
};

// ============================== QUERY API ==============================
// Everything below is ENGINE. None of it names a specific material — adding content must never
// require editing anything here.

function econEntity(id) { return ECONOMY[id] || null; }
function econEntitiesAtTier(tierId) { return Object.values(ECONOMY).filter(e => e.tier === tierId); }
function econAllIds() { return Object.keys(ECONOMY); }

// Every input a recipe can take, flattened with its flavour attached.
function recipeInputs(entityOrId, opts) {
  const e = typeof entityOrId === 'string' ? econEntity(entityOrId) : entityOrId;
  if (!e || !e.recipe) return [];
  const include = opts || { primary: true, substitute: true, optional: true };
  const out = [];
  if (include.primary !== false) (e.recipe.primary || []).forEach(i => out.push({ ...i, flavour: 'primary' }));
  if (include.substitute !== false) (e.recipe.substitute || []).forEach(i => out.push({ ...i, flavour: 'substitute' }));
  if (include.optional !== false) (e.recipe.optional || []).forEach(i => out.push({ ...i, flavour: 'optional' }));
  return out;
}

// §7's requirement: a byproduct must not hardcode a single consumer. Consumers are DERIVED by
// asking which recipes can take it — so adding a new consumer is adding a recipe, nothing else.
function consumersOf(entityId) {
  return Object.values(ECONOMY)
    .filter(e => recipeInputs(e).some(i => i.id === entityId))
    .map(e => e.id);
}
function producersOf(entityId) {
  return Object.values(ECONOMY).filter(e => {
    if (e.id === entityId) return false;
    return (e.recipe && (e.recipe.byproducts || []).some(b => b.id === entityId));
  }).map(e => e.id).concat(ECONOMY[entityId] && ECONOMY[entityId].recipe ? [entityId] : []);
}

// What a company can actually build, given what it can DO and what it can GET. This is §5's
// "capabilities + materials → production options" as one function.
function capabilitiesOf(equipmentIds) {
  const caps = new Set();
  (equipmentIds || []).forEach(id => (EQUIPMENT_CAPABILITIES[id] || []).forEach(c => caps.add(c)));
  return caps;
}
function missingCapabilities(entityId, haveCaps) {
  const e = econEntity(entityId);
  if (!e || !e.recipe) return [];
  return (e.recipe.capabilities || []).filter(c => !haveCaps.has(c));
}
function missingInputs(entityId, haveIds) {
  const e = econEntity(entityId);
  if (!e || !e.recipe) return [];
  const have = new Set(haveIds || []);
  // A primary input is satisfied by itself OR by any declared substitute — that is the whole
  // point of substitution (§25), and it is why "what am I missing" is not just a set difference.
  const subs = new Set((e.recipe.substitute || []).map(i => i.id));
  return (e.recipe.primary || [])
    .filter(i => !have.has(i.id) && ![...subs].some(sid => have.has(sid)))
    .map(i => i.id);
}
function canProduce(entityId, haveIds, haveCaps) {
  return missingInputs(entityId, haveIds).length === 0
    && missingCapabilities(entityId, haveCaps).length === 0;
}
function productionOptions(haveIds, haveCaps) {
  return econAllIds().filter(id => ECONOMY[id].recipe && canProduce(id, haveIds, haveCaps));
}

// ---------------------------------------------------------------- graph distance (Q3)
// Adjacency now reads GRAPH DISTANCE rather than tag-set overlap: how many production hops apart
// two things are. This is what lets cross-branch finished products bridge the branches naturally
// — Office Chair is close to both a metal company and a textile company, so both have a route in.
function econDistance(fromId, toId, maxDepth) {
  if (fromId === toId) return 0;
  const limit = maxDepth || 6;
  const seen = new Set([fromId]);
  let frontier = [fromId];
  for (let depth = 1; depth <= limit; depth++) {
    const next = [];
    frontier.forEach(id => {
      // Walk both directions: what this feeds, and what feeds this.
      consumersOf(id).forEach(c => { if (!seen.has(c)) { seen.add(c); next.push(c); } });
      recipeInputs(id).forEach(i => { if (!seen.has(i.id)) { seen.add(i.id); next.push(i.id); } });
      (ECONOMY[id] && ECONOMY[id].recipe ? (ECONOMY[id].recipe.byproducts || []) : [])
        .forEach(b => { if (!seen.has(b.id)) { seen.add(b.id); next.push(b.id); } });
    });
    if (next.includes(toId)) return depth;
    if (!next.length) break;
    frontier = next;
  }
  return Infinity;
}

// Which entities connect two otherwise-separate branches — the concrete answer to "what should I
// build to get from where I am to where they are?"
// Everything that feeds into an entity, transitively — its whole upstream supply chain.
function upstreamOf(entityId, depth) {
  const limit = depth || 8;
  const seen = new Set();
  const walk = (id, d) => {
    if (d > limit) return;
    recipeInputs(id).forEach(i => {
      if (seen.has(i.id)) return;
      seen.add(i.id);
      walk(i.id, d + 1);
    });
  };
  walk(entityId, 0);
  return seen;
}

// A bridge is an entity whose own supply chain draws on BOTH branches — the concrete answer to
// "what could I build that would connect what I make to what they make?". Precise by
// construction: it asks what the recipe actually needs, not what happens to be nearby.
function bridgesBetween(aId, bId) {
  return Object.values(ECONOMY).filter(e => {
    if (!e.recipe || e.id === aId || e.id === bId) return false;
    const up = upstreamOf(e.id);
    return up.has(aId) && up.has(bId);
  }).map(e => e.id);
}

// ---------------------------------------------------------------- market model (Q4)
// Deliberately the simplest thing that produces §27's opportunities: every entity carries supply,
// demand and a base price; price drifts from the ratio; production moves both sides; and the
// player can see all of it. No clearing engine, and it can evolve into one.
const PRICE_ELASTICITY = 0.6;      // how hard price responds to imbalance
const PRICE_BAND = { min: 0.4, max: 2.6 }; // nothing becomes free or infinite

function makeMarket() {
  const m = {};
  econAllIds().forEach(id => {
    m[id] = { supply: 100, demand: 100, price: ECONOMY[id].basePrice };
  });
  return m;
}
function marketPrice(market, entityId) {
  const e = ECONOMY[entityId];
  const cell = market[entityId];
  if (!e || !cell) return 0;
  const ratio = cell.demand / Math.max(1, cell.supply);
  const mult = clamp(Math.pow(ratio, PRICE_ELASTICITY), PRICE_BAND.min, PRICE_BAND.max);
  return Math.round(e.basePrice * mult * 10) / 10;
}
// A producer adds supply of its output and demand for its inputs — the whole cascade in one step.
function applyProduction(market, entityId, volume) {
  const e = ECONOMY[entityId];
  if (!e || !e.recipe || !market[entityId]) return market;
  market[entityId].supply += volume;
  (e.recipe.primary || []).forEach(i => {
    if (market[i.id]) market[i.id].demand += volume * i.qty;
  });
  (e.recipe.byproducts || []).forEach(b => {
    if (market[b.id]) market[b.id].supply += volume * b.rate;
  });
  return market;
}
function applyConsumption(market, entityId, volume) {
  if (market[entityId]) market[entityId].demand += volume;
  return market;
}
function recomputePrices(market) {
  Object.keys(market).forEach(id => { market[id].price = marketPrice(market, id); });
  return market;
}

// §27: the economy must be something the player can STUDY. These are the questions worth asking.
function marketBottlenecks(market, threshold) {
  const t = threshold || 1.3;
  return Object.keys(market)
    .map(id => ({ id, ratio: market[id].demand / Math.max(1, market[id].supply), price: market[id].price }))
    .filter(x => x.ratio >= t)
    .sort((a, b) => b.ratio - a.ratio);
}
function marketGluts(market, threshold) {
  const t = threshold || 0.75;
  return Object.keys(market)
    .map(id => ({ id, ratio: market[id].demand / Math.max(1, market[id].supply), price: market[id].price }))
    .filter(x => x.ratio <= t)
    .sort((a, b) => a.ratio - b.ratio);
}
// Underused waste: a byproduct in surplus that something out there could actually consume.
function underusedByproducts(market) {
  return econEntitiesAtTier('byproduct')
    .filter(b => consumersOf(b.id).length > 0)
    .map(b => ({ id: b.id, consumers: consumersOf(b.id), ratio: market[b.id] ? market[b.id].demand / Math.max(1, market[b.id].supply) : 1 }))
    .filter(x => x.ratio < 1)
    .sort((a, b) => a.ratio - b.ratio);
}
// The margin on making something at current prices — the core "could I make this cheaper?" query.
function productionMargin(market, entityId) {
  const e = ECONOMY[entityId];
  if (!e || !e.recipe) return null;
  const inputCost = (e.recipe.primary || []).reduce((sum, i) => sum + (market[i.id] ? market[i.id].price * i.qty : 0), 0);
  const revenue = market[entityId] ? market[entityId].price : e.basePrice;
  return { entityId, inputCost: Math.round(inputCost * 10) / 10, revenue, margin: Math.round((revenue - inputCost) * 10) / 10 };
}
function rankByMargin(market) {
  return econAllIds()
    .filter(id => ECONOMY[id].recipe)
    .map(id => productionMargin(market, id))
    .sort((a, b) => b.margin - a.margin);
}

// ---------------------------------------------------------------- validation
// The architecture is only cheap to extend if malformed content is caught immediately. This is
// what makes "adding a product should not require rewriting core logic" actually safe.
function validateEconomy() {
  const errors = [];
  Object.values(ECONOMY).forEach(e => {
    if (!ECON_TIERS[e.tier]) errors.push(`${e.id}: unknown tier ${e.tier}`);
    if (!e.name || !e.name.en || !e.name.es) errors.push(`${e.id}: missing bilingual name`);
    if (typeof e.basePrice !== 'number' || e.basePrice <= 0) errors.push(`${e.id}: invalid basePrice`);
    if (!e.recipe) return;
    recipeInputs(e).forEach(i => {
      if (!ECONOMY[i.id]) errors.push(`${e.id}: input ${i.id} does not exist`);
      if (!(i.qty > 0)) errors.push(`${e.id}: input ${i.id} has invalid qty`);
    });
    (e.recipe.byproducts || []).forEach(b => {
      if (!ECONOMY[b.id]) errors.push(`${e.id}: byproduct ${b.id} does not exist`);
      if (!(b.rate > 0)) errors.push(`${e.id}: byproduct ${b.id} has invalid rate`);
    });
    (e.recipe.capabilities || []).forEach(c => {
      if (!CAPABILITIES[c]) errors.push(`${e.id}: unknown capability ${c}`);
    });
    if (e.family && !PRODUCT_FAMILIES[e.family]) errors.push(`${e.id}: unknown family ${e.family}`);
  });
  return errors;
}

// ============================== PHASE 2 — MIGRATION ADAPTER ==============================
// The graph becomes the single source of truth. Rather than rewriting 22 call sites at once and
// leaving 1,473 tests dark through the largest refactor in the project, the legacy product shape
// is now GENERATED from graph entities. Existing consumers keep working unchanged; the adapter
// gets deleted opportunistically once things settle.

// Capability tier drives how hard something is to make — a recipe needing cncMachining is harder
// than one needing cutting. Derived rather than authored, so a new entity gets sensible numbers
// for free (§20: adding content must be cheap).
function econCapabilityLoad(entityId) {
  const e = econEntity(entityId);
  if (!e || !e.recipe) return 1;
  const caps = e.recipe.capabilities || [];
  if (!caps.length) return 1;
  return caps.reduce((max, c) => Math.max(max, (CAPABILITIES[c] || {}).tier || 1), 1);
}

// What a recipe's inputs cost at base prices — the honest floor under a product's material cost.
function econInputCost(entityId) {
  const e = econEntity(entityId);
  if (!e || !e.recipe) return 0;
  return (e.recipe.primary || []).reduce((sum, i) => {
    const input = econEntity(i.id);
    return sum + (input ? input.basePrice * i.qty : 0);
  }, 0);
}

// Consumer appeal. Upstream entities genuinely have no consumer segments — a sawmill does not
// sell to designConscious shoppers, it sells to component makers. So appeal comes from the
// product FAMILY for finished goods, and from B2B channels only for everything upstream.
// Direction's Q2 answer: the market sets price in both cases; this governs consumer VOLUME.
const ECON_TIER_B2B_APPEAL = {
  processedMaterial: { independentRetailers: 0.5, nationalRetailChains: 0.45, developers: 0.6, hospitalityCommercial: 0.35 },
  component:         { independentRetailers: 0.55, nationalRetailChains: 0.5, developers: 0.7, hospitalityCommercial: 0.4 },
  subAssembly:       { independentRetailers: 0.5, nationalRetailChains: 0.55, developers: 0.75, hospitalityCommercial: 0.45 },
};
function econAppealSegments(entityId) {
  const e = econEntity(entityId);
  if (!e) return {};
  if (e.tier === 'finishedProduct' && e.family && PRODUCT_FAMILIES[e.family]) {
    // A finished product inherits its family's channels — §10's whole point is that families
    // share customers, so this is where that becomes mechanical.
    const fam = PRODUCT_FAMILIES[e.family];
    const out = {};
    // B2B channels come straight from the family.
    fam.sharedChannels.filter(ch => B2B_SEGMENTS.includes(ch)).forEach(ch => { out[ch] = 0.55; });
    // CONSUMER appeal is DERIVED from each segment's philosophy against the product itself,
    // rather than being authored per product. A high-quality entity genuinely appeals to
    // Design-Led and Heritage; a cheap one to Everyday Value; a recycled one to Conscientious.
    // Doing it this way means a new consumer segment is a data entry, not an edit to every
    // product — and it is what lets Hospitality reuse this untouched.
    // Position on the mass<->premium line, from the product's own complexity and quality reach.
    // Using complexity as well as capability load matters: without it every finished product in
    // a family lands on an identical number and the segments stop discriminating at all.
    const load = econCapabilityLoad(entityId);
    const complexity = (e.recipe.primary || []).length + (e.recipe.capabilities || []).length;
    const premiumPos = clamp((load * 0.13) + (complexity * 0.06) - 0.35, -1, 1);
    // Sustainability fit comes from what this product is MADE OF, not what it is. A furniture
    // line running on recycled stock is what earns Conscientious — nobody sells scrap to
    // shoppers, so keying off the entity's own name would have measured the wrong thing.
    const inputs = (e.recipe.primary || []).concat(e.recipe.substitute || []);
    const greenInputs = inputs.filter(i => String(i.id).startsWith('recycled')).length;
    const greenShare = inputs.length ? greenInputs / inputs.length : 0;
    CONSUMER_SEGMENT_LIST.forEach(seg => {
      const premiumFit = 1 - Math.abs((seg.premiumVsMass / 100) - premiumPos) / 2;
      // A green-minded segment rewards recycled content; an indifferent one simply ignores it.
      const greenFit = 0.5 + (greenShare - 0.5) * (seg.sustainability / 100);
      const fit = clamp(premiumFit * 0.72 + greenFit * 0.28, 0.05, 0.95);
      if (fit > 0.25) out[seg.id] = Math.round(fit * 100) / 100;
    });
    return out;
  }
  return { ...(ECON_TIER_B2B_APPEAL[e.tier] || ECON_TIER_B2B_APPEAL.processedMaterial) };
}

// The adapter proper: a graph entity expressed in the shape the live product system expects.
// Everything is DERIVED — adding an entity to ECONOMY makes it immediately playable.
function econToProduct(entityId) {
  const e = econEntity(entityId);
  if (!e || !e.recipe) return null;
  const load = econCapabilityLoad(entityId);
  const inputCost = econInputCost(entityId);
  const tierOrder = (ECON_TIERS[e.tier] || {}).order || 1;
  const primary = (e.recipe.primary || []).map(i => i.id);
  const byproduct = (e.recipe.byproducts || [])[0];

  return {
    id: e.id,
    name: e.name,
    blurb: e.blurb || {
      en: `Made from ${primary.map(id => (econEntity(id) || {}).name ? econEntity(id).name.en : id).join(' and ')}.`,
      es: `Hecho de ${primary.map(id => (econEntity(id) || {}).name ? econEntity(id).name.es : id).join(' y ')}.`,
    },
    materialCost: Math.max(4, Math.round(inputCost)),
    // Deeper in the chain and higher capability load both mean more work per unit.
    laborHours: Math.max(2, Math.round(load * 1.6 + tierOrder)),
    skillRequired: clamp(load, 1, 5),
    productionTime: clamp(1 + Math.floor(load / 2) + Math.floor(tierOrder / 2), 1, 6),
    complexity: clamp(load, 1, 5),
    // A more demanding process can reach higher quality — that is why you buy the better machine.
    // Quality is scored out of 100 (QUALITY_MAX). A 1-10 scale gave decay and premium-contract
    // bars nowhere to breathe: with ceilings of 5-7, a "0.4/month" decay was 8% of the whole
    // range per month, and a premium bar could not be expressed without exceeding the ceiling.
    // Range here is 45-95, so a commodity line and a precision line are genuinely far apart.
    qualityCeiling: clamp(35 + load * 12, QUALITY_FLOOR_MIN, QUALITY_MAX),
    defectRateBase: Math.round(clamp(0.04 + load * 0.015, 0.03, 0.14) * 1000) / 1000,
    // Simple things scale; intricate things do not.
    scalability: clamp(6 - load, 1, 5),
    priceFloor: Math.round(e.basePrice * 0.9),
    priceCeiling: Math.round(e.basePrice * 2.4),
    retoolCost: Math.max(4, Math.round(e.basePrice * 0.35)),
    byproduct: byproduct ? { id: byproduct.id, ratePerUnit: byproduct.rate } : null,
    resourceProfile: {
      materials: primary,
      // CAPABILITIES replace the old equipment-tag gate (direction's Q2 = A). One vocabulary.
      capabilities: e.recipe.capabilities || [],
      skills: e.recipe.capabilities || [],
      channels: Object.keys(econAppealSegments(entityId)),
    },
    appealSegments: econAppealSegments(entityId),
    econTier: e.tier,
    family: e.family || null,
  };
}

// ---------------------------------------------------------------- curated starting businesses
// Direction's Q1 = C: a curated set, not all 25 recipe-bearing entities. "What kind of business
// are you starting?" is a better question than "what will you make?", and twelve readable
// archetypes beats twenty-five undifferentiated ones — analysis paralysis is a real failure mode.
