const BUYER_BY_ID = BUYER_CHARACTERS.reduce((a, b) => { a[b.id] = b; return a; }, {});

// Which buyers would plausibly want what this company makes. A buyer purchases at one tier, so a
// sawmill meets converters and joiners while a furniture maker meets retailers and fit-out firms.
// ---------------------------------------------------------------- buyer discovery
// Direction: the player starts knowing a handful of buyers and finds the rest through play.
// Four routes in, each with a different cost and character:
//   1. COMMON KNOWLEDGE — one buyer per tier is simply public, so nobody is ever unable to sell
//   2. SOURCING — a deliberate, targeted action against a product line you actually make
//   3. TRADE SHOWS — a windowed opportunity: cheap and broad, but only while it is open
//   4. INTRODUCTIONS — an investor who rates you puts your name in front of someone
//
// Discovery is per-run. PERMANENT unlock is separate and comes from completing a contract, which
// is the meta-progression layer built alongside relationships.
function knownBuyers(game) {
  const out = new Set();
  BUYER_CHARACTERS.forEach(b => { if (b.commonKnowledge) out.add(b.id); });
  (game.discoveredBuyers || []).forEach(id => out.add(id));
  // A buyer you permanently unlocked in a past run is someone you already know.
  ((game.careerSnapshot || {}).unlockedBuyers || []).forEach(id => out.add(id));
  (game.unlockedBuyers || []).forEach(id => out.add(id));
  return out;
}
function buyerIsKnown(game, buyerId) { return knownBuyers(game).has(buyerId); }

// Who is still out there for a given product line — what a sourcing action can actually find.
function undiscoveredBuyersFor(game, productId) {
  const known = knownBuyers(game);
  return buyersForEntity(productId).filter(b => !known.has(b.id));
}

const SCOUT_BUYERS_COST = { ap: 1, presence: 2, capital: 8 };
const TRADE_SHOW_WINDOW_MONTHS = 3;
const TRADE_SHOW_MIN_GAP = 14;      // months; a trade show should feel like an occasion
const INTRODUCTION_MIN_STANDING = 55;

// An investor who thinks well of you will make an introduction — but only once each, so this is
// a finite benefit of a relationship rather than a renewable resource.
function introductionCandidates(game) {
  const standings = game.investorStandings || {};
  const used = game.usedIntroductions || [];
  return Object.keys(standings)
    .filter(id => standings[id] >= INTRODUCTION_MIN_STANDING && !used.includes(id));
}

// ---------------------------------------------------------------- buyer relationships
// Direction: relationships improve with completed contracts, decline with failed ones, and are
// used to negotiate better terms. They CARRY ACROSS RUNS — but only for buyers the player has
// permanently unlocked, which happens by completing a contract with them. Deliver once and that
// buyer, and your standing with them, becomes part of your career.
//
// The asymmetry is the point: standing is slow to build and fast to lose, the way a real
// commercial relationship behaves.
const BUYER_REL_PER_DELIVERY = 2;      // a month delivered in full
const BUYER_REL_ON_COMPLETION = 12;    // seeing a whole term through
const BUYER_REL_BREACH_BASE = -9;      // scaled by how badly you missed
const BUYER_REL_MIN = -100;
const BUYER_REL_MAX = 100;

const BUYER_RELATIONSHIP_BANDS = [
  { min: 70, id: 'preferred', label: { en: 'Preferred Supplier', es: 'Proveedor Preferente' },
    priceBonus: 0.14, qualityRelief: 0.10, volumeBonus: 0.25, termBonus: 6 },
  { min: 35, id: 'trusted', label: { en: 'Trusted', es: 'De Confianza' },
    priceBonus: 0.08, qualityRelief: 0.05, volumeBonus: 0.12, termBonus: 3 },
  { min: 10, id: 'known', label: { en: 'Known Quantity', es: 'Conocido' },
    priceBonus: 0.03, qualityRelief: 0.02, volumeBonus: 0.05, termBonus: 0 },
  { min: -14, id: 'neutral', label: { en: 'No History', es: 'Sin Historial' },
    priceBonus: 0, qualityRelief: 0, volumeBonus: 0, termBonus: 0 },
  { min: -49, id: 'strained', label: { en: 'Strained', es: 'Tensa' },
    priceBonus: -0.07, qualityRelief: -0.05, volumeBonus: -0.15, termBonus: 0 },
  { min: -100, id: 'burned', label: { en: 'Burned', es: 'Quemada' },
    priceBonus: -0.15, qualityRelief: -0.10, volumeBonus: -0.35, termBonus: 0 },
];
function buyerRelationshipBand(v) {
  const n = typeof v === 'number' ? v : 0;
  return BUYER_RELATIONSHIP_BANDS.find(b => n >= b.min) || BUYER_RELATIONSHIP_BANDS[BUYER_RELATIONSHIP_BANDS.length - 1];
}

// Standing with a buyer = what carried in from previous runs, plus everything earned this run.
// Career standing only exists for unlocked buyers, so an un-unlocked buyer always starts fresh.
function buyerStanding(game, buyerId) {
  const carried = ((game.careerSnapshot || {}).buyerStandings || {})[buyerId] || 0;
  const thisRun = (game.buyerStandings || {})[buyerId] || 0;
  return clamp(carried + thisRun, BUYER_REL_MIN, BUYER_REL_MAX);
}

function adjustBuyerStanding(draft, buyerId, delta) {
  if (!buyerId || !delta) return;
  draft.buyerStandings = { ...(draft.buyerStandings || {}) };
  draft.buyerStandings[buyerId] = clamp((draft.buyerStandings[buyerId] || 0) + delta, BUYER_REL_MIN, BUYER_REL_MAX);
}

// A buyer becomes permanent career content the first time you see a contract through with them.
function unlockBuyer(draft, buyerId) {
  if (!buyerId) return false;
  const already = (draft.unlockedBuyers || []).includes(buyerId);
  if (already) return false;
  draft.unlockedBuyers = [...(draft.unlockedBuyers || []), buyerId];
  return true;
}
function buyerIsUnlocked(game, buyerId) {
  return ((game.careerSnapshot || {}).unlockedBuyers || []).includes(buyerId)
    || (game.unlockedBuyers || []).includes(buyerId);
}

// A buyer declares `buys`: the TIERS it purchases at, optionally narrowed by `buysOnly` /
// `buysNot` to specific lines. A national retailer takes several finished products; a diversified
// manufacturer takes processed material AND components. A single-tier field could express
// neither, so a large account looked identical to a specialist.
function buyerTiers(b) {
  if (Array.isArray(b.buys)) return b.buys;
  return b.buysTier ? [b.buysTier] : [];      // tolerate the older single-tier shape
}
function buyerWants(b, entityId) {
  const e = econEntity(entityId);
  if (!e) return false;
  if (!buyerTiers(b).includes(e.tier)) return false;
  if (Array.isArray(b.buysOnly) && b.buysOnly.length) return b.buysOnly.includes(entityId);
  if (Array.isArray(b.buysNot) && b.buysNot.includes(entityId)) return false;
  return true;
}
function buyersForEntity(entityId) {
  return BUYER_CHARACTERS.filter(b => buyerWants(b, entityId));
}
// Everything a given buyer will take — so the UI can show that a big account covers several of
// the player's lines at once rather than implying one buyer per product.
function entitiesBuyerWants(buyerId) {
  const b = BUYER_BY_ID[buyerId];
  if (!b) return [];
  return Object.keys(ECONOMY).filter(id => buyerWants(b, id));
}

function companyResourceProfile(game, industry) {
  const profile = { materials: new Set(), equipment: new Set(), capabilities: new Set(), skills: new Set(), channels: new Set() };
  if (!industry) return profile;

  // REAL equipment ownership for the three PHYSICAL tags, not a completed-project stub anymore
  // (build order item 2). A machine that has failed and is sitting in downtime still COUNTS
  // here — "do we own a CNC" and "is the CNC running this month" are different questions; this
  // answers the first one. The second is what equipmentCapacityFactor checks, separately, inside
  // capacity derivation.
  Object.values(game.equipment || {}).forEach(eq => {
    profile.equipment.add(eq.originTag);
    // Capabilities the company can actually perform, from the machines it owns.
    (EQUIPMENT_CAPABILITIES[eq.id] || []).forEach(c => profile.capabilities.add(c));
  });

  // Quality stays on the completed-project-tag stub — it's QC-process investment (a system, not
  // a machine or a material relationship), and not part of this build-order item.
  const completedTags = new Set(
    (industry.content.projects || [])
      .filter(p => game.completed && game.completed[p.id])
      .map(p => p.tag)
  );
  if (completedTags.has('Quality')) profile.equipment.add('Quality');

  // 'Sourcing' as an equipment-gate tag now means the company has an ACTUAL supplier
  // relationship, not that it once completed a Sourcing-tagged project — build order item 3's
  // upgrade to the same tag two authored products (cabinetry, flatPackSideTable) already
  // required. A company with zero contracts and zero acquired suppliers genuinely has no
  // sourcing capability yet, which is the honest state of things now that suppliers are real.
  const hasAnySourcing = Object.entries(game.supplierContracts || {}).some(([, c]) => c.active !== false)
    || Object.keys(game.acquiredSuppliers || {}).length > 0;
  if (hasAnySourcing) profile.equipment.add('Sourcing');

  // Materials come from REAL supplier contracts (or acquired/owned suppliers), not from products
  // that happened to reach Production — that was circular (the tag arrived FROM reaching
  // Production, but Production needed the tag to be reachable at all). See activeMaterialTags.
  activeMaterialTags(game).forEach(m => profile.materials.add(m));

  // Skills still accrue from products pushed to Production — real named-employee skills are
  // item 4's territory, not this one, so this stub is intentionally left as it was.
  Object.values((game.products || {})).forEach(inst => {
    if (!(PRODUCT_PHASE_ORDER_INDEX[inst.phase] >= PRODUCT_PHASE_ORDER_INDEX.production)) return;
    const def = PRODUCT_BY_ID[inst.productId];
    if (!def) return;
    (def.resourceProfile.skills || []).forEach(s => profile.skills.add(s));
  });

  // Channels accrue only from LAUNCHED products, and only the channels that launch actually
  // opened (B2B launch opens the B2B segments the product appeals to; B2C the B2C ones) — a
  // product still in testing has not opened any market channel.
  Object.values((game.products || {})).forEach(inst => {
    if (inst.phase !== 'launched') return;
    (inst.channelsOpened || []).forEach(c => profile.channels.add(c));
  });

  return profile;
}

// Pure scoring function: how adjacent is `product` to what the company can already do.
function productAdjacency(product, profile) {
  const req = product.resourceProfile;
  const breakdown = {
    materials: tagOverlap(req.materials, profile.materials),
    // Capabilities replaced the equipment-tag gate everywhere else (Q2=A); adjacency was the one
    // place still comparing the retired field, which is undefined on every adapter-generated
    // product — silently scoring every equipment term as zero rather than crashing.
    capabilities: tagOverlap(req.capabilities || req.equipment, profile.capabilities || profile.equipment),
    skills: tagOverlap(req.skills, profile.skills),
    channels: tagOverlap(req.channels, profile.channels),
  };
  const score = Object.entries(ADJACENCY_WEIGHTS)
    .reduce((sum, [key, w]) => sum + w * breakdown[key], 0);
  return { score, band: adjacencyBand(score), breakdown };
}

// ---------------------------------------------------------------- lifecycle
// idea -> prototype -> testing -> production -> launched -> (iterating is a modifier on
// launched, not a separate phase) -> retired. Pivot is implemented as retire-with-refund; see
// handlePivotProduct.
const PRODUCT_PHASE_ORDER = ['idea', 'prototype', 'testing', 'production', 'launched'];
const PRODUCT_PHASE_ORDER_INDEX = PRODUCT_PHASE_ORDER.reduce((a, p, i) => { a[p] = i; return a; }, {});

// Three intensities at every development phase — this IS the "how much to spend" decision the
// Bible insists on at every transition (§A.3). Lean is faster and cheaper but ships a worse
// product; thorough is the opposite. Standard is the anchor at 1.0 everywhere.
const INTENSITY_BLURB = {
  lean: { en: 'Cheap and quick. Lower quality ceiling, more defects.', es: 'Barato y rápido. Menor calidad, más defectos.' },
  standard: { en: 'The balanced option.', es: 'La opción equilibrada.' },
  thorough: { en: 'Slow and expensive. Best quality, fewest defects.', es: 'Lento y caro. Mejor calidad, menos defectos.' },
};
const PRODUCT_INTENSITIES = {
  lean: { costMult: 0.6, durationMult: 0.7, qualityMult: 0.75, defectMult: 1.35 },
  standard: { costMult: 1.0, durationMult: 1.0, qualityMult: 1.0, defectMult: 1.0 },
  thorough: { costMult: 1.6, durationMult: 1.4, qualityMult: 1.2, defectMult: 0.65 },
};

// Base cost/duration per phase, derived from the product's own DNA rather than being flat
// numbers — a complex, expensive-to-build product costs more to prototype and test than a
// simple one, which is the whole point of product attributes creating strategic weight.
function basePhaseCost(phase, product) {
  const m = product.materialCost, c = product.complexity;
  if (phase === 'prototype') return Math.round(m * 2.5 + c * 4);
  if (phase === 'testing') return Math.round(m * 1.5 + c * 3);
  if (phase === 'production') return Math.round(m * 5 + c * 6 + product.retoolCost);
  return 0;
}
function basePhaseDuration(phase, product) {
  const c = product.complexity;
  if (phase === 'prototype') return 1 + Math.ceil(c / 2);
  if (phase === 'testing') return 1 + Math.ceil(c / 3);
  if (phase === 'production') return 1 + Math.ceil(c / 2);
  return 1;
}

// What advancing the CURRENT phase of a product instance will cost, at a given intensity.
// Returned shape matches the {capital, presence, duration} the rest of the engine already uses
// for projects, so it can flow through the same cost-display and cost-check code paths.
function productPhaseCost(product, currentPhase, intensity, mfx) {
  const mult = PRODUCT_INTENSITIES[intensity] || PRODUCT_INTENSITIES.standard;
  // A rapid-development manager cuts what each phase costs to run.
  const devRelief = 1 - (mfx ? mfx.prototypeSpeed : 0);
  return {
    capital: Math.max(1, Math.round(basePhaseCost(currentPhase, product) * mult.costMult * devRelief)),
    presence: currentPhase === 'production' ? 2 : 1,
    duration: Math.max(1, Math.round(basePhaseDuration(currentPhase, product) * mult.durationMult)),
  };
}

// Equipment gate for entering Production specifically — the one phase that requires the company
// to actually be ABLE to build the thing, not just afford to try. Prototype/testing can proceed
// on a workbench; standing up real production cannot.
function missingEquipmentTags(product, profile) {
  // Capabilities, not tags: a product needs verbs the company can perform, and equipment is
  // what provides them. One vocabulary, one gate.
  const have = profile.capabilities instanceof Set ? profile.capabilities : new Set(profile.capabilities || []);
  return (product.resourceProfile.capabilities || []).filter(cap => !have.has(cap));
}

// Resolves the quality/defect outcome of Testing — the one phase whose intensity has a directly
// visible, permanent consequence on every unit the product ever sells. Locked in at the end of
// Testing so Iteration (a later, separate spend) is what improves on it, not a redo of Testing.
function resolveTestingOutcome(product, intensity, opsStatValue, precisionFloor, mfx) {
  const mult = PRODUCT_INTENSITIES[intensity] || PRODUCT_INTENSITIES.standard;
  const opsBonus = clamp((opsStatValue || 0) / 20, 0, 0.3); // a strong Operations stat helps, modestly, never dominates
  // Manager perks. Small-batch craft only helps products that are ACTUALLY small-batch (low
  // scalability) — the perk is named for a production philosophy, so it would be dishonest for
  // it to boost a mass-market flat-pack line. Both terms respect the ceiling clamp below.
  const managerQuality = (mfx && product.scalability <= 2) ? mfx.smallBatchQuality : 0;
  const managerDefect = mfx ? mfx.defectReduction : 0;
  // Clamped to the PRODUCT's own ceiling AND to what the equipment can actually deliver — Bible
  // §B.4's "effectiveQuality = min(qualityCeiling, equipment.precision, workerSkill)". Minimum,
  // not average: a worn or basic machine caps achievable quality no matter how thorough the
  // testing plan or how strong the Operations stat, same "no buying past a bad link" rule that
  // already governs the ceiling clamp itself. precisionFloor defaults to 10 (no constraint) so
  // Hospitality and any call site with no equipment context is unaffected.
  const ceiling = Math.min(product.qualityCeiling, precisionFloor != null ? precisionFloor : QUALITY_MAX);
  const quality = clamp(Math.round(ceiling * mult.qualityMult * (0.85 + opsBonus + managerQuality)), 1, ceiling);
  const defectRate = clamp(product.defectRateBase * mult.defectMult * (1 - opsBonus * 0.5) * (1 - managerDefect), 0, 0.5);
  return { quality, defectRate };
}

// ---------------------------------------------------------------- new-product eligibility
function productSlotLimit(stageId) { return PRODUCT_SLOTS_BY_STAGE[stageId] || 1; }

function activeProductCount(game) {
  return Object.values(game.products || {}).filter(p => p.phase !== 'retired').length;
}

// Candidates the player could START right now: not already active, adjacency computed against
// the company's current footprint. Unrelated products are still LISTED (so the player can see
// what is out of reach and why) but are not startable — the only routes past Unrelated are
// acquisition or a new-facility project, neither of which exists yet (future build-order items).
function availableNewProducts(game, industry) {
  if (!industry.productCatalog) return [];
  const profile = companyResourceProfile(game, industry);
  const started = new Set(Object.keys(game.products || {}));
  return industry.productCatalog
    .filter(p => !started.has(p.id))
    .map(p => ({ product: p, adjacency: productAdjacency(p, profile) }))
    .sort((a, b) => b.adjacency.score - a.adjacency.score);
}

// ---------------------------------------------------------------- derived capacity/demand
// The NEW, purely-derived term composed on top of the legacy accumulator — see the file banner.
// Recomputed fresh every call; nothing here is ever written back into draft.capacity/demand.

// How much a launched line actually produces. Tuned so a single line is a real business rather
// than a rounding error beside project-granted capacity — see PRODUCTION_SCALE.
const PRODUCTION_SCALE = 5;
// Demand scales alongside capacity — otherwise output is stranded and the player just eats
// shortfall reputation penalties for producing things nobody is modelled as wanting.
const DEMAND_SCALE = 5.5;

// A launched product's production capacity: how many units/month its own line can turn out,
// bounded by labor actually available, quality/defects, AND now the equipment actually running
// it (Bible §0.2: capacity = Σequipment(...) × laborAvailability × skillMatch − downtime). A
// machine in downtime after a failure drives this to zero for the product depending on it — the
// production-halt link in the maintenance cascade (§B.2) reaching all the way to revenue.
function productCapacityContribution(inst, product, game) {
  if (inst.phase !== 'launched') return 0;
  const laborFactor = Math.min(1, (game.laborPool || 0) / Math.max(1, product.laborHours));
  const qualityDrag = 1 - (inst.defectRate || 0) * 0.5; // defects eat finished-goods throughput
  const equipmentFactor = capabilityCapacityFactor(game, product.resourceProfile.capabilities);
  // Managers: a throughput manager lifts output; locations nobody is running drag it down. Both
  // compose multiplicatively with the equipment/labour/quality terms already here.
  const mfx = managerFx(game);
  // Integration drag: a company mid-acquisition underperforms until it beds in.
  const managerFactor = (1 + mfx.throughput) * (1 - unmanagedLocationDrag(game)) * (1 - integrationDrag(game));
  // PRODUCTION_SCALE: a launched line is a working factory. Without this the whole Products
  // system was decorative next to project-granted capacity.
  const base = (24 / Math.max(1, product.laborHours)) * product.scalability * PRODUCTION_SCALE;
  return Math.max(0, Math.round(base * laborFactor * qualityDrag * equipmentFactor * managerFactor));
}

// A launched product's market pull: appeal-weighted demand across whichever segments its launch
// actually opened, scaled by achieved quality against the ceiling and by company reputation.
// Deliberately NOT decayed the way legacy demand is — it tracks live company state every month
// rather than sliding toward it, which is the behavioural difference "derived" is meant to buy.
// ============================== BRAND (Phase D, step 3) ==============================
// Brand is TWO things, not one (direction's Q1):
//
//   STRENGTH  — how well known you are. 0-100. Built by marketing spend, eroded by neglect.
//   POSITION  — what you are known FOR. A vector on the same axes consumers judge by, so it can
//               be compared directly against a segment's philosophy.
//
// The distinction is the point: "our brand is weak" and "our brand is wrong for this product"
// are different problems with different fixes. A company famous for cheap goods has real
// strength and a position that actively repels Design-Led — being well known is not the same as
// being well regarded by the people you now want.
//
// Reputation acts as a SOFT CEILING (Q2). Being beloved by the public while shipping badly to
// your trade customers does not hold; the two are intertwined, and brand cannot drift far above
// the standing that supports it.

const BRAND_DECAY_PER_MONTH = 1.4;        // a leaky bucket by design — stop marketing and it falls
const BRAND_REPUTATION_SLACK = 18;        // how far brand may float above reputation before capping
const BRAND_POSITION_DRIFT = 0.12;        // how fast position moves toward what you actually do

// What you spend every month, as a standing policy rather than a repeated decision.
const MARKETING_POLICIES = {
  none:   { id: 'none',   spendMult: 0,    strengthGain: 0,   label: { en: 'None', es: 'Ninguno' },
            blurb: { en: 'Nothing. Brand decays from here.', es: 'Nada. La marca se deteriora desde aquí.' } },
  low:    { id: 'low',    spendMult: 0.35, strengthGain: 1.8, label: { en: 'Low', es: 'Bajo' },
            blurb: { en: 'A holding pattern. Roughly cancels decay.', es: 'Mantenimiento. Aproximadamente cancela el deterioro.' } },
  medium: { id: 'medium', spendMult: 0.8,  strengthGain: 3.4, label: { en: 'Medium', es: 'Medio' },
            blurb: { en: 'Real growth, at a real cost.', es: 'Crecimiento real, a un costo real.' } },
  high:   { id: 'high',   spendMult: 1.6,  strengthGain: 5.6, label: { en: 'High', es: 'Alto' },
            blurb: { en: 'Aggressive. Expensive, and it shows.', es: 'Agresivo. Caro, y se nota.' } },
};
function marketingPolicy(id) { return MARKETING_POLICIES[id] || MARKETING_POLICIES.none; }

// Targeting costs more per point of strength but moves POSITION decisively toward that segment.
const TARGETED_MARKETING_PREMIUM = 1.35;
const CAMPAIGN_AP_COST = 1;
const CAMPAIGN_STRENGTH_BURST = 9;
const CAMPAIGN_TARGETED_BURST = 13;

function brandStrength(game) { return clamp((game.brand && game.brand.strength) || 0, 0, 100); }
function brandPosition(game) {
  const p = (game.brand && game.brand.position) || {};
  return {
    premiumVsMass: p.premiumVsMass || 0,
    sustainability: p.sustainability || 0,
    noveltyVsHeritage: p.noveltyVsHeritage || 0,
  };
}

// Reputation as a soft ceiling. Brand may run a little ahead of standing — marketing genuinely
// works — but not indefinitely, and not without the substance to support it.
function brandCeiling(game) {
  return clamp((game.reputation || 0) + BRAND_REPUTATION_SLACK, 0, 100);
}

// How well what you are KNOWN FOR matches what a segment wants. Same axes, so this is a direct
// comparison rather than a translation.
function brandPositionFit(game, seg) {
  const pos = brandPosition(game);
  const d = (a, b) => 1 - Math.abs((a - b) / 200);   // both on -100..100
  const premium = d(pos.premiumVsMass, seg.premiumVsMass);
  const green = d(pos.sustainability, seg.sustainability);
  const novelty = d(pos.noveltyVsHeritage, seg.noveltyVsHeritage);
  return clamp(premium * 0.45 + green * 0.25 + novelty * 0.3, 0, 1);
}

// Where the company's brand SHOULD sit, given what it actually makes and sells. Position drifts
// toward this every month — you become known for what you do, not what you say.
function naturalBrandPosition(game, industry) {
  const launched = Object.values(game.products || {}).filter(i => i.phase === 'launched');
  if (!launched.length) return null;
  let premium = 0, green = 0, novelty = 0, n = 0;
  launched.forEach(inst => {
    const def = PRODUCT_BY_ID[inst.productId];
    if (!def) return;
    const ceiling = Math.max(1, def.qualityCeiling);
    const achieved = inst.quality != null ? inst.quality : ceiling;
    premium += ((achieved / ceiling) * 2 - 1) * 100;
    green += productGreenness(def, game) * 100;
    novelty += productNovelty(inst, game) * 100;
    n += 1;
  });
  if (!n) return null;
  return { premiumVsMass: premium / n, sustainability: green / n, noveltyVsHeritage: novelty / n };
}

// A public failure. Loud, per direction's Q5 — a recall should be a moment you remember, not a
// rounding error absorbed into the monthly drift.
const BRAND_SHOCKS = {
  recall:        { strength: -14, label: { en: 'Product Recall', es: 'Retiro de Producto' } },
  fire:          { strength: -7,  label: { en: 'Warehouse Fire', es: 'Incendio en el Almacén' } },
  breach:        { strength: -9,  label: { en: 'Contract Breach', es: 'Incumplimiento de Contrato' } },
  spoilage:      { strength: -5,  label: { en: 'Spoiled Stock', es: 'Existencias Echadas a Perder' } },
  safetyFailure: { strength: -11, label: { en: 'Safety Failure', es: 'Falla de Seguridad' } },
};
function applyBrandShock(draft, kind) {
  const shock = BRAND_SHOCKS[kind];
  if (!shock) return 0;
  draft.brand = { ...(draft.brand || { strength: 0, position: {} }) };
  draft.brand.strength = clamp((draft.brand.strength || 0) + shock.strength, 0, 100);
  return shock.strength;
}

// A founder who has done this before opens doors a first-timer cannot (direction's Q6). The
// COMPANY is new — this is the founder's name travelling, not the old company's.
const FOUNDER_REPUTATION_BRAND_BONUS = 6;
function startingBrandStrength(career) {
  const wins = (career && career.wins) || 0;
  if (wins <= 0) return 0;
  return Math.min(18, FOUNDER_REPUTATION_BRAND_BONUS + (wins - 1) * 4);
}

// ============================== CONSUMER DEMAND (Phase D, step 2) ==============================
// Segment demand is a FUNCTION, not a constant:
//
//   demand = size x philosophyFit x brandFactor x priceFactor x trendFactor
//
// brandFactor and trendFactor are stubbed neutral here — they arrive in steps 3 and 5. The shape
// is in place so those layers slot in without rewriting this.
//
// Written against generic product properties (quality, price, inputs, age) so Hospitality and
// later B2C-first industries can reuse it without a factory anywhere in sight.

// How novel a product still feels. Keyed to TIME ON MARKET, which gives the segments genuinely
// opposite trajectories for free: Trend Followers drift away from a line as it ages while
// Heritage Buyers warm to it. A player is therefore never optimal for everyone at once, and the
// same product changes audience over a run without any trend system existing yet.
const NOVELTY_HALF_LIFE = 18;   // months for a line to read as fully established
function productNovelty(inst, game) {
  const launched = inst.launchedMonth != null ? inst.launchedMonth : 0;
  const age = Math.max(0, (game.month || 0) - launched);
  // +1 brand new -> -1 fully established
  return clamp(1 - (age / NOVELTY_HALF_LIFE) * 2, -1, 1);
}

// Recycled content in what this product is MADE OF, plus credit for actually reusing your own
// byproducts. Keyed to inputs rather than to the product's own name — nobody sells scrap to
// shoppers, so the green story belongs to how a thing was made.
function productGreenness(def, game) {
  const e = econEntity(def.id);
  if (!e || !e.recipe) return 0;
  const inputs = (e.recipe.primary || []).concat(e.recipe.substitute || []);
  const recycled = inputs.filter(i => String(i.id).startsWith('recycled')).length;
  let share = inputs.length ? recycled / inputs.length : 0;
  // A standing 'reuse' policy on this line's own byproduct is a real sustainability practice.
  if (def.byproduct && game && effectiveByproductPolicy(game, def.byproduct.id) === 'reuse') share += 0.35;
  return clamp(share, 0, 1);
}

// How well a product matches what a segment actually wants, across all three consumer axes.
// Each axis is a distance, so a product can be a poor fit by being TOO premium as well as by
// being too cheap — which is what stops one "best" product dominating every segment.
function segmentFit(inst, def, seg, game) {
  const ceiling = Math.max(1, def.qualityCeiling);
  const achieved = inst.quality != null ? inst.quality : ceiling;
  // Position on mass<->premium comes from ACHIEVED quality, so investing in quality genuinely
  // moves which audience you are for, rather than being locked in at launch.
  const premiumPos = clamp((achieved / ceiling) * 2 - 1, -1, 1);
  // Exponent > 1 sharpens the curve: near-misses still sell, real mismatches genuinely do not.
  const AXIS_SHARPNESS = 2.1;
  const premiumFit = Math.pow(1 - Math.abs((seg.premiumVsMass / 100) - premiumPos) / 2, AXIS_SHARPNESS);

  const noveltyPos = productNovelty(inst, game);
  const noveltyFit = Math.pow(1 - Math.abs((seg.noveltyVsHeritage / 100) - noveltyPos) / 2, AXIS_SHARPNESS);

  // An indifferent segment neither rewards nor punishes; a green one cares a great deal.
  const green = productGreenness(def, game);
  const greenWeight = seg.sustainability / 100;
  const greenFit = 1 - greenWeight * (1 - green);

  // Weighted so premium position dominates, novelty matters, and sustainability is the
  // differentiator it should be for the one segment built around it.
  return clamp(premiumFit * 0.5 + noveltyFit * 0.28 + greenFit * 0.22, 0.02, 1);
}

// Price elasticity, per segment. Everyday Value collapses when you raise the price; Design-Led
// barely notices. Measured against the product's own price band rather than an absolute figure.
function segmentPriceFactor(price, def, seg) {
  const mid = (def.priceFloor + def.priceCeiling) / 2;
  if (mid <= 0) return 1;
  const over = (price - mid) / mid;          // +0.5 = half again over the middle of the band
  if (over <= 0) {
    // Cheaper than mid helps, and helps a price-sensitive segment most.
    return clamp(1 + (-over) * seg.priceSensitivity * 0.8, 1, 1.6);
  }
  return clamp(1 - over * seg.priceSensitivity * 1.3, 0.05, 1);
}

// Brand gates access AND scales demand, using BOTH halves of the meter:
//
//   STRENGTH decides whether a segment will consider you at all, and how loudly you register.
//   POSITION decides whether being known actually helps with THIS audience.
//
// A company famous for cheap goods (high strength, mass position) clears Design-Led's awareness
// gate and then converts badly, because what it is known for is wrong. That is the failure mode
// the two-meter design exists to express — and it is invisible in a single-number brand.
function segmentBrandFactor(seg, game) {
  const strength = brandStrength(game);
  if (strength < (seg.brandGate || 0)) return 0;   // will not consider a name they do not know
  const w = seg.brandWeight || 0;
  const awareness = (1 - w) + w * (strength / 100) * 1.5;
  // Position only matters to segments that care about brand at all — the mass market buys on
  // price regardless of what you stand for.
  const fit = brandPositionFit(game, seg);
  const positionEffect = 1 + (fit - 0.5) * w * 1.2;
  return clamp(awareness * positionEffect, 0.05, 1.8);
}

// Trends arrive in step 5. Neutral until then.
function segmentTrendFactor(seg, game) {
  const trends = (game && game.consumerTrends) || [];
  if (!trends.length) return 1;
  return clamp(trends.reduce((m, tr) => m * (1 + (tr.axisWeight || 0) * ((seg[tr.axis] || 0) / 100)), 1), 0.4, 2.2);
}

const CONSUMER_DEMAND_SCALE = 9;
function segmentDemand(inst, def, seg, game, price) {
  if (inst.phase !== 'launched') return 0;
  const p = price != null ? price
    : ((game.market && game.market[def.id]) ? game.market[def.id].price : def.priceCeiling);
  const raw = seg.size
    * segmentFit(inst, def, seg, game)
    * segmentBrandFactor(seg, game)
    * segmentPriceFactor(p, def, seg)
    * segmentTrendFactor(seg, game)
    * CONSUMER_DEMAND_SCALE * DEMAND_SCALE;
  return Math.max(0, Math.round(raw));
}

// Everything a consumer-facing line can sell this month, and to whom. The breakdown is the point:
// a player should be able to see WHICH audience is carrying them and which has walked away.
function consumerDemand(inst, def, game, price) {
  const bySegment = {};
  let total = 0;
  CONSUMER_SEGMENT_LIST.forEach(seg => {
    const d = segmentDemand(inst, def, seg, game, price);
    if (d > 0) bySegment[seg.id] = d;
    total += d;
  });
  return { total, bySegment };
}

function productDemandContribution(inst, product, game) {
  if (inst.phase !== 'launched') return 0;
  const qualityRatio = clamp((inst.quality || product.qualityCeiling) / Math.max(1, product.qualityCeiling), 0.4, 1.15);
  const repFactor = 0.6 + (game.reputation || 0) / 125;
  const segments = inst.channelsOpened || [];
  // Owning Retail puts a modest shelf under every product you make, including one with no other
  // open channel — the forward mirror of how acquisition bypasses adjacency. Deliberately modest:
  // a stranded product becomes viable, never optimal, so appealSegments still matters.
  const appeal = segments.reduce((sum, seg) => sum + (product.appealSegments[seg] || 0), 0)
    + retailChannelAppeal(game, product);
  // A channel-reach manager widens the market the same product can address.
  const base = appeal * 14 * DEMAND_SCALE * qualityRatio * repFactor * (1 + managerFx(game).channelReach);
  return Math.max(0, Math.round(base));
}

function totalProductCapacity(game, industry) {
  if (!industry.productCatalog) return 0;
  return Object.entries(game.products || {}).reduce((sum, [id, inst]) => {
    const def = PRODUCT_BY_ID[inst.productId];
    return def ? sum + productCapacityContribution(inst, def, game) : sum;
  }, 0);
}
function totalProductDemand(game, industry) {
  if (!industry.productCatalog) return 0;
  return Object.entries(game.products || {}).reduce((sum, [id, inst]) => {
    const def = PRODUCT_BY_ID[inst.productId];
    return def ? sum + productDemandContribution(inst, def, game) : sum;
  }, 0);
}

function scaledProjectCost(proj, stageId, teamStyle, scaling) {
  const costTable = (scaling && scaling.projectCostMult) || PROJECT_COST_MULT_BY_STAGE;
  const durTable = (scaling && scaling.projectDurationMult) || PROJECT_DURATION_MULT_BY_STAGE;
  const costMult = costTable[stageId] || 1;
  const durMult = durTable[stageId] || 1;
  const capital = Math.round((proj.cost.capital || 0) * costMult);
  const presence = proj.cost.presence || 0;
  let duration = Math.round(proj.duration * durMult);
  if (teamStyle === 'Operator') duration = Math.max(1, duration - 1);
  return { capital, presence, labor: proj.labor || 0, duration };
}
function scaleDeltas(deltas, mult) {
  const scaled = {};
  Object.entries(deltas).forEach(([k, v]) => {
    scaled[k] = k === 'statBonus' ? v : Math.round(v * mult);
  });
  return scaled;
}

// ============================== HELPERS ==============================
function clamp(n, min, max) { return Math.max(min, Math.min(max, n)); }
function roll(sides = 10) { return 1 + Math.floor(Math.random() * sides); }
function pick(arr) { return arr[Math.floor(Math.random() * arr.length)]; }
function randInt(min, max) { return min + Math.floor(Math.random() * (max - min + 1)); }
// Internal money unit is THOUSANDS (capital: 175 means $175,000). Rounding the display to the
// nearest whole thousand was destroying every sub-thousand distinction — a contract at 8.5 and
// one at 9.1 both rendered "$9k", which made advertised percentage discounts invisible and
// sometimes look inverted. Whole-dollar resolution is what lets percentages read honestly.
function fmtMoney(n) {
  const dollars = (n || 0) * 1000;
  const abs = Math.abs(dollars);
  // Compact only once the exact figure stops being useful and starts being unreadable.
  if (abs >= 1000000) return `$${(dollars / 1000000).toFixed(2)}M`;
  return `$${Math.round(dollars).toLocaleString('en-US')}`;
}
function fmtMoneySigned(n) {
  const sign = (n || 0) >= 0 ? '+' : '-';
  return `${sign}${fmtMoney(Math.abs(n || 0))}`;
}
function quarterOf(month) { return Math.ceil(month / 3); }

// Turns any deltas object (choice events, minor/major events, competitor attacks — anything that
// runs through applyDelta) into a short, signed, human-readable line like "-10 Reputation, +2
// Agility". This is what actually answers "did I make the right call?" instead of leaving the
// player to guess from the flavor text alone.
function deltaSummaryText(deltas, lang) {
  if (!deltas) return '';
  const t = (s) => translate(s, lang);
  const sign = (n) => (n > 0 ? '+' : '') + n;
  const bits = [];
  if (deltas.capital) bits.push(`${fmtMoneySigned(deltas.capital)} ${t('Capital')}`);
  if (deltas.revenuePerMonth) bits.push(`${fmtMoneySigned(deltas.revenuePerMonth)}/${t('mo')} ${t('Revenue')}`);
  if (deltas.reputation) bits.push(`${sign(deltas.reputation)} ${t('Reputation')}`);
  if (deltas.morale) bits.push(`${sign(deltas.morale)} ${t('Morale')}`);
  if (deltas.marketPosition) bits.push(`${sign(deltas.marketPosition)} ${t('Market Position')}`);
  if (deltas.boardConfidence) bits.push(`${sign(deltas.boardConfidence)} ${t('Board Confidence')}`);
  if (deltas.laborPool) bits.push(`${sign(deltas.laborPool)} ${t('Labor')}`);
  if (deltas.capacity) bits.push(`${sign(deltas.capacity)} ${t('Capacity')}`);
  if (deltas.demand) bits.push(`${sign(deltas.demand)} ${t('Demand')}`);
  if (deltas.burnReduction) bits.push(`${sign(-deltas.burnReduction)} ${t('Burn (permanent)')}`);
  if (deltas.companyValuation) bits.push(`${fmtMoneySigned(deltas.companyValuation)} ${t('Company Valuation')}`);
  if (deltas.statBonus) Object.entries(deltas.statBonus).forEach(([k, v]) => { if (v) bits.push(`${sign(v)} ${statLabel(k, lang)}`); });
  return bits.join(', ');
}

function applyDelta(draft, d = {}) {
  if (d.capital) draft.capital += d.capital;
  if (d.presence) draft.presence = clamp(draft.presence + d.presence, 0, 15);
  if (d.laborPool) draft.laborPool = Math.max(0, draft.laborPool + d.laborPool);
  if (d.reputation) draft.reputation = clamp(draft.reputation + d.reputation, 0, 100);
  if (d.morale) {
    let m = d.morale;
    if (m < 0 && draft.team && draft.team.style === 'Hustler') m -= 2;
    draft.morale = clamp(draft.morale + m, 0, 100);
  }
  if (d.marketPosition) draft.marketPosition = clamp(draft.marketPosition + d.marketPosition, 0, 100);
  if (d.revenuePerMonth) draft.revenuePerMonth = Math.max(0, draft.revenuePerMonth + d.revenuePerMonth);
  if (d.capacity) draft.capacity = Math.max(0, (draft.capacity || 0) + d.capacity);
  if (d.demand) draft.demand = Math.max(0, (draft.demand || 0) + d.demand);
  if (d.boardConfidence) draft.boardConfidence = clamp(draft.boardConfidence + d.boardConfidence, 0, 100);
  if (d.burnReduction) draft.burnReduction = (draft.burnReduction || 0) + d.burnReduction;
  if (d.statBonus) {
    Object.entries(d.statBonus).forEach(([k, v]) => {
      draft.stats[k] = clamp((draft.stats[k] || 0) + v, 0, 10);
    });
  }
}

function mkTicket(month, quarter, kind, tone, title, body) {
  return { id: `${month}-${kind}-${Math.random().toString(36).slice(2, 7)}`, month, quarter, kind, tone, title, body };
}

function denyTicket(prev, action, reason, lang) {
  const q = quarterOf(prev.month);
  const suffix = lang === 'es' ? ' — No Disponible' : ' — Unavailable';
  return { ...prev, log: [mkTicket(prev.month, q, 'action', 'bad', `${action}${suffix}`, reason), ...prev.log] };
}

function resolveEvent(draft, ev, atMonth, lang, industry) {
  const scaling = (industry && industry.scaling) || {};
  const stageId = stageOf(atMonth, industry && industry.stages).id;
  const threshold = 10 + ((scaling.eventThresholdBonus || EVENT_THRESHOLD_BONUS_BY_STAGE)[stageId] || 0);
  const severity = ((scaling.eventSeverity || EVENT_SEVERITY_BY_STAGE)[stageId] || 1) * founderFx(draft).eventSeverityMult;
  const localized = localizeEvent(ev, lang);
  if (ev.statCheck) {
    const fxE = founderFx(draft);
    const r = rollTracked(draft) + (draft.stats[ev.statCheck] || 0);
    // Risk Model gets one look per quarter at a check that just failed.
    const checked = checkWithRiskModel(draft, fxE, r, threshold, atMonth);
    const success = checked.success;
    const deltas = success ? (ev.goodDeltas || {}) : scaleDeltas(ev.badDeltas || {}, severity);
    const heldLine = lang === 'es' ? 'resistió.' : 'held the line.';
    const notEnough = lang === 'es' ? 'no fue suficiente para amortiguarlo del todo.' : "wasn't enough to fully absorb it.";
    const deltaText = deltaSummaryText(deltas, lang);
    // The reroll is called out explicitly — an invisible save is a wasted moment.
    const modelNote = checked.rerolled
      ? (lang === 'es' ? ' El modelo de riesgo lo detectó a tiempo.' : ' The risk model caught it in time.')
      : '';
    const body = `${localized.body} ${statLabel(ev.statCheck, lang)} ${success ? heldLine : notEnough}${modelNote}${deltaText ? ` (${deltaText})` : ''}`;
    return { deltas, tone: success ? 'mixed' : 'bad', body };
  }
  const deltaText = deltaSummaryText(ev.deltas, lang);
  const body = deltaText ? `${localized.body} (${deltaText})` : localized.body;
  return { deltas: ev.deltas || {}, tone: ev.tone === 'good' ? 'good' : 'bad', body };
}

// Choice-event options resolve one of two ways: a stat-weighted roll, or — if traitCheck is
// set — a guaranteed good outcome when a leader with that trait is on the team, otherwise a
// flat, unmodified roll (so the option is always pickable, just risky without the right leader).
// The pass threshold climbs and bad-outcome deltas scale up in later stages — see
// EVENT_THRESHOLD_BONUS_BY_STAGE / EVENT_SEVERITY_BY_STAGE.
function resolveChoiceOption(draft, option, atMonth, industry) {
  const scaling = (industry && industry.scaling) || {};
  const stageId = stageOf(atMonth, industry && industry.stages).id;
  const fx = founderFx(draft);
  const threshold = 10 + ((scaling.eventThresholdBonus || EVENT_THRESHOLD_BONUS_BY_STAGE)[stageId] || 0) + fx.choiceThresholdBonus;
  const severity = ((scaling.eventSeverity || EVENT_SEVERITY_BY_STAGE)[stageId] || 1) * fx.eventSeverityMult;
  if (option.traitCheck) {
    // A trait check is a guaranteed pass when held — never forecast, matching the UI, which
    // shows "Assured" instead of a chip in exactly this case.
    if (draft.team.leaders.some(l => l.trait === option.traitCheck)) return { success: true, via: 'trait', severity, preview: null };
    return { success: roll(10) >= threshold, via: 'roll', severity, preview: null };
  }
  const statTotal = draft.stats[option.statCheck] || 0;
  // Computed BEFORE the roll, from the exact same inputs the UI chip used, so this is
  // provably the forecast the player actually saw — not a plausible reconstruction of it.
  const preview = previewChance('choiceOption', draft, { statTotal, bar: threshold });
  const r = roll(10) + statTotal;
  return { success: r >= threshold, via: 'stat', severity, preview };
}

function completedEffects(proj, team) {
  const base = proj.onComplete || {};
  if (team.style !== 'Visionary') return base;
  const factor = 0.7 + Math.random() * 0.7;
  const scaled = {};
  Object.entries(base).forEach(([k, v]) => {
    scaled[k] = k === 'statBonus' ? v : Math.round(v * factor);
  });
  return scaled;
}

function projectCompleteBody(effects, lang) {
  const t = (s) => translate(s, lang);
  const bits = [];
  if (effects.revenuePerMonth) bits.push(lang === 'es' ? `+${fmtMoney(effects.revenuePerMonth)}/mes de ingresos` : `+${fmtMoney(effects.revenuePerMonth)}/mo revenue`);
  if (effects.reputation) bits.push(`+${effects.reputation} ${t('Reputation')}`);
  if (effects.marketPosition) bits.push(`+${effects.marketPosition} ${t('Market Position')}`);
  if (effects.morale) bits.push(`+${effects.morale} ${t('Morale')}`);
  if (effects.capital) bits.push(`+${fmtMoney(effects.capital)} ${t('Capital')}`);
  if (effects.burnReduction) bits.push(`-${effects.burnReduction} ${t('Burn (permanent)')}`);
  if (effects.statBonus) Object.entries(effects.statBonus).forEach(([k, v]) => bits.push(`+${v} ${statLabel(k, lang)}`));
  return bits.length ? bits.join(', ') + '.' : t('Complete.');
}

function fundraisePresenceCost(game, industry) {
  const stage = stageOf(game.month, industry && industry.stages).id;
  const hasSerialFounder = game.team.leaders.some(l => l.trait === 'Serial Founder');
  const free = hasSerialFounder && !game.usedFreeFundraise[stage];
  let cost = free ? 0 : 2;
  if (game.team.style === 'Hustler') cost = Math.max(0, cost - 1);
  return { cost, free, stage };
}

function recruitCosts(game) {
  return { capital: 10 };
}

