const AUTHORED_SCENARIOS = [TURNAROUND_SCENARIO, SIEGE_SCENARIO];

const BLITZ_STAGE_IDS = ['seed', 'seriesA', 'seriesB', 'exitWindow'];

function getScenario(scenarioId) {
  if (!scenarioId || scenarioId === 'fullRun') return FULL_RUN_SCENARIO;
  if (scenarioId.startsWith('blitz-')) return makeBlitzScenario(scenarioId.replace('blitz-', ''));
  const authored = AUTHORED_SCENARIOS.find(s => s.id === scenarioId);
  return authored || FULL_RUN_SCENARIO;
}

function isFullRun(sc) { return !sc || sc.kind === 'full'; }

// A resumed save may be missing fields a newer engine expects — it finishes on the schema it
// started on (7.1), so the engine has to tolerate the gap rather than the save being migrated.
// Shallow merge: any field actually present in the save wins; anything genuinely absent (added
// by a later version) falls back here. This is the single place that knowledge lives, rather
// than scattered `game.x || fallback` reads at every call site — a field added here is safe
// everywhere the moment it's added, including call sites written before it existed.
const GAME_FIELD_DEFAULTS = {
  scenarioId: 'fullRun', endMonth: RUN_END, metaBucket: 'full', industryId: 'hospitality',
  competitors: [], spawnedCompetitorStages: [],
  attacksDefended: 0, rankHoldStreak: 0,
  philosophy: null, // null, not emptyPhilosophy() — see hydrateResumedGame
  usedFreeFundraise: {}, visionaryBonusUsedThisMonth: false,
  usedChoiceEventIds: [], nextChoiceEventMonth: null,
  pendingChoice: null, pendingSummary: null,
  lowMoraleStreak: 0, dilutionCount: 0, locations: 0,
  laborReserved: 0, burnReduction: 0,
  // A save from before the derived valuation model won't have these — falling back to 0 means
  // its very next monthly recompute treats prior spend/raises as unknown rather than crashing,
  // which understates that one resumed run's valuation but never breaks it.
  totalAssetSpend: 0, totalRaised: 0,
  capacity: 0, demand: 0,
  activeTerms: [], closedInstruments: [], investorRelationships: {},
  // Business Model layer — the three strategic commitments and how many times they've been
  // re-tooled. An older save simply has none committed, which is a valid state (the axes are
  // offered again as soon as its stage index qualifies).
  businessModel: {}, retoolCount: 0, pendingCommitAxisId: null,
  investorRoster: [], knownRivals: [],
  investorBackers: {}, investorStandings: {}, allyReliefAnnounced: false,
  perkState: { cooldowns: {}, firedOnce: {}, counters: {} }, suppressNextEvent: false, forecastRecord: { calls: 0, correct: 0 },
  companyName: '', operatedThisMonth: [], successfulChoices: 0, products: {}, equipment: {},
  supplierContracts: {}, acquiredSuppliers: {}, inventoryStrategy: 'balanced',
  managers: {}, careerSnapshot: {}, unlockedSnapshot: [],
  receivables: [], payables: [], debts: [], missedDebtPayments: 0, emergencyFinancingCount: 0,
  rivalSuppliers: {}, scatteredTalent: [], nextLifecycleCheck: 0, lifecycleEvents: [],
  ownedTiers: {}, integrations: [], acquiredRivals: {},
  startingProductId: null, researchPoints: 0, competitorIntel: {},
  byproductPolicies: {},
  spotHoldings: {},
  salesContracts: [], salesContractOffers: [],
  buyerStandings: {}, unlockedBuyers: [],
  brand: { strength: 0, position: { premiumVsMass: 0, sustainability: 0, noveltyVsHeritage: 0 } },
  marketingPolicy: 'none', marketingTarget: null,
  discoveredBuyers: [], usedIntroductions: [], tradeShow: null, lastTradeShowMonth: -99,
  market: null,
};

function hydrateResumedGame(raw) {
  if (!raw) return raw;
  const merged = { ...GAME_FIELD_DEFAULTS, ...raw };
  // emptyPhilosophy() isn't itself JSON-safe to hardcode into a plain defaults object (it builds
  // from PHILOSOPHY_AXES), so it's filled in here rather than above.
  if (!merged.philosophy) merged.philosophy = emptyPhilosophy();
  return merged;
}

// Bridges an in-run Competitor (ephemeral, resets every game) into a persistent Company entity
// (the Nemesis store, industry-scoped, carries across runs). Matched by seedId, not name, so a
// coincidentally-reused name never merges two distinct rivals and a genuine recurrence always
// merges into one entity's history regardless of display-name changes.
//
// The in-run competitor is already the source of truth for everything identity-related by the
// time a run ends — logo/mission/philosophy are fixed at spawn, encounters accumulated live via
// recordNemesisEvent, pastLeaders updated at spawn from the previous record. This function's job
// is just to carry those fields into the shape the store persists, not to recompute anything.
function makeCompanyEntity(competitor, industry) {
  return {
    name: competitor.name, industry, seedId: competitor.seedId,
    logo: competitor.logo, mission: competitor.mission, philosophy: competitor.philosophy,
    leaders: competitor.leaders.map(l => ({ name: l.name, role: l.role, trait: l.trait })),
    pastLeaders: competitor.pastLeaders || [],
    pivotalDecisions: competitor.pivotalDecisions || [],
    encounters: competitor.encounters || {},
    runsSeen: competitor.runsSeen || 1,
    // Cached for list views only (e.g. a future roster-overview screen) — never read back as an
    // input; deriveDisposition/derivePosture always recompute fresh from `encounters` on load,
    // which is what keeps this idempotent across any number of runs.
    disposition: deriveDisposition(competitor),
    posture: derivePosture(competitor),
    firstSeenRun: null, lastSeenRun: null, encounterCount: 0,
    history: [],
  };
}

// Investors are global (7.2) and sized as full characters from the start — goals, strengths,
// weaknesses, domain expertise — even though no gameplay writes to this yet. The funding-source
// system that will actually create these draws from this shape rather than inventing one later.
function makeInvestor(overrides = {}) {
  return {
    id: overrides.id || `inv-${Math.random().toString(36).slice(2, 8)}`,
    name: overrides.name || 'Unnamed Investor',
    type: overrides.type || 'angel', // angel|vc|pe|bank|government|friendsFamily|strategic|accelerator
    archetype: overrides.archetype || '',
    goals: overrides.goals || [],           // e.g. 'fast exit', 'market dominance', 'social impact'
    strengths: overrides.strengths || [],   // domain areas where this investor genuinely helps
    weaknesses: overrides.weaknesses || [], // e.g. 'impatient', 'over-involved', 'herd-follower'
    expertise: overrides.expertise || [],   // ties to the Systems taxonomy, not a new stat set
    philosophy: overrides.philosophy != null ? overrides.philosophy : 50,
    riskTolerance: overrides.riskTolerance != null ? overrides.riskTolerance : 50,
    patience: overrides.patience != null ? overrides.patience : 50,
    industryPrefs: overrides.industryPrefs || [], // preference, not a scoping restriction — see 7.2
    relationship: 0,
    firstMetRun: null, lastDealRun: null,
    deals: [], // { runId, industry, stage, amount, terms, outcome }
    status: 'available', // available|burned|champion|exited
  };
}

function initialState(team, lang, scenario, knownNames) {
  const sc = scenario || FULL_RUN_SCENARIO;
  const ss = sc.startState;
  const startMonth = sc.startMonth || 1;

  const scIndustry = getIndustry(sc.industryId);
  const seeded = seedFromCompleted(sc.preCompleted);
  const stats = {};
  STAT_KEYS.forEach(k => { stats[k] = ss && ss.statBase ? ss.statBase : 2; });
  Object.entries(seeded.statBonus || {}).forEach(([k, v]) => { stats[k] = clamp((stats[k] || 0) + v, 0, 10); });
  team.leaders.forEach(l => {
    Object.entries(l.statBonus || {}).forEach(([k, v]) => { stats[k] = clamp((stats[k] || 0) + v, 0, 10); });
  });
  // Rivals that would already have spawned by the start month get *actually created*, not just
  // marked as spawned — otherwise a mid-game start has no competitors at all, which silently
  // disables the whole rivalry system and makes any market-rank objective unwinnable.
  const alreadySpawned = [];
  const preplaced = [];
  if (!isFullRun(sc) && sc.competitorMode !== 'preset') {
    STAGE_ORDER.forEach(id => {
      const st = STAGES.find(s => s.id === id);
      if (!st || !COMPETITOR_SPAWNS[id] || st.start > startMonth) return;
      alreadySpawned.push(id);
      for (let i = 0; i < COMPETITOR_SPAWNS[id]; i++) {
        const rival = makeCompetitor(
          [...(knownNames || []), ...preplaced.map(c => c.name)],
          preplaced.flatMap(c => c.leaders.map(l => l.name)),
          st.start, lang, sc.industryId || 'hospitality', scIndustry.content);
        // Age them: a rival that has been in the market since month 7 should not look brand new.
        const monthsAlive = Math.max(0, startMonth - st.start);
        rival.strength += monthsAlive * 2;
        rival.marketPosition = clamp(rival.marketPosition + monthsAlive * 2, 0, 100);
        preplaced.push(rival);
      }
    });
  }

  // A player-named company wins over the generated leadership-style label. Quickplay and Blitz
  // never reach the naming screen, so they keep the old behaviour untouched.
  const displayName = (sc.companyName && sc.companyName.trim())
    ? sc.companyName.trim()
    : (lang === 'es' ? (team.style ? `Liderazgo ${STYLE_NAMES_ES[team.style]}` : 'Liderazgo Independiente') : team.name);
  const isFull = isFullRun(sc);
  const ot = sc.openingTicket;
  const openingTitle = ot
    ? (lang === 'es' ? ot.title.es : ot.title.en)
    : (isFull
        ? (lang === 'es' ? OPENING_TITLE_BY_INDUSTRY_ES[sc.industryId] || 'Comienza el Reloj' : OPENING_TITLE_BY_INDUSTRY_EN[sc.industryId] || 'The Clock Starts')
        : (lang === 'es' ? 'Asumes el Cargo' : 'You Take Over'));
  const openingBody = ot ? (lang === 'es' ? ot.body.es : ot.body.en) : isFull
    ? (lang === 'es'
        ? `${displayName} toma las riendas. Comienza el mes 1 de ${sc.endMonth}.`
        : `${team.name} take the reins. Month 1 of ${sc.endMonth} begins.`)
    : (lang === 'es'
        ? `${displayName} toma el mando en el mes ${startMonth}. Tienes hasta el mes ${sc.endMonth}.`
        : `${displayName} takes over at month ${startMonth}. You have until month ${sc.endMonth}.`);

  const state = {
    team, month: startMonth, ap: (scIndustry.apByStage[stageOf(startMonth, scIndustry.stages).id] || 3),
    scenarioId: sc.id, endMonth: sc.endMonth, metaBucket: sc.metaBucket || 'full', industryId: sc.industryId || 'hospitality',
    capital: ss ? ss.capital : (scIndustry.start ? scIndustry.start.capital : 60),
    presence: ss ? ss.presence : 5,
    laborPool: ss ? ss.laborPool : (scIndustry.start ? scIndustry.start.laborPool : 8),
    laborReserved: seeded.laborReserved,
    burnReduction: seeded.burnReduction,
    stats,
    revenuePerMonth: ss ? ss.revenuePerMonth : 0,
    reputation: ss ? ss.reputation : 20,
    morale: ss ? ss.morale : 70,
    marketPosition: ss ? ss.marketPosition : 10,
    boardConfidence: ss ? ss.boardConfidence : 60,
    companyValuation: ss ? ss.companyValuation : 0,
    valuationAtLastReport: ss ? ss.companyValuation : 0,
    totalAssetSpend: seeded.ids.length ? seeded.ids.reduce((s, id) => { const p = PROJECTS.find(x => x.id === id); return s + (p ? (p.cost.capital || 0) : 0); }, 0) : 0,
    totalRaised: 0,
    lowMoraleStreak: 0, dilutionCount: 0, locations: seeded.locations,
    usedFreeFundraise: Object.fromEntries(STAGE_ORDER.map(id => [id, false])),
    visionaryBonusUsedThisMonth: false,
    activeProjects: [], completed: seeded.completed,
    usedChoiceEventIds: [], nextChoiceEventMonth: startMonth + randInt(2, 4),
    pendingChoice: null,
    competitors: sc.competitorMode === 'preset' ? buildPresetCompetitors(sc.presetCompetitors, lang) : preplaced,
    spawnedCompetitorStages: isFull ? [] : (sc.competitorMode === 'preset' ? [...STAGE_ORDER] : alreadySpawned),
    philosophy: emptyPhilosophy(),
    capacity: (ss && ss.capacity) || 0, demand: (ss && ss.demand) || 0,
    activeTerms: [], closedInstruments: [], investorRelationships: {},
    businessModel: {}, retoolCount: 0, pendingCommitAxisId: null,
    // Drawn once at run start and kept — the same investors front the same instruments all run.
    investorRoster: rollInvestorRoster(sc.industryId || 'hospitality'),
    knownRivals: [],
    // Who actually backed this run (drives run-end standings), and the cross-run standings
    // hydrated from the global investor store at start.
    investorBackers: {}, investorStandings: {}, allyReliefAnnounced: false,
    attacksDefended: 0, rankHoldStreak: 0,
    companyName: displayName, operatedThisMonth: [], successfulChoices: 0, products: {}, equipment: {},
    supplierContracts: {}, acquiredSuppliers: {}, inventoryStrategy: 'balanced',
    managers: {}, careerSnapshot: sc.careerSnapshot || {}, unlockedSnapshot: sc.unlockedSnapshot || [],
    receivables: [], payables: [], debts: [], missedDebtPayments: 0, emergencyFinancingCount: 0,
  rivalSuppliers: {}, scatteredTalent: [], nextLifecycleCheck: 0, lifecycleEvents: [],
  ownedTiers: {}, integrations: [], acquiredRivals: {},
  startingProductId: null, researchPoints: 0, competitorIntel: {},
  byproductPolicies: {},
  spotHoldings: {},
  salesContracts: [], salesContractOffers: [],
  buyerStandings: {}, unlockedBuyers: [],
  brand: { strength: 0, position: { premiumVsMass: 0, sustainability: 0, noveltyVsHeritage: 0 } },
  marketingPolicy: 'none', marketingTarget: null,
  discoveredBuyers: [], usedIntroductions: [], tradeShow: null, lastTradeShowMonth: -99,
  market: null,
    // Per-run perk bookkeeping (cooldowns / once-per-run flags). Triggers that consume this are
    // the next implementation pass; the field exists now so save shape is stable.
    perkState: emptyPerkState(), suppressNextEvent: false, forecastRecord: { calls: 0, correct: 0 },
    log: [mkTicket(startMonth, quarterOf(startMonth), 'system', 'neutral', openingTitle, openingBody)],
    pendingSummary: null,
    gameOver: null,
  };
  // The economic market is live for industries that have a product catalogue. Seeded at
  // equilibrium; rival and player production move it from month one.
  if (sc.industryId && getIndustry(sc.industryId).productCatalog) {
    state.market = recomputePrices(makeMarket());
  }

  // The chosen starting product begins in Prototype, not as an idea — the player made this
  // decision on the product screen, so the run opens with it already in flight rather than
  // requiring them to re-select it on turn one.
  if (sc.startingProductId && PRODUCT_BY_ID[sc.startingProductId]) {
    const startDef = PRODUCT_BY_ID[sc.startingProductId];
    state.startingProductId = sc.startingProductId;
    state.products = {
      [startDef.id]: {
        productId: startDef.id, phase: 'prototype',
        phaseMonthsLeft: basePhaseDuration('prototype', startDef),
        currentIntensity: 'standard',
        quality: null, defectRate: null, launchType: null, channelsOpened: [],
        appealBonus: 1, costReduction: 0, totalCapitalSpent: 0, startedMonth: startMonth,
      },
    };
  }

  // ---- Founder identity applied once, at run start ----
  // Company Philosophy starts as a BLEND of whichever founders are actually on the team, not
  // just the custom founder's own seed/class/signature nudges. A roster founder who's lived
  // through runs before contributes their own accumulated philosophy (rosterFounderToLeader
  // carries it in as `leader.philosophy`); one who's never played contributes nothing yet —
  // excluded from the average rather than dragging it toward neutral, since a blank slate isn't
  // a data point. The custom founder's own baseline is computed from seed + class + signature,
  // same as before, and their one-time starting deltas still apply regardless of the blend.
  const leaderBaselines = (team.leaders || []).map(l => {
    if (l.id === CUSTOM_FOUNDER_ID) {
      const seedDef = FOUNDER_SEED_BY_ID[l.seedId];
      const classDef = FOUNDER_CLASS_BY_ID[l.classId];
      const sigDef = SIGNATURE_PERK_BY_ID[l.signaturePerkId];
      if (seedDef && seedDef.startingDelta) applyDelta(state, seedDef.startingDelta);
      const base = emptyPhilosophy();
      [seedDef && seedDef.philosophySeed, classDef && classDef.philosophyLean, sigDef && sigDef.philosophyNudge]
        .forEach(src => {
          if (!src) return;
          Object.entries(src).forEach(([axis, v]) => {
            base[axis] = clamp((base[axis] || 0) + v, -100, 100);
          });
        });
      return base;
    }
    return l.philosophy || null; // roster leader's own accumulated philosophy, if any
  }).filter(Boolean);

  if (leaderBaselines.length) {
    const blended = emptyPhilosophy();
    PHILOSOPHY_AXES.forEach(axis => {
      const sum = leaderBaselines.reduce((a, b) => a + (b[axis] || 0), 0);
      blended[axis] = clamp(Math.round(sum / leaderBaselines.length), -100, 100);
    });
    state.philosophy = blended;
  }
  return state;
}

// ============================== COMPONENT ==============================
// A short, synthesized click — no audio file needed. Created lazily on first use since browsers
// require a user gesture before audio can play, and reused after that (AudioContext is expensive
// to spin up repeatedly).
let __audioCtx = null;
function playClickSound() {
  try {
    if (!__audioCtx) __audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    if (__audioCtx.state === 'suspended') __audioCtx.resume();
    const now = __audioCtx.currentTime;
    const osc = __audioCtx.createOscillator();
    const gain = __audioCtx.createGain();
    osc.type = 'square';
    osc.frequency.setValueAtTime(1000, now);
    gain.gain.setValueAtTime(0.06, now);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.045);
    osc.connect(gain);
    gain.connect(__audioCtx.destination);
    osc.start(now);
    osc.stop(now + 0.05);
  } catch (e) { /* Web Audio unavailable — silently skip */ }
}

// ============================== INDUSTRY REGISTRY ==============================
// Simulation Engine -> Industry -> Business Model -> Company -> Products & Services. Hospitality
// below *references* its existing constants rather than duplicating them — one source of truth,
// zero drift risk between "the registry's copy" and "what the engine actually reads."
// Pre-Seed is deliberately non-zero (not 0) despite starting valuation still landing at exactly
// $0 with no revenue and no assets — a hard 0 here means any revenue picked up before the Seed
// transition contributes nothing until the multiplier flips, producing a single-month 5x+ cliff
// right at the stage boundary rather than organic growth. Caught by a real playthrough trace, not
// theorized: Month 7 $133k -> Month 8 $752k with this table's original preSeed:0.
const HOSPITALITY_VALUATION_MULTIPLES = { preSeed: 1, seed: 2.5, seriesA: 3.5, seriesB: 4, exitWindow: 3 };
const VALUATION_ASSET_MULT = 1.5;   // shared across industries — replacement-value logic isn't industry-specific
const VALUATION_FUNDING_MULT = 1.1; // a company is never worth less than what investors already paid in

// Stage gates as data, not four hardcoded `if` blocks. `passes` returning false ends the run at
// that stage's final month. Bodies are functions so they can interpolate live state (market rank,
// thresholds) and are only evaluated when a gate actually fails.
const HOSPITALITY_STAGE_GATES = [
  {
    stageIndex: 0,
    passes: (g) => !!g.completed['firstLocation'],
    headline: { en: 'Pre-Seed Timeout', es: 'Tiempo Agotado en Pre-Semilla' },
    body: {
      en: () => 'Six months in and you never opened your first location. Investors pull out.',
      es: () => 'Pasaron seis meses y nunca abriste tu primer local. Los inversionistas se retiran.',
    },
  },
  {
    stageIndex: 1,
    passes: (g) => g.revenuePerMonth >= TRACTION_THRESHOLD,
    headline: { en: 'Seed Timeout', es: 'Tiempo Agotado en Semilla' },
    body: {
      en: () => `Nine months into Seed and revenue never reached ${fmtMoney(TRACTION_THRESHOLD)}/mo. The board doesn't see enough traction to justify a Series A.`,
      es: () => `Pasaron nueve meses en Semilla y los ingresos nunca llegaron a ${fmtMoney(TRACTION_THRESHOLD)}/mes. El directorio no ve suficiente tracción para justificar una Serie A.`,
    },
  },
  {
    stageIndex: 2,
    passes: (g) => g.revenuePerMonth >= GROWTH_THRESHOLD && !!g.completed['executiveHires'],
    headline: { en: 'Series A Timeout', es: 'Tiempo Agotado en Serie A' },
    body: {
      en: () => `Series A closes without what the board needed: ${fmtMoney(GROWTH_THRESHOLD)}/mo in revenue and a real leadership bench. The company stalls out.`,
      es: () => `La Serie A se cierra sin lo que el directorio necesitaba: ${fmtMoney(GROWTH_THRESHOLD)}/mes de ingresos y un equipo de liderazgo real. La empresa se estanca.`,
    },
  },
  {
    stageIndex: 3,
    // No rivals at all means the rank check can't be evaluated — that passes rather than fails.
    passes: (g) => { const mr = computeMarketRank(g); return !mr || mr.rank < mr.total; },
    headline: { en: 'Series B Timeout', es: 'Tiempo Agotado en Serie B' },
    body: {
      en: (g) => { const mr = computeMarketRank(g); return `Series B closes and you're still dead last in the market, #${mr.rank} of ${mr.total}. You're too small a player to credibly chase an exit from here.`; },
      es: (g) => { const mr = computeMarketRank(g); return `La Serie B se cierra y sigues en el último lugar del mercado, #${mr.rank} de ${mr.total}. Eres un jugador demasiado pequeño para perseguir una salida creíble desde aquí.`; },
    },
  },
];

