// Re-tooling a permanent commitment is meant to hurt. The cost climbs with how many times you've
// already done it, so a run that keeps changing its mind pays compounding interest for the
// privilege — which is the intended story beat, not a punishment for experimenting once.
const RETOOL_BASE_COST = { capital: 45, presence: 5, ap: 2 };
const RETOOL_BOARD_CONFIDENCE_HIT = 12;
const RETOOL_MORALE_HIT = 8;

function retoolCost(game) {
  const times = (game.retoolCount || 0);
  const scale = 1 + times * 0.75;
  return {
    capital: Math.round(RETOOL_BASE_COST.capital * scale),
    presence: RETOOL_BASE_COST.presence,
    ap: RETOOL_BASE_COST.ap,
  };
}

function findModelOption(axisId, optionId) {
  const axis = BUSINESS_MODEL_AXES.find(a => a.id === axisId);
  if (!axis) return null;
  return axis.options.find(o => o.id === optionId) || null;
}

// Aggregates every committed business-model choice into the effective modifiers the engine reads.
// Same contract as activeTermEffects: multiplicative modifiers compose, so three commitments
// stack predictably and no call site needs to know which ones are active.
function activeModelEffects(game) {
  const out = {
    marginMultiplier: 1, burnMultiplier: 1, projectCostMultiplier: 1, projectSpeedBonus: 0,
    demandGrowthMultiplier: 1, demandDecayMultiplier: 1, marketPositionMultiplier: 1,
    reputationGainMultiplier: 1, reputationLossMultiplier: 1, fundraiseMultiplier: 1,
    attackResistance: 1, moraleImpactMultiplier: 1, talentGainMultiplier: 1,
    innovationGainMultiplier: 1, complianceRisk: 1, laborBurnDivisor: 3,
    favorsExits: new Set(),
  };
  const commitments = (game && game.businessModel) || {};
  BUSINESS_MODEL_AXES.forEach(axis => {
    const chosenId = commitments[axis.id];
    if (!chosenId) return;
    const opt = findModelOption(axis.id, chosenId);
    if (!opt) return;
    const e = opt.effects || {};
    Object.keys(out).forEach(k => {
      if (k === 'favorsExits' || k === 'projectSpeedBonus' || k === 'laborBurnDivisor') return;
      if (e[k] != null) out[k] *= e[k];
    });
    out.projectSpeedBonus += e.projectSpeedBonus || 0;
    // Highest divisor wins rather than multiplying — two "headcount matters less" effects
    // shouldn't compound into burn being effectively free.
    if (e.laborBurnDivisor != null) out.laborBurnDivisor = Math.max(out.laborBurnDivisor, e.laborBurnDivisor);
    (e.favorsExits || []).forEach(x => out.favorsExits.add(x));
  });
  return out;
}

// Which axis (if any) is due for a commitment right now. Returns null when nothing is pending,
// which is the common case — this is checked every month but fires at most three times a run.
function pendingModelAxis(game, industry) {
  if (!game || game.gameOver) return null;
  const stages = (industry && industry.stages) || STAGES;
  const idx = stages.findIndex(s => s.id === stageOf(game.month, stages).id);
  const committed = game.businessModel || {};
  const due = BUSINESS_MODEL_AXES.filter(a => idx >= a.commitAtStageIndex && !committed[a.id]);
  return due.length ? due[0] : null;
}

// ============================== PROCEDURAL PORTRAITS ==============================
// Deterministic layered SVG art, seeded from a founder id or name. Reads as a person while
// staying inside the game's engraved brass-and-ink aesthetic — closer to a period business-card
// etching than a cartoon avatar, which is what suits a 1920s-industrial simulation.
//
// Everything is derived from a hash of the seed, so a given founder always renders identically
// across sessions and devices with nothing stored but the seed itself. When hand-drawn art
// arrives later it drops in behind the same <ProceduralPortrait> call sites.
//
// LIGHTING MODEL: a single key light from the upper-left, a weak fill from the lower-right, and
// a rim light on the right edge. Every shaded element follows that one convention — if a new
// feature is added it must shade the same way or the face stops reading as solid. Volume comes
// from three stacked cheap tricks rather than real 3-D: a radial gradient for the base form,
// hand-placed occlusion shadows where planes meet (under hair, chin, nose, collar), and small
// high-opacity speculars on the surfaces that face the key light.

function hashSeed(str) {
  let h = 2166136261;
  const s = String(str || 'seed');
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

// Small deterministic PRNG so each portrait feature draws from an independent stream.
function seededPicker(seed) {
  let state = hashSeed(seed) || 1;
  return () => {
    state ^= state << 13; state >>>= 0;
    state ^= state >> 17;
    state ^= state << 5; state >>>= 0;
    return state / 4294967296;
  };
}

