const SIGNATURE_PERK_BY_ID = SIGNATURE_PERKS.reduce((a, p) => { a[p.id] = p; return a; }, {});

// ---------------------------------------------------------------- General Perks — 10
// Category-organized, unlock-gated by the SAME 10 UNLOCK_MARKERS as before. Purely passive
