const GENERAL_PERK_BY_ID = GENERAL_PERKS.reduce((a, p) => { a[p.id] = p; return a; }, {});

// ---------------------------------------------------------------- point-buy (unchanged)
const FOUNDER_BASE_STAT_POINTS = 4;
const FOUNDER_MAX_PER_STAT = 3;
const CUSTOM_FOUNDER_ID = 'custom';

// ---------------------------------------------------------------- roster experience (unchanged)
const FOUNDER_XP_LEVELS = [0, 100, 240, 430, 680, 1000, 1400, 1900];
function founderLevel(xp) {
  const x = xp || 0;
  let lvl = 1;
  for (let i = 0; i < FOUNDER_XP_LEVELS.length; i++) if (x >= FOUNDER_XP_LEVELS[i]) lvl = i + 1;
  return Math.min(lvl, FOUNDER_XP_LEVELS.length);
}
function founderXpToNext(xp) {
  const lvl = founderLevel(xp);
  if (lvl >= FOUNDER_XP_LEVELS.length) return null;
  return FOUNDER_XP_LEVELS[lvl] - (xp || 0);
}
function founderEarnedPoints(xp) { return Math.max(0, founderLevel(xp) - 1); }
function founderRunXp({ months, won, outcome }) {
  let xp = 30 + Math.round((months || 0) * 2.5);
  if (won) xp += 120;
  if (outcome === 'ipo') xp += 60;
  else if (outcome === 'insolvent') xp += 25;
  return xp;
}

// ---------------------------------------------------------------- portrait (unchanged handles)
const PORTRAIT_SHAPES = ['round', 'square', 'shield', 'hex'];
function initialsFrom(name) {
  const parts = String(name || '').trim().split(/\s+/).filter(Boolean);
  if (!parts.length) return '??';
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}
function makeFounderPortrait(name, hue, shape) {
  return {
    initials: initialsFrom(name),
    hue: hue != null ? ((hue % 360) + 360) % 360 : Math.floor(Math.random() * 360),
    shape: shape || PORTRAIT_SHAPES[0],
  };
}

// ---------------------------------------------------------------- gating
// Signatures unlock in two waves per class: 2 starters, 1 career-gated (a global UNLOCK_MARKERS
// id), 1 class-mastery-gated (commitment to THIS class specifically, read from career.byClass).
// All checks are PURE recomputes from the career record — never cached — same rule that governs
// evaluateUnlocks and deriveDisposition: a cached, incrementally-toggled unlock list drifts and
// can't be repaired, especially dangerous here since a class-mastery record spans many runs.
function classMasteryMet(classId, gate, career, unlockedIds) {
  const rec = ((career && career.byClass) || {})[classId] || { runs: 0, wins: 0, bestStageFraction: 0 };
  if (rec.runs < gate.runs) return false;
  if (gate.requireWinInClass && rec.wins < 1) return false;
  // Stage-progress gates are industry-agnostic on purpose: Hospitality's stages
  // (preSeed/seed/seriesA/seriesB/exitWindow) and Manufacturing's (preSeed/seed/early/growth/
  // expansion/exit) don't share names past "seed" — comparing against a named stage id would
  // make a gate like "reach Growth" permanently unreachable in Hospitality. Comparing a 0..1
  // fraction of progress through whichever industry's own stage order works in both.
  if (gate.requireStageFraction != null && rec.bestStageFraction < gate.requireStageFraction) return false;
  if (gate.requireMarker && !(unlockedIds || []).includes(gate.requireMarker)) return false;
  return true;
}

function signatureUnlocked(perk, career, unlockedIds) {
  if (perk.gate.type === 'starter') return true;
  if (perk.gate.type === 'career') return (unlockedIds || []).includes(perk.gate.markerId);
  if (perk.gate.type === 'mastery') return classMasteryMet(perk.classId, perk.gate, career, unlockedIds);
  return false;
}

// Which signatures the player may currently pick for a given class.
function availableSignatures(classId, career, unlockedIds) {
  return SIGNATURE_PERKS.filter(p => p.classId === classId && signatureUnlocked(p, career, unlockedIds));
}

// Which general perks the player may currently pick — unchanged shape from the old availablePerks.
function availableGeneralPerks(unlockedIds) {
  return GENERAL_PERKS.filter(p => (unlockedIds || []).includes(p.unlockedBy));
}

function availableStatPoints(unlockedIds) {
  const bonus = UNLOCK_MARKERS
    .filter(u => (unlockedIds || []).includes(u.id))
    .reduce((a, u) => a + (u.grants.statPoints || 0), 0);
  return FOUNDER_BASE_STAT_POINTS + bonus;
}
function spentStatPoints(statPoints) {
  return Object.values(statPoints || {}).reduce((a, b) => a + (b || 0), 0);
}

// ---------------------------------------------------------------- the custom founder
function emptyCustomFounder() {
  return {
    id: CUSTOM_FOUNDER_ID,
    name: '',
    seedId: 'laidOffEngineer',
    classId: 'Visionary',
    signaturePerkId: 'blueOcean',
    generalPerkId: null,
    statPoints: {},
    portraitSeed: `custom-${Math.random().toString(36).slice(2, 9)}`,
    portrait: makeFounderPortrait('', 210, 'round'),
    createdAt: null,
  };
}

// Validation before a run can start. Returns [] when the founder is legal.
function validateCustomFounder(founder, career, unlockedIds) {
  const errs = [];
  if (!founder) return ['missing'];
  if (!String(founder.name || '').trim()) errs.push('name');
  if (!FOUNDER_SEED_BY_ID[founder.seedId]) errs.push('seed');
  if (!FOUNDER_CLASS_BY_ID[founder.classId]) errs.push('class');
  const sig = SIGNATURE_PERK_BY_ID[founder.signaturePerkId];
  if (!sig || sig.classId !== founder.classId) errs.push('signature');
  else if (!signatureUnlocked(sig, career, unlockedIds)) errs.push('signature');
  if (founder.generalPerkId) {
    const gp = GENERAL_PERK_BY_ID[founder.generalPerkId];
    if (!gp || !(unlockedIds || []).includes(gp.unlockedBy)) errs.push('generalPerk');
  }
  const spent = spentStatPoints(founder.statPoints);
  if (spent > availableStatPoints(unlockedIds)) errs.push('overspent');
  if (Object.values(founder.statPoints || {}).some(v => v > FOUNDER_MAX_PER_STAT || v < 0)) errs.push('statCap');
  return errs;
}

// Converts the custom founder into the exact leader shape the engine already consumes. The
// signature's ACTIVE ability becomes the leader's Operate action — no new plumbing needed for
// actives, since that mechanism already exists. classId/signaturePerkId/generalPerkId/seedId are
// carried on the leader object itself so founderFx can read them straight from game.team.leaders
// without a second lookup table.
function customFounderToLeader(founder, lang, career) {
  const cls = FOUNDER_CLASS_BY_ID[founder.classId] || FOUNDER_CLASSES[0];
  const sig = SIGNATURE_PERK_BY_ID[founder.signaturePerkId] || SIGNATURE_PERKS[0];
  const seed = FOUNDER_SEED_BY_ID[founder.seedId] || FOUNDER_SEEDS[0];
  const L = lang === 'es' ? 'es' : 'en';
  const statBonus = {};
  Object.entries(founder.statPoints || {}).forEach(([k, v]) => { if (v) statBonus[k] = v; });
  return {
    id: CUSTOM_FOUNDER_ID,
    name: founder.name || 'Founder',
    role: L === 'es' ? 'Fundador y CEO' : 'Founder & CEO',
    style: cls.styleMatch ? cls.id : null, // Analyst/Statesman never style-match (no co-founder yet)
    classId: cls.id,
    seedId: seed.id,
    signaturePerkId: sig.id,
    generalPerkId: founder.generalPerkId || null,
    trait: null,
    traitDesc: cls.mechanics[L],
    bio: seed.blurb[L],
    isCustom: true,
    portrait: founder.portrait,
    portraitSeed: founder.portraitSeed,
    statBonus,
    // Forecast sharpness is derived once, here, from career mastery — founderFx runs against
    // run state only and has no view of the career record.
    forecastHalfWidth: forecastHalfWidth(career, sig.id === 'dataDriven'),
    operate: { label: sig.name[L], desc: sig.activeDesc[L], deltas: sig.active.deltas },
  };
}

// Roster founders enter a run with their authored statBonus PLUS whatever the player has
// allocated from earned experience, PLUS an equipped signature if their tier has unlocked a slot
// (§6b of the design doc — engine support only; tier/slot content is a later authoring pass).
function rosterFounderToLeader(leader, record) {
  const allocated = (record && record.allocated) || {};
  const statBonus = { ...(leader.statBonus || {}) };
  Object.entries(allocated).forEach(([k, v]) => { if (v) statBonus[k] = (statBonus[k] || 0) + v; });
  const equippedSigId = record && record.signaturePerkId;
  const equippedSig = equippedSigId ? SIGNATURE_PERK_BY_ID[equippedSigId] : null;
  return {
    ...leader, statBonus,
    xp: (record && record.xp) || 0, level: founderLevel(record && record.xp),
    signaturePerkId: equippedSig ? equippedSig.id : null,
    // Carried through to run start so Company Philosophy can blend from what this founder has
    // actually lived through, not just from the custom founder's seed/class/signature. Null for
    // a founder who's never been on a run — nothing to blend in yet.
    philosophy: (record && record.philosophy) || null,
  };
}

// ---------------------------------------------------------------- unlock evaluation (unchanged)
function evaluateUnlocks(meta) {
  const m = {
    wins: 0, totalMonths: 0, totalRaised: 0, rivalDefeats: 0, alliesFormed: 0,
    byOutcome: {}, winsByIndustry: {}, investorStandings: {},
    ...(meta || {}),
  };
  m.byOutcome = m.byOutcome || {};
  m.winsByIndustry = m.winsByIndustry || {};
  m.investorStandings = m.investorStandings || {};
  return UNLOCK_MARKERS.filter(u => {
    try { return !!u.check(m); } catch (e) { return false; }
  }).map(u => u.id);
}

// Folds one finished run into the career record. Extended with `byClass` (new — required for
// signature mastery gates, §4.0 of the design doc): per-class runs/wins/months/bestStageIndex,
// populated only when a custom founder was on the team (Quickplay/Blitz still contribute nothing
// to career, consistent with the existing rule).
function accumulateCareer(prev, run) {
  const m = {
    runs: 0, wins: 0, totalMonths: 0, totalRaised: 0, rivalDefeats: 0, alliesFormed: 0,
    byOutcome: {}, winsByIndustry: {}, investorStandings: {}, byClass: {},
    buyerStandings: {}, unlockedBuyers: [],
    ...(prev || {}),
  };
  m.byOutcome = { ...(m.byOutcome || {}) };
  m.winsByIndustry = { ...(m.winsByIndustry || {}) };
  m.byClass = { ...(m.byClass || {}) };
  m.runs += 1;
  m.totalMonths += run.months || 0;
  m.totalRaised += run.totalRaised || 0;
  m.rivalDefeats += run.rivalDefeats || 0;
  m.alliesFormed += run.alliesFormed || 0;
  if (run.won) {
    m.wins += 1;
    m.winsByIndustry[run.industry] = (m.winsByIndustry[run.industry] || 0) + 1;
  }
  if (run.outcome) m.byOutcome[run.outcome] = (m.byOutcome[run.outcome] || 0) + 1;
  if (run.investorStandings) m.investorStandings = { ...run.investorStandings };
  // ---- Buyer relationships (meta-progression) ----
  // Standing ACCUMULATES across runs rather than being replaced, but only for buyers the player
  // has actually unlocked by completing a contract. A buyer you traded with once and never
  // finished a term with leaves no permanent trace — the unlock is the thing that makes it stick.
  m.unlockedBuyers = [...new Set([...(m.unlockedBuyers || []), ...(run.unlockedBuyers || [])])];
  if (run.buyerStandings) {
    m.buyerStandings = { ...(m.buyerStandings || {}) };
    Object.entries(run.buyerStandings).forEach(([bid, delta]) => {
      if (!m.unlockedBuyers.includes(bid)) return; // not permanent content yet
      m.buyerStandings[bid] = clamp((m.buyerStandings[bid] || 0) + delta, -100, 100);
    });
  }
  // ---- Leader-unlock metrics ----
  // Best-ever rather than cumulative: both unlocks ask "did you pull this off in a single run",
  // so summing across runs would let attrition substitute for the competence being tested.
  if (run.won) {
    m.bestChoiceWinsInExit = Math.max(m.bestChoiceWinsInExit || 0, run.successfulChoices || 0);
  }
  m.bestFriendlyInvestors = Math.max(m.bestFriendlyInvestors || 0, run.friendlyInvestors || 0);
  m.bestFriendlyCompanies = Math.max(m.bestFriendlyCompanies || 0, run.friendlyCompanies || 0);
  // The Statesman gate needs BOTH in the SAME run, so it's latched here rather than derived
  // from the two independent bests — which could otherwise be satisfied by two separate runs.
  if ((run.friendlyInvestors || 0) >= STATESMAN_FRIENDLY_INVESTORS
    && (run.friendlyCompanies || 0) >= STATESMAN_FRIENDLY_COMPANIES) {
    m.diplomatRunAchieved = true;
  }
  if (run.classId) {
    const rec = m.byClass[run.classId] || { runs: 0, wins: 0, months: 0, bestStageFraction: 0 };
    rec.runs += 1;
    rec.months += run.months || 0;
    if (run.won) rec.wins += 1;
    // Caller (Store.commitFounderRun) computes this as
    // stageOrder.indexOf(finalStageId) / (stageOrder.length - 1) using the RUN's own industry's
    // stage order — see the fraction-based gate comment in classMasteryMet for why a raw index
    // or named stage id doesn't work across industries with different stage lists.
    if (run.stageFraction != null && run.stageFraction > rec.bestStageFraction) rec.bestStageFraction = run.stageFraction;
    m.byClass[run.classId] = rec;
  }
  return m;
}


// ---------------------------------------------------------------- migration
// Founder docs saved before the class/perk redesign carry a single flat `perkId` and no seed.
// Migrating on READ (rather than with a one-shot writer) means a save that never gets written
// again still loads correctly, and re-running the migration on an already-migrated doc is a
// no-op — the same idempotence rule that governs deriveDisposition and evaluateUnlocks.
const LEGACY_PERK_TO_GENERAL = {
  closer: 'closer',
  turnaround: 'firefighter',
  bellRinger: 'roadshowVeteran',
  warmIntro: 'innerCircle',
  pressAdvantage: 'trendHunter',
  toolmaker: 'automationPioneer',
  fullHouse: 'qualityFirst',
  termSheet: 'innerCircle',
  institutional: 'naturalMentor',
  // supplyPartner's effect became Coalition Builder, which is now a Statesman SIGNATURE rather
  // than a general perk — there is no equivalent general slot, so it maps to null and the
  // player simply re-picks. The four old starters (walkTheFloor/workTheRoom/tightenBelt/
  // sketchItOut) were flat-delta Operate abilities with no mechanic to carry forward; they also
  // map to null, since every class now supplies its own Operate through its signature.
  supplyPartner: null,
  walkTheFloor: null, workTheRoom: null, tightenBelt: null, sketchItOut: null,
};
// First signature of each class, used as the landing spot for a migrated founder.
const LEGACY_CLASS_DEFAULT_SIGNATURE = {
  Visionary: 'blueOcean', Operator: 'kaizen', Hustler: 'handshakeDeal',
  Analyst: 'dataDriven', Statesman: 'diplomat',
};

function migrateFounderDoc(doc) {
  if (!doc) return doc;
  const out = { ...doc, roster: { ...(doc.roster || {}) }, career: { ...(doc.career || {}) } };
  // byClass didn't exist before the redesign; absent is legitimately "no class history".
  if (!out.career.byClass) out.career.byClass = {};
  const c = out.custom;
  if (!c) return out;
  if (c.signaturePerkId && c.seedId && !('perkId' in c)) return out; // already current

  const migrated = { ...c };
  if (!migrated.seedId) migrated.seedId = 'laidOffEngineer'; // the most neutral origin
  if (!FOUNDER_CLASS_BY_ID[migrated.classId]) migrated.classId = 'Visionary';
  if (!migrated.signaturePerkId) {
    migrated.signaturePerkId = LEGACY_CLASS_DEFAULT_SIGNATURE[migrated.classId] || 'blueOcean';
  }
  if (migrated.generalPerkId === undefined) {
    const mapped = LEGACY_PERK_TO_GENERAL[c.perkId];
    // Only carry the general perk over if its unlock marker was actually earned — otherwise the
    // migration would hand the player something they hadn't unlocked.
    const gp = mapped ? GENERAL_PERK_BY_ID[mapped] : null;
    migrated.generalPerkId = (gp && (doc.unlocked || []).includes(gp.unlockedBy)) ? gp.id : null;
  }
  if (!migrated.portraitSeed) migrated.portraitSeed = `custom-${migrated.name || 'founder'}`;
  delete migrated.perkId;
  out.custom = migrated;
  return out;
}

// ============================== LEADER UNLOCKS ==============================
// Six leaders are available from the first run — two in each of the three starting classes.
// Everyone else is earned. This keeps the opening roster small enough to actually read (the
// old six-at-once grid was already the point at which players stopped comparing carefully) and
// makes the roster something that visibly grows across a career.
//
// Analyst and Statesman are deliberately gated behind conditions that can only be met by
// PLAYING those classes' concerns, not by grinding runs:
//   - The Analyst arrives once you've proven you can read a situation — an exit with enough
//     choice events called correctly.
//   - The Statesman arrives once you've proven you can hold relationships — a single run
//     ending with two warm investors AND two friendly rival companies at the same time.
// Both are "do this thing well once", not "do this thing N times", so they reward a deliberate
// playstyle rather than attrition.

const ANALYST_UNLOCK_CHOICES = 6;      // successful choice events in a single winning run
const STATESMAN_FRIENDLY_INVESTORS = 2;
const STATESMAN_FRIENDLY_COMPANIES = 2;

// Thresholds for what counts as "friendly", reusing the existing relationship/disposition bands
// rather than inventing a parallel scale — warm+ for investors, cordial+ for rivals.
const FRIENDLY_INVESTOR_STANDING = 15;  // RELATIONSHIP_BANDS 'warm'
const FRIENDLY_COMPANY_DISPOSITION = 20; // DISPOSITION_BANDS 'cordial'

const LEADER_UNLOCKS = {
  // ---- Analyst ----
  analystUnlock: {
    id: 'analystUnlock',
    name: { en: 'The Analyst', es: 'La Analista' },
    requirement: {
      en: `Exit a run having called ${ANALYST_UNLOCK_CHOICES} choice events correctly.`,
      es: `Sal de una partida habiendo acertado ${ANALYST_UNLOCK_CHOICES} eventos de decisión.`,
    },
    check: (career) => (career.bestChoiceWinsInExit || 0) >= ANALYST_UNLOCK_CHOICES,
    // Progress line so a locked card can say how close you got, rather than just "locked".
    progress: (career) => ({ have: career.bestChoiceWinsInExit || 0, need: ANALYST_UNLOCK_CHOICES }),
  },
  // ---- Statesman ----
  statesmanUnlock: {
    id: 'statesmanUnlock',
    name: { en: 'The Statesman', es: 'El Estadista' },
    requirement: {
      en: `Finish a run holding ${STATESMAN_FRIENDLY_INVESTORS} warm investors and ${STATESMAN_FRIENDLY_COMPANIES} friendly rival companies at once.`,
      es: `Termina una partida con ${STATESMAN_FRIENDLY_INVESTORS} inversionistas cordiales y ${STATESMAN_FRIENDLY_COMPANIES} empresas rivales amistosas a la vez.`,
    },
    check: (career) => !!career.diplomatRunAchieved,
    progress: (career) => ({
      have: Math.min(career.bestFriendlyInvestors || 0, STATESMAN_FRIENDLY_INVESTORS)
        + Math.min(career.bestFriendlyCompanies || 0, STATESMAN_FRIENDLY_COMPANIES),
      need: STATESMAN_FRIENDLY_INVESTORS + STATESMAN_FRIENDLY_COMPANIES,
    }),
  },
  // ---- Veteran specialists: a third leader in a class you've already committed to ----
  veteranOperator: {
    id: 'veteranOperator',
    name: { en: 'Veteran Operator', es: 'Operador Veterano' },
    requirement: {
      en: 'Complete 3 runs with an Operator on the team.',
      es: 'Completa 3 partidas con un Operador en el equipo.',
    },
    check: (career) => (((career.byClass || {}).Operator || {}).runs || 0) >= 3,
    progress: (career) => ({ have: ((career.byClass || {}).Operator || {}).runs || 0, need: 3 }),
  },
  veteranHustler: {
    id: 'veteranHustler',
    name: { en: 'Veteran Hustler', es: 'Emprendedor Veterano' },
    requirement: {
      en: 'Raise 300k across your career.',
      es: 'Recauda 300k en toda tu carrera.',
    },
    check: (career) => (career.totalRaised || 0) >= 300,
    progress: (career) => ({ have: Math.round(career.totalRaised || 0), need: 300 }),
  },
};

// A leader with no `unlockedBy` is available from the first run. Pure recompute from the career
// record every time, never cached — same rule as every other unlock in this codebase.
function leaderUnlocked(leader, career) {
  if (!leader.unlockedBy) return true;
  const def = LEADER_UNLOCKS[leader.unlockedBy];
  if (!def) return true; // unknown gate fails open rather than hiding content forever
  try { return !!def.check(career || {}); } catch (e) { return false; }
}

// Counts the friendly relationships a finished run ended with. Kept next to the unlock
// definitions so the thresholds and the measurement can't drift apart.
function countFriendlyRelationships(game, settledStandings) {
  const standings = settledStandings || game.investorStandings || {};
  const friendlyInvestors = Object.values(standings)
    .filter(v => (v || 0) >= FRIENDLY_INVESTOR_STANDING).length;
  const friendlyCompanies = (game.competitors || [])
    .filter(c => deriveDisposition(c) >= FRIENDLY_COMPANY_DISPOSITION).length;
  return { friendlyInvestors, friendlyCompanies };
}

// ============================== FOUNDER FX AGGREGATOR ==============================
// Mirrors activeTermEffects/activeModelEffects exactly: one pure function, called at each hook
// site, that reduces every relevant source into a single neutral-default effects object. Call
// sites never know which perks exist — they just read a named key.
//
// Sources aggregated, per the design doc's §6b supersession of §5's original "custom founder
// only" reading:
//   - The custom founder's CLASS mechanics (Analyst/Statesman only — Visionary/Operator/Hustler
//     still deliver via team.style, unchanged) — custom-founder-only, classes don't travel.
//   - Every team leader's SIGNATURE perk (custom founder's chosen one, or a roster founder's
//     equipped one once tier/slot content exists) — same-id signatures on multiple leaders take
//     the single strongest instance, not stacked.
//   - The custom founder's GENERAL perk.
//
// Triggers (Kaizen's 12-month accrual, Moonshot's once-per-run Breakthrough, Handshake Deal,
// Risk Model's quarterly reroll, Predictive Analytics' active suppression, Master Scheduler's
// active, Skunkworks, Firefighter) need `perkState` bookkeeping and are NOT implemented here —
// this is passives only. Each is marked in SIGNATURE_PERKS/GENERAL_PERKS fx with a comment
// pointing here. Wiring them is the next session's work.
function founderFx(game) {
  const neutral = {
    // Analyst / Statesman class mechanics
    eventSeverityMult: 1, eventChanceMult: 1,
    fundraiseChanceFloor: 4, fundraiseFailBCMult: 1,
    alignmentBonus: 0, coexistMonthsOverride: null,
    // Signature/general passives
    frontierCostMult: 1, frontierSpeedBonus: 0,
    moonshotEligible: false, moonshotSeverityMult: 1,
    forecastEnabled: false, forecastHalfWidth: FORECAST_BASE_HALF_WIDTH,
    projectCompleteReputation: 0,
    stageTransitionMP: 0, stageTransitionBC: 0, showNextStageGate: false,
    projectCostMult: 1,
    idleBurnFree: false, shortfallRepMult: 1, locationOverheadDelta: 0,
    activeProjectBurnFree: false,
    demandGenChance: 0, demandGenAmount: 0, repGenAmount: 0,
    externalPresenceDiscount: 0, externalRollBonus: 0,
    recruitBonusLabor: 0, raidBarBonus: 0,
    choiceThresholdBonus: 0, showChoiceOdds: false,
    dispositionDamageMult: 1, coexistCreditBonus: 0,
    complianceDefenseBonus: 0,
    allyReliefPer: 2, allyReliefCap: 6,
    repFloor: 0, repHighBCTick: null,
    // General-perk-only keys
    fundraiseChanceBonus: 0,
    investorGraceMonthsBonus: 0, equityDemandMult: 1,
    rosterXpMult: 1,
    rivalGrowthMult: 1,
    exitTargetMult: 1,
    rivalDossier: false, firstStrikeBonus: 0,
    capacityEffMult: 1, capacityEffThreshold: Infinity,
    idleRepMult: 1, negativeEventRepMult: 1,
  };
  if (!game || !game.team || !Array.isArray(game.team.leaders)) return neutral;

  const custom = game.team.leaders.find(l => l.id === CUSTOM_FOUNDER_ID);
  const fx = { ...neutral };

  // ---- Class mechanics (custom-founder-only; the three legacy classes deliver via team.style
  // and need no representation here) ----
  if (custom && custom.classId === 'Analyst') {
    fx.eventSeverityMult *= 0.8;
    fx.fundraiseChanceFloor = Math.max(fx.fundraiseChanceFloor, 12);
    fx.fundraiseFailBCMult *= 0.5;
    // Forewarned. Sharpness was computed from career mastery when the leader was built —
    // founderFx only sees run state, so carrying it on the leader keeps this pure.
    fx.forecastEnabled = true;
    if (typeof custom.forecastHalfWidth === 'number') fx.forecastHalfWidth = custom.forecastHalfWidth;
  }
  if (custom && custom.classId === 'Statesman') {
    fx.alignmentBonus += 0.08;
    fx.coexistMonthsOverride = 8; // down from the default 12 — see tickCoexistence's hook
  }

  // ---- Signature perks: every leader that carries one, deduped by perk id (strongest-once,
  // not stacked) ----
  const seenSigIds = new Set();
  game.team.leaders.forEach(l => {
    const sigId = l.signaturePerkId;
    if (!sigId || seenSigIds.has(sigId)) return;
    const sig = SIGNATURE_PERK_BY_ID[sigId];
    if (!sig) return;
    seenSigIds.add(sigId);
    mergeFx(fx, sig.fx);
  });
  // Moonshot Founder courts risk: the whole run lands harder. Folded into the general severity
  // multiplier here rather than being read separately, so the cost is paid at every severity
  // site automatically instead of only wherever someone remembered to check for it.
  if (fx.moonshotSeverityMult) fx.eventSeverityMult *= fx.moonshotSeverityMult;

  // ---- General perk: custom founder only, by design (§6 of the doc — a quiet background trait,
  // not something that travels with roster founders) ----
  if (custom && custom.generalPerkId) {
    const gp = GENERAL_PERK_BY_ID[custom.generalPerkId];
    if (gp) mergeFx(fx, gp.fx);
  }

  return fx;
}

// Merges one perk's fx contribution into the running aggregate. Multiplicative keys multiply,
// additive/bonus keys add, boolean keys OR, and a couple of special-cased keys take the more
// generous of the two values (floors/caps/overrides) rather than blindly overwriting — so two
// perks that both touch, say, allyReliefCap don't have the second silently clobber the first.
function mergeFx(fx, contrib) {
  if (!contrib) return;
  Object.entries(contrib).forEach(([k, v]) => {
    if (typeof v === 'boolean') { fx[k] = fx[k] || v; return; }
    if (typeof v !== 'number') { fx[k] = v; return; } // e.g. repHighBCTick object — last write wins
    switch (k) {
      // Multiplicative
      case 'eventSeverityMult': case 'eventChanceMult': case 'frontierCostMult':
      case 'projectCostMult': case 'shortfallRepMult': case 'dispositionDamageMult':
      case 'equityDemandMult': case 'rosterXpMult': case 'rivalGrowthMult':
      case 'exitTargetMult': case 'capacityEffMult': case 'idleRepMult':
      case 'negativeEventRepMult': case 'fundraiseFailBCMult': case 'moonshotSeverityMult':
        fx[k] *= v; break;
      // Take-the-better-floor/cap
      case 'fundraiseChanceFloor': case 'allyReliefPer': case 'allyReliefCap': case 'repFloor':
        fx[k] = Math.max(fx[k], v); break;
      case 'capacityEffThreshold':
        fx[k] = Math.min(fx[k], v); break;
      // Everything else additive
      default:
        fx[k] = (fx[k] || 0) + v;
    }
  });
}

// ============================== FOUNDER TRIGGERS ==============================
// The "memorable moment" layer. founderFx (above) handles everything that is a quiet ongoing
// modifier; this handles everything that FIRES — the beats a player recounts afterwards ("the
// month Kaizen finally paid off", "the breakthrough that carried the run", "the angel who wired
// me fifteen grand when I was three weeks from dead").
//
// Design rules, learned from the rest of this codebase:
//   1. Every fire MUST emit a ticket. A silent trigger is a wasted mechanic — the player has to
//      be able to attribute the moment to the founder they built.
//   2. All rate/cadence bookkeeping goes through the shared helpers below, never ad-hoc month
//      arithmetic at the call site. One place to reason about "how often can this happen".
//   3. Bookkeeping lives in game.perkState, which is per-run and saved, so a reload can't
//      resurrect a spent once-per-run moment.
//   4. Triggers MUTATE draft; founderFx stays pure. Keeping the two apart is what makes founderFx
//      safe to call from anywhere, including inside render.

// ---------------------------------------------------------------- cadence plumbing
// perkState shape: { cooldowns: { perkId: monthLastFired }, firedOnce: { perkId: true },
//                    counters: { perkId: n } }
function emptyPerkState() {
  return { cooldowns: {}, firedOnce: {}, counters: {} };
}

// Defensive: older saves and hand-built test states may not carry every sub-object.
function normalizePerkState(ps) {
  const s = ps || {};
  return {
    cooldowns: s.cooldowns || {},
    firedOnce: s.firedOnce || {},
    counters: s.counters || {},
  };
}

// True when `perkId` has never fired, or fired at least `cadence` months ago. A cadence of 0 or
// null means "no cooldown" — the caller is gating on something else.
// `waitFullCadence` distinguishes the two kinds of cadence-gated perk, which want opposite
// behaviour on their FIRST fire:
//   - periodic accrual (Kaizen): must earn its first payout, so a full period has to elapse from
//     the start of the run. Otherwise "every 12 months" hands out a free grant in month 1.
//   - reactive rescue (Firefighter): must be able to fire the moment the condition appears, even
//     in month 1 — a cooldown on a rescue is about repeat use, not about a waiting period.
function perkCadenceReady(perkState, perkId, month, cadence, waitFullCadence) {
  const ps = normalizePerkState(perkState);
  if (!cadence) return true;
  const last = ps.cooldowns[perkId];
  if (last == null) return waitFullCadence ? month >= cadence : true;
  return (month - last) >= cadence;
}

function perkFiredOnce(perkState, perkId) {
  return !!normalizePerkState(perkState).firedOnce[perkId];
}

function perkCounter(perkState, perkId) {
  return normalizePerkState(perkState).counters[perkId] || 0;
}

// Records a fire against draft.perkState. Always clones so a trigger can never mutate the
// previous state object React is still holding.
function stampPerkFire(draft, perkId, month, opts = {}) {
  const ps = normalizePerkState(draft.perkState);
  draft.perkState = {
    cooldowns: { ...ps.cooldowns, [perkId]: month },
    firedOnce: opts.once ? { ...ps.firedOnce, [perkId]: true } : { ...ps.firedOnce },
    counters: opts.countUp
      ? { ...ps.counters, [perkId]: (ps.counters[perkId] || 0) + 1 }
      : { ...ps.counters },
  };
}

// ---------------------------------------------------------------- monthly triggers
// Evaluated once per month in endMonth, in this order. Each entry declares its own gating so the
// endMonth loop stays a dumb driver — adding a trigger never means editing endMonth.
//
//   enabled(fx)         -> is this perk equipped at all?
//   cadence             -> minimum months between fires (null = not cadence-gated)
//   once                -> fires at most once per run
//   when(draft, fx, m)  -> the actual game-state condition
//   fire(draft, ctx)    -> mutate, return { title, body, tone } for the ticket
const KAIZEN_MAX_ACCRUAL = 4;

const FOUNDER_MONTHLY_TRIGGERS = [
  {
    id: 'kaizen',
    enabled: (fx) => fx.kaizenAccrual,
    cadence: 12,
    waitFullCadence: true, // a year of improvement has to actually happen before it pays out
    // Capped on the perk's OWN accrued total, not on draft.burnReduction — otherwise unrelated
    // burn reduction from projects or business models would silently exhaust the cap.
    when: (draft) => perkCounter(draft.perkState, 'kaizen') < KAIZEN_MAX_ACCRUAL,
    fire: (draft, { language, t }) => {
      applyDelta(draft, { burnReduction: 1 });
      const n = perkCounter(draft.perkState, 'kaizen') + 1;
      return {
        tone: 'good',
        title: t('Kaizen'),
        body: language === 'es'
          ? `Otro año de mejoras pequeñas y constantes. Gasto permanentemente -1 (${n}/${KAIZEN_MAX_ACCRUAL} acumulado).`
          : `Another year of small, relentless improvements. Burn permanently -1 (${n}/${KAIZEN_MAX_ACCRUAL} accrued).`,
      };
    },
    countUp: true,
  },
  {
    id: 'firefighter',
    enabled: (fx) => fx.firefighterThreshold > 0,
    cadenceFrom: (fx) => fx.firefighterCooldown,
    when: (draft, fx) => draft.morale < fx.firefighterThreshold,
    fire: (draft, { language, t, fx }) => {
      const before = Math.round(draft.morale);
      draft.morale = clamp(fx.firefighterTarget, 0, 100);
      return {
        tone: 'good',
        title: t('Firefighter'),
        body: language === 'es'
          ? `La moral se desplomó a ${before} y actuaste antes de que se volviera permanente. Moral restaurada a ${fx.firefighterTarget}.`
          : `Morale cratered to ${before} and you moved before it set. Morale restored to ${fx.firefighterTarget}.`,
      };
    },
  },
  {
    id: 'handshakeDeal',
    enabled: (fx) => fx.handshakeEligible,
    once: true,
    // Fires when the runway gets genuinely short — three months or less of burn in the bank.
    when: (draft, fx, month, ctx) => draft.capital < ctx.burn * 3,
    fire: (draft, { language, t }) => {
      // Named from the run's own investor roster, so the moment belongs to a person the player
      // has met rather than an anonymous cash injection. Angel-stage investors only — this is a
      // favour, not a round.
      const roster = (draft.investorRoster || []).map(id => INVESTOR_BY_ID[id]).filter(Boolean);
      const angels = roster.filter(i => i.stages.includes('preSeed') || i.stages.includes('seed'));
      const angel = angels.length ? angels[0] : (roster.length ? roster[0] : null);
      const amount = 15;
      draft.capital += amount;
      draft.totalRaised = (draft.totalRaised || 0) + amount;
      const who = angel ? angel.name : (language === 'es' ? 'Un viejo contacto' : 'An old contact');
      return {
        tone: 'good',
        title: `${t('Handshake Deal')} — ${who}`,
        body: language === 'es'
          ? `${who} se entera de que estás corto y transfiere ${fmtMoney(amount)} el mismo día. Sin hoja de términos, sin dilución. Ahora le debes una.`
          : `${who} hears you're short and wires ${fmtMoney(amount)} the same day. No term sheet, no dilution. You owe them one now.`,
      };
    },
  },
  {
    id: 'publicServantWatch',
    // Not a "moment" — a quiet confirmation the floor is doing something, emitted rarely so it
    // never becomes noise. Fires at most once a year, only when the floor actually caught a fall.
    enabled: (fx) => fx.repFloor > 0,
    cadence: 12,
    when: (draft, fx) => draft.reputation <= fx.repFloor,
    fire: (draft, { language, t, fx }) => ({
      tone: 'mixed',
      title: t('Public Standing'),
      body: language === 'es'
        ? `Un año duro para la reputación, pero tu posición pública no se derrumba del todo. Piso de ${fx.repFloor} sostenido.`
        : `A hard year for reputation, but your public standing doesn't fully collapse. Floor of ${fx.repFloor} held.`,
    }),
  },
];

// Drives all monthly triggers. Returns tickets to push; mutates draft in place.
function runFounderMonthlyTriggers(draft, fx, month, ctx) {
  const tickets = [];
  FOUNDER_MONTHLY_TRIGGERS.forEach(trig => {
    if (!trig.enabled(fx)) return;
    if (trig.once && perkFiredOnce(draft.perkState, trig.id)) return;
    const cadence = trig.cadenceFrom ? trig.cadenceFrom(fx) : trig.cadence;
    if (!perkCadenceReady(draft.perkState, trig.id, month, cadence, trig.waitFullCadence)) return;
    if (!trig.when(draft, fx, month, ctx)) return;
    const result = trig.fire(draft, { ...ctx, fx, month });
    stampPerkFire(draft, trig.id, month, { once: trig.once, countUp: trig.countUp });
    if (result) {
      tickets.push(mkTicket(month, quarterOf(month), 'founder', result.tone || 'good', result.title, result.body));
    }
  });
  return tickets;
}

// ---------------------------------------------------------------- completion trigger
// Moonshot Founder: the single biggest swing in the signature set, and the reason a Visionary
// run feels different from an Operator one. Fires on completing a genuinely large project.
const MOONSHOT_MIN_PROJECT_COST = 8;

function tryMoonshotBreakthrough(draft, fx, proj, month, language, t) {
  if (!fx.moonshotEligible) return null;
  if (perkFiredOnce(draft.perkState, 'moonshotFounder')) return null;
  if ((proj.cost && proj.cost.capital ? proj.cost.capital : 0) < MOONSHOT_MIN_PROJECT_COST) return null;
  const deltas = { reputation: 8, marketPosition: 6, statBonus: { innovation: 1 } };
  applyDelta(draft, deltas);
  stampPerkFire(draft, 'moonshotFounder', month, { once: true });
  return mkTicket(month, quarterOf(month), 'founder', 'good',
    t('Breakthrough'),
    language === 'es'
      ? `El proyecto grande dio resultado y todo el mercado lo nota a la vez. (${deltaSummaryText(deltas, language)})`
      : `The big bet lands, and the whole market notices at once. (${deltaSummaryText(deltas, language)})`);
}

// ---------------------------------------------------------------- roll trigger
// Risk Model: once per quarter, the first failed check gets a second look. Implemented as a
// wrapper any d10 check site can route through, so the reroll is consistent everywhere it
// applies rather than reimplemented per site.
//
// Keyed by QUARTER rather than month — "once per quarter" is the design language, and quarter
// arithmetic in one place is safer than three call sites each deriving it.
function checkWithRiskModel(draft, fx, total, bar, month) {
  if (total >= bar) return { success: true, rerolled: false };
  if (!fx.quarterlyReroll) return { success: false, rerolled: false };
  const q = quarterOf(month);
  const lastQ = normalizePerkState(draft.perkState).cooldowns.riskModel;
  if (lastQ === q) return { success: false, rerolled: false };
  // Spend the quarter's reroll. Re-roll only the die — the stat contribution is unchanged.
  const statPart = total - (draft.__lastRollDie || 0);
  const fresh = roll(10);
  const newTotal = statPart + fresh;
  const ps = normalizePerkState(draft.perkState);
  draft.perkState = { ...ps, cooldowns: { ...ps.cooldowns, riskModel: q } };
  return { success: newTotal >= bar, rerolled: true, newTotal };
}

// Rolls a d10 and records the die separately so checkWithRiskModel can reroll just the die.
function rollTracked(draft) {
  const d = roll(10);
  draft.__lastRollDie = d;
  return d;
}


// ---------------------------------------------------------------- company naming
// Reuses the same per-industry prefix/suffix pools rival companies draw from, so the player's
// company reads as belonging to the same world rather than to a separate naming scheme.
function rollCompanyName(industryId, lang) {
  const ind = INDUSTRIES[industryId] || INDUSTRIES.hospitality;
  const pools = ind.content || {};
  const PRE = pools.namePrefixes || COMPETITOR_NAME_PREFIXES;
  const SUF = pools.nameSuffixes || COMPETITOR_NAME_SUFFIXES;
  const suffixes = SUF[lang === 'es' ? 'es' : 'en'] || SUF.en;
  return `${pick(PRE)} ${pick(suffixes)}`;
}

// ============================== FORECASTING (Analyst: "Forewarned") ==============================
// The Analyst's defining mechanic: she sees the odds before committing. But nobody fully predicts
// the future, so what she sees is a RANGE, and the range narrows as she gets better at this.
//
// Two rules make this honest rather than a debug overlay:
//
//   1. The preview and the resolution read the SAME math. Every chance shown here comes from a
//      shared helper that the handler also calls — a parallel reimplementation would drift, and
//      a drifted forecast makes the class's whole identity a lie without failing any test,
//      because both halves would still be internally consistent.
//   2. Percentage systems and d10 systems are displayed DIFFERENTLY on purpose. A d10 check is
//      genuinely 10%-granular, so rendering "63%" for one would be false precision an Analyst
//      player would rightly notice. They render as "7 in 10". The format difference quietly
//      teaches which systems are dice and which are models — real, transferable knowledge.

const FORECAST_BANDS = [
  { min: 85, id: 'nearCertain', label: { en: 'Near-certain', es: 'Casi seguro' }, tone: 'good' },
  { min: 65, id: 'likely', label: { en: 'Likely', es: 'Probable' }, tone: 'good' },
  { min: 45, id: 'even', label: { en: 'Even', es: 'Parejo' }, tone: 'neutral' },
  { min: 25, id: 'unlikely', label: { en: 'Unlikely', es: 'Improbable' }, tone: 'bad' },
  { min: -1, id: 'longShot', label: { en: 'Long shot', es: 'Apuesta lejana' }, tone: 'bad' },
];
function forecastBand(pct) {
  return FORECAST_BANDS.find(b => pct >= b.min) || FORECAST_BANDS[FORECAST_BANDS.length - 1];
}

// How wide the Analyst's uncertainty band is, in percentage points either side of her estimate.
// Starts wide, narrows with class mastery, never reaches zero on modelled systems.
const FORECAST_BASE_HALF_WIDTH = 12;
const FORECAST_MIN_HALF_WIDTH = 4;   // the floor: no founder ever sees the future exactly

function forecastHalfWidth(career, hasDataDriven) {
  const rec = ((career && career.byClass) || {}).Analyst || { runs: 0, wins: 0 };
  let w = FORECAST_BASE_HALF_WIDTH;
  if (hasDataDriven) w -= 4;               // Data Driven is the sharper instrument
  w -= Math.min(4, Math.floor(rec.runs / 2)); // experience reading her own models
  w -= Math.min(2, rec.wins);                 // and having been right when it counted
  return Math.max(FORECAST_MIN_HALF_WIDTH, w);
}

// ---------------------------------------------------------------- shared chance math
// Both the preview and the live handler call these. `fundraiseChanceBounds` returns the genuine
// lo/hi the stage roll can produce — the uncertainty in fundraising is REAL, not an artefact of
// the forecast, because baseRoll is itself sampled from a stage range at resolution time.
function fundraiseChanceBounds(game, industry) {
  const stageId = stageOf(game.month, industry && industry.stages).id;
  const rangeTable = (industry && industry.scaling && industry.scaling.fundraiseSuccessRange) || FUNDRAISE_SUCCESS_RANGE_BY_STAGE;
  const [lo, hi] = rangeTable[stageId] || FUNDRAISE_SUCCESS_RANGE_BY_STAGE.seriesB;
  const repMultiplier = game.reputation / 100;
  const bcMultiplier = 0.75 + (game.boardConfidence / 100) * 0.5;
  const modelMultiplier = activeModelEffects(game).fundraiseMultiplier;
  const fFx = founderFx(game);
  const shape = (base) => {
    let c = base * repMultiplier * bcMultiplier * modelMultiplier;
    if (game.team && game.team.style === 'Operator') c -= 15;
    c += fFx.fundraiseChanceBonus;
    return clamp(c, Math.max(3, fFx.fundraiseChanceFloor), 100);
  };
  return { lo: shape(lo), hi: shape(hi), shape };
}

// Deterministic (no stage roll), so the only spread is the Analyst's own uncertainty.
function instrumentChance(game, inst, investor) {
  const terms = investorTerms(investor, inst, game);
  const repMult = game.reputation / 100;
  const bcMult = 0.75 + (game.boardConfidence / 100) * 0.5;
  const fFx = founderFx(game);
  return clamp(terms.successBase * repMult * bcMult + fFx.fundraiseChanceBonus,
    Math.max(4, fFx.fundraiseChanceFloor), 95);
}

// d10 systems: returns how many faces of the die succeed, 0..10.
function d10SuccessFaces(statTotal, bar) {
  // roll(10) yields 1..10; success when statTotal + die >= bar, i.e. die >= bar - statTotal.
  const need = bar - statTotal;
  if (need <= 1) return 10;
  if (need > 10) return 0;
  return 10 - need + 1;
}

// ---------------------------------------------------------------- the preview
// Returns null when the founder has no forecasting ability — callers render nothing at all
// rather than a greyed-out "unlock Analyst" placeholder, which would nag the player about a
// class they deliberately didn't pick.
//
// Shape: { mode: 'pct'|'d10', lo, hi, mid, band, exact }
//   mode 'pct' -> render "56%–75%"
//   mode 'd10' -> render "6–8 in 10", or "7 in 10" when exact
function previewChance(kind, game, params = {}) {
  const fx = founderFx(game);
  if (!fx.forecastEnabled) return null;
  const half = fx.forecastHalfWidth;

  if (kind === 'fundraise' || kind === 'instrument') {
    let trueLo, trueHi;
    if (kind === 'fundraise') {
      const b = fundraiseChanceBounds(game, params.industry);
      trueLo = b.lo; trueHi = b.hi;
    } else {
      const c = instrumentChance(game, params.instrument, params.investor);
      trueLo = c; trueHi = c;
    }
    // Her estimate straddles the real band, widened by however sharp she currently is.
    const lo = clamp(Math.round(trueLo - half), 1, 99);
    const hi = clamp(Math.round(trueHi + half), 2, 99);
    const mid = Math.round((lo + hi) / 2);
    return { mode: 'pct', lo, hi, mid, band: forecastBand(mid), exact: false };
  }

  if (kind === 'choiceOption' || kind === 'externalAction') {
    const faces = d10SuccessFaces(params.statTotal || 0, params.bar || 10);
    // Uncertainty expressed in whole faces, since the underlying system is 10-sided. A skilled
    // enough Analyst reads a d10 EXACTLY — dice are genuinely knowable, unlike a model. That
    // asymmetry is the lesson the two formats exist to teach.
    const slack = Math.round(half / 10);
    const lo = clamp(faces - slack, 0, 10);
    const hi = clamp(faces + slack, 0, 10);
    const mid = Math.round((lo + hi) / 2);
    return { mode: 'd10', lo, hi, mid, band: forecastBand(mid * 10), exact: lo === hi };
  }

  return null;
}

// Formats a preview for display. Kept next to previewChance so the two never drift apart.
function forecastText(preview, lang) {
  if (!preview) return '';
  const L = lang === 'es' ? 'es' : 'en';
  if (preview.mode === 'd10') {
    const inTen = L === 'es' ? 'de 10' : 'in 10';
    return preview.exact ? `${preview.mid} ${inTen}` : `${preview.lo}–${preview.hi} ${inTen}`;
  }
  return preview.lo === preview.hi ? `${preview.mid}%` : `${preview.lo}%–${preview.hi}%`;
}

// ---------------------------------------------------------------- the calibration payoff
// Two small touches that turn the forecast from a utility into a running character note:
//   1. The outcome ticket says what she predicted and whether it held.
//   2. A run-end line scores her track record: how often she served the founder well.
//
// "Right" is scored asymmetrically, on purpose — a strict statistical hit-rate (did the
// FAVORED side happen) would mark a long-shot success as a model MISS, and no player reads a
// win that way. Landing a 20% shot never feels like the forecast failed you; it feels like the
// upside the range was already warning you about. The only call that actually burns a founder
// is false comfort: the model said you'd probably make it, and you didn't. So a SUCCESS is
// always scored correct, whatever the odds were, and the only way to score incorrect is a
// favored call (>=50%) that fails. This is a deliberately different question from strict
// calibration accuracy (whether "72%" truly means 72% — see calibration_playtest.cjs for that
// measurement) — this number answers "did my model serve me well", which is what the run-end
// line is actually telling the player.
function predictedPct(preview) {
  return preview.mode === 'd10' ? preview.mid * 10 : preview.mid;
}

function recordForecastOutcome(draft, preview, success) {
  if (!preview) return; // nothing was shown, nothing to score
  const rec = draft.forecastRecord || { calls: 0, correct: 0 };
  const favoredSuccess = predictedPct(preview) >= 50;
  // Correct unless the model favored success and the founder didn't get it.
  const servedWell = success || !favoredSuccess;
  draft.forecastRecord = {
    calls: rec.calls + 1,
    correct: rec.correct + (servedWell ? 1 : 0),
  };
}

// The flavor line appended to the outcome ticket. Four variants depending on whether the model
// favored this outcome AND whether it actually happened — "the model called it" reads very
// differently from "the long shot came through anyway", and both are true, tellable moments.
function forecastOutcomeNote(preview, success, lang) {
  if (!preview) return '';
  const L = lang === 'es' ? 'es' : 'en';
  const favored = predictedPct(preview) >= 50;
  const range = forecastText(preview, lang);
  const lines = {
    en: {
      hitFavored: `Your model called it — ${range}, and it landed.`,
      missFavored: `The model liked this one at ${range}. It didn't pay off.`,
      hitLongshot: `A long shot at ${range} — and it came through anyway.`,
      missLongshot: `The model gave this ${range}. It saw this one coming.`,
    },
    es: {
      hitFavored: `Tu modelo lo predijo — ${range}, y se cumplió.`,
      missFavored: `El modelo confiaba en esto con ${range}. No dio resultado.`,
      hitLongshot: `Una apuesta lejana con ${range} — y se cumplió de todos modos.`,
      missLongshot: `El modelo le dio ${range}. Esto lo vio venir.`,
    },
  };
  const set = lines[L];
  const key = favored ? (success ? 'hitFavored' : 'missFavored') : (success ? 'hitLongshot' : 'missLongshot');
  return ` ${set[key]}`;
}

// Run-end summary line. Returns null when nothing was ever forecast, so the card simply doesn't
// render rather than showing "0 calls, 0%".
function forecastCalibrationSummary(forecastRecord, lang) {
  const rec = forecastRecord || { calls: 0, correct: 0 };
  if (rec.calls === 0) return null;
  const pct = Math.round((rec.correct / rec.calls) * 100);
  return { calls: rec.calls, correct: rec.correct, pct, band: forecastBand(pct) };
}

