const INVESTOR_BY_ID = INVESTOR_CHARACTERS.reduce((acc, i) => { acc[i.id] = i; return acc; }, {});

// A run draws a roster at start and keeps it. Not every investor appears in every run — that's
// what makes learning who's who worth doing. The roster is stored on game state, so the same
// people front the same instruments from month 1 to the exit.
const ROSTER_SIZE = 9;

function rollInvestorRoster(industryId, rnd) {
  const rng = rnd || Math.random;
  const eligible = INVESTOR_CHARACTERS.filter(i => i.industries.includes(industryId));
  const pool = [...eligible];
  const roster = [];
  while (roster.length < Math.min(ROSTER_SIZE, pool.length)) {
    const idx = Math.floor(rng() * pool.length);
    roster.push(pool.splice(idx, 1)[0].id);
  }
  // Guarantee coverage: every stage an instrument can fire in must have at least one investor
  // willing to act there, or a run can hit a stage with a funding screen and nobody behind it.
  const covered = (stageId) => roster.some(id => INVESTOR_BY_ID[id].stages.includes(stageId));
  eligible.forEach(inv => {
    inv.stages.forEach(st => {
      if (!covered(st) && !roster.includes(inv.id)) roster.push(inv.id);
    });
  });
  return roster;
}

// Which rostered investor fronts a given instrument at a given stage. Deterministic for a run:
// the same instrument always shows the same face, which is what makes the relationship legible.
function investorForInstrument(game, instrumentId, stageId) {
  const roster = (game && game.investorRoster) || [];
  if (!roster.length) return null;
  const candidates = roster
    .map(id => INVESTOR_BY_ID[id])
    .filter(Boolean)
    .filter(inv => inv.stages.includes(stageId));
  if (!candidates.length) return null;
  const preferred = candidates.filter(inv => inv.prefers.includes(instrumentId));
  const finalPool = preferred.length ? preferred : candidates;
  // Stable pick: hash the instrument id so it doesn't reshuffle between renders.
  let h = 0;
  for (let i = 0; i < instrumentId.length; i++) h = (h * 31 + instrumentId.charCodeAt(i)) >>> 0;
  return finalPool[h % finalPool.length];
}


// ============================== INVESTOR BEHAVIOR ENGINE ==============================
// Phase 4 / Item 15. The characters existed; nothing read them back into play. This is the layer
// where an investor's `behavior` block and `philosophy` spread stop being flavour text and start
// changing what happens at the table.
//
// The design goal is that WHO backs you matters as much as HOW MUCH they gave you. Three
// interacting mechanisms produce that:
//
//   1. ALIGNMENT  — how close their philosophy is to the one you've been accumulating. This is
//                   the connective tissue: the Founder Philosophy system already existed and
//                   already recorded your drift; now it determines who finds you legible.
//   2. GATING     — some investors decline outright, and their reasons are *characterful*
//                   rather than generic. Chandra loses interest when you get popular. Walter
//                   only appears when you're desperate. Greta cannot bend her mandate.
//   3. TERMS      — the same instrument yields different capital, dilution and ongoing board
//                   pressure depending on who fronted it.
//
// Alignment is deliberately the input to both 2 and 3, so a single legible quantity drives the
// whole system and a player can reason about it.

// Distance across the six axes, normalised to 0..1, then flipped so 1 = perfectly aligned.
// Uses mean absolute difference rather than Euclidean so one wildly divergent axis can't
// dominate the reading — an investor who agrees with you about five things and violently
// disagrees about one should still read as broadly compatible.
//
// Normalised against ALIGNMENT_MAX_DIVERGENCE, not the theoretical maximum of 200. Two axis
// values in -100..100 can differ by 200 only if both sit at opposite extremes on every axis at
// once, which no authored investor and no realistically-played founder ever does. Dividing by
// 200 compressed every real pairing into roughly 0.5-1.0, which made the bottom two alignment
// bands unreachable and Greta Lindqvist's mandate gate impossible to trigger — she would fund
// literally anyone. 120 is the observed ceiling for a genuinely opposed pairing and lets the
// scale actually use its range.
const ALIGNMENT_MAX_DIVERGENCE = 120;

function investorAlignment(investor, philosophy, alignmentBonus) {
  if (!investor || !investor.philosophy) return 0.5;
  const p = philosophy || emptyPhilosophy();
  let total = 0;
  PHILOSOPHY_AXES.forEach(axis => {
    total += Math.abs((investor.philosophy[axis] || 0) - (p[axis] || 0));
  });
  const meanDiff = total / PHILOSOPHY_AXES.length;
  // The Statesman's bonus is applied AFTER normalisation, so it shifts the read rather than
  // distorting the underlying philosophy distance the Index displays.
  return clamp(1 - meanDiff / ALIGNMENT_MAX_DIVERGENCE + (alignmentBonus || 0), 0, 1);
}

// Alignment bands, so the UI and the log can say something specific rather than print a decimal.
const ALIGNMENT_BANDS = [
  { min: 0.78, id: 'kindred', label: { en: 'Kindred', es: 'Afín' }, tone: 'good' },
  { min: 0.62, id: 'comfortable', label: { en: 'Comfortable', es: 'Cómodo' }, tone: 'good' },
  { min: 0.45, id: 'workable', label: { en: 'Workable', es: 'Viable' }, tone: 'neutral' },
  { min: 0.30, id: 'strained', label: { en: 'Strained', es: 'Tenso' }, tone: 'bad' },
  { min: -1, id: 'irreconcilable', label: { en: 'Irreconcilable', es: 'Irreconciliable' }, tone: 'bad' },
];
function alignmentBand(v) {
  return ALIGNMENT_BANDS.find(b => v >= b.min) || ALIGNMENT_BANDS[ALIGNMENT_BANDS.length - 1];
}

// Cross-run relationship standing, -100..100. Distinct from alignment: alignment is about
// whether they understand you, relationship is about whether they trust you. A kindred investor
// you burned twice is still a hard no.
const RELATIONSHIP_BANDS = [
  { min: 55, id: 'champion', label: { en: 'Champion', es: 'Defensor' } },
  { min: 15, id: 'warm', label: { en: 'Warm', es: 'Cordial' } },
  { min: -15, id: 'neutral', label: { en: 'Neutral', es: 'Neutral' } },
  { min: -55, id: 'cool', label: { en: 'Cool', es: 'Frío' } },
  { min: -101, id: 'burned', label: { en: 'Burned', es: 'Quemado' } },
];
function relationshipBand(v) {
  const n = typeof v === 'number' ? v : 0;
  return RELATIONSHIP_BANDS.find(b => n >= b.min) || RELATIONSHIP_BANDS[RELATIONSHIP_BANDS.length - 1];
}

// ---- Gating: will this investor even take the meeting? ----
// Returns { open: bool, reason, reasonText } — a refusal always explains itself IN CHARACTER,
// because an unexplained "no" reads as a bug and an explained one teaches the player who this
// person is. That's the whole pedagogical loop the roster exists to support.
function investorGate(investor, game, stageId) {
  const L = 'en';
  if (!investor) return { open: true };
  const b = investor.behavior || {};
  const rel = ((game.investorStandings || {})[investor.id]) || 0;
  const align = investorAlignment(investor, game.philosophy, founderFx(game).alignmentBonus);

  // Burned relationships close the door regardless of anything else.
  if (rel <= -55) {
    return { open: false, reason: 'burned', reasonText: {
      en: `${investor.name} does not return the call. You have history, and it is not good.`,
      es: `${investor.name} no devuelve la llamada. Tienen historia, y no es buena.`,
    } };
  }

  // Greta Lindqvist: a hard mandate she has no discretion to bend. Alignment IS the mandate.
  if (b.mandateStrict && align < 0.45) {
    return { open: false, reason: 'mandate', reasonText: {
      en: `${investor.name} cannot write the cheque. The fund's mandate does not stretch to how you are building this, and she does not pretend otherwise.`,
      es: `${investor.name} no puede firmar el cheque. El mandato del fondo no alcanza a cómo estás construyendo esto, y ella no finge lo contrario.`,
    } };
  }

  // Howard Pryce / Saoirse Byrne / Raoul Espinoza: lend against revenue, not ambition.
  if (b.requiresRevenue && (game.revenuePerMonth || 0) < 8) {
    return { open: false, reason: 'noRevenue', reasonText: {
      en: `${investor.name} wants to see coverage before capital. Come back with revenue on the page.`,
      es: `${investor.name} quiere ver cobertura antes que capital. Vuelve con ingresos en la página.`,
    } };
  }

  // Omar Ben Salah: the reporting obligation is real and audited.
  if (b.complianceRequirement && (game.stats.compliance || 0) < 3) {
    return { open: false, reason: 'compliance', reasonText: {
      en: `${investor.name} runs a public mandate. Your compliance posture will not survive the audit, and he will not sign something he cannot defend.`,
      es: `${investor.name} gestiona un mandato público. Tu cumplimiento no sobrevive la auditoría, y no firmará algo que no pueda defender.`,
    } };
  }

  // Walter Krumm: appears when the phone has stopped ringing. If you're healthy, he's not
  // interested — his entire business is the discount that comes with desperation.
  if (b.rescueCapital) {
    const burnEst = Math.max(1, 2 + Math.ceil((game.laborPool || 0) / 3));
    const runway = (game.capital || 0) / burnEst;
    if (runway > 10 && (game.boardConfidence || 100) > 45) {
      return { open: false, reason: 'tooHealthy', reasonText: {
        en: `${investor.name} passes, politely. His terms only make sense to someone with no other options, and you still have some.`,
        es: `${investor.name} declina, cortésmente. Sus condiciones solo tienen sentido para quien no tiene alternativas, y tú aún las tienes.`,
      } };
    }
  }

  // Chandra Malhotra: openly bored by anything competitive to fund. High reputation is exactly
  // the signal that everyone else has arrived — which is her cue to leave.
  if (b.contrarian && (game.reputation || 0) > 72) {
    return { open: false, reason: 'tooPopular', reasonText: {
      en: `${investor.name} has lost interest. Everyone wants in now, which she takes as evidence the interesting part is over.`,
      es: `${investor.name} perdió el interés. Ahora todos quieren entrar, lo que ella toma como prueba de que lo interesante ya pasó.`,
    } };
  }

  return { open: true, alignment: align, relationship: rel };
}

// ---- Terms: the same instrument, different deal ----
// Everything here composes multiplicatively off the base instrument so the underlying balance
// tables stay the single source of truth and an investor is a MODIFIER, never a replacement.
function investorTerms(investor, inst, game) {
  const base = {
    capitalLo: inst.capital[0], capitalHi: inst.capital[1],
    dilution: inst.dilution || 0, successBase: inst.successBase,
    boardPressure: 1, patience: 1, alignment: 0.5,
  };
  if (!investor) return base;
  const b = investor.behavior || {};
  const align = investorAlignment(investor, game.philosophy, founderFx(game).alignmentBonus);
  const rel = ((game.investorStandings || {})[investor.id]) || 0;

  // Alignment swings the deal by up to ±20%: an investor who gets what you're building pays up
  // and asks for less. This is the main reward for having a coherent philosophy at all, and the
  // main cost of drifting incoherently.
  const alignSwing = 1 + (align - 0.5) * 0.4;
  // Standing swings it by up to ±15% on top. A champion investor is meaningfully cheaper money.
  const relSwing = 1 + (rel / 100) * 0.15;

  const capMult = (b.capitalMultiplier || 1) * alignSwing * relSwing;
  // Equity moves INVERSELY to alignment and standing — they want more of a company they don't
  // understand, and less of a founder they already trust.
  // Inner Circle: people who already trust you ask for less of the company.
  const equityMult = (b.equityDemand != null ? b.equityDemand : 1) * founderFx(game).equityDemandMult / (alignSwing * relSwing);

  // Reputation weight can be negative (Chandra), which flips the usual "reputation helps you
  // raise" relationship on its head for that one character.
  const repW = b.reputationWeight != null ? b.reputationWeight : 1;
  const repEffect = 1 + ((game.reputation || 0) / 100 - 0.5) * repW;

  return {
    capitalLo: Math.max(1, Math.round(base.capitalLo * capMult)),
    capitalHi: Math.max(2, Math.round(base.capitalHi * capMult)),
    dilution: Math.max(0, Math.round(base.dilution * equityMult * 10) / 10),
    successBase: clamp(base.successBase * repEffect * (1 + rel / 400), 4, 96),
    // Divergent investors sit heavier on the board; aligned ones give you room. Patience moves
    // the same way, which is what makes a philosophical mismatch compound rather than being a
    // one-time price.
    boardPressure: (b.boardPressure || 1) * (1 + (0.5 - align) * 0.6),
    patience: (b.patience || 1) * (0.7 + align * 0.6),
    alignment: align, relationship: rel,
  };
}

// An investor with real board pressure installs a lasting term, so their presence is felt every
// month rather than only on the month you took the money. Patience sets the grace period before
// it starts biting — which is precisely the mechanical difference between Terrence Okafor and
// Dwayne Borg.
function investorTerm(investor, terms, month, graceBonus) {
  if (!investor) return null;
  const pressure = terms.boardPressure || 1;
  if (pressure <= 1.05) return null; // patient / hands-off money installs nothing
  const graceMonths = Math.round(6 * (terms.patience || 1)) + (graceBonus || 0);
  return {
    kind: 'investorPressure',
    investorId: investor.id,
    investorName: investor.name,
    startedMonth: month,
    activeFromMonth: month + graceMonths,
    // Scaled off how far above "hands-off" they are, so a 1.7x investor is genuinely worse to
    // carry than a 1.2x one rather than both being "has pressure: yes". Floored at 1 because the
    // old (pressure-1)*4 rounded to ZERO for anything under ~1.13x — installing a term that
    // showed up in the UI, named an investor, and then did nothing at all every month.
    monthlyBoardConfidence: -Math.max(1, Math.round((pressure - 1) * 8)),
    returnsExpectation: investor.behavior.returnsExpectation || 1,
    detail: {
      en: `${investor.name} expects results from month ${month + graceMonths}.`,
      es: `${investor.name} espera resultados desde el mes ${month + graceMonths}.`,
    },
  };
}

// Applied inside endMonth. Pressure only bites after the grace period, and an investor whose
// expectations you ARE meeting backs off — that conditionality is what stops this from being a
// flat tax and makes it feel like a relationship with a person who is watching.
function applyInvestorPressure(draft, month) {
  const terms = (draft.activeTerms || []).filter(t => t.kind === 'investorPressure' && month >= t.activeFromMonth);
  if (!terms.length) return null;
  let totalBC = 0;
  const complaints = [];
  terms.forEach(t => {
    // "Are you delivering?" measured against the expectation they set. Revenue is the universal
    // yardstick both industries produce.
    const expected = 6 * (t.returnsExpectation || 1) * Math.max(1, Math.floor((month - t.startedMonth) / 6));
    const delivering = (draft.revenuePerMonth || 0) >= expected;
    if (delivering) return; // meeting the number buys silence — the relationship is conditional
    totalBC += t.monthlyBoardConfidence;
    complaints.push({ name: t.investorName, expected: Math.round(expected) });
  });
  if (!totalBC) return null;
  applyDelta(draft, { boardConfidence: totalBC });
  return { boardConfidence: totalBC, complaints };
}

// Run-end settlement. What the player did with the money determines whether these people take
// the next call — across industries, since investors are global (§7.2).
function settleInvestorStandings(game, won, outcome) {
  const standings = { ...(game.investorStandings || {}) };
  const backers = Object.keys(game.investorBackers || {});
  backers.forEach(id => {
    const cur = standings[id] || 0;
    let delta;
    if (won) {
      // A good exit is the whole point. Investors whose preferred exit you actually hit are
      // markedly happier — Evelyn Ashcroft cares that it was an IPO, not merely that it worked.
      const inv = INVESTOR_BY_ID[id];
      const preferredHit = inv && inv.behavior && inv.behavior.exitBias === outcome;
      delta = preferredHit ? 34 : 22;
    } else if (outcome === 'ousted') {
      delta = -12; // they may well have been the ones who did it; it's still a bad outcome
    } else if (outcome === 'insolvent') {
      delta = -26;
    } else {
      delta = -14;
    }
    standings[id] = clamp(cur + delta, -100, 100);
  });
  return standings;
}

