function instrumentsForStage(industry, stageId) {
  if (!industry.fundingInstruments) return [];
  return industry.fundingInstruments.filter(inst => inst.stages.includes(stageId));
}

// Aggregates every active term into the effective modifiers the engine reads, so no call site
// has to know which instruments exist or how they stack.
function activeTermEffects(game) {
  const terms = (game && game.activeTerms) || [];
  const out = {
    disabledActions: new Set(), blockedExits: new Set(),
    monthlyPresence: 0, boardConfidenceFloor: 0, burnMultiplier: 1, gateRevenueMultiplier: 1,
  };
  terms.forEach(t => {
    (t.disablesActions || []).forEach(a => out.disabledActions.add(a));
    (t.blocksExits || []).forEach(e => out.blockedExits.add(e));
    out.monthlyPresence += t.monthlyPresence || 0;
    out.boardConfidenceFloor = Math.max(out.boardConfidenceFloor, t.boardConfidenceFloor || 0);
    out.burnMultiplier *= t.burnMultiplier || 1;
    out.gateRevenueMultiplier *= t.gateRevenueMultiplier || 1;
  });
  return out;
}

