export default function FounderHospitalityPrototype() {
  const [game, setGame] = useState(null);
  const [showTutorial, setShowTutorial] = useState(false);
  const [showSettings, setShowSettings] = useState(false);
  const [showIndex, setShowIndex] = useState(false);
  const [selectedIds, setSelectedIds] = useState([]);
  const [showLocked, setShowLocked] = useState(false);
  const [targetCompetitorId, setTargetCompetitorId] = useState(null);
  const [showTicketRail, setShowTicketRail] = useState(false);
  const [expandedStageTiers, setExpandedStageTiers] = useState(null);
  const [showStatInfo, setShowStatInfo] = useState(false);
  const [showActionsInfo, setShowActionsInfo] = useState(false);
  const [showMetersInfo, setShowMetersInfo] = useState(false);
  const [showBrandInfo, setShowBrandInfo] = useState(false);
  const [preGameView, setPreGameView] = useState('title');
  const [pendingScenarioId, setPendingScenarioId] = useState('fullRun');
  const [pendingIndustryId, setPendingIndustryId] = useState('hospitality');
  const [metaStats, setMetaStats] = useState({ full: { ...EMPTY_META }, scenario: { ...EMPTY_META } });
  const recordedRunRef = useRef(null);
  const prefsRef = useRef(EMPTY_RECORD.prefs());
  // Persisted rival names for the active industry, loaded once when a run starts. Spawning
  // happens no earlier than month 7 (Seed), which is ample time for this single async read to
  // land — worst case on a genuinely slow load is one rare historical-name collision, not a crash.
  const knownCompanyNamesRef = useRef([]);
  const [showAchievements, setShowAchievements] = useState(false);
  const [showMetaProgression, setShowMetaProgression] = useState(false);
  // Founder identity: the player's own founder, the roster's accumulated experience, and the
  // career record that drives unlocks. Hydrated once at boot alongside everything else.
  const [founderDoc, setFounderDoc] = useState(() => EMPTY_RECORD.founders());
  const [draftFounder, setDraftFounder] = useState(null); // in-progress edits on the customize screen
  // Quickplay/blitz skip the custom founder entirely — those are stage practice and must not
  // write to the career record that drives unlocks.
  const [useCustomFounder, setUseCustomFounder] = useState(false);
  // Named on the leader-select screen, once the industry is known (the roller draws from that
  // industry's own name pools).
  const [pendingCompanyName, setPendingCompanyName] = useState('');
  const [pendingProductId, setPendingProductId] = useState(null);
  // In-run bottom tab bar. 'invest' first because building is the default verb of a turn.
  const [gameTab, setGameTab] = useState('mycompany');
  const [openCharacterId, setOpenCharacterId] = useState(null);
  const [openInvestorId, setOpenInvestorId] = useState(null);
  const [openCompanySeed, setOpenCompanySeed] = useState(null);
  const [openLeaderId, setOpenLeaderId] = useState(null);
  const [savedGame, setSavedGame] = useState(null);
  const [saveChecked, setSaveChecked] = useState(false);
  const [confirmDiscardSave, setConfirmDiscardSave] = useState(false);
  const [soundEnabled, setSoundEnabled] = useState(true);
  const [language, setLanguage] = useState('en');

  // One boot read: adopts legacy keys, runs migrations, then hydrates save + prefs + meta
  // in a single pass instead of four separate round trips.
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const boot = await Store.boot();
        if (cancelled) return;
        prefsRef.current = boot.prefs;
        if (boot.prefs.language) setLanguage(boot.prefs.language);
        if (boot.prefs.sound != null) setSoundEnabled(!!boot.prefs.sound);
        if (boot.active) setSavedGame(boot.active);
        setMetaStats({
          full: boot.profile.totals.byBucket.full || { ...EMPTY_META },
          scenario: boot.profile.totals.byBucket.scenario || { ...EMPTY_META },
        });
        const fdoc = await Store.getFounders();
        if (!cancelled) {
          // Unlocks are always recomputed from the career record on load rather than trusting the
          // cached list — if the marker definitions change between versions, the player's unlocks
          // re-derive correctly instead of being frozen at whatever was cached.
          setFounderDoc({ ...fdoc, unlocked: evaluateUnlocks(fdoc.career) });
        }
      } catch (e) {
        // storage unavailable — the game still plays, just without persistence
      } finally {
        if (!cancelled) setSaveChecked(true);
      }
    })();
    return () => { cancelled = true; };
  }, []);

  function toggleLanguage() {
    setLanguage(prev => {
      const next = prev === 'es' ? 'en' : 'es';
      prefsRef.current = { ...prefsRef.current, language: next };
      Store.savePrefs(prefsRef.current);
      return next;
    });
  }

  // Shorthand for the main component's JSX: t('English text') -> Spanish, when language is 'es'.
  const t = (text) => translate(text, language);

  function toggleSound() {
    setSoundEnabled(prev => {
      const next = !prev;
      prefsRef.current = { ...prefsRef.current, sound: next };
      Store.savePrefs(prefsRef.current);
      return next;
    });
  }

  // One delegated listener covers every button in the app — no need to touch dozens of call
  // sites individually. Skips disabled buttons, since those don't register as a "press" anyway.
  useEffect(() => {
    if (!soundEnabled) return;
    function onClick(e) {
      const btn = e.target.closest && e.target.closest('button');
      if (btn && !btn.disabled) playClickSound();
    }
    document.addEventListener('click', onClick, true);
    return () => document.removeEventListener('click', onClick, true);
  }, [soundEnabled]);

  // Autosave: fires on every action, End Month, choice resolution — anything that changes `game`.
  // Nothing to remember to click; closing the tab mid-turn loses nothing.
  useEffect(() => {
    if (!game) return;
    (async () => {
      await Store.saveActive(game, game.industryId || 'hospitality');
    })();
  }, [game]);

  // Loading an exported save file. Replaces the live run outright, writes it straight to the
  // active slot (so a reload resumes the IMPORTED game, not the one it replaced), and drops the
  // player back onto their company screen rather than leaving them in a menu.
  const handleImportSave = React.useCallback((restoredGame, industryId) => {
    if (!restoredGame) return;
    const withIndustry = { ...restoredGame, industryId: industryId || restoredGame.industryId || 'manufacturing' };
    setGame(withIndustry);
    setGameTab('mycompany');
    setShowSettings(false);
    (async () => {
      await Store.saveActive(withIndustry, withIndustry.industryId);
    })();
  }, []);

  // Record a finished run into its own bucket, exactly once per run.
  useEffect(() => {
    if (!game || !game.gameOver) return;
    const runKey = `${game.scenarioId || 'fullRun'}:${game.month}:${game.gameOver.reason}`;
    if (recordedRunRef.current === runKey) return;
    recordedRunRef.current = runKey;
    const bucket = game.metaBucket === 'scenario' ? 'scenario' : 'full';
    (async () => {
      const res = await Store.commitRun({
        game, industry: game.industryId || 'hospitality', bucket,
        outcome: game.gameOver.reason, won: !!game.gameOver.won,
        headline: game.gameOver.headline,
      });
      if (res) {
        setMetaStats({
          full: res.profile.totals.byBucket.full || { ...EMPTY_META },
          scenario: res.profile.totals.byBucket.scenario || { ...EMPTY_META },
        });
      }
    })();
  }, [game && game.gameOver]);

  async function clearSave() {
    setSavedGame(null);
    await Store.clearActive();
  }

  function resumeSavedGame() {
    if (!savedGame) return;
    setGame(hydrateResumedGame(savedGame));
  }

  const holdTimer = useRef(null);
  function cancelHold() { if (holdTimer.current) { clearTimeout(holdTimer.current); holdTimer.current = null; } }
  function makeHoldHandlers(setter) {
    const start = () => { holdTimer.current = setTimeout(() => setter(true), 450); };
    return {
      onMouseDown: start, onMouseUp: cancelHold, onMouseLeave: cancelHold,
      onTouchStart: start, onTouchEnd: cancelHold, onTouchCancel: cancelHold,
      onContextMenu: (e) => e.preventDefault(),
    };
  }
  const statHoldHandlers = makeHoldHandlers(setShowStatInfo);
  const actionsHoldHandlers = makeHoldHandlers(setShowActionsInfo);
  const metersHoldHandlers = makeHoldHandlers(setShowMetersInfo);
  const brandHoldHandlers = makeHoldHandlers(setShowBrandInfo);

  function toggleLeader(id) {
    const sc = getScenario(pendingScenarioId);
    const teamSize = sc.teamSize || 2;
    // The mandatory custom founder already holds a slot on full runs, so the selectable cap is
    // one fewer than the team size. Kept in sync with the same condition the render uses.
    const founderIsMandatory = !!(useCustomFounder && founderDoc.custom) && sc.kind === 'full';
    const cap = founderIsMandatory ? teamSize - 1 : teamSize;
    // Locked leaders are refused here as well as being unclickable in the UI — the render
    // guard is a convenience, this is the actual rule.
    const allLeaders = Object.values(INDUSTRIES).flatMap(ind => ind.content.leaders || []);
    const target = allLeaders.find(l => l.id === id);
    if (target && !leaderUnlocked(target, founderDoc.career || {})) return;
    setSelectedIds(prev => {
      if (prev.includes(id)) return prev.filter(x => x !== id);
      if (prev.length >= cap) return cap === 1 ? [id] : [...prev.slice(1), id];
      return [...prev, id];
    });
  }
  // The chosen industry overrides the scenario's declared one for full runs, so a single
  // fullRun descriptor serves every industry rather than needing one scenario per industry.
  function scenarioForStart() {
    const base = getScenario(pendingScenarioId);
    const named = pendingCompanyName && pendingCompanyName.trim()
      ? { companyName: pendingCompanyName.trim() } : {};
    // Snapshot the career/unlock state into the run so handlers (which live in a scope with no
    // access to founderDoc) can gate the manager roster. Snapshotting rather than reading live
    // also means the roster a run offers can't shift mid-run because a marker ticked over.
    // A founder who has done this before opens doors a first-timer cannot — the COMPANY is new,
    // but the name behind it travels. Small on purpose: it is a head start, not a free market.
    const founderBrand = startingBrandStrength(founderDoc.career || {});
    const snapshot = { careerSnapshot: founderDoc.career || {}, unlockedSnapshot: founderDoc.unlocked || [],
      brand: { strength: founderBrand, position: { premiumVsMass: 0, sustainability: 0, noveltyVsHeritage: 0 } } };
    const startProduct = pendingProductId ? { startingProductId: pendingProductId } : {};
    if (base.kind !== 'full') return { ...base, ...named, ...snapshot, ...startProduct };
    const ind = getIndustry(pendingIndustryId);
    return { ...base, industryId: pendingIndustryId, endMonth: ind.runEnd, ...named, ...snapshot, ...startProduct };
  }

  function startGame(team) {
    knownCompanyNamesRef.current = [];
    Store.getAllCompanyNames(pendingIndustryId).then(names => { knownCompanyNamesRef.current = names; });
    // Full runs never pre-place rivals at month 1, so the empty ref here is a non-issue for them.
    // Blitz/scenario starts that DO pre-place immediately may miss the very first uniqueness
    // check if this fetch hasn't resolved yet — acceptable: worst case is one rare historical
    // name collision, not a crash, and every spawn after month 1 has the ref fully populated.
    setGame(initialState(team, language, scenarioForStart(), knownCompanyNamesRef.current));
    // Same acceptable-race posture as the name fetch above: spawning starts no earlier than the
    // stage's first competitor wave, and hydration typically resolves well before that. Worst
    // case on a genuinely slow storage backend is one rival that could have returned spawning as
    // new instead — not a crash, not lost data, just one missed revival.
    Store.getCompaniesForIndustry(pendingIndustryId).then(companies => {
      setGame(prev => (prev ? { ...prev, knownRivals: companies } : prev));
    });
    // Investor standings are global (§7.2), so this is deliberately NOT industry-filtered — a
    // VC you burned running restaurants remembers it when you show up with a factory.
    Store.getInvestorStandings().then(standings => {
      setGame(prev => (prev ? { ...prev, investorStandings: standings } : prev));
    });
  }
  function endRun(targetView) {
    setGame(null);
    setSelectedIds([]);
    setShowLocked(false);
    setShowStatInfo(false);
    setShowActionsInfo(false);
    setShowMetersInfo(false);
    setShowSettings(false);
    setPreGameView(targetView);
    clearSave();
  }
  function resetGame() { endRun('select'); }
  function forfeitRun() { endRun('title'); }
  function closeSummary() { setGame(prev => prev ? { ...prev, pendingSummary: null } : prev); }

  // ---------------- Action handlers ----------------
  // ---- Business Model layer: commit and re-tool ----
  // Committing is free and costs no AP — it's a fork the run hands you, not an action you spend
  // resources to take. Re-tooling is where the cost lives, because that's the locked decision:
  // permanent commitment with a costly reversal.
  function handleCommitModel(axisId, optionId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const axis = BUSINESS_MODEL_AXES.find(a => a.id === axisId);
      const opt = findModelOption(axisId, optionId);
      if (!axis || !opt) return prev;
      if ((prev.businessModel || {})[axisId]) return prev; // already committed — use re-tool

      const draft = { ...prev, stats: { ...prev.stats }, log: [...prev.log] };
      draft.businessModel = { ...(prev.businessModel || {}), [axisId]: optionId };
      draft.pendingCommitAxisId = null;
      applyDelta(draft, opt.onCommit || {});
      if (opt.philosophy) {
        draft.philosophy = { ...(draft.philosophy || emptyPhilosophy()) };
        Object.entries(opt.philosophy).forEach(([ax, v]) => {
          draft.philosophy[ax] = clamp((draft.philosophy[ax] || 0) + v, -100, 100);
        });
      }
      const L = language === 'es' ? 'es' : 'en';
      const deltaText = deltaSummaryText(opt.onCommit || {}, language);
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'system', 'good',
        `${axis.name[L]} — ${opt.name[L]}`,
        `${opt.detail[L]}${deltaText ? ` (${deltaText})` : ''}`), ...draft.log];
      return draft;
    });
  }

  function handleRetoolModel(axisId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const axis = BUSINESS_MODEL_AXES.find(a => a.id === axisId);
      if (!axis || !(prev.businessModel || {})[axisId]) return prev;
      const cost = retoolCost(prev);
      const L = language === 'es' ? 'es' : 'en';
      if (prev.ap < cost.ap) return denyTicket(prev, `${t('Re-tool')}: ${axis.name[L]}`, t('No Action Points remaining this month.'), language);
      if (cost.capital > prev.capital) return denyTicket(prev, `${t('Re-tool')}: ${axis.name[L]}`, `${t('Needs')} ${fmtMoney(cost.capital)} ${t('Capital')} (${t('you have')} ${fmtMoney(prev.capital)}).`, language);
      if (cost.presence > prev.presence) return denyTicket(prev, `${t('Re-tool')}: ${axis.name[L]}`, `${t('Needs')} ${cost.presence} ${t('Presence')} (${t('you have')} ${prev.presence}).`, language);

      const draft = { ...prev, stats: { ...prev.stats }, log: [...prev.log] };
      draft.capital -= cost.capital;
      draft.presence -= cost.presence;
      draft.ap -= cost.ap;
      draft.retoolCount = (prev.retoolCount || 0) + 1;
      const bm = { ...(prev.businessModel || {}) };
      delete bm[axisId];
      draft.businessModel = bm;
      applyDelta(draft, { boardConfidence: -RETOOL_BOARD_CONFIDENCE_HIT, morale: -RETOOL_MORALE_HIT });
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'system', 'bad',
        `${t('Re-tool')} — ${axis.name[L]}`,
        `${language === 'es'
          ? 'Desmantelas un compromiso permanente. El directorio y el equipo lo sienten.'
          : 'You unwind a permanent commitment. The board and the team both feel it.'} (${deltaSummaryText({ boardConfidence: -RETOOL_BOARD_CONFIDENCE_HIT, morale: -RETOOL_MORALE_HIT }, language)})`), ...draft.log];
      return draft;
    });
  }

  function handleInvest(projectId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const ind = getIndustry(prev.industryId);
      const proj = ind.content.projects.find(p => p.id === projectId);
      if (!proj) return prev;
      const dProj = localizeProject(proj, language);
      if (prev.ap < 1) return denyTicket(prev, dProj.name, t('No Action Points remaining this month.'), language);
      if (prev.completed[projectId] || prev.activeProjects.some(p => p.id === projectId)) return prev;
      if (proj.requires.some(r => !prev.completed[r])) return prev;
      const scaled = scaledProjectCost(proj, stageOf(prev.month, ind.stages).id, prev.team.style, ind.scaling);
      // Business-model commitments change what building anything costs and how fast it lands.
      const mfx = activeModelEffects(prev);
      const ffx = founderFx(prev);
      scaled.capital = Math.round(scaled.capital * mfx.projectCostMultiplier * ffx.projectCostMult);
      scaled.duration = Math.max(1, scaled.duration - (mfx.projectSpeedBonus || 0));
      // Blue Ocean: frontier work (no prerequisites) is cheaper and faster still, on top of
      // whatever the general project-cost perk already did.
      if ((proj.requires || []).length === 0) {
        scaled.capital = Math.round(scaled.capital * ffx.frontierCostMult);
        scaled.duration = Math.max(1, scaled.duration - ffx.frontierSpeedBonus);
      }
      if (scaled.capital > prev.capital) return denyTicket(prev, dProj.name, `${t('Needs')} ${fmtMoney(scaled.capital)} ${t('Capital')} (${t('you have')} ${fmtMoney(prev.capital)}).`, language);
      if (scaled.presence > prev.presence) return denyTicket(prev, dProj.name, `${t('Needs')} ${scaled.presence} ${t('Presence')} (${t('you have')} ${prev.presence}).`, language);
      const freeLabor = prev.laborPool - prev.laborReserved;
      if (scaled.labor > freeLabor) return denyTicket(prev, dProj.name, `${t('Needs')} ${scaled.labor} ${t('free Labor')} (${t('you have')} ${freeLabor}).`, language);

      const draft = { ...prev, activeProjects: [...prev.activeProjects], log: [...prev.log] };
      draft.capital -= scaled.capital;
      draft.presence -= scaled.presence;
      const duration = scaled.duration;
      draft.laborReserved += scaled.labor;
      draft.activeProjects.push({ id: proj.id, monthsLeft: duration, labor: scaled.labor, laborPermanent: !!proj.laborPermanent, capitalPaid: scaled.capital });
      draft.ap -= 1;
      if (prev.team.style === 'Visionary' && !prev.visionaryBonusUsedThisMonth) {
        draft.ap += 1;
        draft.visionaryBonusUsedThisMonth = true;
      }
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'action', 'neutral',
        `${t('Invested:')} ${dProj.name}`, `${t('Committed resources.')} ${duration} ${t('month(s) to completion.')}`), ...draft.log];
      return draft;
    });
  }

  function handleFundraise() {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      if (prev.ap < 1) return denyTicket(prev, t('Fundraise'), t('No Action Points remaining this month.'), language);
      const ind = getIndustry(prev.industryId);
      const { cost, free, stage } = fundraisePresenceCost(prev, ind);
      if (cost > prev.presence) return denyTicket(prev, t('Fundraise'), `${t('Needs')} ${cost} ${t('Presence')} (${t('you have')} ${prev.presence}).`, language);

      const draft = { ...prev, log: [...prev.log], usedFreeFundraise: { ...prev.usedFreeFundraise } };
      draft.presence -= cost;
      draft.ap -= 1;
      if (free) draft.usedFreeFundraise[stage] = true;

      const stageId = stageOf(prev.month, ind.stages).id;
      // Board Confidence is the secondary lever: neutral at 50 (1.00x), as low as 0.75x at BC 0,
      // as high as 1.25x at BC 100. It's a smaller swing than Reputation on purpose, and it
      // multiplies the Reputation-adjusted number rather than blending into the stage roll — so
      // the two can offset each other (strong Rep, weak BC) or compound (both strong or both weak).
      // All of that shaping now lives in fundraiseChanceBounds, which the Analyst's forecast also
      // calls — one implementation, so a preview can never disagree with the resolution it
      // predicts. Only the stage roll itself is sampled here.
      const fFx = founderFx(draft);
      const bounds = fundraiseChanceBounds(draft, ind);
      // Computed BEFORE the roll, from the same state the button's chip was just showing.
      const preview = previewChance('fundraise', draft, { industry: ind });
      const rangeTable = (ind.scaling && ind.scaling.fundraiseSuccessRange) || FUNDRAISE_SUCCESS_RANGE_BY_STAGE;
      const [lo, hi] = rangeTable[stageId] || FUNDRAISE_SUCCESS_RANGE_BY_STAGE.seriesB;
      const chance = bounds.shape(lo + Math.random() * (hi - lo));
      const success = Math.random() * 100 < chance;
      recordForecastOutcome(draft, preview, success);
      if (success) {
        // Variable payout: a range whose midpoint scales with Reputation, not a fixed amount.
        const midpoint = 15 + draft.reputation / 5;
        const low = Math.max(6, Math.round(midpoint * 0.6));
        const high = Math.round(midpoint * 1.6);
        const gain = low + Math.floor(Math.random() * (high - low + 1));
        draft.capital += gain;
        draft.dilutionCount += 1;
        draft.totalRaised = (draft.totalRaised || 0) + gain;
        const n = draft.dilutionCount;
        const modelNote = forecastOutcomeNote(preview, success, language);
        const body = language === 'es'
          ? `Recaudaste ${fmtMoney(gain)} (términos entre ${fmtMoney(low)}–${fmtMoney(high)}).${modelNote} ${n} ronda${n > 1 ? 's' : ''} hasta la fecha.`
          : `Raised ${fmtMoney(gain)} (terms ranged ${fmtMoney(low)}–${fmtMoney(high)}).${modelNote} ${n} round${n > 1 ? 's' : ''} to date.`;
        draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'action', 'good', t('Fundraise — Closed'), body), ...draft.log];
      } else {
        // Analyst halves the sting; Roadshow Veteran removes it entirely. Rounded so a perk that
        // zeroes the multiplier really does mean zero rather than a stray -1.
        const moraleHit = -Math.round(5 * fFx.fundraiseFailBCMult);
        if (moraleHit) draft.morale = clamp(draft.morale + moraleHit, 0, 100);
        const modelNote = forecastOutcomeNote(preview, success, language);
        draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'action', 'bad', t('Fundraise — Passed On'),
          `${t('Investors pass this round. The team feels it.')}${modelNote}${moraleHit ? ` (${deltaSummaryText({ morale: moraleHit }, language)})` : ''}`), ...draft.log];
      }
      return draft;
    });
  }

  function handleRecruit() {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      if (prev.ap < 1) return denyTicket(prev, t('Hire Staff'), t('No Action Points remaining this month.'), language);
      const { capital } = recruitCosts(prev);
      if (capital > prev.capital) return denyTicket(prev, t('Hire Staff'), `${t('Needs')} ${fmtMoney(capital)} ${t('Capital')} (${t('you have')} ${fmtMoney(prev.capital)}).`, language);

      const draft = { ...prev, stats: { ...prev.stats }, log: [...prev.log] };
      const rFx = founderFx(prev);
      const hired = 3 + rFx.recruitBonusLabor; // Natural Recruiter
      draft.capital -= capital;
      draft.laborPool += hired;
      draft.ap -= 1;
      let body = language === 'es' ? `+${hired} al grupo de Personal.` : `+${hired} Labor pool.`;
      if (Math.random() < 0.3) {
        draft.stats.talentCulture = clamp(draft.stats.talentCulture + 1, 0, 10);
        body += language === 'es' ? ' Una contratación destacada también mejora tu Cultura de Talento.' : ' A standout hire also sharpens your Talent Culture.';
      }
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'action', 'good', t('Hired Staff'), body), ...draft.log];
      return draft;
    });
  }

  function handleLayoff() {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      if (prev.ap < 1) return denyTicket(prev, t('Layoff'), t('No Action Points remaining this month.'), language);
      const freeLabor = prev.laborPool - prev.laborReserved;
      if (freeLabor <= 0) return denyTicket(prev, t('Layoff'), t("No spare staff to lay off — everyone is already committed to a location or project."), language);
      const cut = Math.min(3, freeLabor);
      const draft = { ...prev, log: [...prev.log] };
      draft.laborPool -= cut;
      draft.ap -= 1;
      applyDelta(draft, { morale: -6, reputation: -4 });
      const body = language === 'es'
        ? `Recortaste ${cut} del grupo de Personal para aliviar el Gasto de aquí en adelante. -6 Moral, -4 Reputación. (El personal comprometido con locales abiertos o proyectos activos no puede tocarse.)`
        : `Cut ${cut} from the Labor pool to ease Burn going forward. -6 Morale, -4 Reputation. (Staff committed to open locations or active projects can't be touched.)`;
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'action', 'bad', t('Layoffs'), body), ...draft.log];
      return draft;
    });
  }

  function handleOperate(leaderId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const leader = prev.team.leaders.find(l => l.id === leaderId);
      if (!leader) return prev;
      const dLeader = localizeLeader(leader, language);
      // Each leader's Operate is once per month. Without this, three leaders on a team would
      // just be three interchangeable ways to spend the same Action Points, and the strongest
      // single ability would be spammed every turn. Per-leader gating makes the roster a set of
      // distinct monthly options rather than one option with a bigger budget.
      if ((prev.operatedThisMonth || []).includes(leaderId)) {
        return denyTicket(prev, dLeader.operateLabelDisplay,
          language === 'es'
            ? `${leader.name} ya actuó este mes.`
            : `${leader.name} has already acted this month.`, language);
      }
      if (prev.ap < 1) return denyTicket(prev, dLeader.operateLabelDisplay, t('No Action Points remaining this month.'), language);
      const draft = { ...prev, stats: { ...prev.stats }, log: [...prev.log], perkState: normalizePerkState(prev.perkState) };
      draft.operatedThisMonth = [...(prev.operatedThisMonth || []), leaderId];
      applyDelta(draft, leader.operate.deltas || {});
      draft.ap -= 1;

      // ---- Signature actives that DO something beyond deltas ----
      // Auto-targeted rather than prompting for a pick: the interesting decision in all three is
      // WHEN to spend the action, not which item to point it at, and auto-targeting keeps them
      // out of the modal-prompt plumbing entirely. Each returns its own ticket line.
      const oFx = founderFx(prev);
      const sigId = leader.signaturePerkId;
      let extraBody = '';

      if (sigId === 'masterScheduler' && draft.activeProjects.length) {
        // Pull in whichever project is furthest from done — the one actually gating progress.
        draft.activeProjects = draft.activeProjects.map(p => ({ ...p }));
        const target = draft.activeProjects.reduce((a, b) => (b.monthsLeft > a.monthsLeft ? b : a));
        if (target.monthsLeft > 1) {
          target.monthsLeft -= 1;
          const tProj = getIndustry(prev.industryId).content.projects.find(x => x.id === target.id);
          const tName = tProj ? localizeProject(tProj, language).name : target.id;
          extraBody = language === 'es'
            ? ` Reprogramaste ${tName}: un mes menos.`
            : ` You re-sequenced ${tName}: one month sooner.`;
        }
      }

      if (sigId === 'predictiveAnalytics') {
        const cd = oFx.suppressEventCooldown || 6;
        if (perkCadenceReady(draft.perkState, 'predictiveSuppress', prev.month, cd)) {
          // Suppression is consumed by NEXT month's event roll, so spending the action is a real
          // read of where the run is heading rather than a retroactive undo.
          draft.suppressNextEvent = true;
          stampPerkFire(draft, 'predictiveSuppress', prev.month, {});
          extraBody = language === 'es'
            ? ' El modelo señala el próximo mes: lo rodeas antes de que ocurra.'
            : ' The model flags next month, and you route around it before it happens.';
        } else {
          extraBody = language === 'es' ? ' (El modelo aún se recalibra.)' : ' (The model is still recalibrating.)';
        }
      }

      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'action', 'good',
        `${leader.name} — ${dLeader.operateLabelDisplay}`, dLeader.operateDescDisplay + extraBody), ...draft.log];
      return draft;
    });
  }

  // Skunkworks is a GENERAL perk with a once-per-run active, so it gets its own action rather
  // than riding on a leader's Operate slot. Completes the active project closest to done.
  function handleSkunkworks() {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const fx = founderFx(prev);
      const label = t('Skunkworks');
      if (!fx.skunkworksEligible) return denyTicket(prev, label, t('Not available.'), language);
      if (perkFiredOnce(prev.perkState, 'skunkworks')) {
        return denyTicket(prev, label, language === 'es' ? 'Ya lo usaste esta partida.' : 'Already used this run.', language);
      }
      if (prev.ap < 2) return denyTicket(prev, label, t('No Action Points remaining this month.'), language);
      const eligible = (prev.activeProjects || []).filter(p => p.monthsLeft <= 2);
      if (!eligible.length) {
        return denyTicket(prev, label,
          language === 'es' ? 'Ningún proyecto está lo bastante cerca de terminar.' : 'No project is close enough to finishing.',
          language);
      }
      const ind = getIndustry(prev.industryId);
      const draft = { ...prev, stats: { ...prev.stats }, log: [...prev.log], perkState: normalizePerkState(prev.perkState) };
      const target = eligible.reduce((a, b) => (b.monthsLeft < a.monthsLeft ? b : a));
      draft.activeProjects = prev.activeProjects.map(p => (p.id === target.id ? { ...p, monthsLeft: 0 } : { ...p }));
      draft.ap -= 2;
      stampPerkFire(draft, 'skunkworks', prev.month, { once: true });
      const proj = ind.content.projects.find(x => x.id === target.id);
      const pName = proj ? localizeProject(proj, language).name : target.id;
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'founder', 'good', label,
        language === 'es'
          ? `Un equipo pequeño trabajó de noche y ${pName} queda listo para el cierre de mes.`
          : `A small team worked nights, and ${pName} lands at month's end.`), ...draft.log];
      return draft;
    });
  }

  function handleRestCulture() {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      if (prev.ap < 1) return denyTicket(prev, t('Rest & Culture'), t('No Action Points remaining this month.'), language);
      const cost = 5;
      if (cost > prev.capital) return denyTicket(prev, t('Rest & Culture'), `${t('Needs')} ${fmtMoney(cost)} ${t('Capital')} (${t('you have')} ${fmtMoney(prev.capital)}).`, language);
      const draft = { ...prev, log: [...prev.log] };
      draft.capital -= cost;
      draft.ap -= 1;
      applyDelta(draft, { morale: 15, boardConfidence: 2 });
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'action', 'good', t('Rest & Culture'),
        `${language === 'es' ? 'El equipo se recompone.' : 'The team pulls itself together.'} (${deltaSummaryText({ morale: 15, boardConfidence: 2 }, language)})`), ...draft.log];
      return draft;
    });
  }

  // Closing a round is the decision; the terms are what you actually live with. A failed raise
  // still costs the AP and Presence — pitching badly has a price.
  function handleFundingInstrument(instrumentId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const ind = getIndustry(prev.industryId);
      const inst = (ind.fundingInstruments || []).find(x => x.id === instrumentId);
      if (!inst) return prev;
      const L = language === 'es' ? 'es' : 'en';
      const label = inst.name[L];

      if (prev.ap < (inst.cost.ap || 1)) return denyTicket(prev, label, t('No Action Points remaining this month.'), language);
      if ((inst.cost.presence || 0) > prev.presence) return denyTicket(prev, label, `${t('Needs')} ${inst.cost.presence} ${t('Presence')} (${t('you have')} ${prev.presence}).`, language);
      if ((prev.closedInstruments || []).includes(instrumentId)) {
        return denyTicket(prev, label, t('This round has already been closed.'), language);
      }

      const draft = { ...prev, stats: { ...prev.stats }, log: [...prev.log], activeTerms: [...(prev.activeTerms || [])] };

      // Who is actually across the table. Deterministic per instrument for this run's roster, so
      // the same round is always fronted by the same person.
      const stageIdF = stageOf(prev.month, ind.stages).id;
      const investor = investorForInstrument(prev, instrumentId, stageIdF);

      // Gating happens BEFORE any cost is charged — being turned down at the door shouldn't
      // consume the Action Point, because the player learns the rule by hitting it and charging
      // for that lesson makes the roster feel punitive rather than legible.
      if (investor) {
        const gate = investorGate(investor, prev, stageIdF);
        if (!gate.open) {
          return denyTicket(prev, `${label} — ${investor.name}`, gate.reasonText[L], language);
        }
      }

      draft.presence -= (inst.cost.presence || 0);
      draft.ap -= (inst.cost.ap || 1);

      // The investor's own terms replace the instrument's flat numbers.
      const terms = investorTerms(investor, inst, prev);
      const aBand = alignmentBand(terms.alignment);

      // Same Reputation x Board Confidence shape as Fundraise, so the two systems teach the same
      // lesson rather than contradicting each other — but successBase now carries the investor's
      // own reputation weighting, which for a contrarian is inverted.
      const repMult = draft.reputation / 100;
      const bcMult = 0.75 + (draft.boardConfidence / 100) * 0.5;
      const iFx = founderFx(prev);
      const chance = clamp(terms.successBase * repMult * bcMult + iFx.fundraiseChanceBonus,
        Math.max(4, iFx.fundraiseChanceFloor), 95);
      // Computed from `prev`, matching exactly what the instrument card's chip showed before
      // this click — the same investor, the same terms, nothing mutated yet.
      const preview = previewChance('instrument', prev, { instrument: inst, investor });
      const success = Math.random() * 100 < chance;
      recordForecastOutcome(draft, preview, success);

      if (!success) {
        const failDeltas = {
          morale: -Math.round(4 * iFx.fundraiseFailBCMult),
          boardConfidence: -Math.round(2 * iFx.fundraiseFailBCMult),
        };
        applyDelta(draft, failDeltas);
        const whoPassed = investor ? `${investor.name} ${language === 'es' ? 'declina' : 'passes'}.` : t('They pass. Word travels.');
        const modelNote = forecastOutcomeNote(preview, success, language);
        draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'action', 'bad', `${label} — ${t('Passed')}`,
          `${inst.blurb[L]} ${whoPassed}${modelNote}${deltaSummaryText(failDeltas, language) ? ` (${deltaSummaryText(failDeltas, language)})` : ''}`), ...draft.log];
        return draft;
      }

      const gain = terms.capitalLo + Math.floor(Math.random() * (terms.capitalHi - terms.capitalLo + 1));
      draft.capital += gain;
      draft.totalRaised = (draft.totalRaised || 0) + gain;
      draft.dilutionCount += 1;
      draft.equityGiven = (draft.equityGiven || 0) + terms.dilution;
      draft.closedInstruments = [...(prev.closedInstruments || []), instrumentId];
      applyDelta(draft, inst.onClose || {});
      if (inst.philosophy) {
        draft.philosophy = { ...(draft.philosophy || emptyPhilosophy()) };
        Object.entries(inst.philosophy).forEach(([axis, v]) => {
          draft.philosophy[axis] = clamp((draft.philosophy[axis] || 0) + v, -100, 100);
        });
      }

      // What this specific person brings beyond money. Jim Leonard walks your line; Günter Hess
      // buys you a machine; Billy McGrath brings a crowd. These are the reasons to prefer a
      // smaller cheque from the right person.
      let contributionLine = '';
      if (investor) {
        const b = investor.behavior || {};
        const contribution = {};
        if (b.operationsBonus) contribution.statBonus = { ...(contribution.statBonus || {}), operations: b.operationsBonus };
        if (b.innovationBonus) contribution.statBonus = { ...(contribution.statBonus || {}), innovation: b.innovationBonus };
        if (b.capacityBonus) contribution.capacity = b.capacityBonus;
        if (b.presenceBonus) contribution.presence = b.presenceBonus;
        if (b.networkBonus) contribution.reputation = 6;
        if (b.verticalBonus) contribution.burnReduction = 3;
        if (Object.keys(contribution).length) {
          applyDelta(draft, contribution);
          contributionLine = ` ${deltaSummaryText(contribution, language)}.`;
        }
        draft.investorBackers = { ...(draft.investorBackers || {}),
          [investor.id]: { month: prev.month, amount: gain, instrumentId, alignment: terms.alignment } };
        draft.investorRelationships = { ...(draft.investorRelationships || {}),
          [investor.name]: { type: inst.type, archetype: investor.archetype[L], instrumentId, month: prev.month, amount: gain } };

        const pressureTerm = investorTerm(investor, terms, prev.month, iFx.investorGraceMonthsBonus);
        if (pressureTerm) draft.activeTerms.push(pressureTerm);
      }

      const investorLine = investor
        ? (language === 'es'
          ? ` Liderada por ${investor.name} (${investor.archetype.es}) — relación ${aBand.label.es}.`
          : ` Led by ${investor.name} (${investor.archetype.en}) — a ${aBand.label.en.toLowerCase()} fit.`)
        : '';

      let termLine = '';
      if (inst.terms) {
        draft.activeTerms.push({ ...inst.terms, startedMonth: prev.month, instrumentId });
        termLine = ` ${language === 'es' ? 'Condiciones' : 'Terms'}: ${inst.terms.detail[L]}`;
      }

      const deltaText = deltaSummaryText({ ...(inst.onClose || {}), capital: gain }, language);
      const closeModelNote = forecastOutcomeNote(preview, success, language);
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'action', 'good', `${label} — ${t('Closed')}`,
        `${language === 'es' ? 'Recaudaste' : 'Raised'} ${fmtMoney(gain)} ${language === 'es' ? `por ${terms.dilution}% de participación.` : `for ${terms.dilution}% equity.`}${investorLine}${contributionLine}${termLine}${closeModelNote} (${deltaText})`), ...draft.log];
      return draft;
    });
  }

  // ============================== PRODUCT LIFECYCLE HANDLERS ==============================
  // IDEA is free and implicit (choosing which product to start IS the idea phase — there is no
  // separate "have an idea" click). Prototype/Testing/Production each require an explicit,
  // separately-costed commitment, matching Bible §A.3's "the player must feel they actually
  // developed this, not clicked Research." Intensity (lean/standard/thorough) is chosen at the
  // moment each phase is STARTED, not after — you decide how rigorous your test plan will be
  // before running it.
  function handleAdvanceProduct(productId, intensity) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const industry = getIndustry(prev.industryId);
      const def = PRODUCT_BY_ID[productId];
      if (!def || !industry.productCatalog || !industry.productCatalog.some(p => p.id === productId)) return prev;
      const L = language === 'es' ? 'es' : 'en';
      const intens = PRODUCT_INTENSITIES[intensity] ? intensity : 'standard';
      const existing = (prev.products || {})[productId];

      // ---- Starting a NEW product ----
      if (!existing) {
        const stageId = stageOf(prev.month, industry.stages).id;
        if (activeProductCount(prev) >= productSlotLimit(stageId)) {
          return denyTicket(prev, def.name.en,
            language === 'es' ? 'No hay espacio en el portafolio de productos en esta etapa.' : 'No room in the product portfolio at this stage.', language);
        }
        const profile = companyResourceProfile(prev, industry);
        const adj = productAdjacency(def, profile);
        // A company that has never built anything has nothing to BE adjacent to — the concept
        // only means something once there's a first product to measure against. Without this,
        // every company's first-ever product scores zero on every axis (no equipment owned yet,
        // no materials handled yet, no skills or channels yet) and would be permanently blocked,
        // which would make the industry unplayable at Pre-Seed rather than merely constrained.
        const isFirstEverProduct = Object.keys(prev.products || {}).length === 0;
        if (adj.band.id === 'unrelated' && !isFirstEverProduct) {
          return denyTicket(prev, def.name.en,
            language === 'es'
              ? 'Esto no tiene relación con lo que la empresa puede hacer hoy. Solo una adquisición o una nueva instalación podría abrir esto.'
              : 'This has nothing to do with what the company can do today. Only an acquisition or a new facility could open this up.', language);
        }
        const cost = productPhaseCost(def, 'prototype', intens, managerFx(prev));
        if (prev.ap < 1) return denyTicket(prev, def.name.en, t('No Action Points remaining this month.'), language);
        if (prev.capital < cost.capital) return denyTicket(prev, def.name.en, t('Not enough Capital.'), language);
        if (prev.presence < cost.presence) return denyTicket(prev, def.name.en, `${t('Needs')} ${cost.presence} ${t('Presence')}.`, language);
        const draft = { ...prev, products: { ...(prev.products || {}) }, log: [...prev.log] };
        draft.ap -= 1; draft.capital -= cost.capital; draft.presence -= cost.presence;
        draft.products[productId] = {
          productId, phase: 'prototype', phaseMonthsLeft: cost.duration, currentIntensity: intens,
          quality: null, defectRate: null, launchType: null, channelsOpened: [],
          appealBonus: 1, costReduction: 0, totalCapitalSpent: cost.capital, startedMonth: prev.month,
        };
        draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'product', 'good',
          `${t('New Product')} — ${def.name[L]}`,
          language === 'es'
            ? `Comienza el desarrollo de ${def.name.es} (${adj.band.label.es}, prototipo ${language==='es'?'esfuerzo':''} ${intens}). ${cost.duration} meses.`
            : `Development begins on ${def.name.en} (${adj.band.label.en}, ${intens} prototype). ${cost.duration} months.`), ...draft.log];
        return draft;
      }

      // ---- Still working the current phase ----
      if (existing.phaseMonthsLeft > 0) {
        return denyTicket(prev, def.name.en,
          language === 'es' ? 'Aún en progreso este mes.' : 'Still in progress this month.', language);
      }

      // ---- Committing to the NEXT phase ----
      const nextPhase = PRODUCT_PHASE_ORDER[PRODUCT_PHASE_ORDER_INDEX[existing.phase] + 1];
      if (!nextPhase || nextPhase === 'launched') {
        return denyTicket(prev, def.name.en,
          language === 'es' ? 'Lista para lanzar — usa Lanzar Producto.' : 'Ready to launch — use Launch Product instead.', language);
      }
      if (nextPhase === 'production') {
        const profile = companyResourceProfile(prev, industry);
        const missing = missingEquipmentTags(def, profile);
        if (missing.length) {
          return denyTicket(prev, def.name.en,
            language === 'es'
              ? `Falta capacidad: ${missing.join(', ')}. Completa un proyecto de ese tipo primero.`
              : `Missing capability: ${missing.join(', ')}. Complete a project of that type first.`, language);
        }
      }
      const cost = productPhaseCost(def, nextPhase, intens, managerFx(prev));
      if (prev.ap < 1) return denyTicket(prev, def.name.en, t('No Action Points remaining this month.'), language);
      if (prev.capital < cost.capital) return denyTicket(prev, def.name.en, t('Not enough Capital.'), language);
      if (prev.presence < cost.presence) return denyTicket(prev, def.name.en, `${t('Needs')} ${cost.presence} ${t('Presence')}.`, language);
      const draft = { ...prev, products: { ...(prev.products || {}) }, log: [...prev.log] };
      draft.ap -= 1; draft.capital -= cost.capital; draft.presence -= cost.presence;
      draft.products[productId] = {
        ...existing, phase: nextPhase, phaseMonthsLeft: cost.duration, currentIntensity: intens,
        totalCapitalSpent: (existing.totalCapitalSpent || 0) + cost.capital,
      };
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'product', 'good',
        `${def.name[L]} — ${t('Advancing')}`,
        language === 'es'
          ? `Entra en ${nextPhase} (esfuerzo ${intens}). ${cost.duration} meses.`
          : `Moving into ${nextPhase} (${intens}). ${cost.duration} months.`), ...draft.log];
      return draft;
    });
  }

  // The pivotal B2B/B2C fork (Bible §A.3, §D.1). Only reachable once Production has finished.
  function handleLaunchProduct(productId, launchType) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const def = PRODUCT_BY_ID[productId];
      const existing = (prev.products || {})[productId];
      if (!def || !existing) return prev;
      const L = language === 'es' ? 'es' : 'en';
      if (existing.phase !== 'production' || existing.phaseMonthsLeft > 0) {
        return denyTicket(prev, def.name.en, language === 'es' ? 'Aún no está lista para lanzar.' : 'Not ready to launch yet.', language);
      }
      if (launchType !== 'b2b' && launchType !== 'b2c') return prev;
      // Marketing spend scales with the product's own price ceiling — launching a premium
      // heirloom line costs more to introduce than a flat-pack table.
      const marketingCost = Math.round(def.priceCeiling * (launchType === 'b2c' ? 1.4 : 0.9));
      if (prev.ap < 1) return denyTicket(prev, def.name.en, t('No Action Points remaining this month.'), language);
      if (prev.capital < marketingCost) return denyTicket(prev, def.name.en, t('Not enough Capital.'), language);
      const draft = { ...prev, products: { ...prev.products }, log: [...prev.log] };
      draft.ap -= 1; draft.capital -= marketingCost;
      const segments = launchType === 'b2c' ? B2C_SEGMENTS : B2B_SEGMENTS;
      const channelsOpened = (def.resourceProfile.channels || [])
        .filter(c => segments.includes(c) && (def.appealSegments[c] || 0) > 0);
      draft.products[productId] = { ...existing, phase: 'launched', phaseMonthsLeft: 0, launchType, channelsOpened,
        // Finished-goods inventory starts empty with sane defaults — Balanced production,
        // Sell All sales. A player who wants to speculate on price switches stances explicitly.
        stock: 0, lots: [], launchedMonth: prev.month, productionStance: 'balanced', salesStance: 'sellAll',
        holdPriceFloor: defaultHoldPriceFloor(def), lastProducedUnits: 0, lastSoldUnits: 0 };
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'product', 'good',
        `${t('Launch')} — ${def.name[L]}`,
        language === 'es'
          ? `Lanzado como ${launchType === 'b2c' ? 'consumo directo' : 'negocio a negocio'}, dirigido a: ${channelsOpened.join(', ') || 'ningún segmento con atractivo'}.`
          : `Launched ${launchType === 'b2c' ? 'direct-to-consumer' : 'B2B'}, reaching: ${channelsOpened.join(', ') || 'no segments with real appeal'}.`), ...draft.log];
      return draft;
    });
  }

  // Iteration — the loop back from Market Feedback (Bible's lifecycle diagram). A standing,
  // repeatable spend on a launched product, not a phase you leave.
  function handleIterateProduct(productId, focus) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const def = PRODUCT_BY_ID[productId];
      const existing = (prev.products || {})[productId];
      if (!def || !existing || existing.phase !== 'launched') return prev;
      const L = language === 'es' ? 'es' : 'en';
      const cost = Math.round(def.materialCost * 3 + def.complexity * 3);
      if (prev.ap < 1) return denyTicket(prev, def.name.en, t('No Action Points remaining this month.'), language);
      if (prev.capital < cost) return denyTicket(prev, def.name.en, t('Not enough Capital.'), language);
      const draft = { ...prev, products: { ...prev.products }, log: [...prev.log] };
      draft.ap -= 1; draft.capital -= cost;
      const inst = { ...existing };
      let note = '';
      if (focus === 'quality') {
        inst.quality = clamp((inst.quality || def.qualityCeiling) + QUALITY_ITERATE_STEP, 1, def.qualityCeiling);
        note = language === 'es' ? `Calidad ${inst.quality}/${def.qualityCeiling}.` : `Quality now ${inst.quality}/${def.qualityCeiling}.`;
      } else if (focus === 'cost') {
        inst.costReduction = clamp((inst.costReduction || 0) + 0.08, 0, 0.4);
        note = language === 'es' ? `Costo reducido ${Math.round(inst.costReduction * 100)}%.` : `Cost reduced ${Math.round(inst.costReduction * 100)}% from baseline.`;
      } else { // appeal
        inst.appealBonus = clamp((inst.appealBonus || 1) + 0.12, 1, 1.8);
        note = language === 'es' ? 'El atractivo de mercado mejora.' : 'Market appeal improves.';
      }
      draft.products[productId] = inst;
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'product', 'good',
        `${t('Iterate')} — ${def.name[L]}`, note), ...draft.log];
      return draft;
    });
  }

  function handleRetireProduct(productId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const def = PRODUCT_BY_ID[productId];
      const existing = (prev.products || {})[productId];
      if (!def || !existing || existing.phase === 'retired') return prev;
      const L = language === 'es' ? 'es' : 'en';
      const draft = { ...prev, products: { ...prev.products }, log: [...prev.log] };
      draft.products[productId] = { ...existing, phase: 'retired', phaseMonthsLeft: 0 };
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'product', 'mixed',
        `${t('Retired')} — ${def.name[L]}`,
        language === 'es' ? 'La línea se cierra.' : 'The line is wound down.'), ...draft.log];
      return draft;
    });
  }

  // Pivot: retire early and salvage something from the sunk cost — organisational learning
  // rather than nothing. Deliberately worse than finishing what you started; it exists so a
  // clearly-doomed product isn't a total loss, not so pivoting is ever the plan.
  function handlePivotProduct(productId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const def = PRODUCT_BY_ID[productId];
      const existing = (prev.products || {})[productId];
      if (!def || !existing || existing.phase === 'retired' || existing.phase === 'launched') return prev;
      const L = language === 'es' ? 'es' : 'en';
      const draft = { ...prev, products: { ...prev.products }, log: [...prev.log] };
      const refund = Math.round((existing.totalCapitalSpent || 0) * 0.25);
      applyDelta(draft, { capital: refund, statBonus: { innovation: 1 } });
      draft.products[productId] = { ...existing, phase: 'retired', phaseMonthsLeft: 0 };
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'product', 'mixed',
        `${t('Pivot')} — ${def.name[L]}`,
        language === 'es'
          ? `Abandonado antes de lanzar. Se recupera ${fmtMoney(refund)} y una lección de innovación. (${deltaSummaryText({ capital: refund, statBonus: { innovation: 1 } }, language)})`
          : `Abandoned before launch. Recovers ${fmtMoney(refund)} and a lesson in innovation. (${deltaSummaryText({ capital: refund, statBonus: { innovation: 1 } }, language)})`), ...draft.log];
      return draft;
    });
  }

  // Free to change, effective from next month's tick — a standing policy choice, not a spend.
  function handleSetMaintenanceStance(equipmentId, stance) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const eq = (prev.equipment || {})[equipmentId];
      const catalogEntry = EQUIPMENT_CATALOG[equipmentId];
      if (!eq || !catalogEntry || !MAINTENANCE_STANCES[stance]) return prev;
      if (eq.stance === stance) return prev;
      const draft = { ...prev, equipment: { ...prev.equipment }, log: [...prev.log] };
      draft.equipment[equipmentId] = { ...eq, stance };
      const eqName = catalogEntry.name[language === 'es' ? 'es' : 'en'];
      const stanceLabel = MAINTENANCE_STANCES[stance].label[language === 'es' ? 'es' : 'en'];
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'equipment', 'neutral',
        `${t('Maintenance')} — ${eqName}`,
        language === 'es' ? `Postura cambiada a ${stanceLabel}.` : `Stance changed to ${stanceLabel}.`), ...draft.log];
      return draft;
    });
  }

  // Replace — a one-time capex action, not a stance. Resets condition to new, and carries a real
  // chance of coming back with one more automation level than it had (Bible §B.2: "Replacement
  // ... reset condition, chance to raise automation").
  function handleReplaceEquipment(equipmentId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const eq = (prev.equipment || {})[equipmentId];
      const catalogEntry = EQUIPMENT_CATALOG[equipmentId];
      if (!eq || !catalogEntry) return prev;
      const label = catalogEntry.name[language === 'es' ? 'es' : 'en'];
      // Cost scales with what the machine is worth, not a flat number — replacing a megaline
      // should cost more than replacing a workbench.
      const cost = Math.round(catalogEntry.maintenanceCost * 8 + catalogEntry.capacityContribution * 15);
      if (prev.ap < 1) return denyTicket(prev, label, t('No Action Points remaining this month.'), language);
      if (prev.capital < cost) return denyTicket(prev, label, t('Not enough Capital.'), language);
      const draft = { ...prev, equipment: { ...prev.equipment }, log: [...prev.log] };
      draft.ap -= 1; draft.capital -= cost;
      const automationBump = Math.random() < 0.25 && eq.automationLevel < 3;
      draft.equipment[equipmentId] = {
        ...eq, condition: 100, downtimeMonthsLeft: 0,
        automationLevel: automationBump ? eq.automationLevel + 1 : eq.automationLevel,
      };
      const bumpNote = automationBump
        ? (language === 'es' ? ' El reemplazo llega con un nivel de automatización más alto.' : ' The replacement arrives one automation level higher.')
        : '';
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'equipment', 'good',
        `${t('Replace')} — ${label}`,
        (language === 'es' ? `Máquina nueva instalada. (${fmtMoney(cost)})` : `New machine installed. (${fmtMoney(cost)})`) + bumpNote), ...draft.log];
      return draft;
    });
  }

  // Byproduct policy: a standing choice per waste stream, free to change. Deliberately free —
  // the decision that costs something is whether you BUILT the line that eats it.
  function handleSetByproductPolicy(byproductId, policyId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const bp = BYPRODUCTS[byproductId];
      const pol = BYPRODUCT_POLICIES[policyId];
      if (!bp || !pol) return prev;
      const L = language === 'es' ? 'es' : 'en';
      if (policyId === 'reuse' && !reuseAvailable(prev, byproductId)) {
        return denyTicket(prev, bp.name[L],
          L === 'es'
            ? 'No tienes una línea que consuma esto todavía. Constrúyela y esto se vuelve gratis.'
            : 'You have no line that consumes this yet. Build it and this becomes free.', language);
      }
      if (policyId === 'burn' && bp.energyValue <= 0) {
        return denyTicket(prev, bp.name[L],
          L === 'es' ? 'Esto no arde de forma útil.' : 'This does not usefully burn.', language);
      }
      if ((prev.byproductPolicies || {})[byproductId] === policyId) return prev;
      const draft = { ...prev, byproductPolicies: { ...prev.byproductPolicies }, log: [...prev.log] };
      draft.byproductPolicies[byproductId] = policyId;
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'byproduct', 'neutral',
        `${bp.name[L]} — ${pol.label[L]}`, pol.blurb[L]), ...draft.log];
      return draft;
    });
  }

  // ---------------------------------------------------------------- brand & marketing
  // A standing policy, set once and adjusted — not a decision to re-make every month. Free to
  // change, like every other stance in this game; the money is the cost, not the attention.
  function handleSetMarketingPolicy(policyId, targetSegmentId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const L = language === 'es' ? 'es' : 'en';
      const policy = marketingPolicy(policyId);
      const seg = targetSegmentId ? consumerSegment(targetSegmentId) : null;
      const draft = { ...prev, marketingPolicy: policy.id, marketingTarget: seg ? seg.id : null, log: [...prev.log] };
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'product', 'neutral', t('Brand'),
        L === 'es'
          ? `Marketing puesto en ${policy.label.es}${seg ? `, dirigido a ${seg.name.es}` : ' (general)'}. ${policy.blurb.es}`
          : `Marketing set to ${policy.label.en}${seg ? `, aimed at ${seg.name.en}` : ' (broad)'}. ${policy.blurb.en}`), ...draft.log];
      return draft;
    });
  }

  // A campaign is a PUSH: costs AP and money, delivers a burst of strength now rather than a
  // trickle. Targeting one segment costs more and hits harder, and drags position with it.
  function handleBrandCampaign(targetSegmentId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const L = language === 'es' ? 'es' : 'en';
      const seg = targetSegmentId ? consumerSegment(targetSegmentId) : null;
      const scaleBase = Math.max(10, Math.round((prev.revenuePerMonth || 0) * 0.14) + 10);
      const cost = Math.round(scaleBase * (seg ? TARGETED_MARKETING_PREMIUM : 1));
      if (prev.ap < CAMPAIGN_AP_COST) return denyTicket(prev, t('Brand Campaign'), t('No Action Points remaining this month.'), language);
      if (prev.capital < cost) return denyTicket(prev, t('Brand Campaign'), t('Not enough Capital.'), language);

      const draft = { ...prev, brand: { ...(prev.brand || { strength: 0, position: {} }) }, log: [...prev.log] };
      draft.ap -= CAMPAIGN_AP_COST;
      draft.capital -= cost;
      const burst = seg ? CAMPAIGN_TARGETED_BURST : CAMPAIGN_STRENGTH_BURST;
      // The soft ceiling applies to campaigns too — a burst cannot buy a reputation you lack.
      const ceiling = brandCeiling(draft);
      let next = (draft.brand.strength || 0) + burst;
      if (next > ceiling) next = ceiling + (next - ceiling) * 0.25;
      draft.brand.strength = clamp(next, 0, 100);

      if (seg) {
        // A targeted campaign moves position hard toward that audience — this is the lever for
        // deliberately repositioning rather than being slowly defined by what you make.
        const pos = brandPosition(draft);
        const pull = 0.3;
        draft.brand.position = {
          premiumVsMass: pos.premiumVsMass + (seg.premiumVsMass - pos.premiumVsMass) * pull,
          sustainability: pos.sustainability + (seg.sustainability - pos.sustainability) * pull,
          noveltyVsHeritage: pos.noveltyVsHeritage + (seg.noveltyVsHeritage - pos.noveltyVsHeritage) * pull,
        };
      }
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'product', 'good', t('Brand Campaign'),
        L === 'es'
          ? `${seg ? `Campaña dirigida a ${seg.name.es}` : 'Campaña general'} por ${fmtMoney(cost)}. Fuerza de marca ahora ${Math.round(draft.brand.strength)}.`
          : `${seg ? `Campaign aimed at ${seg.name.en}` : 'Broad campaign'} for ${fmtMoney(cost)}. Brand strength now ${Math.round(draft.brand.strength)}.`), ...draft.log];
      return draft;
    });
  }

  // ---------------------------------------------------------------- buyer discovery
  // Targeted sourcing: you go looking for customers for a SPECIFIC line, not for buyers in
  // general. Gated on the same research as contract solicitation, since knowing how to find
  // buyers and knowing how to approach them are the same capability.
  function handleScoutBuyers(productId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const L = language === 'es' ? 'es' : 'en';
      const def = PRODUCT_BY_ID[productId];
      const label = def ? def.name[L] : productId;
      if (!canSolicitContracts(prev)) {
        return denyTicket(prev, label,
          L === 'es' ? 'Necesitas completar Buscar Compradores Potenciales primero.'
                     : 'You need to complete Source Potential Buyers first.', language);
      }
      const inst = (prev.products || {})[productId];
      if (!def || !inst || inst.phase !== 'launched') {
        return denyTicket(prev, label,
          L === 'es' ? 'Esa línea aún no está lanzada.' : 'That line is not launched yet.', language);
      }
      if (prev.ap < SCOUT_BUYERS_COST.ap) return denyTicket(prev, label, t('No Action Points remaining this month.'), language);
      if (prev.presence < SCOUT_BUYERS_COST.presence) return denyTicket(prev, label, `${t('Needs')} ${SCOUT_BUYERS_COST.presence} ${t('Presence')}.`, language);
      if (prev.capital < SCOUT_BUYERS_COST.capital) return denyTicket(prev, label, t('Not enough Capital.'), language);

      const pool = undiscoveredBuyersFor(prev, productId);
      if (!pool.length) {
        return denyTicket(prev, label,
          L === 'es' ? 'Ya conoces a todos los compradores de esta línea.'
                     : 'You already know every buyer for this line.', language);
      }
      const found = pool[Math.floor(Math.random() * pool.length)];
      const draft = { ...prev, discoveredBuyers: [...(prev.discoveredBuyers || []), found.id], log: [...prev.log] };
      draft.ap -= SCOUT_BUYERS_COST.ap;
      draft.presence -= SCOUT_BUYERS_COST.presence;
      draft.capital -= SCOUT_BUYERS_COST.capital;
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'contract', 'good',
        `${t('Buyer Found')} — ${found.name}`,
        L === 'es'
          ? `${found.name} compra ${label}. ${found.tell.es} Ahora puedes ofrecerles un contrato.`
          : `${found.name} buys ${label}. ${found.tell.en} You can offer them a contract now.`), ...draft.log];
      return draft;
    });
  }

  // A trade show is a WINDOW, not an action you can take whenever you like. While it is open,
  // finding buyers is cheap and broad; when it closes, it closes.
  function handleAttendTradeShow() {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const L = language === 'es' ? 'es' : 'en';
      const show = prev.tradeShow;
      if (!show || show.endsMonth <= prev.month) {
        return denyTicket(prev, t('Trade Show'),
          L === 'es' ? 'No hay ninguna feria abierta ahora mismo.' : 'No trade show is open right now.', language);
      }
      if (show.attended) {
        return denyTicket(prev, t('Trade Show'),
          L === 'es' ? 'Ya asististe a esta feria.' : 'You already worked this show.', language);
      }
      if (prev.ap < 1) return denyTicket(prev, t('Trade Show'), t('No Action Points remaining this month.'), language);
      if (prev.capital < show.cost) return denyTicket(prev, t('Trade Show'), t('Not enough Capital.'), language);

      // A show surfaces buyers across every line the company actually sells.
      const launched = Object.values(prev.products || {}).filter(i => i.phase === 'launched').map(i => i.productId);
      const pool = [];
      launched.forEach(pid => undiscoveredBuyersFor(prev, pid).forEach(b => { if (!pool.some(x => x.id === b.id)) pool.push(b); }));
      const draft = { ...prev, tradeShow: { ...show, attended: true }, log: [...prev.log] };
      draft.ap -= 1;
      draft.capital -= show.cost;
      applyDelta(draft, { reputation: 3 });
      if (!pool.length) {
        draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'contract', 'neutral', t('Trade Show'),
          L === 'es'
            ? 'Trabajaste el salón entero y no encontraste a nadie nuevo. Al menos te vieron.'
            : 'You worked the whole floor and met nobody new. At least you were seen.'), ...draft.log];
        return draft;
      }
      const take = Math.min(pool.length, show.reach);
      const found = pool.sort(() => Math.random() - 0.5).slice(0, take);
      draft.discoveredBuyers = [...(prev.discoveredBuyers || []), ...found.map(b => b.id)];
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'contract', 'good', t('Trade Show'),
        L === 'es'
          ? `Tres días de apretones de manos. Conociste a ${found.map(b => b.name).join(', ')}.`
          : `Three days of handshakes. You met ${found.map(b => b.name).join(', ')}.`), ...draft.log];
      return draft;
    });
  }

  // An investor who rates you spends some of their own credibility on your behalf. Once each.
  function handleRequestIntroduction(investorId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const L = language === 'es' ? 'es' : 'en';
      const inv = INVESTOR_BY_ID[investorId];
      if (!inv) return prev;
      const standing = (prev.investorStandings || {})[investorId] || 0;
      if (standing < INTRODUCTION_MIN_STANDING) {
        return denyTicket(prev, inv.name,
          L === 'es' ? 'Tu relación con ellos no da para pedir un favor así todavía.'
                     : 'Your standing with them does not stretch to that favour yet.', language);
      }
      if ((prev.usedIntroductions || []).includes(investorId)) {
        return denyTicket(prev, inv.name,
          L === 'es' ? 'Ya te presentaron a alguien. No van a repetir.'
                     : 'They already made an introduction for you. They will not do it twice.', language);
      }
      if (prev.ap < 1) return denyTicket(prev, inv.name, t('No Action Points remaining this month.'), language);
      const launched = Object.values(prev.products || {}).filter(i => i.phase === 'launched').map(i => i.productId);
      const pool = [];
      launched.forEach(pid => undiscoveredBuyersFor(prev, pid).forEach(b => { if (!pool.some(x => x.id === b.id)) pool.push(b); }));
      if (!pool.length) {
        return denyTicket(prev, inv.name,
          L === 'es' ? 'No conocen a nadie que no conozcas ya.' : 'They know nobody you do not already know.', language);
      }
      // An introduction is warmer than a cold approach: it starts you above zero with that buyer.
      const found = pool[Math.floor(Math.random() * pool.length)];
      const draft = {
        ...prev,
        discoveredBuyers: [...(prev.discoveredBuyers || []), found.id],
        usedIntroductions: [...(prev.usedIntroductions || []), investorId],
        log: [...prev.log],
      };
      draft.ap -= 1;
      adjustBuyerStanding(draft, found.id, 12);
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'contract', 'good',
        `${t('Introduction')} — ${found.name}`,
        L === 'es'
          ? `${inv.name} te presentó a ${found.name}. Llegas recomendado, no en frío.`
          : `${inv.name} introduced you to ${found.name}. You arrive recommended, not cold.`), ...draft.log];
      return draft;
    });
  }

  // ---------------------------------------------------------------- sales contracts
  function handleAcceptSalesContract(offerId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const offer = (prev.salesContractOffers || []).find(o => o.id === offerId);
      if (!offer) return prev;
      const L = language === 'es' ? 'es' : 'en';
      const def = PRODUCT_BY_ID[offer.productId];
      const label = def ? def.name[L] : offer.productId;
      if (offer.expiresMonth <= prev.month) {
        return denyTicket(prev, label, L === 'es' ? 'Esa oferta ya venció.' : 'That offer has expired.', language);
      }
      // Q5: one live contract per counterparty at a time.
      if (hasActiveContractWith(prev, offer.counterpartyId)) {
        return denyTicket(prev, label,
          L === 'es' ? `Ya tienes un contrato activo con ${offer.counterpartyName}.`
                     : `You already have an active contract with ${offer.counterpartyName}.`, language);
      }
      const term = salesContractTerm(offer.termId);
      const draft = {
        ...prev,
        salesContracts: [...(prev.salesContracts || []), {
          id: offer.id, productId: offer.productId,
          counterpartyId: offer.counterpartyId, counterpartyName: offer.counterpartyName,
          termId: offer.termId, unitsPerMonth: offer.unitsPerMonth,
          lockedPrice: offer.lockedPrice, monthsLeft: offer.months, signedMonth: prev.month,
        }],
        salesContractOffers: (prev.salesContractOffers || []).filter(o => o.id !== offerId),
        log: [...prev.log],
      };
      // Committing to a named buyer is a public signal that someone trusts your output.
      applyDelta(draft, { reputation: 2 });
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'contract', 'good',
        `${t('Sales Contract Signed')} — ${offer.counterpartyName}`,
        L === 'es'
          ? `${offer.unitsPerMonth} unidades de ${label} al mes, ${offer.months} meses, a ${fmtMoney(offer.lockedPrice)}/u fijo. Tu producción no se ajusta sola — asegúrate de tener la capacidad.`
          : `${offer.unitsPerMonth} units of ${label} a month for ${offer.months} months at ${fmtMoney(offer.lockedPrice)}/u locked. Your production does not adjust on its own — make sure the capacity is there.`), ...draft.log];
      return draft;
    });
  }

  function handleDeclineSalesContract(offerId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      if (!(prev.salesContractOffers || []).some(o => o.id === offerId)) return prev;
      return { ...prev, salesContractOffers: prev.salesContractOffers.filter(o => o.id !== offerId) };
    });
  }

  // Going out and finding a buyer, rather than waiting for one. Gated on the research project.
  function handleSolicitContract(productId, counterpartyId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const L = language === 'es' ? 'es' : 'en';
      const def = PRODUCT_BY_ID[productId];
      const inst = (prev.products || {})[productId];
      const label = def ? def.name[L] : productId;
      if (!canSolicitContracts(prev)) {
        return denyTicket(prev, label,
          L === 'es' ? 'Necesitas completar Buscar Compradores Potenciales primero.'
                     : 'You need to complete Source Potential Buyers first.', language);
      }
      if (!def || !inst || inst.phase !== 'launched') {
        return denyTicket(prev, label,
          L === 'es' ? 'Ese producto aún no está lanzado.' : 'That product is not launched yet.', language);
      }
      if (prev.ap < 1) return denyTicket(prev, label, t('No Action Points remaining this month.'), language);
      if (prev.presence < 1) return denyTicket(prev, label, `${t('Needs')} 1 ${t('Presence')}.`, language);
      const buyers = potentialBuyers(prev).filter(b => !counterpartyId || b.id === counterpartyId);
      if (!buyers.length) {
        return denyTicket(prev, label,
          L === 'es' ? 'Nadie disponible con quien firmar ahora mismo.' : 'Nobody available to sign with right now.', language);
      }
      const capacity = productCapacityContribution(inst, def, prev);
      if (capacity <= 0) {
        return denyTicket(prev, label,
          L === 'es' ? 'Esa línea no está produciendo nada — no hay nada que prometer.'
                     : 'That line is producing nothing — there is nothing to promise.', language);
      }
      const buyer = buyers[Math.floor(Math.random() * buyers.length)];
      const mp = (prev.market && prev.market[productId]) ? prev.market[productId].price : def.priceFloor;
      // A solicited buyer negotiates harder than one who came to you: shorter terms only.
      const termIds = ['trial', 'standard'];
      const termId = termIds[Math.floor(Math.random() * termIds.length)];
      const offer = makeSalesContractOffer(prev, productId, buyer, termId, prev.month, mp, capacity);
      const draft = { ...prev, salesContractOffers: [...(prev.salesContractOffers || []), offer], log: [...prev.log] };
      draft.ap -= 1;
      draft.presence -= 1;
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'contract', 'good',
        `${t('Contract Offer')} — ${buyer.name}`,
        L === 'es'
          ? `${buyer.name} respondió: ${offer.unitsPerMonth} unidades/mes de ${label} por ${offer.months} meses a ${fmtMoney(offer.lockedPrice)}/u. Pendiente de tu aceptación.`
          : `${buyer.name} came back with: ${offer.unitsPerMonth} units/mo of ${label} for ${offer.months} months at ${fmtMoney(offer.lockedPrice)}/u. Pending your acceptance.`), ...draft.log];
      return draft;
    });
  }

  // ---------------------------------------------------------------- spot market trading
  // Buying and selling on the open market, outside any contract. Deliberately WORSE than a
  // contract per unit — the spread is what makes contracts worth signing — but available
  // instantly with no commitment. This is the "in a pinch" and "stockpile while cheap" valve.
  const SPOT_BUY_PREMIUM = 1.18;  // you pay above market to buy without a relationship
  const SPOT_SELL_DISCOUNT = 0.85; // you take below market to dump without a buyer lined up

  function handleSpotBuy(entityId, units) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const e = econEntity(entityId);
      const cell = prev.market && prev.market[entityId];
      if (!e || !cell) return prev;
      const L = language === 'es' ? 'es' : 'en';
      const qty = Math.max(1, Math.round(units || 0));
      const cost = Math.round(cell.price * SPOT_BUY_PREMIUM * qty * 10) / 10;
      // No AP cost: the spot market is instant and uncommitted by design — that immediacy is
      // exactly what you pay the 18% premium for. Charging AP on top would make it compete with
      // deliberate actions for the same scarce resource, which defeats "in a pinch."
      if (prev.capital < cost) return denyTicket(prev, e.name[L], t('Not enough Capital.'), language);
      const draft = { ...prev, spotHoldings: { ...(prev.spotHoldings || {}) }, log: [...prev.log] };
      draft.capital -= cost;
      draft.spotHoldings[entityId] = (draft.spotHoldings[entityId] || 0) + qty;
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'market', 'neutral',
        `${t('Spot Purchase')} — ${e.name[L]}`,
        L === 'es'
          ? `Compraste ${qty} unidades a ${fmtMoney(cell.price * SPOT_BUY_PREMIUM)}/u (prima del ${Math.round((SPOT_BUY_PREMIUM - 1) * 100)}% sobre mercado). Total ${fmtMoney(cost)}.`
          : `Bought ${qty} units at ${fmtMoney(cell.price * SPOT_BUY_PREMIUM)}/u (${Math.round((SPOT_BUY_PREMIUM - 1) * 100)}% over market). Total ${fmtMoney(cost)}.`), ...draft.log];
      return draft;
    });
  }

  function handleSpotSell(entityId, units) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const e = econEntity(entityId);
      const cell = prev.market && prev.market[entityId];
      if (!e || !cell) return prev;
      const L = language === 'es' ? 'es' : 'en';
      // Sellable: raw stock bought on spot, OR finished goods this company actually made.
      const spotHeld = (prev.spotHoldings || {})[entityId] || 0;
      const productInst = (prev.products || {})[entityId];
      const madeStock = productInst && productInst.phase === 'launched' ? totalStock(productInst) : 0;
      const available = spotHeld + madeStock;
      const qty = Math.min(Math.max(1, Math.round(units || 0)), Math.floor(available));
      if (qty <= 0) {
        return denyTicket(prev, e.name[L],
          L === 'es' ? 'No tienes nada de esto para vender.' : 'You hold none of this to sell.', language);
      }
      // No AP cost here either — same reasoning as the buy side.
      const proceeds = Math.round(cell.price * SPOT_SELL_DISCOUNT * qty * 10) / 10;
      const draft = { ...prev, spotHoldings: { ...(prev.spotHoldings || {}) }, products: { ...prev.products }, log: [...prev.log] };
      draft.capital += proceeds;
      // Draw from purchased spot stock first, then from your own finished goods.
      const fromSpot = Math.min(spotHeld, qty);
      if (fromSpot > 0) draft.spotHoldings[entityId] = spotHeld - fromSpot;
      const fromMade = qty - fromSpot;
      if (fromMade > 0 && productInst) {
        const drawResult = drawFromLots(lotsOf(productInst), fromMade);
        // Degraded lots fetch less on the spot market too — the discount already applied above
        // assumed face value, so refund the difference the player did NOT actually earn.
        const drawnRatio = drawResult.drawn.length
          ? drawResult.drawn.reduce((s2, l) => s2 + l.units * lotValueRatio(l, entityId, prev.month || 0, prev), 0)
            / Math.max(1, drawResult.drawn.reduce((s2, l) => s2 + l.units, 0))
          : 1;
        if (drawnRatio < 1) {
          const facePortion = Math.round(cell.price * SPOT_SELL_DISCOUNT * fromMade * 100) / 100;
          draft.capital -= Math.round(facePortion * (1 - drawnRatio) * 100) / 100;
        }
        draft.products[entityId] = { ...productInst, lots: drawResult.kept, stock: totalStock({ lots: drawResult.kept }) };
      }
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'market', 'good',
        `${t('Spot Sale')} — ${e.name[L]}`,
        L === 'es'
          ? `Vendiste ${qty} unidades a ${fmtMoney(cell.price * SPOT_SELL_DISCOUNT)}/u (descuento del ${Math.round((1 - SPOT_SELL_DISCOUNT) * 100)}% bajo mercado). Total ${fmtMoney(proceeds)}.`
          : `Sold ${qty} units at ${fmtMoney(cell.price * SPOT_SELL_DISCOUNT)}/u (${Math.round((1 - SPOT_SELL_DISCOUNT) * 100)}% under market). Total ${fmtMoney(proceeds)}.`), ...draft.log];
      return draft;
    });
  }

  // ---------------------------------------------------------------- mothballing
  // Closing a plant cuts its overhead during a downturn. Reopening costs an AP, Presence, and a
  // full month of warm-up before it produces again — so this is a real bet on how long the
  // downturn lasts, not a free toggle.
  function handleToggleTierOpen(tierId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const tier = chainTier(tierId);
      if (!tier || !ownsTier(prev, tierId)) return prev;
      const L = language === 'es' ? 'es' : 'en';
      const owned = (prev.ownedTiers || {})[tierId] || {};
      const closing = !owned.mothballed;
      if (closing) {
        const draft = { ...prev, ownedTiers: { ...prev.ownedTiers }, log: [...prev.log] };
        draft.ownedTiers[tierId] = { ...owned, mothballed: true, warmupMonthsLeft: 0 };
        draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'integration', 'mixed',
          `${t('Plant Closed')} — ${tier.name[L]}`,
          L === 'es'
            ? `Cerrada temporalmente. Ahorras ${fmtMoney(tier.monthlyOverhead)}/mes, pero no produce nada mientras esté cerrada.`
            : `Temporarily closed. You save ${fmtMoney(tier.monthlyOverhead)}/mo, but it produces nothing while shut.`), ...draft.log];
        return draft;
      }
      // Reopening
      if (prev.ap < 1) return denyTicket(prev, tier.name[L], t('No Action Points remaining this month.'), language);
      if (prev.presence < 2) return denyTicket(prev, tier.name[L], `${t('Needs')} 2 ${t('Presence')}.`, language);
      const draft = { ...prev, ownedTiers: { ...prev.ownedTiers }, log: [...prev.log] };
      draft.ap -= 1;
      draft.presence -= 2;
      draft.ownedTiers[tierId] = { ...owned, mothballed: false, warmupMonthsLeft: 1 };
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'integration', 'good',
        `${t('Plant Reopening')} — ${tier.name[L]}`,
        L === 'es'
          ? 'Reabriendo. Un mes de arranque antes de que vuelva a producir.'
          : 'Reopening. One month of warm-up before it produces again.'), ...draft.log];
      return draft;
    });
  }

  // Production stance — free to change, a standing policy like every other stance in this game.
  // Takes effect next month, since this month's production has already been decided by the time
  // a player is reacting to what happened.
  function handleSetProductionStance(productId, stanceId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const def = PRODUCT_BY_ID[productId];
      const existing = (prev.products || {})[productId];
      if (!def || !existing || existing.phase !== 'launched' || !PRODUCTION_STANCES[stanceId]) return prev;
      if (existing.productionStance === stanceId) return prev;
      const L = language === 'es' ? 'es' : 'en';
      const draft = { ...prev, products: { ...prev.products }, log: [...prev.log] };
      draft.products[productId] = { ...existing, productionStance: stanceId };
      const stance = PRODUCTION_STANCES[stanceId];
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'product', 'neutral',
        `${def.name[L]} — ${stance.label[L]}`, stance.blurb[L]), ...draft.log];
      return draft;
    });
  }

  // Sales stance — Hold for Price takes an optional floor; omitted, it defaults to a sensible
  // fraction of the product's own price ceiling rather than leaving it unset and never selling.
  function handleSetSalesStance(productId, stanceId, holdPriceFloor) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const def = PRODUCT_BY_ID[productId];
      const existing = (prev.products || {})[productId];
      if (!def || !existing || existing.phase !== 'launched' || !SALES_STANCES[stanceId]) return prev;
      const nextFloor = stanceId === 'holdForPrice'
        ? (holdPriceFloor != null ? Math.max(0, Math.round(holdPriceFloor)) : (existing.holdPriceFloor != null ? existing.holdPriceFloor : defaultHoldPriceFloor(def)))
        : existing.holdPriceFloor;
      if (existing.salesStance === stanceId && nextFloor === existing.holdPriceFloor) return prev;
      const L = language === 'es' ? 'es' : 'en';
      const draft = { ...prev, products: { ...prev.products }, log: [...prev.log] };
      draft.products[productId] = { ...existing, salesStance: stanceId, holdPriceFloor: nextFloor };
      const stance = SALES_STANCES[stanceId];
      const floorNote = stanceId === 'holdForPrice'
        ? (L === 'es' ? ` Mínimo: ${fmtMoney(nextFloor)}.` : ` Floor: ${fmtMoney(nextFloor)}.`)
        : '';
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'product', 'neutral',
        `${def.name[L]} — ${stance.label[L]}`, stance.blurb[L] + floorNote), ...draft.log];
      return draft;
    });
  }

  // ---------------------------------------------------------------- early-game actions
  // Cheap, repeatable, available from month 1. These exist because the first plant takes months to
  // open and a founder with nothing to do is a founder watching a progress bar. Each one seeds a
  // system that pays off later rather than just handing out stats.
  function handleEarlyAction(actionId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const act = EARLY_ACTIONS[actionId];
      if (!act) return prev;
      const L = language === 'es' ? 'es' : 'en';
      const label = act.name[L];
      if (prev.ap < (act.cost.ap || 1)) return denyTicket(prev, label, t('No Action Points remaining this month.'), language);
      if (act.cost.capital && prev.capital < act.cost.capital) return denyTicket(prev, label, t('Not enough Capital.'), language);
      if (act.cost.presence && prev.presence < act.cost.presence) return denyTicket(prev, label, t('Not enough Presence.'), language);

      const draft = { ...prev, log: [...prev.log] };
      draft.ap -= (act.cost.ap || 1);
      if (act.cost.capital) draft.capital -= act.cost.capital;
      if (act.cost.presence) draft.presence -= act.cost.presence;
      let body = '';

      if (actionId === 'networking') {
        // Builds standing with an investor who is NOT already backing you — courting the room
        // you haven't won yet, which is what networking actually is.
        const backers = new Set(Object.keys(prev.investorBackers || {}));
        const candidates = INVESTOR_CHARACTERS
          .filter(inv => !backers.has(inv.id))
          .sort((a, b) => ((prev.investorStandings || {})[b.id] || 0) - ((prev.investorStandings || {})[a.id] || 0));
        if (candidates.length) {
          const target = candidates[Math.floor(Math.random() * Math.min(3, candidates.length))];
          draft.investorStandings = { ...(prev.investorStandings || {}) };
          draft.investorStandings[target.id] = clamp((draft.investorStandings[target.id] || 0) + randInt(6, 12), -100, 100);
          body = L === 'es'
            ? `${target.name} ahora te conoce. Posición: ${relationshipBand(draft.investorStandings[target.id]).label.es}.`
            : `${target.name} knows who you are now. Standing: ${relationshipBand(draft.investorStandings[target.id]).label.en}.`;
        } else {
          body = L === 'es' ? 'Ya conoces a todos en la sala.' : 'You already know everyone in the room.';
        }
        applyDelta(draft, { presence: 1 });
      } else if (actionId === 'supplierCourtship') {
        // Warms a supplier relationship BEFORE you contract them — which then feeds trade credit
        // eligibility and the acquire-a-supplier threshold.
        const active = Object.entries(prev.supplierContracts || {}).filter(([, c]) => c.active !== false);
        if (active.length) {
          const [sid, contract] = active[Math.floor(Math.random() * active.length)];
          const sp = resolveSupplier(prev, sid);
          draft.supplierContracts = { ...prev.supplierContracts };
          draft.supplierContracts[sid] = { ...contract, relationship: clamp((contract.relationship || 0) + randInt(5, 9), -100, 100) };
          body = L === 'es'
            ? `${sp ? sp.name : sid} te tiene más confianza.`
            : `${sp ? sp.name : sid} trusts you a little more.`;
        } else {
          applyDelta(draft, { statBonus: { agility: 1 } });
          body = L === 'es'
            ? 'Todavía no tienes proveedores, pero ahora sabes a quién llamar.'
            : 'No suppliers yet, but you know who to call now.';
        }
      } else if (actionId === 'competitorResearch') {
        // Intel makes your NEXT external action against that rival land easier — knowledge
        // converted into a concrete edge rather than a stat bump.
        const rivals = prev.competitors || [];
        if (rivals.length) {
          const target = rivals[Math.floor(Math.random() * rivals.length)];
          draft.competitorIntel = { ...(prev.competitorIntel || {}) };
          draft.competitorIntel[target.seedId] = (draft.competitorIntel[target.seedId] || 0) + 1;
          body = L === 'es'
            ? `Ahora entiendes cómo opera ${target.name}. Tu próximo movimiento contra ellos será más fácil.`
            : `You understand how ${target.name} operates now. Your next move against them lands easier.`;
        } else {
          body = L === 'es' ? 'Nadie a quien estudiar todavía.' : 'Nobody to study yet.';
        }
      } else if (actionId === 'benchResearch') {
        // The small research tree: points accumulate and convert to a permanent Innovation gain.
        draft.researchPoints = (prev.researchPoints || 0) + 1;
        if (draft.researchPoints >= 3) {
          draft.researchPoints = 0;
          applyDelta(draft, { statBonus: { innovation: 1 } });
          body = L === 'es'
            ? 'Tres meses de experimentos por fin dan algo. Innovación +1.'
            : 'Three months of experiments finally produce something. Innovation +1.';
        } else {
          body = L === 'es'
            ? `Progreso de investigación ${draft.researchPoints}/3.`
            : `Research progress ${draft.researchPoints}/3.`;
        }
      }

      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'action', 'good', label, body), ...draft.log];
      return draft;
    });
  }

  // ---------------------------------------------------------------- vertical integration (7a)
  // Build a tier directly. The other route in is acquiring a supplier, which grants its tier for
  // free — see ownedTiers. Every tier bills monthly forever: obligation-with-capability.
  function handleBuildTier(tierId, colocated) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const tier = chainTier(tierId);
      if (!tier) return prev;
      const L = language === 'es' ? 'es' : 'en';
      const label = tier.name[L];
      const gate = tierBuildable(prev, tierId);
      if (!gate.open) {
        const why = {
          deferred: language === 'es' ? 'Aún no disponible.' : 'Not available yet.',
          owned: language === 'es' ? 'Ya lo posees.' : 'You already own it.',
          needsTier: language === 'es'
            ? `Primero necesitas poseer ${(chainTier(gate.need) || {}).name ? chainTier(gate.need).name.es : gate.need}.`
            : `You need to own ${(chainTier(gate.need) || {}).name ? chainTier(gate.need).name.en : gate.need} first.`,
        }[gate.reason] || (language === 'es' ? 'No disponible.' : 'Not available.');
        return denyTicket(prev, label, why, language);
      }
      if (prev.ap < 2) return denyTicket(prev, label, t('No Action Points remaining this month.'), language);
      if (prev.capital < tier.buildCost) return denyTicket(prev, label, t('Not enough Capital.'), language);
      const draft = { ...prev, ownedTiers: { ...prev.ownedTiers }, integrations: [...(prev.integrations || [])], log: [...prev.log] };
      draft.ap -= 2;
      draft.capital -= tier.buildCost;
      // Retail can be co-located with production: cheaper to supply (goods walk across the yard
      // rather than riding someone else's truck) but a smaller footprint, so less margin uplift.
      draft.ownedTiers[tierId] = { acquiredMonth: prev.month, builtNotBought: true,
        ...(tierId === 'retail' ? { colocated: !!colocated } : {}) };
      const months = integrationMonthsFor(prev);
      draft.integrations.push({ kind: 'tier', tierId, monthsLeft: months, startedMonth: prev.month });
      applyDelta(draft, { statBonus: { operations: 1 } });
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'integration', 'good',
        `${t('Tier Acquired')} — ${label}`,
        language === 'es'
          ? `${fmtMoney(tier.buildCost)} y ${tier.monthlyOverhead}/mes de gasto fijo, para siempre. ${months} meses de integración antes de que rinda del todo.${tierId === 'retail' ? (colocated ? ' Ubicada junto a producción: logística casi gratis, alcance menor.' : ' Independiente: mayor alcance, pero algo debe transportar el producto.') : ''}`
          : `${fmtMoney(tier.buildCost)} and ${tier.monthlyOverhead}/mo of fixed overhead, permanently. ${months} months of integration before it fully pays.${tierId === 'retail' ? (colocated ? ' Co-located with production: logistics nearly free, reach is smaller.' : ' Standalone: wider reach, but something has to move the goods.') : ''}`), ...draft.log];
      return draft;
    });
  }

  // Acquire a rival outright. Everything transfers — chain position, a product line, their people,
  // their market share, AND their debts. Bible §10: an acquisition must change the company.
  function handleAcquireRival(competitorId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const rival = (prev.competitors || []).find(c => c.id === competitorId || c.seedId === competitorId);
      if (!rival) return prev;
      const L = language === 'es' ? 'es' : 'en';
      const label = rival.name;
      const gate = rivalAcquirable(prev, rival);
      if (!gate.open) {
        const why = {
          needsIntegrationCapability: language === 'es' ? 'Requiere capacidad de integración vertical.' : 'Requires vertical integration capability.',
          hostile: language === 'es' ? 'No te venderían a ningún precio.' : 'They would not sell to you at any price.',
          tooBig: language === 'es' ? 'Son demasiado grandes para que los absorbas.' : 'They are too big for you to swallow.',
        }[gate.reason] || (language === 'es' ? 'No disponible.' : 'Not available.');
        return denyTicket(prev, label, why, language);
      }
      if (prev.ap < 3) return denyTicket(prev, label, t('No Action Points remaining this month.'), language);
      if (prev.capital < gate.cost) return denyTicket(prev, label, t('Not enough Capital.'), language);

      const ind = getIndustry(prev.industryId);
      const draft = {
        ...prev,
        competitors: prev.competitors.filter(c => c.seedId !== rival.seedId),
        ownedTiers: { ...prev.ownedTiers },
        acquiredRivals: { ...prev.acquiredRivals },
        integrations: [...(prev.integrations || [])],
        products: { ...prev.products },
        debts: [...(prev.debts || [])],
        scatteredTalent: [...(prev.scatteredTalent || [])],
        log: [...prev.log],
      };
      draft.ap -= 3;
      draft.capital -= gate.cost;
      draft.acquiredRivals[rival.seedId] = { name: rival.name, acquiredMonth: prev.month };

      const gained = [];
      // 1. Market position — most of theirs, not all; integration always loses some.
      const sharePickup = Math.round(rival.marketPosition * 0.7);
      applyDelta(draft, { marketPosition: sharePickup });
      gained.push(L === 'es' ? `+${sharePickup} posición de mercado` : `+${sharePickup} market position`);

      // 2. Their chain position, if they had one.
      const rivalTier = rival.archetype === 'verticalIntegrator' ? 'processing' : null;
      if (rivalTier && !draft.ownedTiers[rivalTier]) {
        draft.ownedTiers[rivalTier] = { acquiredMonth: prev.month, fromRival: rival.seedId };
        gained.push(chainTier(rivalTier).name[L]);
      }

      // 3. A product line — specifically one adjacency would otherwise have blocked. This is the
      // legitimate route past the block, exactly as Bible §A.5.3 describes.
      const inherited = inheritedProductFrom(rival, prev, ind);
      if (inherited) {
        draft.products[inherited.id] = {
          productId: inherited.id, phase: 'launched',
          phaseMonthsLeft: 0, currentIntensity: 'standard',
          quality: Math.max(QUALITY_FLOOR_MIN, Math.round(inherited.qualityCeiling * 0.7)),
          defectRate: inherited.defectRateBase,
          launchType: 'b2b',
          channelsOpened: (inherited.resourceProfile.channels || []).slice(0, 2),
          appealBonus: 1, costReduction: 0, totalCapitalSpent: 0,
          startedMonth: prev.month, inheritedFrom: rival.name,
        };
        gained.push(inherited.name[L]);
      }

      // 4. Their people.
      const person = scatterTalent(rival, prev.month);
      if (person) {
        draft.scatteredTalent.push({ ...person, joinedViaAcquisition: true });
        gained.push(person.name);
      }

      // 5. Their obligations — the part that makes this a decision rather than a purchase.
      const debt = inheritedDebtFrom(rival);
      let debtNote = '';
      if (debt) {
        draft.debts.push(debt);
        debtNote = L === 'es'
          ? ` Heredaste ${fmtMoney(debt.remaining)} de su deuda (${fmtMoney(debt.monthlyPayment)}/mes).`
          : ` You inherited ${fmtMoney(debt.remaining)} of their debt (${fmtMoney(debt.monthlyPayment)}/mo).`;
      }

      const months = integrationMonthsFor(prev);
      draft.integrations.push({ kind: 'rival', seedId: rival.seedId, name: rival.name, monthsLeft: months, startedMonth: prev.month });
      applyDelta(draft, { reputation: 4, morale: -4 });

      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'integration', 'good',
        `${t('Company Acquired')} — ${rival.name}`,
        (L === 'es'
          ? `Adquiriste ${rival.name} por ${fmtMoney(gate.cost)}. Obtuviste: ${gained.join(', ')}.${debtNote} ${months} meses de integración.`
          : `You acquired ${rival.name} for ${fmtMoney(gate.cost)}. Gained: ${gained.join(', ')}.${debtNote} ${months} months of integration.`)), ...draft.log];
      return draft;
    });
  }

  // The escape valve: sell a tier back when its obligations outweigh what it returns. Lossy on
  // purpose — a forced sale never recovers what the asset was worth.
  function handleSellTier(tierId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const tier = chainTier(tierId);
      if (!tier || !(prev.ownedTiers || {})[tierId]) return prev;
      const L = language === 'es' ? 'es' : 'en';
      const proceeds = selloffValue(prev, tierId);
      const draft = { ...prev, ownedTiers: { ...prev.ownedTiers }, log: [...prev.log] };
      delete draft.ownedTiers[tierId];
      draft.capital += proceeds;
      applyDelta(draft, { reputation: -3, morale: -3 });
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'integration', 'mixed',
        `${t('Asset Sold')} — ${tier.name[L]}`,
        language === 'es'
          ? `Recuperaste ${fmtMoney(proceeds)} de ${fmtMoney(tier.buildCost)}. El gasto fijo desaparece; la capacidad también.`
          : `Recovered ${fmtMoney(proceeds)} of ${fmtMoney(tier.buildCost)}. The overhead goes away; so does the capability.`), ...draft.log];
      return draft;
    });
  }

  // ---------------------------------------------------------------- working capital & finance
  // Debt: cash now, fixed repayment with interest, and it does not care how the month went.
  function handleTakeDebt(instrumentId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const inst = DEBT_INSTRUMENTS[instrumentId];
      if (!inst) return prev;
      const L = language === 'es' ? 'es' : 'en';
      const label = inst.name[L];
      const gate = debtInstrumentAvailable(instrumentId, prev);
      if (!gate.open) {
        const reasonText = {
          boardConfidence: language === 'es' ? `Requiere Confianza del Directorio ${gate.need}.` : `Requires Board Confidence ${gate.need}.`,
          reputation: language === 'es' ? `Requiere Reputación ${gate.need}.` : `Requires Reputation ${gate.need}.`,
          revenue: language === 'es' ? `Requiere ingresos de ${fmtMoney(gate.need)}/mes.` : `Requires ${fmtMoney(gate.need)}/mo revenue.`,
          backers: language === 'es' ? 'Requiere un inversionista que ya te respalde.' : 'Requires an investor already backing you.',
        }[gate.reason] || (language === 'es' ? 'No disponible.' : 'Not available.');
        return denyTicket(prev, label, reasonText, language);
      }
      if (prev.ap < 1) return denyTicket(prev, label, t('No Action Points remaining this month.'), language);
      // One outstanding facility per instrument type — stacking three merchant advances is not a
      // strategy, it's a bug waiting to be found.
      if ((prev.debts || []).some(d => d.instrumentId === instrumentId)) {
        return denyTicket(prev, label,
          language === 'es' ? 'Ya tienes una facilidad de este tipo abierta.' : 'You already have one of these outstanding.', language);
      }
      const principal = inst.amountOf(prev);
      const monthlyPayment = debtMonthlyPayment(principal, inst.interestRate, inst.termMonths);
      const draft = { ...prev, debts: [...(prev.debts || [])], log: [...prev.log] };
      draft.ap -= 1;
      draft.capital += principal;
      draft.debts.push({
        instrumentId, principal,
        remaining: Math.round(principal * (1 + inst.interestRate) * 10) / 10,
        monthlyPayment, monthsLeft: inst.termMonths, takenMonth: prev.month,
      });
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'finance', 'good',
        `${t('Debt Taken')} — ${label}`,
        language === 'es'
          ? `+${fmtMoney(principal)} ahora. ${fmtMoney(monthlyPayment)}/mes durante ${inst.termMonths} meses (${Math.round(inst.interestRate * 100)}% interés).`
          : `+${fmtMoney(principal)} now. ${fmtMoney(monthlyPayment)}/mo for ${inst.termMonths} months (${Math.round(inst.interestRate * 100)}% interest).`), ...draft.log];
      return draft;
    });
  }

  // Factoring: sell the receivables book for cash today at a discount. The direct answer to the
  // pressure B2B terms create — and it costs real margin, so it is a relief valve, not a fix.
  function handleFactorReceivables() {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const label = t('Factor Receivables');
      const total = totalReceivables(prev);
      if (total <= 0) {
        return denyTicket(prev, label, language === 'es' ? 'No hay cuentas por cobrar.' : 'Nothing outstanding to factor.', language);
      }
      if (prev.ap < 1) return denyTicket(prev, label, t('No Action Points remaining this month.'), language);
      const proceeds = Math.round(total * (1 - FACTORING_DISCOUNT));
      const draft = { ...prev, receivables: [], log: [...prev.log] };
      draft.ap -= 1;
      draft.capital += proceeds;
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'finance', 'mixed', label,
        language === 'es'
          ? `Vendiste ${fmtMoney(total)} en cuentas por cobrar por ${fmtMoney(proceeds)}. La diferencia es el precio de tener el dinero hoy.`
          : `Sold ${fmtMoney(total)} of receivables for ${fmtMoney(proceeds)}. The difference is what having the money today costs.`), ...draft.log];
      return draft;
    });
  }

  // Trade credit: a supplier who trusts you lets you pay later. A free working-capital loan from
  // someone who likes you — the cash-side payoff of the relationship item 3 already tracks.
  function handleTakeTradeCredit() {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const label = t('Trade Credit');
      if (!tradeCreditEligible(prev)) {
        return denyTicket(prev, label,
          language === 'es' ? 'Ningún proveedor confía lo suficiente todavía.' : 'No supplier trusts you enough yet.', language);
      }
      if ((prev.payables || []).length > 0) {
        return denyTicket(prev, label,
          language === 'es' ? 'Ya estás usando crédito comercial.' : 'Already running on trade credit.', language);
      }
      // Defers this month's supplier spend rather than creating new money.
      const deferred = Object.entries(prev.supplierContracts || {})
        .filter(([, c]) => c.active !== false)
        .reduce((sum, [id, c]) => {
          const supplier = resolveSupplier(prev, id);
          return sum + (supplier ? contractMonthlyCost(supplier, c.contractType) : 0);
        }, 0);
      if (deferred <= 0) return denyTicket(prev, label, language === 'es' ? 'No hay gasto que diferir.' : 'Nothing to defer.', language);
      const draft = { ...prev, payables: [...(prev.payables || [])], log: [...prev.log] };
      draft.capital += Math.round(deferred);
      draft.payables.push({ amount: Math.round(deferred), monthsLeft: TRADE_CREDIT_DEFERRAL_MONTHS });
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'finance', 'good', label,
        language === 'es'
          ? `Un proveedor de confianza te da ${TRADE_CREDIT_DEFERRAL_MONTHS} mes(es) para pagar ${fmtMoney(deferred)}.`
          : `A trusted supplier gives you ${TRADE_CREDIT_DEFERRAL_MONTHS} month(s) to pay ${fmtMoney(deferred)}.`), ...draft.log];
      return draft;
    });
  }

  // ---------------------------------------------------------------- named managers
  // Hiring costs capital up front and adds ongoing salary burn — a stable of S-Tiers is a real
  // financial commitment, which is what stops a player hoarding everyone they unlock.
  function handleHireManager(managerId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const def = MANAGER_BY_ID[managerId];
      if (!def) return prev;
      const label = def.name;
      if ((prev.managers || {})[managerId]) {
        return denyTicket(prev, label, language === 'es' ? 'Ya trabaja aquí.' : 'Already works here.', language);
      }
      if (!managerUnlocked(def, prev.careerSnapshot || {}, prev.unlockedSnapshot || [])) {
        return denyTicket(prev, label, language === 'es' ? 'Aún no está disponible.' : 'Not available yet.', language);
      }
      const tier = managerTier(def.tier);
      if (prev.ap < 1) return denyTicket(prev, label, t('No Action Points remaining this month.'), language);
      if (prev.capital < tier.hireCost) return denyTicket(prev, label, t('Not enough Capital.'), language);
      const draft = { ...prev, managers: { ...prev.managers }, log: [...prev.log] };
      draft.ap -= 1; draft.capital -= tier.hireCost;
      draft.managers[managerId] = { managerId, assignedLocation: null, hiredMonth: prev.month };
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'manager', 'good',
        `${t('Hired')} — ${label}`,
        language === 'es'
          ? `${tier.label.es} · ${def.role.es}. Salario ${fmtMoney(tier.salary)}/mes. Asígnale una ubicación para activar su habilidad.`
          : `${tier.label.en} · ${def.role.en}. Salary ${fmtMoney(tier.salary)}/mo. Assign them to a location to activate their perk.`), ...draft.log];
      return draft;
    });
  }

  // Assignment is what ACTIVATES a manager. A hired-but-benched manager is still paid and
  // contributes nothing — locations are the real constraint on how much manager power a company
  // can field at once.
  function handleAssignManager(managerId, locationIndex) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const inst = (prev.managers || {})[managerId];
      const def = MANAGER_BY_ID[managerId];
      if (!inst || !def) return prev;
      const label = def.name;
      if (locationIndex == null) { // unassign back to the bench
        const draft = { ...prev, managers: { ...prev.managers }, log: [...prev.log] };
        draft.managers[managerId] = { ...inst, assignedLocation: null };
        draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'manager', 'neutral',
          `${t('Unassigned')} — ${label}`,
          language === 'es' ? 'Vuelve a la banca. Su habilidad ya no aplica.' : 'Back on the bench. Their perk no longer applies.'), ...draft.log];
        return draft;
      }
      if (locationIndex < 0 || locationIndex >= (prev.locations || 0)) {
        return denyTicket(prev, label, language === 'es' ? 'Esa ubicación no existe.' : 'That location does not exist.', language);
      }
      const occupant = Object.values(prev.managers || {}).find(m => m.assignedLocation === locationIndex && m.managerId !== managerId);
      if (occupant) {
        return denyTicket(prev, label,
          language === 'es' ? 'Otra persona ya dirige esa ubicación.' : 'Someone else already runs that location.', language);
      }
      const draft = { ...prev, managers: { ...prev.managers }, log: [...prev.log] };
      draft.managers[managerId] = { ...inst, assignedLocation: locationIndex };
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'manager', 'good',
        `${t('Assigned')} — ${label}`,
        language === 'es'
          ? `Ahora dirige la ubicación ${locationIndex + 1}. ${MANAGER_PERKS[def.perkId].desc(managerPerkPercent(def), 'es')}`
          : `Now running location ${locationIndex + 1}. ${MANAGER_PERKS[def.perkId].desc(managerPerkPercent(def), 'en')}`), ...draft.log];
      return draft;
    });
  }

  function handleDismissManager(managerId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const inst = (prev.managers || {})[managerId];
      const def = MANAGER_BY_ID[managerId];
      if (!inst || !def) return prev;
      const draft = { ...prev, managers: { ...prev.managers }, log: [...prev.log] };
      delete draft.managers[managerId];
      // Letting someone go is felt by everyone still there.
      applyDelta(draft, { morale: -3 });
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'manager', 'mixed',
        `${t('Let Go')} — ${def.name}`,
        language === 'es' ? 'Su salario sale de la nómina. El equipo lo nota.' : 'Their salary leaves the payroll. The team notices.'), ...draft.log];
      return draft;
    });
  }

  // Contract a supplier — the slot limit comes from the Sourcing project chain (mirrors how
  // Tooling/Line/Plant unlock equipment), international suppliers need mfgOffshoreSourcing
  // specifically, and only one active contract per MATERIAL is allowed (contracting a second
  // supplier for the same material should mean SWITCHING, via cancel-then-contract, not stacking).
  function handleContractSupplier(supplierId, contractTypeId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const supplier = resolveSupplier(prev, supplierId);
      const ct = CONTRACT_TYPES[contractTypeId];
      if (!supplier || !ct) return prev;
      const label = supplier.name;
      const activeContracts = Object.entries(prev.supplierContracts || {}).filter(([, c]) => c.active !== false);
      if (activeContracts.length >= supplierSlotLimit(prev)) {
        return denyTicket(prev, label,
          language === 'es' ? 'No hay espacio en la cadena de suministro en esta etapa.' : 'No room in the supply chain at this stage.', language);
      }
      if (supplier.origin === 'international' && !internationalSourcingUnlocked(prev)) {
        return denyTicket(prev, label,
          language === 'es' ? 'El abastecimiento internacional aún no está disponible.' : 'International sourcing is not available yet.', language);
      }
      if (activeContracts.some(([id]) => { const sp = resolveSupplier(prev, id); return sp && sp.material === supplier.material; })) {
        return denyTicket(prev, label,
          language === 'es' ? 'Ya tienes un proveedor para este material — cancela ese contrato primero.' : 'Already have a supplier for this material — cancel that contract first.', language);
      }
      const draft = { ...prev, supplierContracts: { ...prev.supplierContracts }, log: [...prev.log] };
      draft.supplierContracts[supplierId] = { contractType: contractTypeId, active: true, relationship: 0, startedMonth: prev.month };
      const cost = contractMonthlyCost(supplier, contractTypeId);
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'supplier', 'good',
        `${t('New Supplier')} — ${label}`,
        language === 'es'
          ? `Contrato ${ct.label.es} por ${supplier.material}. ~${fmtMoney(cost)}/mes.`
          : `${ct.label.en} contract for ${supplier.material}. ~${fmtMoney(cost)}/mo.`), ...draft.log];
      return draft;
    });
  }

  // Cancelling pays the contract type's exit cost — real for longTerm/exclusive (the "locked in
  // when demand changes" tension the Bible names explicitly), negligible for spot/multiSource.
  function handleCancelSupplierContract(supplierId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const supplier = resolveSupplier(prev, supplierId);
      const contract = (prev.supplierContracts || {})[supplierId];
      if (!supplier || !contract || contract.active === false) return prev;
      const ct = CONTRACT_TYPES[contract.contractType] || CONTRACT_TYPES.spot;
      const draft = { ...prev, supplierContracts: { ...prev.supplierContracts }, log: [...prev.log] };
      // A renegotiator manager takes a real bite out of the stated exit fee.
      const exitCost = Math.round(ct.exitCost * (1 - managerFx(prev).supplierSwitchRelief) * 10) / 10;
      draft.capital -= exitCost;
      draft.supplierContracts[supplierId] = { ...contract, active: false };
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'supplier', 'mixed',
        `${t('Contract Ended')} — ${supplier.name}`,
        exitCost > 0
          ? (language === 'es' ? `Costo de salida: ${fmtMoney(exitCost)}.` : `Exit cost: ${fmtMoney(exitCost)}.`)
          : (language === 'es' ? 'Sin costo de salida.' : 'No exit cost.')), ...draft.log];
      return draft;
    });
  }

  // Free to change, same pattern as maintenance stance — a standing policy, not a spend.
  function handleSetInventoryStrategy(strategyId) {
    setGame(prev => {
      if (!prev || prev.gameOver || !INVENTORY_STRATEGIES[strategyId]) return prev;
      if (prev.inventoryStrategy === strategyId) return prev;
      const draft = { ...prev, log: [...prev.log] };
      draft.inventoryStrategy = strategyId;
      const label = INVENTORY_STRATEGIES[strategyId].label[language === 'es' ? 'es' : 'en'];
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'supplier', 'neutral',
        t('Inventory Strategy'),
        language === 'es' ? `Cambiada a ${label}.` : `Changed to ${label}.`), ...draft.log];
      return draft;
    });
  }

  // Vertical integration (Bible §C.6): buying the supplier outright ends contract cost and risk
  // for that material entirely, at real capital cost — obligation-with-capability, not flat
  // power. Gated behind mfgBackwardIntegration AND a trusted relationship; a supplier that
  // doesn't trust the company yet won't sell, no matter how much capital is on the table.
  function handleAcquireSupplier(supplierId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const supplier = resolveSupplier(prev, supplierId);
      const contract = (prev.supplierContracts || {})[supplierId];
      const label = supplier ? supplier.name : supplierId;
      if (!supplier || !contract || contract.active === false) return prev;
      if (!backwardIntegrationUnlocked(prev)) {
        return denyTicket(prev, label, language === 'es' ? 'Requiere Adquirir un Proveedor Clave.' : 'Requires Acquire a Key Supplier.', language);
      }
      if ((contract.relationship || 0) < ACQUIRE_SUPPLIER_RELATIONSHIP_THRESHOLD) {
        return denyTicket(prev, label,
          language === 'es' ? 'La relación no es lo bastante fuerte todavía — necesitas su confianza.' : 'The relationship isn\u2019t strong enough yet — you need their trust.', language);
      }
      const cost = Math.round(supplier.minimumOrder * supplier.priceIndex * 12);
      if (prev.capital < cost) return denyTicket(prev, label, t('Not enough Capital.'), language);
      if (prev.ap < 2) return denyTicket(prev, label, t('No Action Points remaining this month.'), language);
      const draft = { ...prev, acquiredSuppliers: { ...prev.acquiredSuppliers }, supplierContracts: { ...prev.supplierContracts }, log: [...prev.log] };
      draft.ap -= 2; draft.capital -= cost;
      draft.acquiredSuppliers[supplierId] = { acquiredMonth: prev.month };
      draft.supplierContracts[supplierId] = { ...contract, active: false }; // superseded by ownership
      applyDelta(draft, { reputation: 3, statBonus: { operations: 1 } });
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'supplier', 'good',
        `${t('Acquired')} — ${label}`,
        language === 'es'
          ? `El proveedor ahora es parte de la empresa. Sin más costo de contrato ni riesgo de interrupción para ${supplier.material}. (${fmtMoney(cost)})`
          : `The supplier is now part of the company. No more contract cost or disruption risk for ${supplier.material}. (${fmtMoney(cost)})`), ...draft.log];
      return draft;
    });
  }

  function handlePivot() {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      // A term can foreclose an action entirely — this is what makes PE money a commitment
      // rather than a purchase.
      if (activeTermEffects(prev).disabledActions.has('pivot')) {
        return denyTicket(prev, t('Pivot'), t('Your investors\u2019 terms do not permit a pivot.'), language);
      }
      if (prev.ap < 2) return denyTicket(prev, t('Pivot'), t('Needs 2 Action Points.'), language);
      const cost = 20;
      if (cost > prev.capital) return denyTicket(prev, t('Pivot'), `${t('Needs')} ${fmtMoney(cost)} ${t('Capital')} (${t('you have')} ${fmtMoney(prev.capital)}).`, language);
      const draft = { ...prev, stats: { ...prev.stats }, log: [...prev.log] };
      draft.capital -= cost;
      draft.ap -= 2;
      applyDelta(draft, { statBonus: { agility: 1 }, reputation: -8, boardConfidence: 6 });
      const body = language === 'es'
        ? 'Reposicionaste el concepto. +1 Agilidad, -8 Reputación, +6 Confianza del Directorio — el directorio interpreta un cambio de rumbo decisivo como una buena señal, aunque el mercado tarde un momento en ponerse al día.'
        : 'Repositioned the concept. +1 Agility, -8 Reputation, +6 Board Confidence — the board reads decisive course-correction as a good sign, even if the market takes a beat to catch up.';
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'action', 'neutral', t('Pivot'), body), ...draft.log];
      return draft;
    });
  }

  function handleExternalAction(actionId, competitorId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const def = (getIndustry(prev.industryId).content.externalActions.length ? getIndustry(prev.industryId).content.externalActions : EXTERNAL_ACTIONS).find(a => a.id === actionId);
      if (!def) return prev;
      const target = (prev.competitors || []).find(c => c.id === competitorId);
      const L = language === 'es' ? 'es' : 'en';
      const label = def.label[L];
      if (!target) return denyTicket(prev, label, t('No competitor selected.'), language);
      if (prev.ap < (def.cost.ap || 1)) return denyTicket(prev, label, t('No Action Points remaining this month.'), language);
      if ((def.cost.capital || 0) > prev.capital) return denyTicket(prev, label, `${t('Needs')} ${fmtMoney(def.cost.capital)} ${t('Capital')} (${t('you have')} ${fmtMoney(prev.capital)}).`, language);
      const xFx = founderFx(prev);
      // Street Smart makes moving on a rival cheaper; clamped at 0 so it can never refund.
      const extPresenceCost = Math.max(0, (def.cost.presence || 0) - xFx.externalPresenceDiscount);
      if (extPresenceCost > prev.presence) return denyTicket(prev, label, `${t('Needs')} ${extPresenceCost} ${t('Presence')} (${t('you have')} ${prev.presence}).`, language);

      const draft = { ...prev, stats: { ...prev.stats }, log: [...prev.log] };
      draft.capital -= (def.cost.capital || 0);
      draft.presence -= extPresenceCost;
      draft.ap -= (def.cost.ap || 1);

      // Same d10 + stat check as everything else, but a stronger rival is harder to land a hit on.
      const extInd = getIndustry(prev.industryId);
      const extScaling = extInd.scaling || {};
      const stageId = stageOf(prev.month, extInd.stages).id;
      const bar = 10 + ((extScaling.eventThresholdBonus || EVENT_THRESHOLD_BONUS_BY_STAGE)[stageId] || 0) + Math.floor(target.strength / 12)
        + rivalDefenceBonus(target); // a fortified rival is harder to touch — your own past aggression, coming back
      // Trend Hunter's dossier makes the FIRST move against a given rival land easier — after
      // that you're working from the same information everyone else has.
      const firstStrike = !((target.encounters || {}).attackedByPlayer) ? xFx.firstStrikeBonus : 0;
      // Competitor research pays off here: intel gathered on this specific rival makes the move
      // against them land easier, and is consumed when it does. Knowledge spent, not hoarded.
      const intel = (draft.competitorIntel || {})[target.seedId] || 0;
      if (intel > 0) {
        draft.competitorIntel = { ...draft.competitorIntel, [target.seedId]: intel - 1 };
      }
      const statTotal = (draft.stats[def.stat] || 0) + xFx.externalRollBonus + firstStrike + Math.min(3, intel);
      // Computed BEFORE the roll, from the exact same statTotal/bar the button's chip showed —
      // one implementation shared by preview and resolution, same discipline as every other
      // forecasted action.
      const preview = previewChance('externalAction', draft, { statTotal, bar });
      const success = roll(10) + statTotal >= bar;
      const severity = ((extScaling.eventSeverity || EVENT_SEVERITY_BY_STAGE)[stageId] || 1) * xFx.eventSeverityMult;
      recordForecastOutcome(draft, preview, success);

      let appliedDeltas;
      // Every attack is written onto the rival's own record, win or lose. This is the raw
      // material the NEXT run reads to decide how this company comes back — see derivePosture.
      draft.competitors = draft.competitors.map(c =>
        c.id === target.id ? recordNemesisEvent(c, 'attackedByPlayer') : c);

      if (success) {
        // A landed hit against a rival is exactly the kind of decisive move a board reads as
        // competent leadership — a small, universal Board Confidence gain on top of whatever
        // that specific action already grants.
        appliedDeltas = { ...def.goodDeltas, boardConfidence: (def.goodDeltas.boardConfidence || 0) + 2 };
        applyDelta(draft, appliedDeltas);
        draft.competitors = draft.competitors.map(c =>
          c.id === target.id
            ? recordNemesisEvent({ ...c, strength: Math.max(5, c.strength - def.rivalDamage), marketPosition: Math.max(0, c.marketPosition - Math.round(def.rivalDamage / 2)) }, 'defeatedByPlayer')
            : c);
      } else {
        appliedDeltas = scaleDeltas(def.badDeltas, severity);
        applyDelta(draft, appliedDeltas);
      }
      const textFn = success ? def.good[L] : def.bad[L];
      const deltaText = deltaSummaryText(appliedDeltas, language);
      const modelNote = forecastOutcomeNote(preview, success, language);
      const extBody = textFn(target.name) + modelNote + (deltaText ? ` (${deltaText})` : '');
      draft.log = [mkTicket(prev.month, quarterOf(prev.month), 'external', success ? 'good' : 'bad',
        `${label} — ${target.name}`, extBody), ...draft.log];
      return draft;
    });
  }

  function handleChoiceOption(optionIndex) {
    setGame(prev => {
      if (!prev || !prev.pendingChoice) return prev;
      const { event, month, quarter } = prev.pendingChoice;
      const option = event.options[optionIndex];
      const draft = { ...prev, stats: { ...prev.stats }, log: [...prev.log] };
      const { success, severity, preview } = resolveChoiceOption(draft, option, month, getIndustry(prev.industryId));
      const outcome = success ? option.good : option.bad;
      const deltas = success ? (outcome.deltas || {}) : scaleDeltas(outcome.deltas || {}, severity);
      applyDelta(draft, deltas);
      recordForecastOutcome(draft, preview, success);
      // Counted for the Analyst leader unlock: calling choice events correctly is the specific
      // competence that unlock is meant to recognise.
      if (success) draft.successfulChoices = (draft.successfulChoices || 0) + 1;
      // The choice itself is what reveals philosophy, not whether the dice cooperated — a
      // bribe attempt that gets caught is still a founder who chose to offer one.
      if (option.philosophy) {
        draft.philosophy = { ...(draft.philosophy || emptyPhilosophy()) };
        Object.entries(option.philosophy).forEach(([axis, v]) => {
          draft.philosophy[axis] = clamp((draft.philosophy[axis] || 0) + v, -100, 100);
        });
      }
      const dEvent = localizeChoiceEvent(event, language);
      const dOption = dEvent.options[optionIndex];
      const dOutcomeText = success ? dOption.good.text : dOption.bad.text;
      const deltaText = deltaSummaryText(deltas, language);
      const modelNote = forecastOutcomeNote(preview, success, language);
      const body = deltaText ? `${dOutcomeText}${modelNote} (${deltaText})` : `${dOutcomeText}${modelNote}`;
      const ticket = mkTicket(month, quarter, 'choice', success ? 'good' : 'bad', `${dEvent.title} — ${dOption.label}`, body);
      draft.log = [ticket, ...draft.log];
      draft.pendingSummary = prev.pendingSummary
        ? { ...prev.pendingSummary, tickets: [ticket, ...prev.pendingSummary.tickets] }
        : prev.pendingSummary;
      draft.pendingChoice = null;
      return draft;
    });
  }

  function endMonth() {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const draft = {
        ...prev,
        stats: { ...prev.stats },
        activeProjects: prev.activeProjects.map(p => ({ ...p })),
        completed: { ...prev.completed },
        usedFreeFundraise: { ...prev.usedFreeFundraise },
        // Cloned so trigger bookkeeping never writes through to the state React still holds.
        perkState: normalizePerkState(prev.perkState),
        log: [...prev.log],
      };
      const tickets = [];
      const month = draft.month;
      const quarter = quarterOf(month);
      const scenario = getScenario(draft.scenarioId);
      const activeIndustry = getIndustry(draft.industryId);
      const runEnd = draft.endMonth || activeIndustry.runEnd;
      const ffx = founderFx(draft);
      const mgrFx = managerFx(draft); // named-manager perks, build order item 4
      // Stage-transition detection for Future Market / Scenario Planner — cheap and stateless:
      // compare the stage this month sits in against the stage the NEXT month will sit in.
      const stageBeforeId = stageOf(month, activeIndustry.stages).id;
      const stageAfterId = stageOf(month + 1, activeIndustry.stages).id;
      const isStageTransition = stageAfterId !== stageBeforeId && (month + 1) <= runEnd;

      // ---- Product development ticks ----
      // Mirrors the existing activeProjects pattern: full cost was paid up front when the phase
      // was started (handleAdvanceProduct), so this is a pure countdown with no further spend.
      // Resolved BEFORE capacityDemand so a product finishing Testing this month can be seen
      // (and reasoned about) before this month's revenue is computed.
      if (draft.products && Object.keys(draft.products).length) {
        const prodIndustry = getIndustry(draft.industryId);
        draft.products = { ...draft.products };
        Object.keys(draft.products).forEach(pid => {
          const inst = draft.products[pid];
          if (inst.phase === 'launched' || inst.phase === 'retired') return;
          if (inst.phaseMonthsLeft <= 0) return; // already sitting ready, awaiting a player decision
          const def = PRODUCT_BY_ID[pid];
          if (!def) return;
          const monthsLeft = inst.phaseMonthsLeft - 1;
          const updated = { ...inst, phaseMonthsLeft: monthsLeft };
          if (monthsLeft <= 0 && inst.phase === 'testing') {
            // Testing's outcome locks in HERE — the one phase whose intensity has a permanent,
            // visible consequence on every unit this product ever sells (Bible §A.3/§12).
            const precisionFloor = Math.min(
              capabilityPrecisionFloor(draft, def.resourceProfile.capabilities),
              materialQualityFloor(draft, def.resourceProfile.materials));
            const outcome = resolveTestingOutcome(def, inst.currentIntensity, draft.stats.operations, precisionFloor, mgrFx);
            updated.quality = outcome.quality; updated.defectRate = outcome.defectRate;
            tickets.push(mkTicket(month, quarter, 'product', outcome.quality >= def.qualityCeiling * 0.8 ? 'good' : 'mixed',
              `${t('Testing Complete')} — ${def.name[language === 'es' ? 'es' : 'en']}`,
              language === 'es'
                ? `Calidad ${outcome.quality}/${def.qualityCeiling}, tasa de defectos ${(outcome.defectRate * 100).toFixed(1)}%.`
                : `Quality ${outcome.quality}/${def.qualityCeiling}, defect rate ${(outcome.defectRate * 100).toFixed(1)}%.`));
          } else if (monthsLeft <= 0 && inst.phase === 'prototype') {
            tickets.push(mkTicket(month, quarter, 'product', 'good',
              `${t('Prototype Complete')} — ${def.name[language === 'es' ? 'es' : 'en']}`,
              language === 'es' ? 'Lista para entrar a pruebas.' : 'Ready to move into testing.'));
          } else if (monthsLeft <= 0 && inst.phase === 'production') {
            // Small additional refinement from production's own intensity, on top of whatever
            // Testing already locked in — careful line setup catches a few more defects.
            const prodMult = PRODUCT_INTENSITIES[inst.currentIntensity] || PRODUCT_INTENSITIES.standard;
            updated.defectRate = clamp((inst.defectRate != null ? inst.defectRate : def.defectRateBase) * (0.85 + prodMult.defectMult * 0.15), 0, 0.5);
            tickets.push(mkTicket(month, quarter, 'product', 'good',
              `${t('Production Ready')} — ${def.name[language === 'es' ? 'es' : 'en']}`,
              language === 'es' ? 'La línea está lista. Elige cómo lanzar.' : 'The line is ready. Choose how to launch.'));
          }
          draft.products[pid] = updated;
        });
      }

      // ---- Mothball warm-up ----
      // A reopened plant takes a full month to come back online before it contributes anything.
      if (draft.ownedTiers) {
        let anyWarmed = false;
        const nextTiers = { ...draft.ownedTiers };
        Object.keys(nextTiers).forEach(tid => {
          const rec = nextTiers[tid];
          if (rec && rec.warmupMonthsLeft > 0) {
            const left = rec.warmupMonthsLeft - 1;
            nextTiers[tid] = { ...rec, warmupMonthsLeft: left };
            if (left === 0) {
              anyWarmed = true;
              const tr = chainTier(tid);
              tickets.push(mkTicket(month, quarter, 'integration', 'good', t('Plant Online'),
                language === 'es'
                  ? `${tr ? tr.name.es : tid} está de vuelta en producción.`
                  : `${tr ? tr.name.en : tid} is back in production.`));
            }
          }
        });
        if (anyWarmed || Object.keys(nextTiers).length) draft.ownedTiers = nextTiers;
      }

      // ---- Integration periods (Bible §10, build order item 7a) ----
      // An acquisition underperforms while it beds in. Timing an acquisition badly is a real
      // mistake, which is the point of making this visible rather than instant.
      if ((draft.integrations || []).length) {
        draft.integrations = draft.integrations.map(i => ({ ...i, monthsLeft: i.monthsLeft - 1 }));
        draft.integrations.filter(i => i.monthsLeft === 0).forEach(done => {
          const what = done.kind === 'rival'
            ? done.name
            : (chainTier(done.tierId) || {}).name
              ? chainTier(done.tierId).name[language === 'es' ? 'es' : 'en'] : done.tierId;
          tickets.push(mkTicket(month, quarter, 'integration', 'good', t('Integration Complete'),
            language === 'es'
              ? `${what} está plenamente integrado. Ya rinde por completo.`
              : `${what} is fully integrated. It pays in full from here.`));
        });
        draft.integrations = draft.integrations.filter(i => i.monthsLeft > 0);
      }

      // ---- Competitor lifecycle (Bible §G.2, build order item 6) ----
      // The market moves without the player. Pacing is deliberate: checks are 18-24 months
      // apart and AT MOST ONE event fires per check, most consequential first. Direction was
      // explicit that a merger must never become noise — so scarcity is the mechanic, not a
      // side effect of tuning.
      if (!draft.nextLifecycleCheck) {
        draft.nextLifecycleCheck = month + LIFECYCLE_CHECK_MIN_MONTHS
          + Math.floor(Math.random() * (LIFECYCLE_CHECK_MAX_MONTHS - LIFECYCLE_CHECK_MIN_MONTHS + 1));
      } else if (month >= draft.nextLifecycleCheck && (draft.competitors || []).length >= 2) {
        const L = language === 'es' ? 'es' : 'en';
        const rivals = draft.competitors;
        let fired = false;

        // 1. FAILURE — the most consequential thing that can happen, so it is checked first.
        const failing = failureCandidate(rivals);
        if (failing) {
          const dead = failing.rival;
          const arch = rivalArchetype(dead.archetype);
          const survivors = rivals.filter(r => r.seedId !== dead.seedId);
          // Market share redistributes to survivors AND to the player — the market is genuinely
          // zero-sum and somebody always benefits from a collapse.
          const sharePool = Math.round(dead.marketPosition * 0.6);
          const playerShare = Math.round(sharePool * 0.4);
          const rivalShare = survivors.length ? Math.floor((sharePool - playerShare) / survivors.length) : 0;
          applyDelta(draft, { marketPosition: playerShare });
          draft.competitors = survivors.map(r => ({ ...r, marketPosition: clamp(r.marketPosition + rivalShare, 0, 100) }));
          // Their people scatter; one may become hireable.
          const scattered = scatterTalent(dead, month);
          if (scattered) draft.scatteredTalent = [...(draft.scatteredTalent || []), scattered];
          // Was this the player's doing? The ticket says so explicitly when it was.
          const enc = dead.encounters || {};
          const playerCaused = (enc.defeatedByPlayer || 0) >= 2;
          const causeText = playerCaused
            ? (L === 'es'
              ? `No sobrevivió a la presión que ejerciste sobre ellos — ${arch.failureNarrative.es}.`
              : `They did not survive the pressure you put on them — ${arch.failureNarrative.en}.`)
            : (L === 'es' ? `Cerró ${arch.failureNarrative.es}.` : `Went under ${arch.failureNarrative.en}.`);
          const scatterText = scattered
            ? (L === 'es' ? ` ${scattered.name} está buscando trabajo.` : ` ${scattered.name} is looking for work.`)
            : '';
          tickets.push(mkTicket(month, quarter, 'market', playerCaused ? 'good' : 'mixed',
            `${t('Competitor Collapse')} — ${dead.name}`,
            `${causeText} ${L === 'es' ? `Su cuota de mercado se reparte (+${playerShare} para ti).` : `Their market share redistributes (+${playerShare} to you).`}${scatterText}`));
          draft.lifecycleEvents = [...(draft.lifecycleEvents || []), { type: 'failure', seedId: dead.seedId, month, playerCaused }];
          fired = true;
        }

        // 2. ACQUISITION — a struggling rival gets bought by a stronger one.
        if (!fired) {
          const pair = acquisitionPair(rivals);
          if (pair) {
            const { buyer, target } = pair;
            draft.competitors = rivals
              .filter(r => r.seedId !== target.seedId)
              .map(r => r.seedId === buyer.seedId
                ? {
                  ...r,
                  strength: Math.round(r.strength + target.strength * 0.5),
                  marketPosition: clamp(r.marketPosition + Math.round(target.marketPosition * 0.7), 0, 100),
                  acquisitionsMade: (r.acquisitionsMade || 0) + 1,
                  // The absorbed company's leaders join the buyer's history.
                  pastLeaders: [...(r.pastLeaders || []), ...(target.leaders || []).map(l => ({ ...l, leftMonth: month }))],
                }
                : r);
            const scattered = scatterTalent(target, month);
            if (scattered) draft.scatteredTalent = [...(draft.scatteredTalent || []), scattered];
            tickets.push(mkTicket(month, quarter, 'market', 'bad',
              `${t('Acquisition')} — ${buyer.name}`,
              (L === 'es'
                ? `${buyer.name} adquirió a ${target.name}. El comprador sale de esto notablemente más grande.`
                : `${buyer.name} has acquired ${target.name}. The buyer comes out of this markedly bigger.`)
              + (scattered ? (L === 'es' ? ` ${scattered.name} no se quedó.` : ` ${scattered.name} did not stay on.`) : '')));
            draft.lifecycleEvents = [...(draft.lifecycleEvents || []), { type: 'acquisition', buyer: buyer.seedId, target: target.seedId, month }];
            fired = true;
          }
        }

        // 3. ALLIANCE — two healthy rivals partner for market control.
        if (!fired) {
          const pair = alliancePair(rivals);
          if (pair) {
            const { a, b } = pair;
            draft.competitors = rivals.map(r => {
              if (r.seedId === a.seedId) return { ...r, allianceWith: [...(r.allianceWith || []), b.seedId] };
              if (r.seedId === b.seedId) return { ...r, allianceWith: [...(r.allianceWith || []), a.seedId] };
              return r;
            });
            tickets.push(mkTicket(month, quarter, 'market', 'bad',
              `${t('Market Alliance')} — ${a.name} & ${b.name}`,
              L === 'es'
                ? `${a.name} y ${b.name} anunciaron una alianza estratégica. Juntos son más difíciles de desplazar que por separado.`
                : `${a.name} and ${b.name} have announced a strategic partnership. Together they are harder to displace than either was alone.`));
            draft.lifecycleEvents = [...(draft.lifecycleEvents || []), { type: 'alliance', a: a.seedId, b: b.seedId, month }];
            fired = true;
          }
        }

        // 4. SUPPLIER CONVERSION — an allied rival offers to supply you (Manufacturing only,
        // since it slots into the real supplier system that industry has).
        if (!fired && activeIndustry.productCatalog) {
          const candidates = rivalSupplierCandidates(draft);
          if (candidates.length) {
            const ally = candidates[0];
            // Offer a material the company doesn't already source well.
            const contracted = new Set(Object.entries(draft.supplierContracts || {})
              .filter(([, c]) => c.active !== false)
              .map(([id]) => (resolveSupplier(draft, id) || {}).material));
            const allMaterials = [...new Set(SUPPLIER_CHARACTERS.map(sp => sp.material))];
            const offered = allMaterials.find(m => !contracted.has(m)) || allMaterials[0];
            const supplier = rivalAsSupplier(ally, offered);
            draft.rivalSuppliers = { ...(draft.rivalSuppliers || {}), [supplier.id]: supplier };
            tickets.push(mkTicket(month, quarter, 'market', 'good',
              `${t('Supply Partnership')} — ${ally.name}`,
              L === 'es'
                ? `${ally.name} se ofrece a suministrarte ${offered}. Compiten contigo y te abastecen a la vez, y ambas partes lo saben.`
                : `${ally.name} offers to supply you with ${offered}. They compete with you and supply you at the same time, and both parties know it.`));
            draft.lifecycleEvents = [...(draft.lifecycleEvents || []), { type: 'supplierOffer', seedId: ally.seedId, month }];
            fired = true;
          }
        }

        // Schedule the next check regardless of whether anything fired — a quiet market is a
        // legitimate outcome, not a reason to keep rolling until something happens.
        draft.nextLifecycleCheck = month + LIFECYCLE_CHECK_MIN_MONTHS
          + Math.floor(Math.random() * (LIFECYCLE_CHECK_MAX_MONTHS - LIFECYCLE_CHECK_MIN_MONTHS + 1));
      }

      // ---- Suppliers & Inventory ticks (Bible §C/§B.3, build order item 3) ----
      // Resolved BEFORE equipment and capacityDemand — materials sit upstream of both in the
      // chain, so a disruption THIS month has to be visible before capacity is derived from it.
      if (draft.supplierContracts && Object.keys(draft.supplierContracts).length) {
        draft.supplierContracts = { ...draft.supplierContracts };
        const strategy = inventoryStrategy(draft.inventoryStrategy);
        let holdingCostTotal = 0;
        Object.keys(draft.supplierContracts).forEach(supplierId => {
          const contract = { ...draft.supplierContracts[supplierId] };
          if (contract.active === false) { draft.supplierContracts[supplierId] = contract; return; }
          const supplier = resolveSupplier(draft, supplierId);
          if (!supplier) return;
          holdingCostTotal += 1; // counted for the inventory holding-cost pool below

          if (contract.disruptedMonthsLeft > 0) {
            contract.disruptedMonthsLeft -= 1;
            if (contract.disruptedMonthsLeft === 0) {
              tickets.push(mkTicket(month, quarter, 'supplier', 'mixed',
                `${t('Shipments Resume')} — ${supplier.name}`,
                language === 'es' ? 'El material vuelve a fluir con normalidad.' : 'Material is flowing normally again.'));
            }
            draft.supplierContracts[supplierId] = contract;
            return;
          }

          // Monthly contract cost, always paid while active.
          draft.capital -= Math.round(contractMonthlyCost(supplier, contract.contractType)
            * (1 - tierMaterialRelief(draft, supplier.material).costReduction) * 10) / 10;
          // Relationship builds slowly through sustained, undisrupted months — mirrors investor
          // standing and rival coexistence, same idea: showing up reliably is what it's made of.
          contract.relationship = clamp((contract.relationship || 0) + 1, -100, 100);

          // The "locked in when demand changes" tension (Bible §C.4/§16), made concrete at this
          // system's level of abstraction: a long-term or exclusive commitment still has to be
          // paid for even if nothing currently needs that material. Consumption tracking at the
          // unit level is a finer grain than this build-order item models; idle-commitment cost
          // is the honest version of the same lesson without inventing a parallel unit ledger.
          const ct = contractType(contract.contractType);
          if (ct.minPurchaseFraction > 0) {
            const materialStillNeeded = Object.values(draft.products || {}).some(inst => {
              if (inst.phase === 'retired') return false;
              const def = PRODUCT_BY_ID[inst.productId];
              return def && (def.resourceProfile.materials || []).includes(supplier.material);
            });
            if (!materialStillNeeded) {
              const idleCost = Math.round(contractMonthlyCost(supplier, contract.contractType) * ct.minPurchaseFraction * 10) / 10;
              draft.capital -= idleCost;
              if (idleCost > 0 && Math.random() < 0.25) { // occasional reminder, not every month
                tickets.push(mkTicket(month, quarter, 'supplier', 'mixed',
                  `${t('Idle Commitment')} — ${supplier.name}`,
                  language === 'es'
                    ? `Nada necesita ${supplier.material} ahora mismo, pero el contrato sigue cobrando. (${fmtMoney(idleCost)})`
                    : `Nothing needs ${supplier.material} right now, but the contract still bills. (${fmtMoney(idleCost)})`));
              }
            }
          }

          // The disruption roll itself.
          // A tier you own cannot be disrupted — you are the supply chain at that point.
          const tierRelief = tierMaterialRelief(draft, supplier.material);
          if (!tierRelief.immune
            && Math.random() < supplierDisruptionChance(supplier, contract.contractType, mgrFx.disruptionBuffer)) {
            const disruptionDuration = 1 + supplier.leadTimeMonths;
            const effectiveMonths = Math.max(0, disruptionDuration - strategy.bufferMonths - warehouseBufferBonus(draft));
            if (effectiveMonths === 0) {
              tickets.push(mkTicket(month, quarter, 'supplier', 'mixed',
                `${t('Disruption Absorbed')} — ${supplier.name}`,
                language === 'es'
                  ? `Un problema de envío surgió, pero el inventario lo absorbió sin afectar la producción.`
                  : `A shipping problem hit, but inventory on hand absorbed it without touching production.`));
            } else {
              contract.disruptedMonthsLeft = effectiveMonths;
              contract.relationship = clamp(contract.relationship - 3, -100, 100);
              let repHit = 0;
              Object.values(draft.products || {}).forEach(inst => {
                if (inst.phase !== 'launched') return;
                const def = PRODUCT_BY_ID[inst.productId];
                if (!def || !(def.resourceProfile.materials || []).includes(supplier.material)) return;
                repHit += 2;
              });
              if (repHit > 0) applyDelta(draft, { reputation: -Math.min(8, repHit) });
              let rivalNote = '';
              if ((draft.competitors || []).length && Math.random() < 0.35) {
                const idx = Math.floor(Math.random() * draft.competitors.length);
                draft.competitors = draft.competitors.map((c, i) => i === idx
                  ? { ...c, strength: c.strength + randInt(1, 3), marketPosition: clamp(c.marketPosition + randInt(1, 2), 0, 100) }
                  : c);
                rivalNote = language === 'es'
                  ? ` ${draft.competitors[idx].name} se beneficia de la escasez.`
                  : ` ${draft.competitors[idx].name} benefits from the shortage.`;
              }
              tickets.push(mkTicket(month, quarter, 'supplier', 'bad',
                `${t('Supply Disruption')} — ${supplier.name}`,
                (language === 'es'
                  ? `${supplier.material} deja de llegar durante ${effectiveMonths} mes(es).${repHit > 0 ? ' Un pedido incompleto cuesta reputación.' : ''}`
                  : `${supplier.material} stops arriving for ${effectiveMonths} month(s).${repHit > 0 ? ' An unfilled order costs reputation.' : ''}`)
                + rivalNote));
            }
          }
          draft.supplierContracts[supplierId] = contract;
        });
        if (holdingCostTotal > 0) {
          draft.capital -= Math.round(inventoryHoldingCost(draft.inventoryStrategy, holdingCostTotal)
            * (1 - warehouseHoldingRelief(draft)) * 10) / 10;
        }
      }

      // ---- Brand (Phase D, step 3) ----
      // Runs every month regardless of whether the player did anything, because doing nothing is
      // itself a choice here: decay is unconditional and marketing is what holds it back.
      if (activeIndustry.productCatalog) {
        draft.brand = { ...(draft.brand || { strength: 0, position: {} }) };
        const policy = marketingPolicy(draft.marketingPolicy);
        const targeted = !!draft.marketingTarget;

        // Spend scales with the size of the business — holding a name in front of a bigger
        // market costs more, so marketing never becomes trivially cheap late.
        const scaleBase = Math.max(6, Math.round((draft.revenuePerMonth || 0) * 0.09) + 6);
        const spend = Math.round(scaleBase * policy.spendMult * (targeted ? TARGETED_MARKETING_PREMIUM : 1));
        let gain = policy.strengthGain * (targeted ? 1.25 : 1);

        if (spend > 0) {
          if (draft.capital >= spend) {
            draft.capital -= spend;
          } else {
            // Cannot pay for it, so it does not happen. Silent underfunding would be worse than
            // an honest gap the player can see in the brand line.
            gain = 0;
          }
        }

        // Decay is unconditional; the policy exists to outrun it.
        const before = draft.brand.strength || 0;
        let next = before + gain - BRAND_DECAY_PER_MONTH;

        // Reputation is a SOFT CEILING. Marketing can run ahead of standing, but not forever —
        // you cannot be beloved by the public while failing the people who actually deal with you.
        const ceiling = brandCeiling(draft);
        if (next > ceiling) next = ceiling + (next - ceiling) * 0.25;
        draft.brand.strength = clamp(next, 0, 100);

        // POSITION drifts toward what the company actually makes and sells. You become known for
        // what you do. A targeted policy pulls position toward that segment's philosophy instead,
        // which is how a player deliberately repositions rather than waiting to be defined.
        const natural = naturalBrandPosition(draft, activeIndustry);
        const targetSeg = targeted ? consumerSegment(draft.marketingTarget) : null;
        const goal = targetSeg
          ? { premiumVsMass: targetSeg.premiumVsMass, sustainability: targetSeg.sustainability,
              noveltyVsHeritage: targetSeg.noveltyVsHeritage }
          : natural;
        if (goal) {
          const pos = brandPosition(draft);
          const rate = BRAND_POSITION_DRIFT * (policy.spendMult > 0 ? 1 : 0.4);
          draft.brand.position = {
            premiumVsMass: pos.premiumVsMass + (goal.premiumVsMass - pos.premiumVsMass) * rate,
            sustainability: pos.sustainability + (goal.sustainability - pos.sustainability) * rate,
            noveltyVsHeritage: pos.noveltyVsHeritage + (goal.noveltyVsHeritage - pos.noveltyVsHeritage) * rate,
          };
        }

        // Tell the player when brand crosses a segment's awareness gate in either direction —
        // that is the moment a whole market opens or closes to them.
        CONSUMER_SEGMENT_LIST.forEach(seg => {
          const wasIn = before >= (seg.brandGate || 0);
          const isIn = draft.brand.strength >= (seg.brandGate || 0);
          if (!wasIn && isIn) {
            tickets.push(mkTicket(month, quarter, 'product', 'good',
              `${t('Brand')} — ${seg.name[language === 'es' ? 'es' : 'en']}`,
              language === 'es'
                ? `${seg.name.es} ahora te reconoce. Ese mercado se te abrió.`
                : `${seg.name.en} know your name now. That market is open to you.`));
          } else if (wasIn && !isIn) {
            tickets.push(mkTicket(month, quarter, 'product', 'bad',
              `${t('Brand')} — ${seg.name[language === 'es' ? 'es' : 'en']}`,
              language === 'es'
                ? `${seg.name.es} te olvidó. Ese mercado se cerró.`
                : `${seg.name.en} have forgotten you. That market has closed.`));
          }
        });
      }

      // ---- Trade shows ----
      // A windowed opportunity rather than a standing action. Spaced by TRADE_SHOW_MIN_GAP so it
      // reads as an occasion the player plans around, and it only appears once the company has
      // something to actually exhibit.
      if (activeIndustry.productCatalog) {
        if (draft.tradeShow && draft.tradeShow.endsMonth <= month) {
          if (!draft.tradeShow.attended) {
            tickets.push(mkTicket(month, quarter, 'contract', 'mixed', t('Trade Show'),
              language === 'es'
                ? 'La feria cerró sus puertas. No fuiste.'
                : 'The trade show closed its doors. You did not go.'));
          }
          draft.tradeShow = null;
        }
        const hasLaunched = Object.values(draft.products || {}).some(i => i.phase === 'launched');
        if (!draft.tradeShow && hasLaunched
            && month - (draft.lastTradeShowMonth || -99) >= TRADE_SHOW_MIN_GAP
            && Math.random() < 0.12) {
          draft.tradeShow = {
            endsMonth: month + TRADE_SHOW_WINDOW_MONTHS,
            cost: 14,
            reach: 2,
            attended: false,
          };
          draft.lastTradeShowMonth = month;
          tickets.push(mkTicket(month, quarter, 'contract', 'good', t('Trade Show'),
            language === 'es'
              ? `Una feria del sector abre durante ${TRADE_SHOW_WINDOW_MONTHS} meses. Un stand cuesta ${fmtMoney(14)} y te pone delante de compradores que de otro modo no conocerías.`
              : `An industry trade show opens for ${TRADE_SHOW_WINDOW_MONTHS} months. A stand costs ${fmtMoney(14)} and puts you in front of buyers you would not otherwise meet.`));
        }
      }

      // ---- Sales contract lifecycle (Phase B) ----
      // Terms count down, expired offers clear, and buyers occasionally find you unprompted.
      // Inbound offers go to the ticket rail rather than the Choice Event deck on purpose —
      // a Choice Event would risk overriding another event in the same month.
      if (activeIndustry.productCatalog) {
        if ((draft.salesContracts || []).length) {
          draft.salesContracts = draft.salesContracts.map(c => ({ ...c, monthsLeft: c.monthsLeft - 1 }));
          draft.salesContracts.filter(c => c.monthsLeft === 0).forEach(c => {
            const def = PRODUCT_BY_ID[c.productId];
            const term = salesContractTerm(c.termId);
            const bonus = contractCompletionBonus(term.months);
            applyDelta(draft, { reputation: bonus });
            adjustBuyerStanding(draft, c.counterpartyId, BUYER_REL_ON_COMPLETION);
            // Seeing a whole term through is what makes this buyer permanent career content —
            // they, and your standing with them, carry into every future run.
            const newlyUnlocked = unlockBuyer(draft, c.counterpartyId);
            if (newlyUnlocked && BUYER_BY_ID[c.counterpartyId]) {
              tickets.push(mkTicket(month, quarter, 'contract', 'good',
                `${t('Buyer Relationship Established')} — ${c.counterpartyName}`,
                language === 'es'
                  ? `${c.counterpartyName} ahora te conoce. Este comprador y tu posición con él perdurarán más allá de esta partida.`
                  : `${c.counterpartyName} knows you now. This buyer, and your standing with them, will outlast this run.`));
            }
            tickets.push(mkTicket(month, quarter, 'contract', 'good',
              `${t('Contract Complete')} — ${c.counterpartyName}`,
              language === 'es'
                ? `El acuerdo de ${def ? def.name.es : c.productId} llegó a su término. Esa capacidad vuelve a estar libre. +${bonus} Reputación por cumplir el plazo completo.`
                : `The ${def ? def.name.en : c.productId} agreement has run its term. That capacity is yours again. +${bonus} Reputation for seeing it through.`));
          });
          draft.salesContracts = draft.salesContracts.filter(c => c.monthsLeft > 0);
        }

        // Expire stale offers so the pending list cannot grow forever.
        if ((draft.salesContractOffers || []).length) {
          draft.salesContractOffers = draft.salesContractOffers.filter(o => o.expiresMonth > month);
        }

        // A buyer approaches, unprompted.
        if (Math.random() < inboundOfferChance(draft)) {
          const launched = Object.values(draft.products || {}).filter(i => i.phase === 'launched');
          const buyers = potentialBuyers(draft);
          if (launched.length && buyers.length) {
            const inst = launched[Math.floor(Math.random() * launched.length)];
            const def = PRODUCT_BY_ID[inst.productId];
            const buyer = buyers[Math.floor(Math.random() * buyers.length)];
            const termIds = Object.keys(SALES_CONTRACT_TERMS);
            const termId = termIds[Math.floor(Math.random() * termIds.length)];
            const mp = (draft.market && draft.market[inst.productId]) ? draft.market[inst.productId].price : (def ? def.priceFloor : 1);
            const cap = def ? productCapacityContribution(inst, def, draft) : 0;
            if (def && cap > 0) {
              const offer = makeSalesContractOffer(draft, inst.productId, buyer, termId, month, mp, cap);
              draft.salesContractOffers = [...(draft.salesContractOffers || []), offer];
              tickets.push(mkTicket(month, quarter, 'contract', 'good',
                `${t('Contract Offer')} — ${buyer.name}`,
                language === 'es'
                  ? `${buyer.name} quiere ${offer.unitsPerMonth} unidades de ${def.name.es} al mes por ${offer.months} meses, a ${fmtMoney(offer.lockedPrice)}/u. Revísalo en Cadena de Suministro.`
                  : `${buyer.name} wants ${offer.unitsPerMonth} units of ${def.name.en} a month for ${offer.months} months, at ${fmtMoney(offer.lockedPrice)}/u. Review it under Supply Chain.`));
            }
          }
        }
      }

      // ---- Finished Goods: Production & Sales (Phase A) ----
      // Two separate events with stock as the buffer between them. Sales resolve against the
      // market's price AS IT STOOD entering this month — last month's close — not a price this
      // month's own production has already moved, which would let a decision see its own
      // consequence before being made. Positioned before the market tick so production this
      // month feeds NEXT month's price, and before byproducts so scrap scales off what was
      // actually made, not raw nameplate capacity.
      // Declared here rather than down in the legacy capacityDemand section — the finished-goods
      // block below needs it too, and runs first.
      const modelFx = activeModelEffects(draft);
      let productRevenueTotal = 0;
      // Accumulated here, applied AFTER this month's receivables aging step runs (further down
      // this function) — creating a receivable before that step would have it immediately
      // decremented and possibly collected in the SAME month it was created, silently shaving a
      // month off every product's payment term.
      let productCashDue = 0;
      const pendingProductReceivables = [];
      if (activeIndustry.productCatalog) {
        draft.products = { ...draft.products };
        Object.keys(draft.products).forEach(pid => {
          const inst = draft.products[pid];
          if (inst.phase !== 'launched') return;
          const def = PRODUCT_BY_ID[pid];
          if (!def) return;
          const rawCapacity = productCapacityContribution(inst, def, draft);
          const produced = resolveProduction(inst, def, draft, rawCapacity);
          // New output becomes its own dated lot, carrying the quality this line is currently
          // capable of. Step 2 will decay that figure with age; step 1 only records it.
          let workingLots = addLot(inst, produced, inst.quality != null ? inst.quality : def.qualityCeiling, month);
          const stockAfterProduction = workingLots.reduce((sum, l) => sum + l.units, 0);

          const marketPrice = (draft.market && draft.market[pid]) ? draft.market[pid].price : def.priceFloor;

          // ---- Sales contracts fill FIRST, at their locked price (direction's Q3) ----
          // Production above deliberately did NOT account for these (Q2) — overcommitting your
          // capacity is meant to be a real, earnable mistake, so any gap here is the player's.
          const delivery = resolveContractDeliveries(draft, pid, workingLots);
          workingLots = delivery.lots;
          let stockAfterContracts = delivery.stockRemaining;
          let contractRevenue = 0;
          delivery.results.forEach(r => {
            contractRevenue += r.revenue;
            if (r.shortfall <= 0) {
              // Delivered in full this month — steady, unglamorous trust accrual, both publicly
              // (reputation) and privately with this specific buyer (standing).
              applyDelta(draft, { reputation: CONTRACT_MONTHLY_REP });
              const c2 = (draft.salesContracts || []).find(c => c.id === r.contractId);
              if (c2) adjustBuyerStanding(draft, c2.counterpartyId, BUYER_REL_PER_DELIVERY);
            }
            if (r.shortfall > 0) {
              const contract = (draft.salesContracts || []).find(c => c.id === r.contractId);
              const consequence = breachConsequence(r, contract ? contract.lockedPrice : marketPrice);
              draft.capital -= consequence.cash;
              if (consequence.reputation > 0) applyDelta(draft, { reputation: -consequence.reputation });
              // A breach is public. Brand takes a loud, discrete hit rather than a quiet drift.
              applyBrandShock(draft, 'breach');
              // Standing falls faster than it rises, scaled by how badly you missed. This buyer
              // remembers it personally, and across runs if they are already unlocked.
              if (contract) adjustBuyerStanding(draft, contract.counterpartyId,
                Math.round(BUYER_REL_BREACH_BASE * (0.4 + r.severity * 0.6)));
              const reasonEn = r.qualityBlocked
                ? ` You had stock, but none of it cleared the ${contract ? contract.qualityRequired : '?'} quality bar.`
                : '';
              const reasonEs = r.qualityBlocked
                ? ` Tenías existencias, pero ninguna alcanzó el mínimo de calidad de ${contract ? contract.qualityRequired : '?'}.`
                : '';
              tickets.push(mkTicket(month, quarter, 'contract', 'bad',
                `${t('Contract Breach')} — ${r.counterpartyName}`,
                language === 'es'
                  ? `Debías ${r.owed} unidades de ${def.name.es} y entregaste ${r.delivered}. Penalización ${fmtMoney(consequence.cash)} y -${consequence.reputation} Reputación.${reasonEs}`
                  : `You owed ${r.owed} units of ${def.name.en} and delivered ${r.delivered}. Penalty ${fmtMoney(consequence.cash)} and -${consequence.reputation} Reputation.${reasonEn}`));
            }
          });
          if (contractRevenue > 0) {
            // Contracts are B2B by nature — they settle on terms, never as instant cash.
            pendingProductReceivables.push({ amount: Math.round(contractRevenue), monthsLeft: receivableTermsFor(draft) });
            productRevenueTotal += Math.round(contractRevenue);
          }

          // Only what contracts did not claim reaches the spot market and the Hold for Price floor.
          // (workingLots already reflects the contract draw — resolveContractDeliveries updates
          // it directly now that it operates on real lots, not a bare stock number.)

          const sold = resolveSales(inst, def, draft, stockAfterContracts, marketPrice);
          const spotDraw = drawFromLots(workingLots, sold);
          workingLots = spotDraw.kept;
          const remainingStock = workingLots.reduce((sum, l) => sum + l.units, 0);
          // Degraded stock fetches less. FIFO means the oldest — and therefore worst — units are
          // the ones going out the door, so neglected inventory shows up directly in revenue
          // rather than as an abstract penalty.
          const soldValueRatio = spotDraw.drawn.length
            ? spotDraw.drawn.reduce((s2, l) => s2 + l.units * lotValueRatio(l, pid, month, draft), 0)
              / Math.max(1, spotDraw.drawn.reduce((s2, l) => s2 + l.units, 0))
            : 1;

          const revenue = Math.round(sold * marketPrice * soldValueRatio * forwardMarginMultiplier(draft) * modelFx.marginMultiplier);
          productRevenueTotal += revenue;
          if (revenue > 0) {
            // Per-product now, and exact rather than approximated: this product's own launchType
            // decides the whole revenue amount's fate, no portfolio-wide share needed.
            if (inst.launchType === 'b2b') {
              pendingProductReceivables.push({ amount: revenue, monthsLeft: receivableTermsFor(draft) });
            } else {
              productCashDue += revenue;
            }
          }

          const holdingCost = finishedGoodsHoldingCost(draft, def, remainingStock);
          draft.capital -= holdingCost;

          // The shortfall consequence split still applies, now exact per product instead of
          // portfolio-share-approximated: this product's own launchType, not an aggregate.
          const marketDemand = productDemandContribution(inst, def, draft);
          const productShortfall = Math.max(0, Math.round(marketDemand) - sold);
          if (productShortfall > 0 && inst.launchType === 'b2b' && salesStance(inst.salesStance).id !== 'holdForPrice') {
            const severityRatio = productShortfall / Math.max(1, marketDemand);
            const repHit = Math.min(6, Math.round(severityRatio * 6 * modelFx.reputationLossMultiplier * ffx.shortfallRepMult));
            if (repHit > 0) applyDelta(draft, { reputation: -repHit });
          }

          // `stock` is kept as a derived mirror of the lots so any code path or older save that
          // still reads the scalar sees the correct total — one seam, no silent divergence.
          draft.products[pid] = { ...inst, lots: workingLots, stock: remainingStock,
            lastProducedUnits: produced, lastSoldUnits: sold };

          // ---- Spoilage -> byproduct (step 5) ----
          // Runs per-product, right here, so overflow liquidation below never tries to sell
          // stock that has already crossed the floor and left the sellable pool.
          const spoiled = lotsOf(draft.products[pid]).reduce((acc, lot) => {
            const q = lotQualityNow(lot, pid, month, draft);
            if (q != null && q < SPOILAGE_QUALITY_FLOOR) acc.units += lot.units; else acc.keep.push(lot);
            return acc;
          }, { units: 0, keep: [] });
          if (spoiled.units > 0) {
            draft.products[pid] = { ...draft.products[pid], lots: spoiled.keep, stock: totalStock({ lots: spoiled.keep }) };
            const outcome = applySpoilageToByproducts(draft, { productId: pid, units: spoiled.units }, def);
            const L = language === 'es' ? 'es' : 'en';
            const bpName = outcome.byproductId ? BYPRODUCTS[outcome.byproductId].name[L] : null;
            const fateEn = outcome.wroteOff
              ? 'Nowhere for it to go — written off entirely.'
              : outcome.reusedInto
                ? `Fed straight into your ${(PRODUCT_BY_ID[outcome.reusedInto] || {}).name ? PRODUCT_BY_ID[outcome.reusedInto].name.en : outcome.reusedInto} line, free.`
                : outcome.cash >= 0
                  ? `Recovered as ${bpName} — ${fmtMoney(outcome.cash)}.`
                  : `Disposed of as ${bpName} — ${fmtMoney(Math.abs(outcome.cash))}.`;
            const fateEs = outcome.wroteOff
              ? 'Sin destino — pérdida total.'
              : outcome.reusedInto
                ? `Alimentó directamente tu línea de ${(PRODUCT_BY_ID[outcome.reusedInto] || {}).name ? PRODUCT_BY_ID[outcome.reusedInto].name.es : outcome.reusedInto}, gratis.`
                : outcome.cash >= 0
                  ? `Recuperado como ${bpName} — ${fmtMoney(outcome.cash)}.`
                  : `Desechado como ${bpName} — ${fmtMoney(Math.abs(outcome.cash))}.`;
            tickets.push(mkTicket(month, quarter, 'byproduct', outcome.cash >= 0 && !outcome.wroteOff ? 'mixed' : 'bad',
              `${t('Stock Spoiled')} — ${def.name[L]}`,
              L === 'es'
                ? `${spoiled.units} unidades cayeron por debajo del mínimo de calidad vendible (${SPOILAGE_QUALITY_FLOOR}) y ya no son producto. ${fateEs}`
                : `${spoiled.units} units fell below the sellable quality floor (${SPOILAGE_QUALITY_FLOOR}) and are no longer product. ${fateEn}`));
          }
        });

        // ---- Warehouse events (step 6) ----
        // Runs AFTER spoilage (so it cannot destroy stock that already left the sellable pool)
        // and BEFORE overflow (so a fire genuinely relieves an over-full warehouse rather than
        // the player being charged for liquidating stock that burned).
        if (Math.random() < warehouseEventChance(draft, activeIndustry)) {
          const ev = pickWarehouseEvent();
          const L = language === 'es' ? 'es' : 'en';
          const holders = Object.keys(draft.products)
            .filter(pid2 => draft.products[pid2].phase === 'launched' && totalStock(draft.products[pid2]) > 0);
          if (holders.length) {
            // Hits the largest holding — that is where a warehouse's contents actually are.
            const pid2 = holders.sort((a, b) => totalStock(draft.products[b]) - totalStock(draft.products[a]))[0];
            const inst2 = draft.products[pid2];
            const def2 = PRODUCT_BY_ID[pid2];
            const before = totalStock(inst2);

            if (ev.id === 'damp') {
              // Nothing is removed; the affected lots simply get worse. Under FIFO that damage
              // surfaces later, when this stock finally ships — a delayed consequence.
              const drop = randInt(ev.qualityLoss[0], ev.qualityLoss[1]);
              const damaged = lotsOf(inst2).map(lot => ({
                ...lot,
                quality: lot.quality == null ? null : Math.max(0, lot.quality - drop),
              }));
              draft.products[pid2] = { ...inst2, lots: mergeLots(damaged), stock: totalStock({ lots: damaged }) };
              tickets.push(mkTicket(month, quarter, 'product', 'bad',
                `${ev.name[L]} — ${def2.name[L]}`,
                L === 'es'
                  ? `Nada se perdió, pero ${before} unidades bajaron ${drop} puntos de calidad. Lo notarás cuando intentes venderlas.`
                  : `Nothing was lost, but ${before} units dropped ${drop} quality points. You will notice when you try to sell them.`));
            } else {
              const frac = ev.lossFraction[0] + Math.random() * (ev.lossFraction[1] - ev.lossFraction[0]);
              const target = Math.max(1, Math.round(before * frac));
              // Theft takes the BEST stock; fire is indiscriminate, so it burns oldest-first.
              const result = ev.id === 'theft'
                ? drawHighestQualityFirst(lotsOf(inst2), target, pid2, month, draft)
                : drawFromLots(lotsOf(inst2), target);
              draft.products[pid2] = { ...inst2, lots: result.kept, stock: totalStock({ lots: result.kept }) };
              const lost = result.taken;
              // Reputation only moves for fire — a fire is public and disrupts commitments;
              // quiet theft is a private loss the market does not see.
              if (ev.id === 'fire') { applyDelta(draft, { reputation: -3, morale: -4 }); applyBrandShock(draft, 'fire'); }
              tickets.push(mkTicket(month, quarter, 'product', 'bad',
                `${ev.name[L]} — ${def2.name[L]}`,
                ev.id === 'theft'
                  ? (L === 'es'
                    ? `Desaparecieron ${lost} unidades — y se llevaron lo mejor que tenías, no lo más viejo.`
                    : `${lost} units are gone — and they took your best stock, not your oldest.`)
                  : (L === 'es'
                    ? `Se perdieron ${lost} unidades. Moral y reputación afectadas.`
                    : `${lost} units destroyed. Morale and reputation both take a hit.`)));
            }
          }
        }

        // ---- Storage overflow (step 3) ----
        // Soft cap: production was never blocked, but what will not fit has to go, now, at
        // whatever the market pays today. Oldest lots first — the overflow is the stock you were
        // least able to sell anyway, which is what makes over-building a real cost.
        const capacity = storageCapacity(draft, activeIndustry);
        const held = totalHeldUnits(draft);
        if (held > capacity) {
          let overflow = Math.round(held - capacity);
          let liquidationProceeds = 0;
          let liquidatedUnits = 0;
          // Drain product by product, biggest holding first, so the liquidation lands where the
          // over-building actually happened.
          const byHolding = Object.keys(draft.products)
            .filter(pid2 => draft.products[pid2].phase === 'launched' && totalStock(draft.products[pid2]) > 0)
            .sort((a, b) => totalStock(draft.products[b]) - totalStock(draft.products[a]));
          byHolding.forEach(pid2 => {
            if (overflow <= 0) return;
            const inst2 = draft.products[pid2];
            const def2 = PRODUCT_BY_ID[pid2];
            if (!def2) return;
            const take = Math.min(overflow, totalStock(inst2));
            const dumped = drawFromLots(lotsOf(inst2), take);
            const price2 = (draft.market && draft.market[pid2]) ? draft.market[pid2].price : def2.priceFloor;
            dumped.drawn.forEach(lot => {
              liquidationProceeds += lot.units * price2 * lotValueRatio(lot, pid2, month, draft);
              liquidatedUnits += lot.units;
            });
            overflow -= dumped.taken;
            draft.products[pid2] = { ...inst2, lots: dumped.kept, stock: totalStock({ lots: dumped.kept }) };
          });
          if (liquidatedUnits > 0) {
            const proceeds = Math.round(liquidationProceeds);
            draft.capital += proceeds;
            tickets.push(mkTicket(month, quarter, 'product', 'mixed', t('Storage Overflow'),
              language === 'es'
                ? `Superaste tu capacidad de almacenaje (${Math.round(capacity)} u). Se liquidaron ${liquidatedUnits} unidades a precio de mercado por ${fmtMoney(proceeds)} — sin poder esperar un mejor precio.`
                : `You exceeded your storage capacity (${Math.round(capacity)} u). ${liquidatedUnits} units were liquidated at market for ${fmtMoney(proceeds)} — with no ability to wait for a better price.`));
          }
        }
      }
      // Only industries that RECOMPUTE revenue fresh each month (capacityDemand) get reset here.
      // Hospitality's 'accumulated' model builds revenuePerMonth via project/event deltas across
      // the whole run — resetting it here would silently erase that history every month.
      if (activeIndustry.revenueModel === 'capacityDemand') {
        draft.revenuePerMonth = productRevenueTotal;
      }


      // Rivals and the player both push on supply and demand, then prices recompute. This is
      // what makes "why is timber expensive?" answerable with "because four rivals run sawmills."
      if (draft.market && activeIndustry.productCatalog) {
        const mkt = {};
        Object.keys(draft.market).forEach(id => { mkt[id] = { ...draft.market[id] }; });
        // Decay toward equilibrium so a single spike does not distort the market forever.
        Object.keys(mkt).forEach(id => {
          mkt[id].supply = mkt[id].supply * 0.88 + 100 * 0.12;
          mkt[id].demand = mkt[id].demand * 0.88 + 100 * 0.12;
        });
        // AMBIENT ECONOMY: the wider market trades whether or not the player or any tracked rival
        // is producing. Without this the whole board sat frozen at baseline until the first rival
        // spawned, which read as a broken simulation rather than a quiet one. Deterministic per
        // entity per month, so prices drift and cycle rather than jittering randomly.
        Object.keys(mkt).forEach(id => {
          const e = ECONOMY[id];
          if (!e) return;
          // Cheap deterministic hash of id+month → a stable pseudo-cycle per entity.
          let h = month * 7;
          for (let i = 0; i < id.length; i++) h = (h * 31 + id.charCodeAt(i)) >>> 0;
          const phase = (h % 1000) / 1000;
          const swing = Math.sin((month / 7 + phase * 6.283)) * 26;
          // Downstream goods are demand-led; raw materials are supply-led. Opposite signs make
          // the chain behave like a chain rather than everything moving together.
          const downstream = ['component', 'subAssembly', 'finishedProduct'].includes(e.tier);
          mkt[id].demand = Math.max(20, mkt[id].demand + swing * (downstream ? 1 : 0.6));
          mkt[id].supply = Math.max(20, mkt[id].supply - swing * (downstream ? 0.3 : 0.8));
        });
        applyRivalProduction(mkt, draft.competitors);
        Object.values(draft.products || {}).forEach(inst => {
          if (inst.phase !== 'launched') return;
          const def = PRODUCT_BY_ID[inst.productId];
          if (!def || !mkt[inst.productId]) return;
          // Actual production, not raw capacity — a Build-to-Order line running under capacity
          // should move the market less than one running flat out on Build to Stock.
          applyProduction(mkt, inst.productId, Math.max(0, inst.lastProducedUnits || 0));
        });
        draft.market = recomputePrices(mkt);
      }

      // ---- Byproducts (base product economy) ----
      // Every launched line throws off scrap. What that costs or earns is entirely down to the
      // policy the player set — and whether they saw the opportunity and built the line that
      // eats it. Resolved before burn so the energy relief can actually reduce this month's burn.
      const byproducts = activeIndustry.productCatalog ? resolveByproducts(draft, activeIndustry) : null;
      if (byproducts && byproducts.lines.length) {
        draft.capital -= byproducts.disposalCost;
        draft.capital += byproducts.wholesaleRevenue;
        if (byproducts.reusedInto.length && month % 6 === 0) {
          const r = byproducts.reusedInto[0];
          const intoName = PRODUCT_BY_ID[r.into] ? PRODUCT_BY_ID[r.into].name[language === 'es' ? 'es' : 'en'] : r.into;
          const fromName = BYPRODUCTS[r.from].name[language === 'es' ? 'es' : 'en'];
          tickets.push(mkTicket(month, quarter, 'byproduct', 'good', t('Closed Loop'),
            language === 'es'
              ? `${fromName} de una línea alimenta ${intoName} en la otra. Nada se compra dos veces.`
              : `${fromName} from one line is feeding ${intoName} on the other. Nothing gets bought twice.`));
        }
        if (byproducts.disposalCost > 0 && month % 6 === 3) {
          tickets.push(mkTicket(month, quarter, 'byproduct', 'mixed', t('Waste Handling'),
            language === 'es'
              ? `Pagaste ${fmtMoney(byproducts.disposalCost)} este mes por llevarse tus desechos. Alguien ahí fuera los quiere.`
              : `You paid ${fmtMoney(byproducts.disposalCost)} this month to have your waste taken away. Somebody out there wants it.`));
        }
      }

      // ---- Equipment & Maintenance ticks (Bible §B.1/§B.2, build order item 2) ----
      // Resolved BEFORE capacityDemand so a failure THIS month actually halts THIS month's
      // production, not next month's — the whole point of the cascade being felt immediately.
      if (draft.equipment && Object.keys(draft.equipment).length) {
        draft.equipment = { ...draft.equipment };
        const hasPredictive = !!draft.completed.mfgPredictiveMaintenance;
        Object.keys(draft.equipment).forEach(eqId => {
          const eq = { ...draft.equipment[eqId] };
          if (eq.downtimeMonthsLeft > 0) {
            eq.downtimeMonthsLeft -= 1;
            if (eq.downtimeMonthsLeft === 0) {
              tickets.push(mkTicket(month, quarter, 'equipment', 'mixed',
                `${t('Back Online')} — ${EQUIPMENT_CATALOG[eqId].name[language === 'es' ? 'es' : 'en']}`,
                language === 'es' ? 'La línea vuelve a producir.' : 'The line is producing again.'));
            }
            draft.equipment[eqId] = eq;
            return;
          }
          // Decay and its recurring cost. Neglect is free this month and expensive later — the
          // "tempting during cash shortages" trap the Bible names explicitly.
          eq.condition = clamp(eq.condition - equipmentDecayThisMonth(eq, hasPredictive, mgrFx.maintenanceDiscipline), 0, 100);
          draft.capital -= equipmentMonthlyCost(eq);

          // The failure roll. Fresh equipment essentially never fails; worn equipment under a
          // cheap stance fails often and hard — risk compounds through decay speed AND severity
          // AND cost avoided, not just one dial.
          if (Math.random() < equipmentFailureChance(eq)) {
            eq.condition = clamp(eq.condition - 15, 0, 100);
            eq.downtimeMonthsLeft = 1 + Math.floor(Math.random() * 2); // 1-2 months halted
            const repairCost = equipmentMonthlyCost(eq) * 6 + 4;
            draft.capital -= repairCost;
            const catalogEntry = EQUIPMENT_CATALOG[eqId];
            const eqName = catalogEntry.name[language === 'es' ? 'es' : 'en'];

            // The cascade's next links, using systems that already exist rather than inventing
            // parallel contract/customer entities: launched products depending on this
            // equipment's tag take a reputation hit (the "late shipment -> contract penalty"
            // step), and — the "customer defects to a rival" step — an existing rival has a
            // chance to pick up the dissatisfied account, via the same growth shape rivals
            // already use monthly.
            let repHit = 0;
            Object.values(draft.products || {}).forEach(inst => {
              if (inst.phase !== 'launched') return;
              const def = PRODUCT_BY_ID[inst.productId];
              const providesCap = (EQUIPMENT_CAPABILITIES[eqId] || []);
              if (!def || !(def.resourceProfile.capabilities || []).some(c => providesCap.includes(c))) return;
              repHit += 2;
            });
            if (repHit > 0) applyDelta(draft, { reputation: -Math.min(8, repHit) });
            let rivalNote = '';
            if ((draft.competitors || []).length && Math.random() < 0.4) {
              const idx = Math.floor(Math.random() * draft.competitors.length);
              draft.competitors = draft.competitors.map((c, i) => i === idx
                ? { ...c, strength: c.strength + randInt(2, 4), marketPosition: clamp(c.marketPosition + randInt(1, 3), 0, 100) }
                : c);
              rivalNote = language === 'es'
                ? ` ${draft.competitors[idx].name} recoge al cliente insatisfecho.`
                : ` ${draft.competitors[idx].name} picks up the dissatisfied customer.`;
            }
            tickets.push(mkTicket(month, quarter, 'equipment', 'bad',
              `${t('Equipment Failure')} — ${eqName}`,
              (language === 'es'
                ? `La producción se detiene. Reparación de emergencia: ${fmtMoney(repairCost)}.${repHit > 0 ? ' Un envío tardío cuesta reputación.' : ''}`
                : `Production halts. Emergency repair: ${fmtMoney(repairCost)}.${repHit > 0 ? ' A late shipment costs reputation.' : ''}`)
              + rivalNote));
          }
          draft.equipment[eqId] = eq;
        });
      }

      // ---- Capacity vs Demand (industries using the derived revenue model) ----
      // Being wrong in either direction hurts, differently: unmet demand costs reputation and
      // the sale; idle capacity burns cash on plant doing nothing. Resolved BEFORE burn/revenue
      // so this month's revenue reflects this month's throughput.
      let cdReport = null;
      if (activeIndustry.revenueModel === 'capacityDemand') {
        const cfg = activeIndustry.capacityDemand;
        // Demand erodes on its own; reputation and market position slow the bleed. This is what
        // stops a single early channel project from carrying the whole run. Business-model
        // commitments scale both the erosion and the regrowth.
        const sustain = ((draft.reputation / 30) + (draft.marketPosition / 30)) * modelFx.demandGrowthMultiplier;
        draft.demand = Math.max(0, (draft.demand || 0) - cfg.demandDecay * modelFx.demandDecayMultiplier + sustain);

        // PHASE A SUPERSEDES THIS COMPOSITION (was: legacy accumulator + derived product terms
        // added on top, per the original Bible §0.2 decision). Every launched product now
        // resolves its own capacity, demand, revenue AND shortfall precisely in the finished-
        // goods block above — folding the same product totals in here a second time would
        // double-count both the revenue and the reputation penalty for every launched product.
        // What remains here is genuinely just the legacy accumulator: generic Tooling/Line/Plant
        // project grants, unconnected to any specific product.
        const capacity = (draft.capacity || 0);
        // Automation Pioneer: past a scale threshold, the plant runs ahead of its nameplate
        // number. Applied to EFFECTIVE capacity only — draft.capacity itself is untouched, so
        // the perk never inflates the stored figure the player sees on their sheet.
        const effCapacity = capacity >= ffx.capacityEffThreshold ? capacity * ffx.capacityEffMult : capacity;
        const demand = (draft.demand || 0);
        const throughput = Math.min(effCapacity, demand);

        const shortfall = Math.max(0, demand - effCapacity);
        const idle = Math.max(0, effCapacity - demand);

        // Scarcity moves price for what you DO sell — the actual supply/demand consequence,
        // not a punishment. Bounded (1.0-1.2x) so starving your own capacity on purpose is never
        // a profitable trick; same elasticity philosophy as the Phase 2 market's price curve,
        // sized down because this applies to the WHOLE industry's throughput, not one material.
        const scarcityRatio = demand / Math.max(1, effCapacity);
        const scarcityPriceMult = shortfall > 0 ? clamp(Math.pow(scarcityRatio, 0.3), 1, 1.2) : 1;

        // Forward tiers compose onto the existing margin chain rather than replacing the
        // industry constant — same discipline that kept capacity/demand intact in item 1.
        // ADDS to product revenue (resolved above) rather than overwriting it — legacy capacity
        // and per-product finished-goods revenue are two separate, additive income sources now.
        draft.revenuePerMonth += Math.round(throughput * cfg.marginPerUnit * modelFx.marginMultiplier
          * forwardMarginMultiplier(draft) * scarcityPriceMult);

        cdReport = { capacity: Math.round(capacity), demand: Math.round(demand), throughput: Math.round(throughput), shortfall: Math.round(shortfall), idle: Math.round(idle), idleBurn: 0,
          scarcityPct: Math.round((scarcityPriceMult - 1) * 100) };

        if (shortfall > 0) {
          // This is now legacy-only shortfall (generic accumulator capacity vs. its own demand
          // pool) — every launched PRODUCT's shortfall is resolved exactly, per product, in the
          // finished-goods block above. Only relevant to industries whose capacity still comes
          // partly from generic (non-product) projects.
          const b2bShare = b2bRevenueShare(draft, activeIndustry);
          const severityRatio = shortfall / Math.max(1, demand);
          const repHit = Math.min(9, Math.round(severityRatio * 8 * modelFx.reputationLossMultiplier
            * ffx.shortfallRepMult * b2bShare));
          if (repHit > 0) applyDelta(draft, { reputation: -repHit });
          cdReport.repHit = repHit;
          cdReport.b2bShare = Math.round(b2bShare * 100);
        }
        if (idle > 0) {
          // Factory Whisperer keeps idle plant from costing anything at all.
          cdReport.idleBurn = ffx.idleBurnFree ? 0 : Math.round(idle * cfg.idleCostPerUnit);
        }
      }

      // Terms that have run their course drop off before this month's effects are computed.
      draft.activeTerms = (draft.activeTerms || []).filter(tm =>
        tm.expiresAfterMonths == null || (month - tm.startedMonth) < tm.expiresAfterMonths);
      const termFx = activeTermEffects(draft);

      const idleBurn = cdReport ? cdReport.idleBurn : 0;
      // Allied rivals supply you, which is real recurring burn relief. Computed here, before
      // burn, because relief that lands after the burn calculation would be cosmetic. Read from
      // live disposition every month rather than latched, so breaking an alliance ends it at once.
      // Coalition Builder raises both the per-ally rate and the cap.
      const allyFx = allyEffects(draft.competitors, ffx.allyReliefPer, ffx.allyReliefCap, ffx.dispositionDamageMult);
      const burnBonusTable = (activeIndustry.scaling && activeIndustry.scaling.stageBurnBonus) || STAGE_BURN_BONUS;
      // Automation-Led raises the labor divisor, so headcount drives burn far more slowly.
      const laborDiv = modelFx.laborBurnDivisor || 3;
      // Master Scheduler removes the active-project term entirely; Factory Whisperer lightens
      // per-location overhead. Both clamp at 0 so neither can pay you to run a company.
      const projectBurnTerm = ffx.activeProjectBurnFree ? 0 : draft.activeProjects.length;
      const locationOverhead = Math.max(0, LOCATION_OVERHEAD + ffx.locationOverheadDelta);
      // Named managers are salaried, assigned or benched — a bench is a real cost, which is what
      // makes "who do I actually need?" a decision rather than "hire everyone I've unlocked".
      const payroll = managerPayroll(draft);
      // Owned chain tiers bill every month, forever — the obligation half of the deal.
      const tierOverhead = tierMonthlyOverhead(draft);
      // Something has to move goods from the plant to your own shelves: free if you own
      // Distribution, nearly free if the shop is co-located, a real fee otherwise.
      const retailLogistics = retailDistributionCost(draft);
      const byproductEnergyRelief = byproducts ? byproducts.energyRelief : 0;
      const baseBurn = Math.max(1, 2 + Math.ceil(draft.laborPool / laborDiv) + draft.locations * locationOverhead + projectBurnTerm + payroll + tierOverhead + retailLogistics - byproductEnergyRelief - (draft.burnReduction || 0) - allyFx.burnRelief + (burnBonusTable[stageOf(month, activeIndustry.stages).id] || 0));
      const burn = Math.round(baseBurn * termFx.burnMultiplier * modelFx.burnMultiplier) + idleBurn;
      draft.capital -= burn;
      draft.presence = clamp(draft.presence + 3 - termFx.monthlyPresence, 0, 15);

      // ---- Working capital: revenue no longer lands as cash automatically ----
      // B2B sells on terms and becomes a receivable; B2C collects at the till. This is where a
      // profitable company can start running out of money, which is the whole point of item 5.
      draft.receivables = (draft.receivables || []).map(r => ({ ...r, monthsLeft: r.monthsLeft - 1 }));
      const collected = draft.receivables.filter(r => r.monthsLeft <= 0).reduce((sum, r) => sum + r.amount, 0);
      draft.receivables = draft.receivables.filter(r => r.monthsLeft > 0);

      // Retail sells directly to consumers, so its slice settles as CASH rather than as B2B
      // paper — direction's Q1 answer. It is netted out of the on-terms share below.
      //
      // Scoped to the LEGACY portion of revenue only: per-product finished-goods revenue
      // (resolved above, exact per product's own launchType) already became cash or a
      // receivable individually. Re-splitting the FULL revenuePerMonth here would double-count
      // both the cash and the receivable for every launched product.
      const legacyRevenueThisMonth = draft.revenuePerMonth - productRevenueTotal;
      const retailShare = retailCashShare(draft, activeIndustry);
      const b2bShare = Math.max(0, b2bRevenueShare(draft, activeIndustry) - retailShare);
      const revenueOnTerms = Math.round(legacyRevenueThisMonth * b2bShare);
      const revenueInCash = legacyRevenueThisMonth - revenueOnTerms;
      draft.capital += revenueInCash + collected;
      if (revenueOnTerms > 0) {
        draft.receivables = [...draft.receivables, { amount: revenueOnTerms, monthsLeft: receivableTermsFor(draft) }];
      }
      // Per-product finished-goods revenue, resolved earlier this month, credited HERE — after
      // aging so a freshly-created receivable starts its full term next month, not this one.
      draft.capital += productCashDue;
      if (pendingProductReceivables.length) {
        draft.receivables = [...draft.receivables, ...pendingProductReceivables];
      }

      // Payables (trade credit) come due.
      draft.payables = (draft.payables || []).map(p2 => ({ ...p2, monthsLeft: p2.monthsLeft - 1 }));
      const payablesDue = draft.payables.filter(p2 => p2.monthsLeft <= 0).reduce((sum, p2) => sum + p2.amount, 0);
      draft.payables = draft.payables.filter(p2 => p2.monthsLeft > 0);
      draft.capital -= payablesDue;

      // ---- Debt service — indifferent to how the month went, which is the point of debt ----
      let debtPaid = 0, debtMissed = false;
      if ((draft.debts || []).length) {
        const service = totalMonthlyDebtService(draft);
        if (draft.capital >= service) {
          draft.capital -= service;
          debtPaid = service;
          draft.debts = draft.debts
            .map(d => ({ ...d, remaining: Math.max(0, Math.round((d.remaining - d.monthlyPayment) * 10) / 10), monthsLeft: d.monthsLeft - 1 }))
            .filter(d => {
              if (d.remaining <= 0.05 || d.monthsLeft <= 0) {
                tickets.push(mkTicket(month, quarter, 'finance', 'good', t('Debt Cleared'),
                  language === 'es' ? `${DEBT_INSTRUMENTS[d.instrumentId].name.es} liquidada por completo.`
                    : `${DEBT_INSTRUMENTS[d.instrumentId].name.en} paid off in full.`));
                return false;
              }
              return true;
            });
          if (draft.missedDebtPayments > 0) draft.missedDebtPayments = 0; // caught back up
        } else {
          debtMissed = true;
          draft.missedDebtPayments = (draft.missedDebtPayments || 0) + 1;
          applyDelta(draft, { boardConfidence: -6, reputation: -3 });
          tickets.push(mkTicket(month, quarter, 'finance', 'bad', t('Missed Debt Payment'),
            language === 'es'
              ? `No hay efectivo para el servicio de deuda (${fmtMoney(service)}). Incumplimiento ${draft.missedDebtPayments}/${DEBT_DEFAULT_MISSES}.`
              : `No cash for debt service (${fmtMoney(service)}). Miss ${draft.missedDebtPayments}/${DEBT_DEFAULT_MISSES}.`));
        }
      }

      // ---- Emergency financing: expensive and avoidable, not fatal ----
      if (draft.capital < 0) {
        const optionId = emergencyFinancingOption(draft);
        const opt = EMERGENCY_FINANCING[optionId];
        const shortfall = Math.abs(draft.capital);
        const raised = Math.round(shortfall * opt.costMultiplier) + 5;
        draft.capital += raised;
        applyDelta(draft, opt.deltas);
        if (opt.dilutes) draft.dilutionCount = (draft.dilutionCount || 0) + 1;
        draft.emergencyFinancingCount = (draft.emergencyFinancingCount || 0) + 1;
        tickets.push(mkTicket(month, quarter, 'finance', 'bad',
          `${t('Emergency Financing')} — ${opt.name[language === 'es' ? 'es' : 'en']}`,
          `${opt.body[language === 'es' ? 'es' : 'en']} (+${fmtMoney(raised)})`));
      }

      const financeDetail = [];
      if (collected > 0) financeDetail.push(language === 'es' ? `Cobrado: +${fmtMoney(collected)}` : `Collected: +${fmtMoney(collected)}`);
      if (revenueOnTerms > 0) financeDetail.push(language === 'es' ? `A crédito: ${fmtMoney(revenueOnTerms)}` : `On terms: ${fmtMoney(revenueOnTerms)}`);
      if (debtPaid > 0) financeDetail.push(language === 'es' ? `Deuda: -${fmtMoney(debtPaid)}` : `Debt: -${fmtMoney(debtPaid)}`);
      tickets.push(mkTicket(month, quarter, 'system', 'neutral', t('Monthly Finances'),
        language === 'es'
          ? `Gasto: -${fmtMoney(burn)} · Ingresos en efectivo: +${fmtMoney(revenueInCash)}${financeDetail.length ? ' · ' + financeDetail.join(' · ') : ''} · Capital Final: ${fmtMoney(draft.capital)}.`
          : `Burn: -${fmtMoney(burn)} · Cash revenue: +${fmtMoney(revenueInCash)}${financeDetail.length ? ' · ' + financeDetail.join(' · ') : ''} · Ending Capital: ${fmtMoney(draft.capital)}.`));

      // Production report — names which side of the balance is wrong, so the player can act on it
      // rather than inferring from a revenue number that quietly underperforms.
      if (cdReport) {
        const es = language === 'es';
        let tone = 'neutral';
        let detail;
        if (cdReport.shortfall > 0) {
          // Tone follows what actually happened: a real contract breach reads as bad; pure
          // market scarcity with a price premium and no broken promise reads as mixed, not bad —
          // charging more for what you did sell is not a setback.
          tone = cdReport.repHit > 0 ? 'bad' : 'mixed';
          const priceNote = cdReport.scarcityPct > 0
            ? (es ? ` La escasez sube el precio de venta +${cdReport.scarcityPct}%.` : ` Scarcity lifts the price you\u2019re getting +${cdReport.scarcityPct}%.`)
            : '';
          const repNote = cdReport.repHit > 0
            ? (es
              ? ` ${cdReport.b2bShare}% de la demanda es B2B — no cumpliste esos pedidos contratados (-${cdReport.repHit} Reputación).`
              : ` ${cdReport.b2bShare}% of demand is B2B — you missed those contracted orders (-${cdReport.repHit} Reputation).`)
            : (es
              ? ' Sin contratos B2B en juego, así que nadie te lo reprocha — el mercado simplemente vendió lo que había.'
              : ' No B2B contracts on the line, so nobody holds it against you — the market just sold what there was.');
          detail = es
            ? `Capacidad ${cdReport.capacity} · Demanda ${cdReport.demand} · Producción ${cdReport.throughput}. Te faltan ${cdReport.shortfall} unidades de capacidad.${priceNote}${repNote}`
            : `Capacity ${cdReport.capacity} · Demand ${cdReport.demand} · Output ${cdReport.throughput}. You are ${cdReport.shortfall} units short of capacity.${priceNote}${repNote}`;
        } else if (cdReport.idle > 0) {
          tone = 'mixed';
          detail = es
            ? `Capacidad ${cdReport.capacity} · Demanda ${cdReport.demand} · Producción ${cdReport.throughput}. ${cdReport.idle} unidades de planta inactiva${cdReport.idleBurn ? ` (-${fmtMoney(cdReport.idleBurn)} de Gasto)` : ''}.`
            : `Capacity ${cdReport.capacity} · Demand ${cdReport.demand} · Output ${cdReport.throughput}. ${cdReport.idle} units of idle plant${cdReport.idleBurn ? ` (-${fmtMoney(cdReport.idleBurn)} Burn)` : ''}.`;
        } else {
          tone = 'good';
          detail = es
            ? `Capacidad ${cdReport.capacity} · Demanda ${cdReport.demand} · Producción ${cdReport.throughput}. La línea está perfectamente equilibrada.`
            : `Capacity ${cdReport.capacity} · Demand ${cdReport.demand} · Output ${cdReport.throughput}. The line is perfectly balanced.`;
        }
        tickets.push(mkTicket(month, quarter, 'system', tone, t('Production Report'), detail));
      }

      const freeLabor = draft.laborPool - draft.laborReserved;
      if (draft.locations > 0 && freeLabor < draft.locations) {
        draft.morale = clamp(draft.morale - 8, 0, 100);
        tickets.push(mkTicket(month, quarter, 'system', 'bad', t('Understaffed'),
          t('Free labor has fallen below what your locations need. Morale takes a hit.')));
      }

      const stillActive = [];
      draft.activeProjects.forEach(p => {
        p.monthsLeft -= 1;
        if (p.monthsLeft <= 0) {
          const proj = activeIndustry.content.projects.find(x => x.id === p.id);
          const effects = completedEffects(proj, draft.team);
          applyDelta(draft, effects);
          // Product Evangelist: every shipped thing becomes a story that travels.
          if (ffx.projectCompleteReputation > 0) {
            applyDelta(draft, { reputation: ffx.projectCompleteReputation });
          }
          // Moonshot Founder: a big enough bet paying off is the run's defining moment.
          const breakthrough = tryMoonshotBreakthrough(draft, ffx, proj, month, language, t);
          if (breakthrough) tickets.push(breakthrough);
          if (!p.laborPermanent) draft.laborReserved = Math.max(0, draft.laborReserved - p.labor);
          if (proj.flags && proj.flags.isLocation) draft.locations += 1;
          draft.completed[p.id] = true;
          // A physical machine, not just a flag — build order item 2. Instantiated fresh
          // (condition 100, corrective stance) the month the project that builds it finishes.
          if (isEquipmentProject(proj.id)) {
            const eq = instantiateEquipment(proj.id);
            eq.installedMonth = month;
            draft.equipment = { ...draft.equipment, [proj.id]: eq };
          }
          draft.totalAssetSpend = (draft.totalAssetSpend || 0) + (p.capitalPaid || 0);
          const dProj = localizeProject(proj, language);
          const evangelistNote = ffx.projectCompleteReputation > 0
            ? ` +${ffx.projectCompleteReputation} ${t('Reputation')}.` : '';
          tickets.push(mkTicket(month, quarter, 'project', 'good', `${dProj.name} — ${t('Complete')}`, projectCompleteBody(effects, language) + evangelistNote));
        } else {
          stillActive.push(p);
        }
      });
      draft.activeProjects = stillActive;

      // Predictive Analytics thins the event stream — she routed around most of these before
      // they became events.
      const monthlyChance = (activeIndustry.scaling.monthlyEventChance[stageOf(month, activeIndustry.stages).id] || 0.25) * ffx.eventChanceMult;
      // Predictive Analytics' active, spent last month, eats this month's roll entirely.
      if (draft.suppressNextEvent) {
        draft.suppressNextEvent = false;
        tickets.push(mkTicket(month, quarter, 'founder', 'good', t('Routed Around It'),
          language === 'es'
            ? 'El modelo marcó este mes con antelación y lo esquivaste por completo.'
            : 'The model flagged this month in advance, and you steered clear of it entirely.'));
      } else if (Math.random() < monthlyChance) {
        const ev = pick(activeIndustry.content.minorEvents.length ? activeIndustry.content.minorEvents : MINOR_EVENTS);
        const result = resolveEvent(draft, ev, month, language, activeIndustry);
        applyDelta(draft, result.deltas);
        tickets.push(mkTicket(month, quarter, 'event', result.tone, localizeEvent(ev, language).title, result.body));
      }

      // ---- Competitors: they grow every month, and each may move against you ----
      // Growth is now posture-driven: an expansionist rival compounds while a fortified one
      // trades growth for durability. That divergence is what makes last run's treatment of
      // them visible in this run's rank table.
      const mpGrowth = scenario.rivalMarketGrowth != null ? scenario.rivalMarketGrowth : 1;
      draft.competitors = (draft.competitors || []).map(c => {
        const g = rivalMonthlyGrowth(c, mpGrowth, ffx.rivalGrowthMult);
        return {
          ...c,
          strength: c.strength + g.strength,
          marketPosition: clamp(c.marketPosition + g.marketPosition, 0, 100),
        };
      });
      const stageThreshold = 10 + (activeIndustry.scaling.eventThresholdBonus[stageOf(month, activeIndustry.stages).id] || 0);
      draft.competitors.forEach(c => {
        const disposition = deriveDisposition(c);
        const dispAggression = dispositionAggression(disposition);
        const postureDef = RIVAL_POSTURES[c.posture] || RIVAL_POSTURES.balanced;

        // Talent raids resolve before ordinary attacks: a Poacher-led hostile rival going after
        // your people is a distinct kind of move, and shouldn't compete with a price war for the
        // same monthly roll.
        if (dispAggression > 0) {
          const raid = attemptTalentRaid(c, draft, ffx.raidBarBonus, mgrFx.talentAnchor);
          if (raid) {
            c.lastFrictionMonth = month;
            if (raid.held) {
              applyDelta(draft, { boardConfidence: 1, morale: 1 });
              tickets.push(mkTicket(month, quarter, 'competitor', 'mixed',
                `${t('Talent Raid Repelled')} — ${c.name}`,
                language === 'es'
                  ? `${c.name} intentó llevarse a tu gente y no lo logró. El equipo se quedó.`
                  : `${c.name} came for your people and left empty-handed. The team stayed.`));
            } else {
              applyDelta(draft, { laborPool: -raid.taken, morale: -6, talentCulture: 0 });
              tickets.push(mkTicket(month, quarter, 'competitor', 'bad',
                `${t('Talent Raid')} — ${c.name}`,
                language === 'es'
                  ? `${c.name} se llevó ${raid.taken} de tu gente. Los que quedan lo notaron. (-${raid.taken} Personal, -6 Moral)`
                  : `${c.name} took ${raid.taken} of your people. The ones who stayed noticed. (-${raid.taken} Labor, -6 Morale)`));
            }
          }
        }

        // A stronger rival moves more often, and low Morale is blood in the water — the cap is
        // raised from the old flat 0.45 so a genuinely struggling company can be targeted more
        // often than a healthy one ever could be. Posture and disposition now both scale this:
        // an ally's aggression multiplier is 0, so they drop out entirely.
        const rawFreq = 0.12 + c.strength / 200;
        const aggression = scenario.aggressionMultiplier || 1;
        const cap = scenario.attackCap || 0.65;
        const attackChance = Math.min(cap, rawFreq * moraleFrequencyMultiplier(draft.morale) * aggression
          * postureDef.attackChance * dispAggression);
        if (Math.random() > attackChance) return;
        const pool = competitorAttackPool(c, activeIndustry);
        // Predatory rivals read your file and pick the attack you are least equipped to answer.
        const attack = c.posture === 'predatory'
          ? predatoryAttackChoice(pool, draft.stats)
          : pick(pool);
        c.lastFrictionMonth = month;
        // Defense is the same d10 + stat check the rest of the game uses, but the rival's strength
        // pushes the bar up, and low Morale pushes it up a little further — a team that can't rally
        // together defends worse, on top of whatever stat the attack itself calls on.
        const bar = stageThreshold + Math.floor(c.strength / 12) + moraleDefensePenalty(draft.morale) - (scenario.defenseBonus || 0);
        // Lobbyist: anything a regulator, inspector or lawyer is behind gets her thumb on the
        // scale — she knows which door to knock on before it becomes a problem.
        // Lobbyist (founder) and a regulatory-shield manager both help, and they stack — the
        // manager's percentage is expressed on the same +roll scale the founder perk uses.
        const managerComplianceAssist = attack.defendStat === 'compliance' ? Math.round(mgrFx.complianceShield * 20) : 0;
        const complianceAssist = (attack.defendStat === 'compliance' ? ffx.complianceDefenseBonus : 0) + managerComplianceAssist;
        const defTotal = rollTracked(draft) + (draft.stats[attack.defendStat] || 0) + complianceAssist;
        const defCheck = checkWithRiskModel(draft, ffx, defTotal, bar, month);
        const defended = defCheck.success;
        // Successfully fending off an attack is its own small, universal Board Confidence gain —
        // a board watching the team hold the line under pressure reads that as competence too.
        // Built as a new object rather than mutating attack.defendedDeltas, which is shared and
        // reused across every rival and every month.
        const deltas = defended
          ? { ...attack.defendedDeltas, boardConfidence: (attack.defendedDeltas.boardConfidence || 0) + 1 }
          : scaleDeltas(attack.hitDeltas, scenario.attackDamageMultiplier || 1);
        if (deltas.laborPool) {
          // Never cut into labor that's committed to a location or active project.
          const freeNow = draft.laborPool - draft.laborReserved;
          const cut = Math.max(deltas.laborPool, -Math.max(0, freeNow));
          applyDelta(draft, { ...deltas, laborPool: cut });
        } else {
          applyDelta(draft, deltas);
        }
        // A successful hit gains them ground too, not just costs you ground — the rank swings on
        // both sides of the same event, which is what makes fending off attacks worth doing.
        if (!defended) c.marketPosition = clamp(c.marketPosition + 3, 0, 100);
        else draft.attacksDefended = (draft.attacksDefended || 0) + 1;
        // Write the rival's OWN aggression onto its record. Without this, derivePosture only ever
        // saw the player's half of the history, so 'aggressive' and 'predatory' — both of which
        // key off attacksOnPlayer/defeatedPlayer — were unreachable postures in practice.
        const encKind = defended ? 'attackedPlayer' : 'defeatedPlayer';
        const enc = { ...(c.encounters || {}) };
        enc.attackedPlayer = (enc.attackedPlayer || 0) + 1;
        if (!defended) enc.defeatedPlayer = (enc.defeatedPlayer || 0) + 1;
        c.encounters = enc;
        const textFn = defended ? attack.defended : attack.hit;
        const attackDeltaText = deltaSummaryText(deltas, language);
        const attackBody = textFn[language === 'es' ? 'es' : 'en'](c.name) + (attackDeltaText ? ` (${attackDeltaText})` : '');
        tickets.push(mkTicket(month, quarter, 'competitor', defended ? 'mixed' : 'bad',
          `${attack.title[language === 'es' ? 'es' : 'en']} — ${c.name}`,
          attackBody));
      });

      // ---- Coexistence drifts toward alliance ----
      // A rival you've shared a market with for a sustained stretch without either side landing
      // a blow accumulates goodwill. This is the only route to the positive half of the
      // disposition axis, and it's passive by design: peace is something you allow, not
      // something you spend an action on.
      draft.competitors = draft.competitors.map(c => {
        const before = (c.encounters || {}).coexistedRuns || 0;
        const ticked = tickCoexistence(c, month, ffx.coexistMonthsOverride, ffx.coexistCreditBonus);
        const after = (ticked.encounters || {}).coexistedRuns || 0;
        if (after > before) {
          const newBand = dispositionBand(deriveDisposition(ticked, ffx.dispositionDamageMult));
          tickets.push(mkTicket(month, quarter, 'competitor', 'good',
            `${t('Quiet Understanding')} — ${c.name}`,
            language === 'es'
              ? `Un año sin fricción con ${c.name}. La relación se ha suavizado a ${newBand.label.es}.`
              : `A year without friction with ${c.name}. The relationship has settled to ${newBand.label.en}.`));
        }
        return ticked;
      });

      // ---- Allies become suppliers ----
      // Announcement only; the relief itself was already applied to this month's burn above.
      if (allyFx.burnRelief > 0 && !draft.allyReliefAnnounced) {
        draft.allyReliefAnnounced = true;
        tickets.push(mkTicket(month, quarter, 'competitor', 'good',
          t('Supply Agreement'),
          language === 'es'
            ? `${allyFx.allies.map(a => a.name).join(', ')} ahora te abastece. Tu competidor se volvió tu proveedor. (-${fmtMoney(allyFx.burnRelief)} gasto/mes)`
            : `${allyFx.allies.map(a => a.name).join(', ')} now supplies you. Your competitor became your supplier. (-${fmtMoney(allyFx.burnRelief)} burn/mo)`));
      }
      if (allyFx.burnRelief === 0) draft.allyReliefAnnounced = false;

      // ---- Investors watching ----
      // Pressure only bites after each investor's own grace period, and only when you're missing
      // the number they set. Meeting expectations buys silence.
      const pressureResult = applyInvestorPressure(draft, month);
      if (pressureResult) {
        const names = pressureResult.complaints.map(c => c.name).join(', ');
        tickets.push(mkTicket(month, quarter, 'system', 'bad',
          `${t('Board Pressure')} — ${names}`,
          language === 'es'
            ? `${names} esperaba más a estas alturas. La paciencia se agota. (${deltaSummaryText({ boardConfidence: pressureResult.boardConfidence }, language)})`
            : `${names} expected more by now. Patience is running out. (${deltaSummaryText({ boardConfidence: pressureResult.boardConfidence }, language)})`));
      }

      // ---- Cross-system: a rival's success becomes a governance problem ----
      const rankNow = computeMarketRank(draft);
      const rankPressure = rivalRankPressure(draft, rankNow);
      if (rankPressure) {
        applyDelta(draft, { boardConfidence: rankPressure.boardConfidence });
        tickets.push(mkTicket(month, quarter, 'system', 'bad',
          `${t('Uncomfortable Question')} — ${rankPressure.investorName}`,
          language === 'es'
            ? `${rankPressure.investorName} quiere saber por qué estás #${rankPressure.rank} de ${rankPressure.total}. No hay buena respuesta este mes. (${deltaSummaryText({ boardConfidence: rankPressure.boardConfidence }, language)})`
            : `${rankPressure.investorName} wants to know why you're #${rankPressure.rank} of ${rankPressure.total}. There isn't a good answer this month. (${deltaSummaryText({ boardConfidence: rankPressure.boardConfidence }, language)})`));
      }
      // Sustained-rank tracking for marketRankHold objectives. Any month spent outside the
      // scenario's required band resets the streak — "held it" has to mean consecutively.
      const holdObj = (scenario.objectives || []).find(o => o.type === 'marketRankHold');
      if (holdObj) {
        const mr = rankNow; // already computed above for investor rank pressure
        const holding = mr && (holdObj.mode === 'atMost' ? mr.rank <= holdObj.value : mr.rank >= holdObj.value);
        draft.rankHoldStreak = holding ? (draft.rankHoldStreak || 0) + 1 : 0;
      }

      // A board seat structurally prevents total collapse of confidence — applied after all of
      // this month's effects, so it's a genuine floor rather than a one-time nudge.
      if (termFx.boardConfidenceFloor > 0 && draft.boardConfidence < termFx.boardConfidenceFloor) {
        draft.boardConfidence = termFx.boardConfidenceFloor;
      }

      // ---- Founder triggers ----
      // Driven off the shared cadence plumbing; ordering is the table's, not endMonth's. Run
      // after burn has been applied so Handshake Deal reads the runway the player actually has,
      // and before the insolvency check below so the rescue can genuinely save a run.
      const triggerTickets = runFounderMonthlyTriggers(draft, ffx, month, { language, t, burn });
      triggerTickets.forEach(tk => tickets.push(tk));

      // ---- Founder passives that settle at month's end ----
      // Public Servant: a reputation floor, applied last so a bad month can't punch through it,
      // plus a slow Board Confidence dividend while the public standing holds.
      if (ffx.repFloor > 0 && draft.reputation < ffx.repFloor) {
        draft.reputation = ffx.repFloor;
      }
      if (ffx.repHighBCTick && draft.reputation >= ffx.repHighBCTick.threshold) {
        applyDelta(draft, { boardConfidence: ffx.repHighBCTick.amount });
      }
      // Community Builder: satisfied customers occasionally bring their own. Demand where the
      // industry models it, reputation where it doesn't, so the perk is never dead weight.
      if (ffx.demandGenChance > 0 && Math.random() < ffx.demandGenChance) {
        if (activeIndustry.revenueModel === 'capacityDemand' && ffx.demandGenAmount > 0) {
          applyDelta(draft, { demand: ffx.demandGenAmount });
          tickets.push(mkTicket(month, quarter, 'system', 'good', t('Word of Mouth'),
            language === 'es'
              ? `Los clientes habituales trajeron amigos. (+${ffx.demandGenAmount} Demanda)`
              : `The regulars brought friends. (+${ffx.demandGenAmount} Demand)`));
        } else if (ffx.repGenAmount > 0) {
          applyDelta(draft, { reputation: ffx.repGenAmount });
          tickets.push(mkTicket(month, quarter, 'system', 'good', t('Word of Mouth'),
            language === 'es'
              ? `Los clientes habituales trajeron amigos. (+${ffx.repGenAmount} Reputación)`
              : `The regulars brought friends. (+${ffx.repGenAmount} Reputation)`));
        }
      }
      // Future Market / Scenario Planner fire on the boundary between stages.
      if (isStageTransition && (ffx.stageTransitionMP > 0 || ffx.stageTransitionBC > 0)) {
        const transDeltas = {};
        if (ffx.stageTransitionMP > 0) transDeltas.marketPosition = ffx.stageTransitionMP;
        if (ffx.stageTransitionBC > 0) transDeltas.boardConfidence = ffx.stageTransitionBC;
        applyDelta(draft, transDeltas);
        tickets.push(mkTicket(month, quarter, 'system', 'good',
          ffx.stageTransitionMP > 0 ? t('Already There') : t('Planned For'),
          `${language === 'es' ? 'La transición de etapa te encontró preparado.' : 'The stage transition found you ready for it.'} (${deltaSummaryText(transDeltas, language)})`));
      }

      // Derived fresh from this month's settled state — burn, revenue, and any completed
      // project are already applied above, so this reflects the company as it actually stands
      // at month's end, not an incremental patch on top of last month's number.
      draft.companyValuation = computeValuation(draft, getIndustry(draft.industryId));

      draft.month += 1;
      draft.ap = activeIndustry.apByStage[stageOf(draft.month, activeIndustry.stages).id] || 3;
      draft.visionaryBonusUsedThisMonth = false;
      // Every leader's Operate refreshes with the new month.
      draft.operatedThisMonth = [];


      if (draft.month <= runEnd) {
        const CE = activeIndustry.content.choiceEvents.length ? activeIndustry.content.choiceEvents : CHOICE_EVENTS;
        const unusedChoices = CE.filter(ev => !draft.usedChoiceEventIds.includes(ev.id));
        if (draft.month >= draft.nextChoiceEventMonth && unusedChoices.length > 0) {
          const chosen = pick(unusedChoices);
          draft.usedChoiceEventIds = [...draft.usedChoiceEventIds, chosen.id];
          draft.pendingChoice = { event: chosen, month: draft.month, quarter: quarterOf(draft.month) };
          draft.nextChoiceEventMonth = draft.month + randInt(2, 4);
        }
      }

      if (month % 3 === 0) {
        const ev = pick(activeIndustry.content.majorEvents.length ? activeIndustry.content.majorEvents : MAJOR_EVENTS);
        const result = resolveEvent(draft, ev, month, language, activeIndustry);
        applyDelta(draft, result.deltas);
        tickets.push(mkTicket(month, quarter, 'event', result.tone, localizeEvent(ev, language).title, result.body));

        const valuationDelta = draft.companyValuation - draft.valuationAtLastReport;
        draft.valuationAtLastReport = draft.companyValuation;
        const sign = valuationDelta >= 0 ? '+' : '';
        tickets.push(mkTicket(month, quarter, 'report', valuationDelta >= 0 ? 'good' : 'bad', `${t('Quarterly Valuation Update — Q')}${quarter}`,
          language === 'es'
            ? `La Valorización de la Empresa ahora es de ${fmtMoney(draft.companyValuation)} (${sign}${fmtMoney(valuationDelta)} este trimestre).`
            : `Company Valuation now stands at ${fmtMoney(draft.companyValuation)} (${sign}${fmtMoney(valuationDelta)} this quarter).`));

        // Ousting is now a JOINT failure, not a morale-only one. The diagnostic found this
        // firing on companies with capital 71k, revenue 24, BC 70 and 17 completed projects —
        // a board does not fire a CEO who is winning just because staff are unhappy. It now
        // needs the board to have lost confidence too.
        //
        // Deliberate hysteresis: the clock STARTS at morale<40 & BC<50, but only STOPS once
        // both climb clear of higher marks (45 / 55). Without that gap a company hovering on
        // the threshold would flicker in and out of danger every quarter, which reads as noise
        // rather than as a crisis you're either in or out of. Recovering has to mean something.
        const inDanger = draft.morale < OUST_MORALE_ENTER && draft.boardConfidence < OUST_BC_ENTER;
        const hasRecovered = draft.morale >= OUST_MORALE_EXIT && draft.boardConfidence >= OUST_BC_EXIT;
        if (hasRecovered) draft.lowMoraleStreak = 0;
        else if (inDanger || draft.lowMoraleStreak > 0) draft.lowMoraleStreak += 1;
        if (draft.lowMoraleStreak >= OUST_QUARTERS) {
          draft.gameOver = language === 'es'
            ? { won: false, reason: 'ousted', headline: 'Destituido por el Directorio',
                body: 'La moral y la confianza del directorio se mantuvieron críticamente bajas durante tres trimestres seguidos. El directorio perdió la fe en tu liderazgo y votó por destituirte.' }
            : { won: false, reason: 'ousted', headline: 'Ousted by the Board',
                body: 'Morale and board confidence both stayed critically low for three straight quarters. The board lost faith in your leadership and voted you out.' };
        }
        if (!draft.gameOver && draft.boardConfidence <= 0) {
          draft.gameOver = language === 'es'
            ? { won: false, reason: 'ousted', headline: 'Destituido por el Directorio',
                body: 'La Confianza del Directorio llegó a cero. El directorio ejerce sus derechos y te remueve como CEO.' }
            : { won: false, reason: 'ousted', headline: 'Ousted by the Board',
                body: 'Board confidence hit zero. The board exercises its rights and removes you as CEO.' };
        }
      }

      // Debt default — the Bible's "fatal if left unserviced", implemented as an escalating
      // counter rather than an instant kill so the player gets visible, actionable warnings
      // first. Same hysteresis principle the ousting rule uses.
      if (!draft.gameOver && (draft.missedDebtPayments || 0) >= DEBT_DEFAULT_MISSES) {
        draft.gameOver = language === 'es'
          ? { won: false, reason: 'debtDefault', headline: 'Incumplimiento de Deuda',
              body: `Tres meses sin cubrir el servicio de deuda. Los acreedores ejecutaron sus garantías y la empresa dejó de ser tuya.` }
          : { won: false, reason: 'debtDefault', headline: 'Debt Default',
              body: `Three straight months without covering debt service. The creditors called in their security, and the company stopped being yours.` };
      }

      if (!draft.gameOver && draft.capital < 0) {
        draft.gameOver = language === 'es'
          ? { won: false, reason: 'insolvent', headline: 'Insolvente',
              body: `El Gasto superó la cuenta bancaria. Con ${fmtMoney(draft.capital)} en caja, no queda margen de maniobra.` }
          : { won: false, reason: 'insolvent', headline: 'Insolvent',
              body: `Burn outran the bank account. With ${fmtMoney(draft.capital)} on the books, there's no runway left.` };
      }

      // Stage-transition gates: only scenarios that opt in (the full run) enforce these.
      // Stage gates, industry-driven. Hospitality declares four; Manufacturing will declare its
      // own six-stage set. The engine no longer knows which industry it's running.
      if (!draft.gameOver && scenario.stageGates) {
        const L = language === 'es' ? 'es' : 'en';
        for (const gate of (activeIndustry.stageGates || [])) {
          const st = activeIndustry.stages[gate.stageIndex];
          if (!st || month !== st.end) continue;
          if (gate.passes(draft)) continue;
          draft.gameOver = { won: false, reason: 'stageTimeout', headline: gate.headline[L], body: gate.body[L](draft) };
          break;
        }
      }
      // Objectives: a scenario is won the moment every required objective reads met.
      if (!draft.gameOver) {
        const { allMet } = evaluateObjectives(draft, scenario, language);
        if (allMet && scenario.kind !== 'full') {
          draft.gameOver = language === 'es'
            ? { won: true, reason: 'objectives', headline: 'Objetivos Cumplidos',
                body: `Lograste todo lo que te propusiste antes del mes ${runEnd}.` }
            : { won: true, reason: 'objectives', headline: 'Objectives Met',
                body: `You hit everything you set out to do before month ${runEnd}.` };
        }
      }
      if (!draft.gameOver && draft.month > runEnd) {
        if (scenario.kind === 'full') {
          draft.gameOver = language === 'es'
            ? { won: false, reason: 'noExit', headline: 'Sin Salida Asegurada',
                body: 'La Ventana de Salida se cierra en el mes 45 sin un trato firmado. El directorio opta por cerrar la operación.' }
            : { won: false, reason: 'noExit', headline: 'No Exit Secured',
                body: 'The Exit Window closes at month 45 without a deal signed. The board opts to wind things down.' };
        } else {
          draft.gameOver = language === 'es'
            ? { won: false, reason: 'objectivesMissed', headline: 'Objetivos No Cumplidos',
                body: `Se acabó el tiempo en el mes ${runEnd} sin cumplir todos los objetivos.` }
            : { won: false, reason: 'objectivesMissed', headline: 'Objectives Missed',
                body: `Time ran out at month ${runEnd} without clearing every objective.` };
        }
      }

      // ---- Business Model: a commitment comes due as its stage opens ----
      // Set as pending state (not a blocking modal in the engine) so the UI can present it and
      // the run continues either way — an unanswered fork is simply offered again next month.
      if (!draft.gameOver && draft.month <= runEnd) {
        const dueAxis = pendingModelAxis(draft, activeIndustry);
        if (dueAxis && draft.pendingCommitAxisId !== dueAxis.id) {
          draft.pendingCommitAxisId = dueAxis.id;
          const L = language === 'es' ? 'es' : 'en';
          tickets.push(mkTicket(draft.month, quarterOf(draft.month), 'system', 'neutral',
            `${t('Strategic Commitment Due')}: ${dueAxis.name[L]}`, dueAxis.question[L]));
        }
      }

      // ---- New rivals arrive as each stage opens ----
      // Placed after the game-over checks so a run that just ended doesn't also announce
      // competitors arriving for a stage the player will never play.
      if (!draft.gameOver && draft.month <= runEnd) {
        const newStage = stageOf(draft.month, activeIndustry.stages);
        const spawnTable = activeIndustry.competitorSpawns || COMPETITOR_SPAWNS;
        const spawnCount = spawnTable[newStage.id] || 0;
        if (spawnCount > 0 && !(draft.spawnedCompetitorStages || []).includes(newStage.id)) {
          draft.spawnedCompetitorStages = [...(draft.spawnedCompetitorStages || []), newStage.id];
          const nq = quarterOf(draft.month);
          for (let i = 0; i < spawnCount; i++) {
            const names = [...knownCompanyNamesRef.current, ...draft.competitors.map(c => c.name)];
            const leaderNames = draft.competitors.flatMap(c => c.leaders.map(l => l.name));
            // A rival you've met before has a real chance of walking back in — same company,
            // same mark, carrying what happened between you. This is the Nemesis payoff.
            const alreadyHere = new Set(draft.competitors.map(c => c.seedId));
            const returnable = (draft.knownRivals || []).filter(r => !alreadyHere.has(r.seedId));
            const revive = returnable.length && Math.random() < 0.45 ? pick(returnable) : null;
            // Exclude both companies currently in the market AND ones remembered from previous
            // runs, so an authored rival isn't spawned as a "new" company the player has
            // already built a history with.
            const usedSeeds = [
              ...draft.competitors.map(c => c.seedId),
              ...(draft.knownRivals || []).map(r => r.seedId),
            ].filter(Boolean);
            const rival = makeCompetitor(names, leaderNames, draft.month, language, draft.industryId || 'hospitality', activeIndustry.content, revive, usedSeeds);
            draft.competitors = [...draft.competitors, rival];
            const roster = rival.leaders.map(l => `${l.name} (${rivalRoleText(l.role, language)})`).join(', ');
            const band = dispositionBand(rival.disposition);
            tickets.push(mkTicket(draft.month, nq, 'competitor', 'bad',
              rival.returning
                ? `${t('They\u2019re Back')}: ${rival.name}`
                : `${t('New Competitor')}: ${rival.name}`,
              rival.returning
                ? (language === 'es'
                  ? `${rival.name} vuelve al mercado, dirigida por ${roster}. Postura: ${(RIVAL_POSTURES[rival.posture] || RIVAL_POSTURES.balanced).label.es}. Relación: ${band.label.es}. Han competido contigo antes — y han aprendido.`
                  : `${rival.name} returns to the market, led by ${roster}. Posture: ${(RIVAL_POSTURES[rival.posture] || RIVAL_POSTURES.balanced).label.en}. Standing: ${band.label.en}. They've competed against you before — and they've learned from it.`)
                : (language === 'es'
                  ? `${rival.name} entra al mercado, dirigida por ${roster}. Estarán construyendo junto a ti de aquí en adelante.`
                  : `${rival.name} enters the market, led by ${roster}. They'll be building alongside you from here on.`)));
          }
        }
      }

      draft.log = [...tickets.slice().reverse(), ...draft.log];
      draft.pendingSummary = { month, quarter, tickets };
      return draft;
    });
  }

  function handleAttemptExit(exitId) {
    setGame(prev => {
      if (!prev || prev.gameOver) return prev;
      const def = (getIndustry(prev.industryId).content.exits.length ? getIndustry(prev.industryId).content.exits : EXIT_DEFS).find(e => e.id === exitId);
      if (!def) return prev;
      const { allMet } = exitProgress(prev, def, language);
      if (!allMet) return prev;
      const n = prev.dilutionCount;
      const flavor = language === 'es' ? {
        acquiHire: `Un operador más pequeño absorbe discretamente al equipo y el concepto. Pago modesto, salida limpia. Recaudaste capital en ${n} ronda${n !== 1 ? 's' : ''}.`,
        acquisition: `Un grupo de hostelería regional adquiere la empresa a un múltiplo sólido. Recaudaste capital en ${n} ronda${n !== 1 ? 's' : ''} en el camino.`,
        peBuyout: `Una firma de capital privado invierte, atraída más por los márgenes que por el revuelo. Recaudaste capital en ${n} ronda${n !== 1 ? 's' : ''}.`,
        ipo: `Tocas la campana de apertura. Mercados públicos, estadísticas sólidas, y un directorio que por fin deja de hacer preguntas difíciles. Recaudaste capital en ${n} ronda${n !== 1 ? 's' : ''} en el camino.`,
      } : {
        acquiHire: `A smaller operator quietly absorbs the team and the concept. Modest payout, clean exit. You raised capital across ${n} round${n !== 1 ? 's' : ''}.`,
        acquisition: `A regional hospitality group acquires the company at a strong multiple. You raised capital across ${n} round${n !== 1 ? 's' : ''} along the way.`,
        peBuyout: `A private equity firm buys in, drawn by the margins more than the buzz. You raised capital across ${n} round${n !== 1 ? 's' : ''}.`,
        ipo: `You ring the opening bell. Public markets, a real stat sheet, and a board that finally stops asking hard questions. You raised capital across ${n} round${n !== 1 ? 's' : ''} on the way here.`,
      };
      const doneWord = language === 'es' ? 'Lograda' : 'Done';
      return { ...prev, gameOver: { won: true, reason: exitId, headline: `${t(def.name)} — ${doneWord}`, body: flavor[exitId] } };
    });
  }

  // ===== END HANDLER BLOCK (harness extraction boundary — see build_harness.mjs) =====
  // Everything ABOVE this line is lifted verbatim into the test harness and must depend only on
  // setGame/language/t/knownCompanyNamesRef. Everything BELOW may use component state freely.

  // Opens the founder customization screen, seeding the draft from the persisted founder so a
  // returning player sees their existing loadout rather than a blank form.
  function openFounderScreen() {
    setDraftFounder(founderDoc.custom ? { ...founderDoc.custom } : emptyCustomFounder());
    setUseCustomFounder(true);
    setPreGameView('founder');
  }

  // Every founder the player could bring along, across both industries, plus their own founder.
  // The roster is career-wide — a Manufacturing engineer you've run with is still part of your
  // history when you're browsing before a Hospitality run.
  const allRosterLeaders = (() => {
    const seen = new Set();
    const out = [];
    if (founderDoc.custom && founderDoc.custom.name) {
      out.push({ ...customFounderToLeader(founderDoc.custom, language, founderDoc.career), isCustom: true });
    }
    Object.values(INDUSTRIES).forEach(ind => {
      (ind.content.leaders || []).forEach(l => {
        if (seen.has(l.id)) return;
        seen.add(l.id);
        // baseStatBonus is preserved separately so the detail window can show authored-vs-earned.
        out.push({ ...localizeLeader(l, language), baseStatBonus: l.statBonus, operate: { label: localizeLeader(l, language).operateLabelDisplay, desc: localizeLeader(l, language).operateDescDisplay, deltas: l.operate.deltas } });
      });
    });
    return out;
  })();

  async function allocateRosterPoints(leaderId, allocated) {
    const doc = await Store.allocateRosterPoints(leaderId, allocated);
    setFounderDoc({ ...doc, unlocked: evaluateUnlocks(doc.career) });
  }

  async function confirmFounder(f) {
    const doc = await Store.saveCustomFounder(f);
    setFounderDoc({ ...doc, unlocked: evaluateUnlocks(doc.career) });
    setSelectedIds([]);
    setPreGameView('industry');
  }

  // ---------------- Render: Founder customization ----------------
  if (!game && preGameView === 'founder' && draftFounder) {
    return (
      <FounderCustomizeScreen
        language={language}
        founderDoc={founderDoc}
        draft={draftFounder}
        setDraft={setDraftFounder}
        onConfirm={confirmFounder}
        onBack={() => setPreGameView('title')}
        t={t}
      />
    );
  }

  // ---------------- Render: Title ----------------
  if (!game && preGameView === 'title') {
    const summary = (() => {
      if (!savedGame) return '';
      const savedInd = getIndustry(savedGame.industryId);
      if (savedGame.gameOver) return `${t('Finished — ')}${savedGame.gameOver.headline} (${t('Month')} ${Math.min(savedGame.month, savedGame.endMonth || savedInd.runEnd)})`;
      const se = savedGame.endMonth || savedInd.runEnd;
      return `${t('Month')} ${savedGame.month}/${se} · ${stageOf(Math.min(savedGame.month, se), savedInd.stages).name} · ${(savedGame.team && savedGame.team.name) || t('in progress')}`;
    })();
    const lines = language === 'es' ? TITLE_LINES_ES : TITLE_LINES;
    return (
      <div style={{ background: C.ink, minHeight: '100vh', fontFamily: F_BODY, color: C.text, position: 'relative' }} className="p-4 md:p-10 flex flex-col items-center justify-center text-center">
        <FontImport />
        {showTutorial && <Modal onClose={() => setShowTutorial(false)} title={t('How to Play')}><TutorialContent language={language} industryId={pendingIndustryId} /></Modal>}
        {showAchievements && <Modal onClose={() => setShowAchievements(false)} title={t('Achievements')}><AchievementsInfoContent language={language} /></Modal>}
        {showMetaProgression && <Modal onClose={() => setShowMetaProgression(false)} title={t('Meta-Progression')}><MetaProgressionInfoContent language={language} metaStats={metaStats} /></Modal>}
        {showSettings && <SettingsModal onClose={() => setShowSettings(false)} onOpenIndex={() => { setShowSettings(false); setShowIndex(true); }} soundEnabled={soundEnabled} onToggleSound={toggleSound} language={language} onToggleLanguage={toggleLanguage} game={null} onImportSave={handleImportSave} />}
        {showIndex && <Modal onClose={() => setShowIndex(false)} title={t('Business & Game Index')}><IndexTabs language={language} game={game} /></Modal>}
        <button onClick={() => setShowSettings(true)} title={t('Settings')}
          style={{ position: 'absolute', top: 16, right: 16, border: `1px solid ${C.hair}`, color: C.muted, background: C.panel }}
          className="rounded-full w-9 h-9 text-base">
          ⚙
        </button>
        {/* Derived from which industries are actually enabled, not hardcoded — so a
            single-industry build (e.g. the Manufacturing vertical slice) labels itself
            correctly with no separate edit, and this line cannot go stale again the way the
            Hospitality-only version did. */}
        <div style={{ color: C.brass, fontFamily: F_MONO, letterSpacing: '0.2em' }} className="text-xs uppercase mb-3">
          {(() => {
            const readyList = Object.values(INDUSTRIES).filter(i => i.ready);
            if (readyList.length === 1) {
              const nm = readyList[0].name[language === 'es' ? 'es' : 'en'];
              return language === 'es' ? `Prototipo · Segmento Vertical de ${nm}` : `Prototype · ${nm} Vertical Slice`;
            }
            return t('Prototype · Multi-Industry Build');
          })()}
        </div>
        <h1 style={{ fontFamily: F_DISPLAY, color: C.paper }} className="text-6xl md:text-7xl font-semibold mb-8">BLUE OCEAN</h1>
        <div className="max-w-md mx-auto mb-10 space-y-2">
          {lines.map((line, i) => (
            <p key={i} style={{ color: C.muted, opacity: 0, animation: 'founderFadeIn 0.9s ease-out forwards', animationDelay: `${i * 1}s` }} className="text-sm md:text-base">
              {line}
            </p>
          ))}
        </div>
        <div className="flex flex-col gap-3 w-full max-w-xs">
          {savedGame && !confirmDiscardSave && (
            <button onClick={resumeSavedGame} style={{ background: C.good, color: C.ink }} className="rounded py-3 text-sm font-semibold hover:brightness-110">
              {t('Continue Run')}
              <div style={{ fontFamily: F_MONO, opacity: 0.8 }} className="text-[10px] font-normal mt-0.5">{summary}</div>
            </button>
          )}
          {confirmDiscardSave ? (
            <div style={{ border: `1px solid ${C.rust}`, background: C.panel }} className="rounded p-3 text-left">
              <div style={{ color: C.text }} className="text-xs mb-2">{t('This discards your saved run in progress')} ({summary}). {t('Are you sure?')}</div>
              <div className="flex gap-2">
                <button onClick={async () => { await clearSave(); setConfirmDiscardSave(false); openFounderScreen(); }}
                  style={{ background: C.rust, color: C.paper }} className="flex-1 rounded py-2 text-xs font-semibold">
                  {t('Discard & Start New')}
                </button>
                <button onClick={() => setConfirmDiscardSave(false)} style={{ border: `1px solid ${C.hair}`, color: C.muted }} className="flex-1 rounded py-2 text-xs font-semibold">
                  {t('Cancel')}
                </button>
              </div>
            </div>
          ) : (
            <button onClick={() => { setPendingScenarioId('fullRun'); if (savedGame) setConfirmDiscardSave(true); else openFounderScreen(); }}
              style={{ background: savedGame ? 'transparent' : C.brass, color: savedGame ? C.muted : C.ink, border: savedGame ? `1px solid ${C.hair}` : 'none' }}
              className="rounded py-3 text-sm font-semibold hover:brightness-110">
              {t('Start New Run')}
            </button>
          )}
          {!confirmDiscardSave && (
            <button onClick={() => { setPendingScenarioId('fullRun'); setUseCustomFounder(false); setPreGameView('quickplay'); }}
              style={{ border: `1px solid ${C.brass}`, color: C.brass }} className="rounded py-3 text-sm font-semibold">
              {t('Quickplay')}
              <div style={{ fontFamily: F_MONO, opacity: 0.75 }} className="text-[10px] font-normal mt-0.5">{t('Jump into a later stage')}</div>
            </button>
          )}
          <button onClick={() => setShowAchievements(true)} style={{ border: `1px solid ${C.hair}`, color: C.text }} className="rounded py-3 text-sm font-semibold">
            {t('Achievements')}
          </button>
          <button onClick={() => setShowMetaProgression(true)} style={{ border: `1px solid ${C.hair}`, color: C.text }} className="rounded py-3 text-sm font-semibold">
            {t('Meta-Progression')}
          </button>
          <button onClick={() => setShowTutorial(true)} style={{ border: `1px solid ${C.hair}`, color: C.text }} className="rounded py-3 text-sm font-semibold">
            {t('Tutorial')}
          </button>
        </div>
        <div style={{ color: C.muted, fontFamily: F_MONO }} className="text-[10px] mt-6">{t('Progress saves automatically after every action — close anytime, pick up where you left off.')}</div>
      </div>
    );
  }

  // ---------------- Render: Quickplay (scenario picker) ----------------
  // ---------------- Render: Industry selection ----------------
  // ---------------- Render: Starting product selection (product-catalogue industries) ----------------
  if (!game && preGameView === 'product') {
    const ind = getIndustry(pendingIndustryId);
    const catalog = ind.productCatalog || [];
    const L = language === 'es' ? 'es' : 'en';
    return (
      <div style={{ background: C.ink, minHeight: '100vh', fontFamily: F_BODY, color: C.text }} className="p-4 md:p-10">
        <FontImport />
        <div className="max-w-4xl mx-auto" style={{ paddingBottom: 40 }}>
          <button onClick={() => setPreGameView('industry')} style={{ color: C.muted, fontFamily: F_MONO }} className="text-xs mb-4">{t('← Back')}</button>
          <div className="mb-6 text-center">
            <h2 style={{ fontFamily: F_DISPLAY, color: C.paper }} className="text-2xl md:text-3xl font-semibold mb-2">
              {L === 'es' ? '¿Qué vas a fabricar?' : 'What Will You Make?'}
            </h2>
            <p style={{ color: C.muted }} className="max-w-xl mx-auto text-sm">
              {L === 'es'
                ? 'Tu primer producto define de qué es capaz la empresa. Todo lo que construyas después se mide contra esto — materiales, máquinas, habilidades y canales compartidos.'
                : 'Your first product defines what the company is capable of. Everything you build afterward is measured against it — shared materials, machines, skills and channels.'}
            </p>
          </div>

          <div className="grid md:grid-cols-2 gap-2 mb-4">
            {catalog.filter(prod => {
              const biz = STARTING_BUSINESSES.find(b => b.entityId === prod.id);
              return !biz || businessUnlocked(biz.id, (founderDoc && founderDoc.career) || {});
            }).map(prod => {
              const sel = pendingProductId === prod.id;
              const biz = STARTING_BUSINESSES.find(b => b.entityId === prod.id);
              const diff = biz && BUSINESS_UNLOCKS[biz.id] ? BUSINESS_DIFFICULTY[BUSINESS_UNLOCKS[biz.id].difficulty] : null;
              return (
                <button key={prod.id} onClick={() => setPendingProductId(prod.id)}
                  style={{ background: sel ? C.panel3 : C.panel2, border: `1px solid ${sel ? C.brass : C.hair}`, textAlign: 'left' }}
                  className="rounded-lg p-3">
                  <div className="flex items-baseline justify-between mb-1">
                    <span style={{ color: C.paper }} className="text-sm font-semibold">{prod.name[L]}</span>
                    <span className="flex items-baseline gap-1.5">
                      {diff && (
                        <span style={{ color: diff.color === 'rust' ? C.rust : diff.color === 'good' ? C.good : C.brass, fontFamily: F_MONO }}
                          className="text-[8px] uppercase tracking-widest">{diff.label[L]}</span>
                      )}
                      {sel && <span style={{ color: C.brass, fontFamily: F_MONO }} className="text-[10px]">✓</span>}
                    </span>
                  </div>
                  <div style={{ color: C.muted }} className="text-[11px] leading-snug mb-1.5">{prod.blurb ? prod.blurb[L] : ''}</div>
                  <div style={{ color: C.brassDim, fontFamily: F_MONO }} className="text-[9px]">
                    {L === 'es' ? 'Materiales' : 'Materials'}: {prod.resourceProfile.materials.join(', ')}
                    {' · '}{L === 'es' ? 'Calidad máx' : 'Quality ceiling'} {prod.qualityCeiling}
                    {' · '}{L === 'es' ? 'Escala' : 'Scale'} {prod.scalability}/5
                  </div>
                </button>
              );
            })}
          </div>

          {/* Placeholders for content that does not exist yet — shown so the eventual shape of the
              catalogue is visible from the first run rather than arriving as a surprise. */}
          {/* Locked businesses are shown with what actually unlocks them — a visible ladder, not a
              vague "coming later". Direction: the harder lines are more rewarding and are earned. */}
          {(() => {
            const career = (founderDoc && founderDoc.career) || {};
            const locked = STARTING_BUSINESSES.filter(b => !businessUnlocked(b.id, career));
            if (!locked.length) return null;
            return (
              <>
                <div style={{ color: C.brass, fontFamily: F_MONO }} className="text-[10px] uppercase tracking-widest mb-1.5">
                  {L === 'es' ? `Por Desbloquear (${locked.length})` : `Locked (${locked.length})`}
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-1.5 mb-4">
                  {locked
                    .sort((a, b) => BUSINESS_DIFFICULTY[BUSINESS_UNLOCKS[a.id].difficulty].order
                      - BUSINESS_DIFFICULTY[BUSINESS_UNLOCKS[b.id].difficulty].order)
                    .map(b => {
                      const u = BUSINESS_UNLOCKS[b.id];
                      const d = BUSINESS_DIFFICULTY[u.difficulty];
                      return (
                        <div key={b.id} style={{ background: C.panel2, border: `1px solid ${C.hair}`, opacity: 0.65 }}
                          className="rounded p-2">
                          <div className="flex items-baseline justify-between">
                            <span style={{ color: C.muted }} className="text-[11px] font-semibold">🔒 {b.name[L]}</span>
                            <span style={{ color: d.color === 'rust' ? C.rust : C.brass, fontFamily: F_MONO }}
                              className="text-[8px] uppercase tracking-widest">{d.label[L]}</span>
                          </div>
                          <div style={{ color: C.brassDim, fontFamily: F_MONO }} className="text-[9px] mt-0.5">
                            {u.hint ? u.hint[L] : ''}
                          </div>
                        </div>
                      );
                    })}
                </div>
              </>
            );
          })()}

          <div style={{ background: C.panel, border: `1px solid ${C.hair}` }} className="rounded-lg p-4 flex items-center justify-between gap-3">
            <div style={{ color: C.muted, fontFamily: F_MONO }} className="text-[10px]">
              {pendingProductId
                ? (L === 'es' ? 'Empezarás desarrollando este producto.' : 'You will begin developing this product.')
                : (L === 'es' ? 'Elige un producto para continuar.' : 'Choose a product to continue.')}
            </div>
            <button onClick={() => pendingProductId && setPreGameView('select')} disabled={!pendingProductId}
              style={{ background: pendingProductId ? C.brass : C.hair, color: pendingProductId ? C.ink : C.muted, opacity: pendingProductId ? 1 : 0.6 }}
              className="rounded px-6 py-2 text-sm font-semibold">
              {t('Continue')}
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (!game && preGameView === 'industry') {
    const L = language === 'es' ? 'es' : 'en';
    const playable = Object.values(INDUSTRIES).filter(ind => ind.ready);
    return (
      <div style={{ background: C.ink, minHeight: '100vh', fontFamily: F_BODY, color: C.text, position: 'relative' }} className="p-4 md:p-10">
        <FontImport />
        {showSettings && <SettingsModal onClose={() => setShowSettings(false)} onOpenIndex={() => { setShowSettings(false); setShowIndex(true); }} soundEnabled={soundEnabled} onToggleSound={toggleSound} language={language} onToggleLanguage={toggleLanguage} game={null} onImportSave={handleImportSave} />}
        {showIndex && <Modal onClose={() => setShowIndex(false)} title={t('Business & Game Index')}><IndexTabs language={language} game={game} /></Modal>}
        <button onClick={() => setShowSettings(true)} title={t('Settings')}
          style={{ position: 'absolute', top: 16, right: 16, border: `1px solid ${C.hair}`, color: C.muted, background: C.panel }}
          className="rounded-full w-9 h-9 text-base">⚙</button>
        <div className="max-w-3xl mx-auto">
          <button onClick={() => setPreGameView('title')} style={{ color: C.muted, fontFamily: F_MONO }} className="text-xs mb-4">{t('← Back')}</button>
          <div className="mb-6 text-center">
            <h2 style={{ fontFamily: F_DISPLAY, color: C.paper }} className="text-2xl md:text-3xl font-semibold mb-2">{t('Choose Your Industry')}</h2>
            <p style={{ color: C.muted }} className="max-w-xl mx-auto text-sm">
              {t('Each industry runs on the same business systems but emphasizes different ones — and has its own lifecycle, projects, rivals, and ways out.')}
            </p>
          </div>
          <div className="space-y-3">
            {playable.map(ind => {
              const coreSystems = SYSTEMS.filter(s => ind.systemProfile[s] === 'core');
              const stageCount = ind.stages.length;
              return (
                <button key={ind.id} onClick={() => {
                  setSelectedIds([]); setPendingIndustryId(ind.id);
                  setPendingCompanyName(rollCompanyName(ind.id, language));
                  // Industries with a product catalogue get a "what will you make?" step first —
                  // it is the decision that defines the company, so it belongs up front.
                  setPreGameView(ind.productCatalog ? 'product' : 'select');
                }}
                  style={{ background: C.panel, border: `1px solid ${C.brass}`, textAlign: 'left' }}
                  className="w-full rounded-lg p-4 hover:brightness-110">
                  <div className="flex items-baseline justify-between gap-3 mb-1">
                    <div style={{ color: C.paper, fontFamily: F_DISPLAY }} className="text-xl">{ind.name[L]}</div>
                    <div style={{ color: C.brass, fontFamily: F_MONO }} className="text-[10px] whitespace-nowrap">
                      {stageCount} {t('stages')} · {ind.runEnd} {t('months')}
                    </div>
                  </div>
                  <div style={{ color: C.text }} className="text-xs mb-2">{INDUSTRY_BLURBS[ind.id] ? INDUSTRY_BLURBS[ind.id][L] : ''}</div>
                  <div style={{ color: C.muted, fontFamily: F_MONO }} className="text-[10px]">
                    {t('Core systems')}: {coreSystems.map(s => t(SYSTEM_LABELS[s][L])).join(' · ')}
                  </div>
                  {ind.revenueModel === 'capacityDemand' && (
                    <div style={{ color: C.rust, fontFamily: F_MONO }} className="text-[10px] mt-1">
                      ⚙ {t('Revenue is limited by Capacity and Demand together.')}
                    </div>
                  )}
                </button>
              );
            })}
          </div>
        </div>
      </div>
    );
  }

  if (!game && preGameView === 'quickplay') {
    const L = language === 'es' ? 'es' : 'en';
    return (
      <div style={{ background: C.ink, minHeight: '100vh', fontFamily: F_BODY, color: C.text, position: 'relative' }} className="p-4 md:p-10">
        <FontImport />
        {showSettings && <SettingsModal onClose={() => setShowSettings(false)} onOpenIndex={() => { setShowSettings(false); setShowIndex(true); }} soundEnabled={soundEnabled} onToggleSound={toggleSound} language={language} onToggleLanguage={toggleLanguage} game={null} onImportSave={handleImportSave} />}
        {showIndex && <Modal onClose={() => setShowIndex(false)} title={t('Business & Game Index')}><IndexTabs language={language} game={game} /></Modal>}
        <button onClick={() => setShowSettings(true)} title={t('Settings')}
          style={{ position: 'absolute', top: 16, right: 16, border: `1px solid ${C.hair}`, color: C.muted, background: C.panel }}
          className="rounded-full w-9 h-9 text-base">⚙</button>
        <div className="max-w-3xl mx-auto">
          <button onClick={() => setPreGameView('title')} style={{ color: C.muted, fontFamily: F_MONO }} className="text-xs mb-4">{t('← Back')}</button>
          <div className="mb-6 text-center">
            <h2 style={{ fontFamily: F_DISPLAY, color: C.paper }} className="text-2xl md:text-3xl font-semibold mb-2">{t('Quickplay')}</h2>
            <p style={{ color: C.muted }} className="max-w-xl mx-auto text-sm">
              {t('Skip the early game. Take over a company that already exists at a later stage and play that stage to its end. Each start is generated fresh, so no two are identical.')}
            </p>
          </div>
          <div style={{ color: C.brass, fontFamily: F_MONO }} className="text-xs uppercase tracking-widest mb-2">{t('Scenarios')}</div>
          <div className="space-y-3 mb-8">
            {AUTHORED_SCENARIOS.map(sc => {
              const objText = sc.objectives.map(o => objectiveBlurb(o, language)).join(' · ');
              return (
                <button key={sc.id} onClick={() => { setSelectedIds([]); setPendingScenarioId(sc.id); setPreGameView('select'); }}
                  style={{ background: C.panel, border: `1px solid ${C.brass}`, textAlign: 'left' }}
                  className="w-full rounded-lg p-4 hover:brightness-110">
                  <div className="flex items-baseline justify-between gap-3 mb-1">
                    <div style={{ color: C.paper, fontFamily: F_DISPLAY }} className="text-lg">{sc.name[L]}</div>
                    <div style={{ color: C.rust, fontFamily: F_MONO }} className="text-[10px] whitespace-nowrap">
                      {sc.difficulty[L]} · {t('Month')} {sc.startMonth}–{sc.endMonth}
                    </div>
                  </div>
                  <div style={{ color: C.text }} className="text-xs mb-2">{sc.framing[L]}</div>
                  <div style={{ color: C.muted }} className="text-[11px] italic mb-2">{sc.briefing[L]}</div>
                  <div style={{ color: C.brass, fontFamily: F_MONO }} className="text-[10px]">
                    {t('Objective')}: {objText}
                  </div>
                </button>
              );
            })}
          </div>

          <div style={{ color: C.brass, fontFamily: F_MONO }} className="text-xs uppercase tracking-widest mb-2">{t('Blitz — Stage Practice')}</div>
          <div className="space-y-3">
            {BLITZ_STAGE_IDS.map(sid => {
              const sc = makeBlitzScenario(sid);
              const stage = STAGES.find(s => s.id === sid);
              const objText = sc.objectives.map(o => objectiveBlurb(o, language)).join(' · ');
              return (
                <button key={sid} onClick={() => { setSelectedIds([]); setPendingScenarioId(`blitz-${sid}`); setPreGameView('select'); }}
                  style={{ background: C.panel, border: `1px solid ${C.hair}`, textAlign: 'left' }}
                  className="w-full rounded-lg p-4 hover:brightness-110">
                  <div className="flex items-baseline justify-between gap-3 mb-1">
                    <div style={{ color: C.paper, fontFamily: F_DISPLAY }} className="text-lg">{t(stage.name)}</div>
                    <div style={{ color: C.brass, fontFamily: F_MONO }} className="text-[10px] whitespace-nowrap">
                      {t('Month')} {sc.startMonth}–{sc.endMonth}
                    </div>
                  </div>
                  <div style={{ color: C.muted }} className="text-xs mb-2">{sc.framing[L]}</div>
                  <div style={{ color: C.brass, fontFamily: F_MONO }} className="text-[10px]">
                    {t('Objective')}: {objText}
                  </div>
                </button>
              );
            })}
          </div>
          <div style={{ color: C.muted, fontFamily: F_MONO }} className="text-[10px] mt-6 text-center">
            {t('Quickplay results are tracked separately from full runs.')}
          </div>
        </div>
      </div>
    );
  }

  // ---------------- Render: Setup (leader selection) ----------------
  if (!game) {
    // Leaders come from the chosen industry — Manufacturing's six are engineers and plant
    // directors, not restaurateurs.
    const setupIndustry = getIndustry(pendingIndustryId);
    const setupLeaders = setupIndustry.content.leaders;
    // The custom founder joins the pool via the adapter, so computeTeam / style matching /
    // handleOperate need no special case.
    const customLeader = (useCustomFounder && founderDoc.custom)
      ? customFounderToLeader(founderDoc.custom, language, founderDoc.career) : null;
    // Roster founders carry the stat points their experience has earned them.
    const rosterAware = setupLeaders.map(l => rosterFounderToLeader(l, (founderDoc.roster || {})[l.id]));
    const setupScenario = getScenario(pendingScenarioId);
    const teamSize = setupScenario.teamSize || 2;
    // On a full run the custom founder is MANDATORY and occupies a slot automatically — they're
    // the career this whole progression system hangs off, so making them optional would let a
    // player quietly opt out of their own memory anchor. The player therefore picks teamSize-1
    // co-founders from the roster, and the founder is never in the selectable grid at all.
    const founderIsMandatory = !!customLeader && setupScenario.kind === 'full';
    const picksNeeded = founderIsMandatory ? teamSize - 1 : teamSize;
    const selectablePool = founderIsMandatory ? rosterAware : (customLeader ? [customLeader, ...rosterAware] : rosterAware);
    const chosenCoFounders = selectablePool.filter(l => selectedIds.includes(l.id));
    const selectedLeaders = founderIsMandatory ? [customLeader, ...chosenCoFounders] : chosenCoFounders;
    const previewTeam = chosenCoFounders.length === picksNeeded ? computeTeam(selectedLeaders) : null;
    return (
      <div style={{ background: C.ink, minHeight: '100vh', fontFamily: F_BODY, color: C.text, position: 'relative' }} className="p-4 md:p-10">
        <FontImport />
        {showTutorial && <Modal onClose={() => setShowTutorial(false)} title={t('How to Play')}><TutorialContent language={language} industryId={pendingIndustryId} /></Modal>}
        {showSettings && <SettingsModal onClose={() => setShowSettings(false)} onOpenIndex={() => { setShowSettings(false); setShowIndex(true); }} soundEnabled={soundEnabled} onToggleSound={toggleSound} language={language} onToggleLanguage={toggleLanguage} game={null} onImportSave={handleImportSave} />}
        {showIndex && <Modal onClose={() => setShowIndex(false)} title={t('Business & Game Index')}><IndexTabs language={language} game={game} /></Modal>}
        <button onClick={() => setShowSettings(true)} title={t('Settings')}
          style={{ position: 'absolute', top: 16, right: 16, border: `1px solid ${C.hair}`, color: C.muted, background: C.panel }}
          className="rounded-full w-9 h-9 text-base">
          ⚙
        </button>
        <div className="max-w-5xl mx-auto">
          <div className="mb-4 flex items-center justify-between">
            <button onClick={() => setPreGameView('title')} style={{ color: C.muted, fontFamily: F_MONO }} className="text-xs">{t('← Back')}</button>
            <button onClick={() => setShowTutorial(true)} style={{ border: `1px solid ${C.brass}`, color: C.brass }} className="rounded px-4 py-1.5 text-xs font-semibold">
              {t('How to Play')}
            </button>
          </div>
          <div className="mb-6 text-center">
            <h2 style={{ fontFamily: F_DISPLAY, color: C.paper }} className="text-2xl md:text-3xl font-semibold mb-2">
              {teamSize === 1 ? t('Choose Your Leader') : t('Assemble Your Leadership Team')}
            </h2>
            {setupScenario.kind !== 'full' && (
              <div style={{ color: C.brass, fontFamily: F_MONO }} className="text-xs uppercase tracking-widest mb-2">
                {setupScenario.name[language === 'es' ? 'es' : 'en']}
              </div>
            )}
            <p style={{ color: C.muted }} className="max-w-xl mx-auto text-sm">
              {founderIsMandatory
                ? (language === 'es'
                  ? `Tu fundador siempre dirige la empresa. Elige ${picksNeeded} co-fundadores más de tu plantel — si dos de los tres comparten clase, se activa el bono de clase.`
                  : `Your founder always leads the company. Choose ${picksNeeded} more co-founders from your roster — if two of the three share a class, the class bonus activates.`)
                : (teamSize === 1
                  ? t('You lead this one alone. The style bonus applies in full — but you give up a second stat spread and a second Operate ability.')
                  : t("Pick exactly two leaders to run the company — matching styles unlock a team-wide bonus; mixing them trades that away for a broader mix of traits."))}
            </p>
          </div>
          {/* Name the company. Only on full runs — Quickplay/Blitz drop the player into an
              already-running company, so naming it there would be fiction. */}
          {getScenario(pendingScenarioId).kind === 'full' && (
            <div style={{ background: C.panel, border: `1px solid ${C.hair}` }} className="rounded-lg p-4 mb-4">
              <div style={{ color: C.brass, fontFamily: F_MONO }} className="text-xs uppercase tracking-widest mb-2">
                {t('Name Your Company')}
              </div>
              <div className="flex gap-2 items-center">
                <input
                  value={pendingCompanyName}
                  onChange={(e) => setPendingCompanyName(e.target.value.slice(0, 40))}
                  placeholder={language === 'es' ? 'Nombre de la empresa' : 'Company name'}
                  style={{ background: C.panel2, border: `1px solid ${pendingCompanyName.trim() ? C.hair : C.rust}`, color: C.text }}
                  className="flex-1 rounded px-3 py-2 text-sm"
                />
                <button onClick={() => setPendingCompanyName(rollCompanyName(pendingIndustryId, language))}
                  style={{ background: C.panel3, border: `1px solid ${C.brassDim}`, color: C.brass, fontFamily: F_MONO }}
                  className="rounded px-3 py-2 text-[11px] whitespace-nowrap">
                  {language === 'es' ? '↻ Aleatorio' : '↻ Roll'}
                </button>
              </div>
            </div>
          )}


          {customLeader && (() => {
            const sel = founderIsMandatory || selectedIds.includes(customLeader.id);
            const career = founderDoc.career || {};
            // On a full run this is a fixed slot, not a choice — rendered as a locked card that
            // can't be toggled off. Elsewhere it stays a normal selectable option.
            const Wrapper = founderIsMandatory ? 'div' : 'button';
            const wrapperProps = founderIsMandatory ? {} : { onClick: () => toggleLeader(customLeader.id) };
            return (
              <Wrapper {...wrapperProps}
                style={{ background: sel ? C.panel3 : C.panel2, border: `1px solid ${sel ? C.brass : C.brassDim}`, textAlign: 'left' }}
                className="w-full rounded-lg p-4 mb-4 flex gap-4 items-start">
                {/* The generated portrait, not the initials placeholder — this is the same
                    founder the player just built a face for on the previous screen, and showing
                    initials here made it look like the portrait hadn't saved. */}
                <ProceduralPortrait seed={customLeader.portraitSeed || customLeader.id} size={56} ring={sel} />
                <div className="min-w-0 flex-1">
                  <div className="flex items-center justify-between mb-1">
                    <div style={{ color: C.paper }} className="text-base font-semibold">
                      {customLeader.name}
                      <span style={{ color: C.brass, fontFamily: F_MONO }} className="text-[10px] ml-2">
                        {language === 'es' ? 'TU FUNDADOR' : 'YOUR FOUNDER'}
                      </span>
                    </div>
                    {founderIsMandatory
                      ? <div style={{ color: C.brass, fontFamily: F_MONO }} className="text-[10px]">
                          {language === 'es' ? '◆ SIEMPRE EN EL EQUIPO' : '◆ ALWAYS ON THE TEAM'}
                        </div>
                      : (sel && <div style={{ color: C.brass, fontFamily: F_MONO }} className="text-[10px]">✓ {t('selected')}</div>)}
                  </div>
                  {/* Read the CLASS off classId, not style. Analyst and Statesman deliberately
                      carry style: null (they deliver via founder presence, not style-match), so
                      keying the label off style left their class blank on this screen. */}
                  <div style={{ color: C.muted }} className="text-xs mb-1">
                    {customLeader.role}
                    {' · '}
                    <span style={{ color: C.brass }}>
                      {(FOUNDER_CLASS_BY_ID[customLeader.classId] || {}).name
                        ? FOUNDER_CLASS_BY_ID[customLeader.classId].name[language === 'es' ? 'es' : 'en']
                        : (customLeader.style || '—')}
                    </span>
                  </div>
                  {FOUNDER_CLASS_BY_ID[customLeader.classId] && (
                    <div style={{ color: C.brassDim, fontFamily: F_MONO }} className="text-[10px] mb-1 leading-snug">
                      {FOUNDER_CLASS_BY_ID[customLeader.classId].mechanics[language === 'es' ? 'es' : 'en']}
                    </div>
                  )}
                  {(career.runs || 0) > 0 && (
                    <div style={{ color: C.muted, fontFamily: F_MONO }} className="text-[10px] mb-1">
                      {career.runs} {language === 'es' ? 'empresas' : 'ventures'} · {career.wins || 0} {language === 'es' ? 'salidas' : 'exits'} · {career.totalMonths || 0} {language === 'es' ? 'meses' : 'months'}
                    </div>
                  )}
                  <div style={{ color: C.muted, fontFamily: F_MONO }} className="text-[10px] mb-1">{statBonusText(customLeader.statBonus, language)}</div>
                  <div style={{ color: C.muted }} className="text-[10px]">{t('Operate:')} {customLeader.operate.label} ({customLeader.operate.desc})</div>
                </div>
              </Wrapper>
            );
          })()}

          {/* The roster lives here now, not on the founder-creation screen: inspecting a
              co-founder's history, spending their earned points, and comparing two of them are
              all things you do WHILE deciding who to bring — not while building your own
              founder. Compare is meaningful here for the same reason. */}
          {allRosterLeaders && allRosterLeaders.length > 0 && (
            <FounderRosterPanel
              leaders={selectablePool}
              founderDoc={founderDoc}
              language={language}
              onAllocate={allocateRosterPoints}
              t={t}
              selectable
              selectedIds={selectedIds}
              onToggleSelect={toggleLeader}
              picksNeeded={picksNeeded}
            />
          )}


          <div style={{ background: C.panel, border: `1px solid ${C.hair}` }} className="rounded-lg p-4 flex flex-wrap items-center justify-between gap-3">
            <div style={{ color: C.muted, fontFamily: F_MONO }} className="text-xs">
              {founderIsMandatory
                ? `${language === 'es' ? 'Co-fundadores' : 'Co-founders'}: ${selectedIds.length}/${picksNeeded}`
                : `${t('Selected')}: ${selectedIds.length}/${picksNeeded}`}
              {previewTeam && (previewTeam.style
                ? ` · ${language === 'es' ? STYLE_NAMES_ES[previewTeam.style] : previewTeam.style} ${t('team bonus active')}`
                : ` · ${t('mixed styles — no team-wide style bonus this run')}`)}
            </div>
            {(() => {
              const nameOk = getScenario(pendingScenarioId).kind !== 'full' || !!pendingCompanyName.trim();
              const ready = !!previewTeam && nameOk;
              return (
                <button onClick={() => ready && startGame(previewTeam)} disabled={!ready}
                  style={{ background: ready ? C.brass : C.hair, color: ready ? C.ink : C.muted, opacity: ready ? 1 : 0.6 }}
                  className="rounded px-6 py-2 text-sm font-semibold">
                  {t('Begin Service')}
                </button>
              );
            })()}
          </div>
        </div>
      </div>
    );
  }

  // ---------------- Render: Choice Event (decision required) ----------------
  if (game.pendingChoice) {
    const event = localizeChoiceEvent(game.pendingChoice.event, language);
    const freeLaborNow = game.laborPool - game.laborReserved;
    return (
      <div style={{ background: C.ink, minHeight: '100vh', fontFamily: F_BODY, color: C.text }} className="p-4 md:p-10 flex items-center justify-center">
        <FontImport />
        {showStatInfo && <Modal onClose={() => setShowStatInfo(false)} title={t('Company Stats')}><StatInfoContent game={game} language={language} /></Modal>}
        <div style={{ background: C.panel, border: `1px solid ${C.brass}`, maxHeight: '85vh' }} className="max-w-lg w-full rounded-lg overflow-y-auto">
          {/* Sticky Resources + Stats — same compact strip, repositioned to fit the decision card instead of the dashboard. Press and hold for stat descriptions. */}
          <div {...statHoldHandlers}
            style={{ position: 'sticky', top: 0, zIndex: 20, background: C.panel, borderBottom: `1px solid ${C.hair}`, cursor: 'pointer', userSelect: 'none', WebkitUserSelect: 'none', WebkitTouchCallout: 'none', touchAction: 'manipulation' }}
            className="px-6 py-3">
            <div className="flex flex-wrap items-center gap-x-4 gap-y-1">
              <InfoChip label={t('Cap')} value={fmtMoney(game.capital)} warn={game.capital < 10} />
              <InfoChip label={t('Pres')} value={game.presence} />
              <InfoChip label={t('Labor')} value={`${freeLaborNow}/${game.laborPool}`} />
              <div style={{ width: 1, alignSelf: 'stretch', background: C.hair }} className="hidden sm:block" />
              {STAT_KEYS.map(k => <InfoChip key={k} label={statShort(k, language)} value={game.stats[k]} />)}
              <div style={{ width: 1, alignSelf: 'stretch', background: C.hair }} className="hidden sm:block" />
              <InfoChip label={t('Val')} value={fmtMoney(game.companyValuation)} valueColor={C.brass} />
              <span style={{ color: C.muted, fontFamily: F_MONO }} className="text-[9px] ml-auto whitespace-nowrap">{t('hold ⓘ')}</span>
            </div>
          </div>
          <div className="px-6 pt-4 pb-6">
            <div style={{ color: C.brass, fontFamily: F_MONO }} className="text-xs uppercase tracking-widest mb-1">{t('A Decision — Month')} {game.pendingChoice.month}</div>
            <div style={{ fontFamily: F_DISPLAY, color: C.paper }} className="text-2xl mb-3">{event.title}</div>
            <p style={{ color: C.muted }} className="text-sm mb-5">{event.body}</p>
            <div className="space-y-2">
              {event.options.map((opt, i) => {
                // Same threshold expression resolveChoiceOption uses, so the forecast predicts
                // the check the player is actually about to face.
                const choiceInd = getIndustry(game.industryId);
                const choiceStage = stageOf(game.pendingChoice.month, choiceInd.stages).id;
                const choiceFx = founderFx(game);
                const choiceBar = 10
                  + (((choiceInd.scaling && choiceInd.scaling.eventThresholdBonus) || EVENT_THRESHOLD_BONUS_BY_STAGE)[choiceStage] || 0)
                  + choiceFx.choiceThresholdBonus;
                // A trait option is a guaranteed pass when the trait is on the team, so it has no
                // meaningful "odds" — showing one would be misleading.
                const traitHeld = opt.traitCheck && game.team.leaders.some(l => l.trait === opt.traitCheck);
                const statTotal = opt.traitCheck ? 0 : (game.stats[opt.statCheck] || 0);
                const preview = traitHeld ? null
                  : previewChance('choiceOption', game, { statTotal, bar: choiceBar });
                return (
                  <button key={i} onClick={() => handleChoiceOption(i)}
                    style={{ background: C.panel2, border: `1px solid ${C.hair}`, textAlign: 'left' }}
                    className="w-full rounded p-3 hover:brightness-110">
                    <div className="flex items-start justify-between gap-3">
                      <div style={{ color: C.paper }} className="text-sm font-semibold">{String.fromCharCode(65 + i)}. {opt.label}</div>
                      {traitHeld
                        ? <span style={{ fontFamily: F_MONO, fontSize: 10, color: C.good, whiteSpace: 'nowrap' }}>
                            {language === 'es' ? 'Asegurado' : 'Assured'}
                          </span>
                        : <ForecastChip preview={preview} language={language} />}
                    </div>
                    <div style={{ color: C.muted, fontFamily: F_MONO }} className="text-[10px] mt-1">
                      {opt.traitCheck ? `${t('Best with a leader who has:')} ${opt.traitCheck}` : `${t('Weighted by:')} ${statLabel(opt.statCheck, language)}`}
                    </div>
                  </button>
                );
              })}
            </div>
          </div>
        </div>
      </div>
    );
  }

  // ---------------- Render: Monthly Summary (alerts) ----------------
  if (game.pendingSummary) {
    const { month, quarter, tickets } = game.pendingSummary;
    return (
      <div style={{ background: C.ink, minHeight: '100vh', fontFamily: F_BODY, color: C.text }} className="p-4 md:p-10 flex items-center justify-center">
        <FontImport />
        <div style={{ background: C.panel, border: `1px solid ${C.hair}` }} className="max-w-lg w-full rounded-lg p-6">
          <div style={{ color: C.brass, fontFamily: F_MONO }} className="text-xs uppercase tracking-widest mb-1">{t('Month')} {month} {t('Resolved')} · Q{quarter}</div>
          <div style={{ fontFamily: F_DISPLAY, color: C.paper }} className="text-2xl mb-4">{t('What Happened')}</div>
          <div className="space-y-2 max-h-[50vh] overflow-y-auto pr-1 mb-4">
            {tickets.map(tk => <Ticket key={tk.id} t={tk} />)}
          </div>
          <button onClick={closeSummary} style={{ background: C.brass, color: C.ink }} className="w-full rounded py-2 font-semibold text-sm">
            {game.gameOver ? t('See Results') : `${t('Continue to Month')} ${Math.min(game.month, game.endMonth || RUN_END)}`}
          </button>
        </div>
      </div>
    );
  }

  // ---------------- Render: Game Over ----------------
  if (game.gameOver) {
    const go = game.gameOver;
    return (
      <div style={{ background: C.ink, minHeight: '100vh', fontFamily: F_BODY, color: C.text }} className="p-4 md:p-10 flex items-center justify-center">
        <FontImport />
        <div style={{ background: C.panel, border: `1px solid ${C.hair}` }} className="max-w-lg w-full rounded-lg p-8 text-center">
          <div style={{ color: go.won ? C.good : C.rust, fontFamily: F_MONO }} className="text-xs uppercase tracking-widest mb-3">
            {go.won ? t('Run Complete — Exit Achieved') : t('Run Complete — No Exit')}
          </div>
          <h2 style={{ fontFamily: F_DISPLAY, color: C.paper }} className="text-3xl mb-4">{go.headline}</h2>
          <p style={{ color: C.muted }} className="text-sm mb-4">{go.body}</p>

          <div style={{ background: C.panel2, border: `1px solid ${C.brass}` }} className="rounded-lg py-3 mb-6">
            <div style={{ color: C.muted, fontFamily: F_MONO }} className="text-[10px] uppercase tracking-widest">{t('Final Company Valuation')}</div>
            <div style={{ color: C.brass, fontFamily: F_MONO }} className="text-2xl font-semibold">{fmtMoney(game.companyValuation)}</div>
            <div style={{ color: C.muted }} className="text-[10px] mt-1">{t('Carried into your lifetime record — see Meta-Progression.')}</div>
          </div>

          {(() => {
            const arch = computeArchetype(game.philosophy, language);
            const anyMovement = PHILOSOPHY_AXES.some(a => Math.abs((game.philosophy || {})[a] || 0) >= 3);
            // Descriptive only — this never gates or restricts anything (7.3). It's what the
            // choices already made added up to, not a category the player picked. The headline
            // name is flavor from whichever axis leans hardest; the full breakdown underneath is
            // the honest picture — a founder holds a position on every axis at once, not one.
            return anyMovement ? (
              <div style={{ background: C.panel2, border: `1px solid ${C.hair}` }} className="rounded-lg p-4 mb-6 text-left">
                <div style={{ color: C.muted, fontFamily: F_MONO }} className="text-[10px] uppercase tracking-widest text-center">{t('The Founder You Became')}</div>
                {arch && <div style={{ color: C.paper, fontFamily: F_DISPLAY }} className="text-xl text-center mb-1">{arch.name}</div>}
                <div style={{ color: C.muted }} className="text-[10px] mb-3 text-center">{t('Shaped by the decisions you made along the way — not chosen at the start.')}</div>
                <div className="grid md:grid-cols-2 gap-x-4 gap-y-2.5">
                  {PHILOSOPHY_AXES.map(axis => (
                    <PhilosophyBar key={axis} axis={axis} value={(game.philosophy || {})[axis]} language={language} />
                  ))}
                </div>
              </div>
            ) : null;
          })()}

          {(() => {
            const cal = forecastCalibrationSummary(game.forecastRecord, language);
            if (!cal) return null;
            const L = language === 'es' ? 'es' : 'en';
            const tone = cal.band.tone === 'good' ? C.good : cal.band.tone === 'bad' ? C.rust : C.brass;
            return (
              <div style={{ background: C.panel2, border: `1px solid ${C.hair}` }} className="rounded-lg p-4 mb-6 text-center">
                <div style={{ color: C.muted, fontFamily: F_MONO }} className="text-[10px] uppercase tracking-widest mb-1">
                  {L === 'es' ? 'Registro del Modelo' : 'The Model\u2019s Track Record'}
                </div>
                <div style={{ color: tone, fontFamily: F_DISPLAY }} className="text-2xl mb-1">{cal.pct}%</div>
                <div style={{ color: C.muted }} className="text-xs">
                  {L === 'es'
                    ? `Tu modelo hizo ${cal.calls} predicción${cal.calls === 1 ? '' : 'es'} — acertó ${cal.correct} de ${cal.calls}.`
                    : `Your model called ${cal.calls} outcome${cal.calls === 1 ? '' : 's'} — right ${cal.correct} out of ${cal.calls}.`}
                </div>
              </div>
            );
          })()}

          {getScenario(game.scenarioId).kind !== 'full' && (
            <div style={{ borderTop: `1px solid ${C.hair}`, borderBottom: `1px solid ${C.hair}` }} className="text-left py-4 mb-6">
              <div style={{ color: C.brass, fontFamily: F_MONO }} className="text-[10px] uppercase tracking-widest mb-2">{t('Objectives')}</div>
              <div className="space-y-0.5">
                {evaluateObjectives(game, getScenario(game.scenarioId), language).checks.map((ck, i) => (
                  <div key={i} className="flex justify-between text-[11px]" style={{ fontFamily: F_MONO }}>
                    <span style={{ color: ck.met ? C.good : C.rust }}>{ck.met ? '✓' : '✗'} {objectiveLabel(ck.key, language)}</span>
                    <span style={{ color: C.muted }}>{ck.display || `${ck.current}/${ck.target}`}</span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {go.reason === 'noExit' && (
            <div style={{ borderTop: `1px solid ${C.hair}`, borderBottom: `1px solid ${C.hair}` }} className="text-left py-4 mb-6 space-y-3">
              <div style={{ color: C.brass, fontFamily: F_MONO }} className="text-[10px] uppercase tracking-widest mb-1">{t('How close were you?')}</div>
              {INDUSTRY_EXITS.map(def => {
                const { checks, allMet } = exitProgress(game, def, language);
                return (
                  <div key={def.id}>
                    <div style={{ color: allMet ? C.good : C.text }} className="text-xs font-semibold mb-1">{allMet ? '✓' : '·'} {t(def.name)}</div>
                    <div className="grid grid-cols-2 gap-x-2 gap-y-0.5">
                      {checks.map((c, i) => c.display ? (
                        <div key={i} className="col-span-2 flex justify-between text-[10px]" style={{ fontFamily: F_MONO }}>
                          <span style={{ color: c.met ? C.good : C.muted }}>{c.met ? '✓' : '✗'} {checkKeyLabel(c.key, language)}</span>
                          <span style={{ color: C.muted }}>{c.display}</span>
                        </div>
                      ) : (
                        <div key={i} className="flex justify-between text-[10px]" style={{ fontFamily: F_MONO }}>
                          <span style={{ color: c.met ? C.good : C.muted }}>{c.met ? '✓' : '✗'} {checkKeyLabel(c.key, language)}</span>
                          <span style={{ color: C.muted }}>{c.current}/{c.target}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
          {go.reason === 'insolvent' && (
            <div style={{ borderTop: `1px solid ${C.hair}`, borderBottom: `1px solid ${C.hair}`, fontFamily: F_MONO }} className="text-xs py-4 mb-6 text-left" >
              <div>{t('Final Capital')}: {fmtMoney(game.capital)}</div>
              <div style={{ color: C.muted }} className="mt-1">{t('Tip: keep a buffer above your monthly Burn.')}</div>
            </div>
          )}
          {go.reason === 'ousted' && (
            <div style={{ borderTop: `1px solid ${C.hair}`, borderBottom: `1px solid ${C.hair}`, fontFamily: F_MONO }} className="text-xs py-4 mb-6 text-left">
              <div>{t('Board crisis streak')}: {game.lowMoraleStreak}/{OUST_QUARTERS} {t('quarters')}</div>
              <div>{t('Morale')}: {Math.round(game.morale)}/100</div>
              <div>{t('Board Confidence')}: {game.boardConfidence}/100</div>
            </div>
          )}

          <button onClick={resetGame} style={{ background: C.brass, color: C.ink }} className="rounded py-2 px-6 font-semibold text-sm">
            {t('Play Again')}
          </button>
        </div>
      </div>
    );
  }

  // ---------------- Render: Playing ----------------
  // Guarded with defaults so a save written before scenarios/competitors existed still loads.
  const activeScenario = getScenario(game.scenarioId);
  const activeIndustry = getIndustry(game.industryId);
  const currentStage = stageOf(game.month, activeIndustry.stages);
  // Floored at game.ap rather than trusting the table blindly — if anything ever granted AP
  // beyond the stage's nominal max, this keeps the bar honest instead of clipping real AP off
  // the end of the row.
  const apMaxThisStage = Math.max(activeIndustry.apByStage[currentStage.id] || 3, game.ap);
  const stage = currentStage.name;
  const quarter = quarterOf(game.month);
  const freeLabor = game.laborPool - game.laborReserved;
  const meetsPrereq = (p) => p.requires.every(r => game.completed[r]);
  const industryStageOrder = activeIndustry.stageOrder || STAGE_ORDER;
  const meetsStage = (p) => !p.minStage || industryStageOrder.indexOf(currentStage.id) >= industryStageOrder.indexOf(p.minStage);
  const lockReason = (p) => {
    if (!meetsPrereq(p)) return `${t('requires')} ${p.requires.map(r => localizeProject(INDUSTRY_PROJECTS.find(x => x.id === r), language)?.name).join(', ')}`;
    if (!meetsStage(p)) {
      const need = (activeIndustry.stages || STAGES).find(s => s.id === p.minStage);
      return `${t('unlocks at')} ${need ? t(need.name) : p.minStage} ${t('stage (Month')} ${need ? need.start : '?'}+)`;
    }
    return '';
  };
  const objectiveChecks = evaluateObjectives(game, activeScenario, language).checks;
  const objectiveProjIds = objectiveProjectIds(activeScenario);
  const competitors = game.competitors || [];
  const marketRank = computeMarketRank(game);
  const activeTargetId = competitors.some(c => c.id === targetCompetitorId)
    ? targetCompetitorId
    : (competitors[0] ? competitors[0].id : null);

  const INDUSTRY_PROJECTS = activeIndustry.content.projects;
  const INDUSTRY_EXITS = activeIndustry.content.exits.length ? activeIndustry.content.exits : EXIT_DEFS;
  const INDUSTRY_EXTERNAL = activeIndustry.content.externalActions.length ? activeIndustry.content.externalActions : EXTERNAL_ACTIONS;
  const availableProjects = INDUSTRY_PROJECTS.filter(p => !game.completed[p.id] && !game.activeProjects.some(a => a.id === p.id) && meetsPrereq(p) && meetsStage(p));
  const lockedProjects = INDUSTRY_PROJECTS.filter(p => !game.completed[p.id] && !game.activeProjects.some(a => a.id === p.id) && !(meetsPrereq(p) && meetsStage(p)));

  const fc = fundraisePresenceCost(game, activeIndustry);
  const fundraiseDisabled = game.ap < 1 || fc.cost > game.presence;
  const fundraiseCostText = `1 ${t('AP')} · ${fc.cost} ${t('Presence')}${fc.free ? ` (${t('free!')})` : ''} · ${t('variable payout')}`;

  const rc = recruitCosts(game);
  const recruitDisabled = game.ap < 1 || rc.capital > game.capital;
  const recruitCostText = `1 ${t('AP')} · ${fmtMoney(rc.capital)}`;

  const freeLaborForLayoff = game.laborPool - game.laborReserved;
  const layoffDisabled = game.ap < 1 || freeLaborForLayoff <= 0;
  const layoffCostText = `1 ${t('AP')} · -6 ${t('Morale')}, -4 ${t('Rep')}`;

  const restDisabled = game.ap < 1 || game.capital < 5;
  const pivotDisabled = game.ap < 2 || game.capital < 20;

  // Derived from the active industry's declared stage gates rather than a Hospitality-shaped
  // switch — a second industry gets correct gate text with no engine change.
  const stageGateText = (() => {
    const stageIdx = activeIndustry.stages.findIndex(s => s.id === currentStage.id);
    const gate = (activeIndustry.stageGates || []).find(g => g.stageIndex === stageIdx);
    if (!gate) {
      return `${t('You\'re in the final stretch. See "Attempt an Exit" below — the run ends the moment one succeeds, or at Month')} ${game.endMonth || activeIndustry.runEnd} ${t('if none do.')}`;
    }
    const stage = activeIndustry.stages[stageIdx];
    const L = language === 'es' ? 'es' : 'en';
    const met = gate.passes(game);
    return met
      ? `✓ ${gate.headline[L]} — ${t('requirement met.')}`
      : `⚑ ${t('By Month')} ${stage.end}: ${gate.body[L](game)}`;
  })();

  return (
    <div style={{ background: C.ink, minHeight: '100vh', fontFamily: F_BODY, color: C.text }} className="p-3 md:p-6">
      <FontImport />
      {showTutorial && <Modal onClose={() => setShowTutorial(false)} title={t('How to Play')}><TutorialContent language={language} industryId={game.industryId} /></Modal>}
      {showSettings && <SettingsModal onClose={() => setShowSettings(false)} onOpenIndex={() => { setShowSettings(false); setShowIndex(true); }} soundEnabled={soundEnabled} onToggleSound={toggleSound} onForfeit={forfeitRun} language={language} onToggleLanguage={toggleLanguage} game={game} onImportSave={handleImportSave} />}
      {showIndex && <Modal onClose={() => setShowIndex(false)} title={t('Business & Game Index')}><IndexTabs language={language} game={game} /></Modal>}
      {showStatInfo && <Modal onClose={() => setShowStatInfo(false)} title={t('Company Stats')}><StatInfoContent game={game} language={language} /></Modal>}
      {showActionsInfo && <Modal onClose={() => setShowActionsInfo(false)} title={t('Actions')}><ActionsInfoContent language={language} /></Modal>}
      {showBrandInfo && (
        <Modal onClose={() => setShowBrandInfo(false)} title={t('Brand')}>
          <BrandDetail game={game} language={language} t={t} />
        </Modal>
      )}

      {showMetersInfo && <Modal onClose={() => setShowMetersInfo(false)} title={t('Company Meters')}><MetersInfoContent language={language} revenueModel={activeIndustry.revenueModel} /></Modal>}
      <div className="max-w-6xl mx-auto" style={{ paddingBottom: 76 }}>

        {/* Sticky Resources + Stats + Turn Control — compact, full-width, flush with the very top. Press and hold the top row for stat descriptions. */}
        <div style={{ position: 'sticky', top: 0, zIndex: 30, background: C.panel, borderBottom: `1px solid ${C.brass}` }} className="rounded-b-lg mb-4">
          <div {...statHoldHandlers}
            style={{ cursor: 'pointer', userSelect: 'none', WebkitUserSelect: 'none', WebkitTouchCallout: 'none', touchAction: 'manipulation' }}
            className="px-4 pt-2 pb-1.5">
            <div className="flex flex-wrap items-center gap-x-4 gap-y-1">
              <InfoChip label={t('Cap')} value={fmtMoney(game.capital)} warn={game.capital < 10} />
              <InfoChip label={t('Pres')} value={game.presence} />
              <InfoChip label={t('Labor')} value={`${freeLabor}/${game.laborPool}`} />
              <div style={{ width: 1, alignSelf: 'stretch', background: C.hair }} className="hidden sm:block" />
              {STAT_KEYS.map(k => <InfoChip key={k} label={statShort(k, language)} value={game.stats[k]} />)}
              <div style={{ width: 1, alignSelf: 'stretch', background: C.hair }} className="hidden sm:block" />
              <InfoChip label={t('Val')} value={fmtMoney(game.companyValuation)} valueColor={C.brass} />
              <span style={{ color: C.muted, fontFamily: F_MONO }} className="text-[9px] ml-auto whitespace-nowrap">{t('hold ⓘ')}</span>
            </div>
          </div>
          <div style={{ borderTop: `1px solid ${C.hair}` }} className="flex items-center justify-between px-4 pt-1.5 pb-2">
            <div className="flex items-center gap-1">
              {/* Dot count follows the STAGE's own AP max (apByStage), not a flat 3 — Manufacturing
                  ranges from 2 at Pre-Seed up to 5 at Expansion, and drawing a fixed three dots
                  either invented an empty slot that was never spendable or silently dropped real
                  AP off the end of the bar. */}
              {Array.from({ length: apMaxThisStage }).map((_, i) => (
                <div key={i} style={{ background: i < game.ap ? C.brass : C.hair, width: 10, height: 10, borderRadius: '50%' }} />
              ))}
              <span style={{ color: C.muted, fontFamily: F_MONO }} className="text-xs ml-1">{t('AP')}</span>
            </div>
            <button onClick={endMonth} style={{ background: C.brass, color: C.ink }} className="rounded px-4 py-1.5 text-xs font-semibold hover:brightness-110">
              {t('End Month →')}
            </button>
          </div>
        </div>

        {/* Header */}
        <div style={{ background: C.panel, border: `1px solid ${C.hair}` }} className="rounded-lg p-4 mb-4 flex flex-wrap items-center justify-between gap-3">
          <div>
            <div style={{ fontFamily: F_DISPLAY, color: C.paper }} className="text-xl">
              {language === 'es' ? (game.team.style ? `Liderazgo ${STYLE_NAMES_ES[game.team.style]}` : 'Liderazgo Independiente') : game.team.name} <span style={{ color: C.muted, fontSize: '0.6em' }}>· {game.team.style ? (language === 'es' ? STYLE_NAMES_ES[game.team.style] : game.team.style) : t('Independent')}</span>
            </div>
            <div style={{ fontFamily: F_MONO, color: C.brass }} className="text-xs uppercase tracking-wide">
              {t('Month')} {game.month}/{game.endMonth || RUN_END} · {t(stage)} · Q{quarter}
            </div>
          </div>
          <div className="flex items-center gap-3">
            <button onClick={() => setShowTutorial(true)} style={{ border: `1px solid ${C.hair}`, color: C.muted }} className="rounded-full w-7 h-7 text-xs font-semibold">?</button>
            <button onClick={() => setShowSettings(true)} title={t('Settings')} style={{ border: `1px solid ${C.hair}`, color: C.muted }} className="rounded-full w-7 h-7 text-sm">⚙</button>
          </div>
        </div>

        {/* Stage progress rail */}
        <div style={{ background: C.panel, border: `1px solid ${C.hair}` }} className="rounded-lg px-4 py-3 mb-4 flex items-center gap-1 overflow-x-auto">
          {activeIndustry.stages.map((s, i) => {
            const done = game.month > s.end;
            const active = s.id === currentStage.id;
            return (
              <React.Fragment key={s.id}>
                <div style={{ color: active ? C.brass : done ? C.good : C.muted, fontFamily: F_MONO }} className="text-[10px] uppercase whitespace-nowrap px-1">
                  {active ? '▶ ' : done ? '✓ ' : ''}{t(s.name)}
                </div>
                {i < STAGES.length - 1 && <div style={{ background: C.hair, height: 1, flex: 1, minWidth: 12 }} />}
              </React.Fragment>
            );
          })}
        </div>

        <div className="space-y-4">
          {/* Main column — now full width; the Ticket Rail lives in the pull-out drawer instead */}
          <div className="space-y-4">

            {/* Objectives — scenarios only. The full run's goal is the exit checklist itself. */}
            {activeScenario.kind !== 'full' && (
              <Panel title={t('Objectives')}>
                <div style={{ color: C.muted, fontFamily: F_MONO }} className="text-[11px] mb-2">
                  {t('Month')} {game.month}/{game.endMonth || RUN_END}
                  {activeScenario.objectiveMode === 'any' ? ` · ${t('any one of:')}` : ''}
                </div>
                <div className="space-y-0.5">
                  {objectiveChecks.map((ck, i) => (
                    <div key={i} className="flex justify-between text-[11px]" style={{ fontFamily: F_MONO }}>
                      <span style={{ color: ck.met ? C.good : C.muted }}>
                        {ck.met ? '✓' : '·'} {objectiveLabel(ck.key, language)}
                      </span>
                      <span style={{ color: ck.met ? C.good : C.text }}>
                        {ck.display || `${ck.current}/${ck.target}`}
                      </span>
                    </div>
                  ))}
                </div>
                <div style={{ color: C.muted, fontFamily: F_MONO }} className="text-[10px] mt-2">
                  {t('Company Valuation')}: <span style={{ color: C.brass }}>{fmtMoney(game.companyValuation)}</span>
                </div>
              </Panel>
            )}

            {/* Path to Exit — the full run's own progress readout. My Company only: it was
                rendering above the tab blocks, so it appeared on every tab as constant noise. */}
            {activeScenario.kind === 'full' && gameTab === 'mycompany' && (
              <Panel title={t('Path to Exit')}>
                <div style={{ color: currentStage.id === 'preSeed' && !game.completed['firstLocation'] ? C.brass : C.muted, fontFamily: F_MONO }} className="text-xs mb-3">
                  {stageGateText}
                </div>
                <div style={{ color: C.muted, fontFamily: F_MONO }} className="text-xs">
                  {t('Company Valuation')}: <span style={{ color: C.brass }}>{fmtMoney(game.companyValuation)}</span> {t('— grows from completed projects and rising Company Stats.')}
                </div>
              </Panel>
            )}

            {/* Attempt an Exit — Exit Window, and only if the scenario allows exits at all */}
            {currentStage.id === 'exitWindow' && activeScenario.allowExits && (
              <Panel title={t('Attempt an Exit')}>
                <div style={{ color: C.muted }} className="text-xs mb-3">{t('Pick any exit whose checklist is fully green. The run ends the moment you succeed — no need to wait for Month')} {game.endMonth || RUN_END}.</div>
                <div className="space-y-3">
                  {INDUSTRY_EXITS.map(def => {
                    const { checks, allMet } = exitProgress(game, def, language);
                    const tagline = language === 'es' ? EXIT_TAGLINES_ES[def.id] : def.tagline;
                    return (
                      <div key={def.id} style={{ background: C.panel2, border: `1px solid ${allMet ? C.good : C.hair}` }} className="rounded p-3">
                        <div className="flex items-center justify-between mb-1">
                          <div style={{ color: C.paper }} className="text-sm font-semibold">{t(def.name)}</div>
                          <button onClick={() => handleAttemptExit(def.id)} disabled={!allMet}
                            style={{ background: allMet ? C.brass : C.hair, color: allMet ? C.ink : C.muted, opacity: allMet ? 1 : 0.6 }}
                            className="rounded px-3 py-1 text-xs font-semibold">
                            {t('Attempt')}
                          </button>
                        </div>
                        <div style={{ color: C.muted }} className="text-[11px] mb-2">{tagline}</div>
                        <div className="grid grid-cols-2 gap-x-2 gap-y-0.5">
                          {checks.map((c, i) => c.display ? (
                            <div key={i} className="col-span-2 flex justify-between text-[10px]" style={{ fontFamily: F_MONO }}>
                              <span style={{ color: c.met ? C.good : C.muted }}>{c.met ? '✓' : '·'} {checkKeyLabel(c.key, language)}</span>
                              <span style={{ color: c.met ? C.good : C.text }}>{c.display}</span>
                            </div>
                          ) : (
                            <div key={i} className="flex justify-between text-[10px]" style={{ fontFamily: F_MONO }}>
                              <span style={{ color: c.met ? C.good : C.muted }}>{c.met ? '✓' : '·'} {checkKeyLabel(c.key, language)}</span>
                              <span style={{ color: c.met ? C.good : C.text }}>{c.current}/{c.target}</span>
                            </div>
                          ))}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </Panel>
            )}

            {/* Meters — shown on My Company, Invest and Actions; deliberately absent from
                Characters and Companies, which are reference/browsing tabs rather than
                turn-to-turn operating surfaces. */}
            {/* Brand lives on My Company: it is a standing property of the company, not a
                turn-to-turn operating control. Press and hold for the full picture. */}
            {gameTab === 'mycompany' && activeIndustry.productCatalog && (
              <BrandPanel game={game} industry={activeIndustry} language={language} t={t}
                onSetPolicy={handleSetMarketingPolicy} onCampaign={handleBrandCampaign}
                holdHandlers={brandHoldHandlers} />
            )}

            {['mycompany', 'invest', 'actions'].includes(gameTab) && (
            <Panel title={t('Company Meters')} holdHandlers={metersHoldHandlers} language={language}>
              <div className="space-y-2">
                {activeIndustry.revenueModel === 'capacityDemand' && (() => {
                  const cap = game.capacity || 0, dem = game.demand || 0;
                  const scale = Math.max(20, cap, dem);
                  // Whichever side is smaller is the bottleneck — highlighting it makes the
                  // constraint readable without the player doing arithmetic every month.
                  return (
                    <>
                      <MeterBar label={t('Capacity')} value={cap} max={scale}
                        display={Math.round(cap)} warn={cap < dem} />
                      <MeterBar label={t('Demand')} value={dem} max={scale}
                        display={Math.round(dem)} warn={dem < cap} />
                    </>
                  );
                })()}
                <MeterBar label={t('Revenue')} value={game.revenuePerMonth} max={40} display={fmtMoney(game.revenuePerMonth) + '/mo'} />
                <MeterBar label={t('Reputation')} value={game.reputation} max={100} />
                <MeterBar label={t('Morale')} value={game.morale} max={100} warn={game.morale < 40} />
                {marketRank ? (
                  <MeterBar label={t('Market Rank')} value={marketRank.total - marketRank.rank + 1} max={marketRank.total}
                    display={`#${marketRank.rank} ${t('of')} ${marketRank.total}`} warn={marketRank.rank === marketRank.total} />
                ) : (
                  <div style={{ color: C.muted }} className="text-[11px] italic">{t('Market Rank appears once rivals enter the market.')}</div>
                )}
                <MeterBar label={t('Board Confidence')} value={game.boardConfidence} max={100} warn={game.boardConfidence < 30} />
              </div>
              {game.lowMoraleStreak > 0 && (
                <div style={{ color: C.rust, fontFamily: F_MONO }} className="text-xs mt-2">
                  <div>{t('⚠ Board crisis')}: {game.lowMoraleStreak}/{OUST_QUARTERS} {t('quarters (ousting risk)')}</div>
                  {/* The recovery bar is higher than the trigger, so it has to be stated or the
                      player will climb to 41 morale, see nothing change, and read it as a bug. */}
                  <div style={{ color: C.muted }} className="mt-0.5">
                    {language === 'es'
                      ? `Para detener el reloj: Moral ${OUST_MORALE_EXIT}+ y Confianza ${OUST_BC_EXIT}+ (tienes ${Math.round(game.morale)} / ${Math.round(game.boardConfidence)})`
                      : `To stop the clock: Morale ${OUST_MORALE_EXIT}+ and Board Confidence ${OUST_BC_EXIT}+ (you have ${Math.round(game.morale)} / ${Math.round(game.boardConfidence)})`}
                  </div>
                </div>
              )}
            </Panel>
            )}

            {/* ======================= MY COMPANY TAB ======================= */}
            {/* Leadership and Company Philosophy live here exclusively — they used to render
                unconditionally above every tab, which meant they were duplicated everywhere.
                Moved to their own home so Actions/Invest can focus on the turn at hand. */}
            {gameTab === 'mycompany' && (<>

            <Panel title={t('Leadership')}>
              <div style={{ color: C.muted }} className="text-[10px] mb-2">
                {language === 'es' ? 'Mantén pulsada la barra para ver el detalle completo.' : 'Press and hold a bar for full detail.'}
              </div>
              <div className="space-y-2">
                {game.team.leaders.map(rawLeader => {
                  const l = localizeLeader(rawLeader, language);
                  return (
                    <LeaderBar key={l.id} leader={l} rawLeader={rawLeader} game={game} language={language} t={t}
                      onOperate={() => handleOperate(l.id)}
                      onHold={() => setOpenLeaderId(l.id)} />
                  );
                })}
              </div>
            </Panel>

            {/* Company Philosophy — was "Founder Philosophy", renamed because it isn't
                necessarily any one founder's own position. It starts as a blend of whichever
                founders are on the team (see the run-start blend in initialState) and shifts
                from there with the decisions made during the run — the company can end up
                somewhere none of its individual founders started. */}
            <Panel title={t('Company Philosophy')}>
              <div className="grid md:grid-cols-2 gap-x-4 gap-y-2.5">
                {PHILOSOPHY_AXES.map(axis => (
                  <PhilosophyBar key={axis} axis={axis} value={(game.philosophy || {})[axis]} language={language} />
                ))}
              </div>
              <div style={{ color: C.muted }} className="text-[10px] mt-2.5">
                {language === 'es'
                  ? 'Comienza como una mezcla de la filosofía de tus fundadores y cambia con las decisiones que tomas — una posición en movimiento, no un rasgo fijo.'
                  : 'Starts as a blend of your founders’ own philosophies and shifts with the decisions you make — a running position, not a fixed trait.'}
              </div>
            </Panel>

            </>)}

            {/* ======================= ACTIONS TAB ======================= */}
            {gameTab === 'actions' && (<>

            {/* Groundwork — always available, cheap, and the answer to "what do I do in month 2?" */}
            <GroundworkPanel game={game} language={language} t={t} onAction={handleEarlyAction} />

            {/* Acquiring a competitor is a move against another company — it belongs with the
                other actions you take on rivals, not in the supply chain ladder. */}
            {activeIndustry.productCatalog && (
              <AcquireCompetitorPanel game={game} language={language} t={t}
                onAcquireRival={handleAcquireRival} />
            )}

            {/* Funding — instrument-based, for industries that declare them. Terms are shown up
                front: the player should be choosing a commitment, not discovering one later. */}
            {(activeIndustry.fundingInstruments || []).length > 0 && (() => {
              const stageId = currentStage.id;
              const avail = instrumentsForStage(activeIndustry, stageId);
              const fx = activeTermEffects(game);
              const L = language === 'es' ? 'es' : 'en';
              return (
                <Panel title={t('Funding')}>
                  {(game.activeTerms || []).length > 0 && (
                    <div style={{ background: C.panel2, border: `1px solid ${C.brass}` }} className="rounded p-2.5 mb-3">
                      <div style={{ color: C.brass, fontFamily: F_MONO }} className="text-[10px] uppercase tracking-widest mb-1">{t('Active Terms')}</div>
                      {(game.activeTerms || []).map((tm, i) => (
                        <div key={i} style={{ color: C.text }} className="text-[11px] mb-0.5">
                          · {tm.label[L]} <span style={{ color: C.muted }}>— {tm.detail[L]}</span>
                        </div>
                      ))}
                    </div>
                  )}
                  {avail.length === 0 ? (
                    <div style={{ color: C.muted }} className="text-xs">{t('No funding available at this stage.')}</div>
                  ) : (
                    <div className="space-y-2">
                      {avail.map(inst => {
                        const closed = (game.closedInstruments || []).includes(inst.id);
                        const disabled = closed || game.ap < (inst.cost.ap || 1) || (inst.cost.presence || 0) > game.presence;
                        return (
                          <div key={inst.id} style={{ background: C.panel2, border: `1px solid ${closed ? C.hair : C.brass}`, opacity: closed ? 0.55 : 1 }} className="rounded p-3">
                            <div className="flex items-baseline justify-between gap-2 mb-1">
                              <div style={{ color: C.paper }} className="text-sm font-semibold">{inst.name[L]}</div>
                              <div style={{ color: C.brass, fontFamily: F_MONO }} className="text-[10px] whitespace-nowrap">
                                {fmtMoney(inst.capital[0])}–{fmtMoney(inst.capital[1])} · {inst.dilution}% {t('equity')}
                              </div>
                            </div>
                            <div style={{ color: C.muted }} className="text-[11px] mb-1.5">{inst.blurb[L]}</div>
                            {!closed && (() => {
                              // Forecast the deal actually on the table — the investor fronting
                              // THIS instrument, since their terms shape the odds.
                              const fInv = investorForInstrument(game, inst.id, stageId);
                              const p = previewChance('instrument', game, { instrument: inst, investor: fInv });
                              return p ? (
                                <div className="mb-2">
                                  <span style={{ color: C.muted, fontFamily: F_MONO }} className="text-[10px]">
                                    {language === 'es' ? 'Probabilidad de cierre' : 'Close chance'}
                                  </span>
                                  <ForecastChip preview={p} language={language} />
                                </div>
                              ) : null;
                            })()}
                            {inst.terms ? (
                              <div style={{ color: C.rust }} className="text-[10px] mb-2">⚠ {inst.terms.detail[L]}</div>
                            ) : (
                              <div style={{ color: C.good }} className="text-[10px] mb-2">✓ {t('No lasting terms.')}</div>
                            )}
                            <button onClick={() => handleFundingInstrument(inst.id)} disabled={disabled}
                              style={{ background: disabled ? C.hair : C.brass, color: disabled ? C.muted : C.ink, opacity: disabled ? 0.6 : 1 }}
                              className="w-full rounded py-1.5 text-[11px] font-semibold">
                              {closed ? t('Already Closed') : `${t('Pursue')} · ${inst.cost.ap || 1} ${t('AP')} · ${inst.cost.presence} ${t('Presence')}`}
                            </button>
                          </div>
                        );
                      })}
                    </div>
                  )}
                </Panel>
              );
            })()}

            {/* Actions — internal (your own company) and external (against rivals), side by side */}
            <div className="grid md:grid-cols-2 gap-4">
              <Panel title={t('Internal Actions')} holdHandlers={actionsHoldHandlers} language={language}>
                <div className="grid grid-cols-2 gap-2">
                  <ActionButton label={t('Fundraise')} cost={fundraiseCostText} onClick={handleFundraise} disabled={fundraiseDisabled}
                    forecast={previewChance('fundraise', game, { industry: activeIndustry })} language={language} />
                  <ActionButton label={t('Hire Staff')} cost={recruitCostText} onClick={handleRecruit} disabled={recruitDisabled} />
                  <ActionButton label={t('Layoff')} cost={layoffCostText} onClick={handleLayoff} disabled={layoffDisabled} />
                  <ActionButton label={t('Rest & Culture')} cost={`1 ${t('AP')} · $5k`} onClick={handleRestCulture} disabled={restDisabled} />
                  <ActionButton label={t('Pivot')} cost={`2 ${t('AP')} · $20k`} onClick={handlePivot} disabled={pivotDisabled} />
                </div>
              </Panel>

              <Panel title={t('External Actions')}>
                {competitors.length === 0 ? (
                  <div style={{ color: C.muted }} className="text-xs">{t('No competitors yet. Rivals start appearing once you reach Seed.')}</div>
                ) : (
                  <>
                    <div style={{ color: C.muted, fontFamily: F_MONO }} className="text-[10px] uppercase tracking-wide mb-1.5">{t('Target')}</div>
                    <div className="flex flex-wrap gap-1.5 mb-3">
                      {competitors.map(c => {
                        const active = c.id === activeTargetId;
                        return (
                          <button key={c.id} onClick={() => setTargetCompetitorId(c.id)}
                            style={{ background: active ? C.brassDim : C.panel2, border: `1px solid ${active ? C.brass : C.hair}`, color: active ? C.paper : C.muted }}
                            className="rounded px-2 py-1 text-[11px] font-semibold">
                            {c.name}
                            <span style={{ fontFamily: F_MONO, opacity: 0.75 }} className="ml-1.5 text-[9px]">{t('STR')} {c.strength}</span>
                          </button>
                        );
                      })}
                    </div>
                    <div className="grid grid-cols-2 gap-2">
                      {INDUSTRY_EXTERNAL.map(a => {
                        const capOk = (a.cost.capital || 0) <= game.capital;
                        const target = competitors.find(c => c.id === activeTargetId);
                        const xFxPreview = founderFx(game);
                        const presCost = Math.max(0, (a.cost.presence || 0) - xFxPreview.externalPresenceDiscount);
                        const presOk = presCost <= game.presence;
                        const apOk = game.ap >= (a.cost.ap || 1);
                        const bits = [`${a.cost.ap || 1} ${t('AP')}`];
                        if (a.cost.capital) bits.push(fmtMoney(a.cost.capital));
                        if (presCost) bits.push(`${presCost} ${t('Presence')}`);
                        bits.push(statShort(a.stat, language));
                        // Same bar/statTotal the handler resolves against, computed against
                        // whichever rival is currently targeted — the forecast is FOR that fight.
                        let forecast = null;
                        if (target) {
                          const extInd = getIndustry(game.industryId);
                          const extScaling = extInd.scaling || {};
                          const stageId = stageOf(game.month, extInd.stages).id;
                          const bar = 10 + ((extScaling.eventThresholdBonus || EVENT_THRESHOLD_BONUS_BY_STAGE)[stageId] || 0)
                            + Math.floor(target.strength / 12) + rivalDefenceBonus(target);
                          const firstStrike = !((target.encounters || {}).attackedByPlayer) ? xFxPreview.firstStrikeBonus : 0;
                          const statTotal = (game.stats[a.stat] || 0) + xFxPreview.externalRollBonus + firstStrike;
                          forecast = previewChance('externalAction', game, { statTotal, bar });
                        }
                        return (
                          <ActionButton key={a.id}
                            label={a.label[language === 'es' ? 'es' : 'en']}
                            cost={bits.join(' · ')}
                            onClick={() => handleExternalAction(a.id, activeTargetId)}
                            disabled={!capOk || !presOk || !apOk || !activeTargetId}
                            forecast={forecast} language={language} />
                        );
                      })}
                    </div>
                  </>
                )}
              </Panel>
            </div>

            {/* Competitors */}
            {competitors.length > 0 && (
              <Panel title={`${t('Competitors')} (${competitors.length})`}>
                <div className="grid md:grid-cols-2 gap-2">
                  {competitors.map(c => (
                    <div key={c.id} style={{ background: C.panel2, border: `1px solid ${c.id === activeTargetId ? C.brass : C.hair}` }} className="rounded p-3">
                      <div className="flex items-baseline justify-between gap-2">
                        <div style={{ color: C.paper }} className="text-sm font-semibold">{c.name}</div>
                        <div style={{ color: C.rust, fontFamily: F_MONO }} className="text-[10px] whitespace-nowrap">{t('STR')} {c.strength}</div>
                      </div>
                      <div style={{ color: C.muted }} className="text-[11px] mt-1">
                        {c.leaders.map(l => `${l.name} · ${rivalRoleText(l.role, language)}`).join('  |  ')}
                      </div>
                      <div style={{ color: C.brass, fontFamily: F_MONO }} className="text-[9px] mt-1.5">
                        {t('Influenced by:')} {[...rivalInfluenceStats(c).map(k => statLabel(k, language)), t('Morale')].join(', ')}
                      </div>
                      <div style={{ color: C.muted, fontFamily: F_MONO }} className="text-[9px] mt-1 uppercase tracking-wide">
                        {t('Since month')} {c.appearedMonth}
                      </div>
                    </div>
                  ))}
                </div>
              </Panel>
            )}

            </>)}

            {/* ======================= INVEST TAB ======================= */}
            {gameTab === 'invest' && (<>

            {/* Products — Manufacturing only. Guarded on productCatalog rather than industryId,
                so this panel simply doesn't exist for an industry that hasn't authored any. */}
            {activeIndustry.productCatalog && (
              <ProductsPanel game={game} industry={activeIndustry} language={language} t={t}
                onAdvance={handleAdvanceProduct} onLaunch={handleLaunchProduct}
                onIterate={handleIterateProduct} onRetire={handleRetireProduct} onPivot={handlePivotProduct}
                onSetProductionStance={handleSetProductionStance} onSetSalesStance={handleSetSalesStance} />
            )}

            {/* Byproducts — sits with Products, since it is a consequence of production. */}
            {activeIndustry.productCatalog && (
              <ByproductsPanel game={game} industry={activeIndustry} language={language} t={t}
                onSetPolicy={handleSetByproductPolicy} />
            )}

            {/* Equipment — same guard: only industries with a real machine catalog see this. */}
            {game.equipment && Object.keys(game.equipment).length > 0 && (
              <EquipmentPanel game={game} language={language} t={t}
                onSetStance={handleSetMaintenanceStance} onReplace={handleReplaceEquipment} />
            )}

            {/* Supply chain — the vertical integration ladder (7a backward + 7b forward) plus
                player-side acquisitions. Manufacturing only, same productCatalog guard. */}
            {activeIndustry.productCatalog && (
              <SupplyChainPanel game={game} industry={activeIndustry} language={language} t={t}
                onBuildTier={handleBuildTier} onSellTier={handleSellTier}
                onToggleTierOpen={handleToggleTierOpen} />
            )}

            {activeIndustry.productCatalog && (
              <SalesContractsPanel game={game} language={language} t={t}
                onAccept={handleAcceptSalesContract} onDecline={handleDeclineSalesContract}
                onSolicit={handleSolicitContract} onScout={handleScoutBuyers}
                onAttendShow={handleAttendTradeShow} onRequestIntro={handleRequestIntroduction} />
            )}

            {/* Working capital & finance — Manufacturing only, same productCatalog guard. Shown
                once there's anything to actually manage (revenue, receivables, or debt). */}
            {activeIndustry.productCatalog
              && ((game.revenuePerMonth || 0) > 0 || totalReceivables(game) > 0 || (game.debts || []).length > 0) && (
              <FinancePanel game={game} industry={activeIndustry} language={language} t={t}
                onTakeDebt={handleTakeDebt} onFactor={handleFactorReceivables}
                onTradeCredit={handleTakeTradeCredit}
                burnEstimate={Math.max(1, 2 + Math.ceil(game.laborPool / 3) + game.activeProjects.length)} />
            )}

            {/* Suppliers — visible once the Sourcing gate opens (mfgSupplierQual), not only
                after a first contract, mirroring how Products shows "start a new one" options
                before anything exists. */}
            {activeIndustry.productCatalog && supplierSlotLimit(game) > 0 && (
              <SuppliersPanel game={game} language={language} t={t}
                onContract={handleContractSupplier} onCancel={handleCancelSupplierContract}
                onAcquire={handleAcquireSupplier} onSetInventoryStrategy={handleSetInventoryStrategy} />
            )}

            {/* Active Projects */}
            {game.activeProjects.length > 0 && (
              <Panel title={t('In Progress')}>
                <div className="space-y-2">
                  {game.activeProjects.map(p => {
                    const proj = localizeProject(INDUSTRY_PROJECTS.find(x => x.id === p.id), language);
                    return (
                      <div key={p.id} style={{ background: C.panel2, border: `1px solid ${C.hair}` }} className="rounded p-3">
                        <div style={{ color: C.paper }} className="text-sm font-semibold">{proj.name}</div>
                        <div style={{ color: C.muted }} className="text-xs">{p.monthsLeft} {t('month(s) remaining')}</div>
                      </div>
                    );
                  })}
                </div>
              </Panel>
            )}

            {/* Available Projects, split into three sections that answer three different
                questions: what can I do now / what am I building toward / what will we be able
                to do. Same grouping machinery, run once per category. */}
            {PROJECT_CATEGORY_ORDER.map(category => (() => {
              const categoryProjects = availableProjects.filter(p => projectCategory(p) === category.id);
              if (!categoryProjects.length) return null;
              // Group by the stage tier that unlocked each project, then by function within
              // that tier — the two axes asked for, without a third level of nested clicking.
              const grouped = {};
              categoryProjects.forEach(p => {
                const tier = p.minStage || 'preSeed';
                grouped[tier] = grouped[tier] || {};
                (grouped[tier][p.tag] = grouped[tier][p.tag] || []).push(p);
              });
              const populatedTiers = activeIndustry.stages.map(s => s.id).filter(id => grouped[id]);
              const tiers = expandedStageTiers || { [currentStage.id]: true };
              const renderRow = (proj) => {
                const scaled = scaledProjectCost(proj, currentStage.id, game.team.style, activeIndustry.scaling);
                const disabled = scaled.capital > game.capital || scaled.presence > game.presence
                  || scaled.labor > freeLabor || game.ap < 1;
                const dProj = localizeProject(proj, language);
                const isObjective = objectiveProjIds.has(proj.id);
                return (
                  <div key={proj.id}
                    style={{ background: C.panel2, border: `${isObjective ? 2 : 1}px solid ${isObjective ? C.brass : C.hair}` }}
                    className="rounded p-2.5 flex items-center justify-between gap-2">
                    <div className="min-w-0">
                      <div style={{ color: C.paper }} className="text-xs font-semibold truncate">
                        {isObjective && <span style={{ color: C.brass }} title={t('Counts toward an objective')}>★ </span>}
                        {dProj.name}
                      </div>
                      <div style={{ color: C.muted }} className="text-[11px] leading-snug">{dProj.desc}</div>
                      <div style={{ color: C.muted, fontFamily: F_MONO }} className="text-[10px] mt-0.5">
                        {t('Cost:')} {scaled.capital ? fmtMoney(scaled.capital) + ' ' : ''}{scaled.presence ? scaled.presence + ' ' + t('Presence') + ' ' : ''}{scaled.labor ? scaled.labor + ' ' + t('Labor') + ' ' : ''}· {scaled.duration}{t('mo')}
                      </div>
                    </div>
                    <button onClick={() => handleInvest(proj.id)} disabled={disabled}
                      style={{ background: disabled ? C.hair : C.brass, color: disabled ? C.muted : C.ink, opacity: disabled ? 0.6 : 1 }}
                      className="rounded px-2.5 py-1 text-[11px] font-semibold whitespace-nowrap flex-shrink-0">
                      {t('Invest')}
                    </button>
                  </div>
                );
              };
              return (
                <Panel key={category.id} title={`${category.name[language === 'es' ? 'es' : 'en']} (${categoryProjects.length})`}>
                  <div style={{ color: C.muted }} className="text-[10px] mb-2">
                    {category.blurb[language === 'es' ? 'es' : 'en']}
                  </div>
                  {categoryProjects.length === 0 ? (
                    <div style={{ color: C.muted }} className="text-xs">{t('Nothing available right now.')}</div>
                  ) : (
                    <div className="grid md:grid-cols-2 gap-3">
                      {populatedTiers.map(tierId => {
                        const stage = STAGES.find(s => s.id === tierId);
                        const tagGroups = grouped[tierId];
                        const tierCount = Object.values(tagGroups).reduce((n, arr) => n + arr.length, 0);
                        const open = !!tiers[tierId];
                        return (
                          <div key={tierId} style={{ background: C.panel3, border: `1px solid ${C.hair}` }} className="rounded-lg overflow-hidden self-start">
                            <button onClick={() => setExpandedStageTiers({ ...tiers, [tierId]: !open })}
                              className="w-full flex items-center justify-between px-3 py-2.5">
                              <span style={{ color: C.brass, fontFamily: F_MONO }} className="text-[11px] uppercase tracking-wide">
                                {t(stage.name)} <span style={{ color: C.muted }}>({tierCount})</span>
                              </span>
                              <span style={{ color: C.muted, fontFamily: F_MONO }} className="text-[10px]">{open ? '▲' : '▼'}</span>
                            </button>
                            {open && (
                              <div className="px-3 pb-3 space-y-3">
                                {(activeIndustry.tagOrder || TAG_ORDER).filter(tag => tagGroups[tag]).map(tag => (
                                  <div key={tag}>
                                    <div style={{ color: C.muted, fontFamily: F_MONO }} className="text-[10px] uppercase tracking-widest mb-1.5">
                                      {language === 'es' ? PROJECT_TAGS_ES[tag] : tag}
                                    </div>
                                    <div className="space-y-1.5">{tagGroups[tag].map(renderRow)}</div>
                                  </div>
                                ))}
                              </div>
                            )}
                          </div>
                        );
                      })}
                    </div>
                  )}
                </Panel>
              );
            })())}

            {lockedProjects.length > 0 && (
              <div style={{ background: C.panel, border: `1px solid ${C.hair}` }} className="rounded-lg overflow-hidden">
                <button onClick={() => setShowLocked(v => !v)} className="w-full flex items-center justify-between px-4 py-3">
                  <span style={{ color: C.brass, fontFamily: F_MONO }} className="text-xs uppercase tracking-widest">{t('Locked')} ({lockedProjects.length})</span>
                  <span style={{ color: C.muted, fontFamily: F_MONO }} className="text-xs">{showLocked ? `▲ ${t('hide')}` : `▼ ${t('show')}`}</span>
                </button>
                {showLocked && (
                  <div className="px-4 pb-4 space-y-1">
                    {lockedProjects.map(proj => {
                      const dProj = localizeProject(proj, language);
                      const isObjective = objectiveProjIds.has(proj.id);
                      return (
                        <div key={proj.id}
                          style={{
                            color: isObjective ? C.text : C.muted,
                            background: isObjective ? C.panel2 : 'transparent',
                            border: isObjective ? `2px solid ${C.brass}` : 'none',
                          }}
                          className={isObjective ? 'text-xs rounded px-2 py-1.5' : 'text-xs'}>
                          🔒 {isObjective && <span style={{ color: C.brass }} title={t('Counts toward an objective')}>★ </span>}
                          {dProj.name} <span style={{ color: C.brass, fontFamily: F_MONO }} className="text-[10px] ml-1">{dProj.tag}</span> — {lockReason(proj)}
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            )}

            </>)}

            {/* ======================= CHARACTERS TAB ======================= */}
            {/* Leadership deliberately does not appear here — it lives in My Company now, and
                showing it in both places was the exact duplication this restructure removed. */}
            {gameTab === 'characters' && (<>
              {/* Managers — Manufacturing only (guarded on productCatalog, same convention as
                  every other item-2/3/4 panel). People belong with people. */}
              {activeIndustry.productCatalog && (
                <ManagersPanel game={game} founderDoc={founderDoc} language={language} t={t}
                  onHire={handleHireManager} onAssign={handleAssignManager} onDismiss={handleDismissManager} />
              )}
              <Panel title={t('Investors')}>
                {(() => {
                  // Only investors this run has actually dealt with or could deal with — the
                  // full 20-strong cast lives in the Index; this is who is in play right now.
                  const rosterIds = game.investorRoster || [];
                  const backed = Object.keys(game.investorBackers || {});
                  const shown = rosterIds.map(id => INVESTOR_BY_ID[id]).filter(Boolean);
                  if (!shown.length) {
                    return <div style={{ color: C.muted }} className="text-xs">
                      {language === 'es' ? 'Aún no hay inversionistas en juego.' : 'No investors in play yet.'}
                    </div>;
                  }
                  return (
                    <>
                      <div style={{ color: C.muted }} className="text-[10px] mb-2">
                        {language === 'es' ? 'Mantén pulsado para ver el detalle. Los marcados te respaldaron.' : 'Press and hold for detail. Highlighted ones backed you.'}
                      </div>
                      <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-6 gap-2">
                        {shown.map(inv => (
                          <CharacterCard key={inv.id} name={inv.name}
                            subtitle={inv.archetype[language === 'es' ? 'es' : 'en']}
                            portraitSeed={inv.id}
                            accent={backed.includes(inv.id) ? C.brass : C.hair}
                            onHold={() => setOpenInvestorId(inv.id)} />
                        ))}
                      </div>
                    </>
                  );
                })()}
              </Panel>
            </>)}

            {/* ======================= COMPANIES TAB ======================= */}
            {gameTab === 'inventory' && activeIndustry.productCatalog && (
              <InventoryTab game={game} industry={activeIndustry} language={language} t={t} />
            )}

            {gameTab === 'market' && activeIndustry.productCatalog && (
              <ProductMarketTab game={game} language={language} t={t}
                onSpotBuy={handleSpotBuy} onSpotSell={handleSpotSell} />
            )}

            {gameTab === 'companies' && (
              <CompaniesTab game={game} language={language} t={t}
                onOpenCompany={(id) => setOpenCompanySeed(id)} />
            )}
          </div>
        </div>
      </div>

      {/* Ticket Rail — a pull-out drawer instead of a scroll-down column, so it's reachable from
          anywhere on the page without hunting for it. The tab stays fixed regardless of scroll. */}
      <button onClick={() => setShowTicketRail(v => !v)}
        style={{
          position: 'fixed', top: '50%', right: showTicketRail ? 'min(340px, 88vw)' : 0, transform: 'translateY(-50%)',
          zIndex: 45, background: C.brass, color: C.ink, border: 'none',
          borderRadius: '8px 0 0 8px', padding: '14px 6px', transition: 'right 0.25s ease',
        }}
        title={t('Ticket Rail')}>
        <div style={{ writingMode: 'vertical-rl' }} className="text-[10px] font-bold uppercase tracking-wide flex items-center gap-1.5">
          <span>{showTicketRail ? '▶' : '◀'}</span>
          <span>{t('Ticket Rail')}</span>
        </div>
      </button>
      {showTicketRail && (
        <div onClick={() => setShowTicketRail(false)} style={{ position: 'fixed', inset: 0, background: 'rgba(20,37,28,0.55)', zIndex: 40 }} />
      )}
      <div style={{
        position: 'fixed', top: 0, right: 0, height: '100vh', width: 'min(340px, 88vw)',
        background: C.ink, borderLeft: `1px solid ${C.hair}`, zIndex: 42,
        transform: showTicketRail ? 'translateX(0)' : 'translateX(100%)', transition: 'transform 0.25s ease',
        overflowY: 'auto', boxShadow: showTicketRail ? '-8px 0 24px rgba(0,0,0,0.4)' : 'none',
      }} className="p-4">
        <div className="flex items-center justify-between mb-3">
          <div style={{ color: C.brass, fontFamily: F_MONO }} className="text-xs uppercase tracking-widest">{t('Ticket Rail')}</div>
          <button onClick={() => setShowTicketRail(false)} style={{ color: C.muted, border: `1px solid ${C.hair}` }} className="rounded-full w-7 h-7 text-xs">✕</button>
        </div>
        <div className="space-y-2">
          {game.log.map(tk => <Ticket key={tk.id} t={tk} />)}
        </div>
      </div>

      {/* ---------------- Detail modals opened by press-and-hold ---------------- */}
      {openLeaderId && (() => {
        const l = (game.team.leaders || []).find(x => x.id === openLeaderId);
        if (!l) return null;
        const rec = (founderDoc.roster || {})[l.id];
        return (
          <FounderDetailModal
            leader={{ ...l, baseStatBonus: l.baseStatBonus || l.statBonus }}
            record={l.isCustom ? { xp: 0, allocated: {}, philosophy: game.philosophy, history: [], investorsBacked: game.investorBackers || {}, runsWith: (founderDoc.career || {}).runs || 0, wins: (founderDoc.career || {}).wins || 0 } : rec}
            language={language}
            unlockedIds={founderDoc.unlocked || []}
            onClose={() => setOpenLeaderId(null)}
            onAllocate={allocateRosterPoints}
            allowCompare={false}
            t={t}
          />
        );
      })()}

      {openInvestorId && (() => {
        const inv = INVESTOR_BY_ID[openInvestorId];
        if (!inv) return null;
        const L = language === 'es' ? 'es' : 'en';
        const standing = (game.investorStandings || {})[inv.id] || 0;
        const rBand = relationshipBand(standing);
        const align = investorAlignment(inv, game.philosophy, founderFx(game).alignmentBonus);
        const aBand = alignmentBand(align);
        return (
          <div style={{ position: 'fixed', inset: 0, background: 'rgba(8,14,10,0.85)', zIndex: 70,
            display: 'flex', alignItems: 'flex-start', justifyContent: 'center', padding: '4vh 12px', overflowY: 'auto' }}
            onClick={() => setOpenInvestorId(null)}>
            <div onClick={(e) => e.stopPropagation()}
              style={{ background: C.panel, border: `1px solid ${C.brassDim}`, maxWidth: 600, width: '100%', borderRadius: 10 }}
              className="relative p-4">
              <button onClick={() => setOpenInvestorId(null)}
                style={{ position: 'absolute', top: 10, right: 10, background: C.panel2, border: `1px solid ${C.hair}`, color: C.muted }}
                className="rounded w-8 h-8 text-sm leading-none z-10">✕</button>
              <div className="flex gap-3 items-start mb-3 pr-8">
                {/* Same procedural generator leaders use, seeded off the investor's own id so
                    Dwayne Borg looks like the same person everywhere he appears. */}
                <ProceduralPortrait seed={inv.id} size={64} />
                <div className="min-w-0">
                  <div style={{ color: C.paper, fontFamily: F_DISPLAY }} className="text-xl">{inv.name}</div>
                  <div style={{ color: C.muted, fontFamily: F_MONO }} className="text-[10px]">
                    {inv.firm} · {inv.archetype[L]}
                  </div>
                  <div style={{ fontFamily: F_MONO }} className="text-[10px] mt-0.5">
                    <span style={{ color: C.brass }}>{rBand.label[L]}</span>
                    <span style={{ color: C.muted }}> · {aBand.label[L]} {language === 'es' ? 'alineación' : 'fit'}</span>
                  </div>
                </div>
              </div>
              <div style={{ color: C.brass, fontStyle: 'italic' }} className="text-xs mb-2">{inv.tell[L]}</div>
              <p style={{ color: C.muted }} className="text-xs leading-relaxed mb-3">{inv.bio[L]}</p>
              <div style={{ color: C.brass, fontFamily: F_MONO }} className="text-[10px] uppercase tracking-widest mb-1.5">
                {language === 'es' ? 'Filosofía' : 'Philosophy'}
              </div>
              <PhilosophySpread philosophy={inv.philosophy} language={language} />
            </div>
          </div>
        );
      })()}

      {openCompanySeed && (() => {
        const all = [...(game.competitors || []).map(c => ({ ...c, industry: c.industry || game.industryId })),
          ...(game.knownRivals || [])];
        let co = all.find(c => (c.seedId || c.id) === openCompanySeed);
        // Suppliers are companies too — adapt one into the shape the modal expects rather than
        // building a second near-identical modal for them.
        if (!co) {
          const sp = resolveSupplier(game, openCompanySeed);
          if (sp) {
            const contract = (game.supplierContracts || {})[sp.id];
            co = {
              seedId: sp.id, name: sp.name, industry: game.industryId,
              strength: Math.round(sp.reliability * 100), marketPosition: sp.qualityGrade * 10,
              posture: 'balanced', archetype: 'costLeader',
              mission: sp.bio, leaders: [], pastLeaders: [], pivotalDecisions: [],
              encounters: { tradedWith: contract ? 1 : 0 },
              isSupplier: true, chainPosition: null,
            };
          }
        }
        if (!co) return null;
        return <CompanyDetailModal company={co} game={game} language={language} onClose={() => setOpenCompanySeed(null)} />;
      })()}

      {/* ---------------- Sticky bottom tab bar ---------------- */}
      {/* Fixed rather than sticky so it survives any scroll container, and padded for iOS home
          indicators. The main column carries matching bottom padding so nothing hides under it. */}
      <div style={{
        position: 'fixed', left: 0, right: 0, bottom: 0, zIndex: 40,
        background: C.panel, borderTop: `1px solid ${C.brassDim}`,
        paddingBottom: 'env(safe-area-inset-bottom, 0px)',
      }}>
        {/* Six tabs when the industry has a live economy, five otherwise — the Market tab has
            nothing to show for an industry with no product graph behind it. */}
        <div className={`max-w-6xl mx-auto grid ${activeIndustry.productCatalog ? 'grid-cols-7' : 'grid-cols-5'}`}>
          {[
            { id: 'mycompany', label: { en: 'My Company', es: 'Mi Empresa' }, glyph: '⌂' },
            { id: 'invest', label: { en: 'Invest', es: 'Invertir' }, glyph: '◆',
              // Pending sales-contract offers expire, so the tab flags them rather than relying
              // on the player to go looking. Direction's Q6: surface it here, not as an event.
              badge: activeIndustry.productCatalog && pendingOffers(game, game.month).length > 0 },
            { id: 'actions', label: { en: 'Actions', es: 'Acciones' }, glyph: '⚑' },
            ...(activeIndustry.productCatalog
              ? [{ id: 'inventory', label: { en: 'Inventory', es: 'Inventario' }, glyph: '▦' },
                 { id: 'market', label: { en: 'Market', es: 'Mercado' }, glyph: '⇅' }] : []),
            { id: 'characters', label: { en: 'Characters', es: 'Personajes' }, glyph: '☗' },
            { id: 'companies', label: { en: 'Companies', es: 'Empresas' }, glyph: '⬢' },
          ].map(tb => {
            const on = gameTab === tb.id;
            return (
              <button key={tb.id} onClick={() => setGameTab(tb.id)}
                style={{
                  background: on ? C.panel3 : 'transparent',
                  color: on ? C.brass : C.muted,
                  borderTop: `2px solid ${on ? C.brass : 'transparent'}`,
                  fontFamily: F_MONO,
                }}
                className="py-2.5 text-[10px] uppercase tracking-wide flex flex-col items-center gap-0.5 relative">
                <span style={{ fontSize: 14 }}>{tb.glyph}</span>
                {tb.label[language === 'es' ? 'es' : 'en']}
                {/* Something time-sensitive is waiting on this tab (currently: expiring contract offers). */}
                {tb.badge && (
                  <span style={{
                    position: 'absolute', top: 4, right: '50%', marginRight: -18,
                    color: C.ink, background: C.brass, borderRadius: '50%',
                    width: 13, height: 13, fontSize: 9, lineHeight: '13px', fontWeight: 700,
                  }}>!</span>
                )}
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
}

// ============================== SUBCOMPONENTS ==============================
function FontImport() {
  return (
    <style>{`
      @import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&family=IBM+Plex+Mono:wght@400;500;600&family=Inter:wght@400;500;600;700&display=swap');
      @keyframes founderFadeIn {
        from { opacity: 0; transform: translateY(6px); }
        to { opacity: 1; transform: translateY(0); }
      }
      button:not(:disabled) {
        transition: transform 0.08s ease-out;
      }
      button:not(:disabled):active {
        transform: scale(0.95);
      }
    `}</style>
  );
}

function Modal({ title, onClose, children }) {
  return (
    <div style={{ position: 'fixed', inset: 0, background: 'rgba(20,37,28,0.85)', zIndex: 50 }} className="flex items-center justify-center p-4">
      <div style={{ background: C.panel, border: `1px solid ${C.hair}`, maxHeight: '85vh' }} className="max-w-2xl w-full rounded-lg p-6 overflow-y-auto">
        <div className="flex items-center justify-between mb-4">
          <div style={{ fontFamily: F_DISPLAY, color: C.paper }} className="text-2xl">{title}</div>
          <button onClick={onClose} style={{ color: C.muted, border: `1px solid ${C.hair}` }} className="rounded-full w-7 h-7 text-xs">✕</button>
        </div>
        {children}
      </div>
    </div>
  );
}

// ---------------------------------------------------------------- save file panel
// Progress already autosaves after every action, but that was entirely invisible — a tester had
// no way to confirm it, and no way to hand a specific game state to anyone else. Export writes
// the whole run to a .json file; import restores it. That makes a save PORTABLE, which is what
// makes balance testing across several people actually workable: hit something odd, send the file.
function SaveFilePanel({ game, language, t, onImported }) {
  const L = language === 'es' ? 'es' : 'en';
  const [status, setStatus] = useState(null);
  const fileRef = useRef(null);

  const exportSave = () => {
    try {
      const payload = {
        format: 'entrepreneur-sim-save',
        version: SCHEMA_VERSION,
        savedAt: new Date().toISOString(),
        industry: (game && game.industryId) || 'manufacturing',
        game,
      };
      const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      const co = (game && game.companyName ? String(game.companyName).replace(/[^a-z0-9]+/gi, '-') : 'run').toLowerCase();
      a.href = url;
      a.download = `founder-${co}-m${(game && game.month) || 0}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
      setStatus(L === 'es' ? 'Archivo de guardado descargado.' : 'Save file downloaded.');
    } catch (e) {
      setStatus(L === 'es' ? 'No se pudo exportar.' : 'Export failed.');
    }
  };

  const importSave = (ev) => {
    const file = ev.target.files && ev.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      try {
        const parsed = JSON.parse(String(reader.result));
        const raw = parsed && parsed.game ? parsed.game : parsed;
        if (!raw || typeof raw.month !== 'number') {
          setStatus(L === 'es' ? 'Ese archivo no es un guardado válido.' : 'That file is not a valid save.');
          return;
        }
        onImported(hydrateResumedGame(raw), (parsed && parsed.industry) || raw.industryId || 'manufacturing');
        setStatus(L === 'es' ? 'Partida cargada.' : 'Save loaded.');
      } catch (e) {
        setStatus(L === 'es' ? 'No se pudo leer el archivo.' : 'Could not read that file.');
      }
    };
    reader.readAsText(file);
    ev.target.value = '';
  };

  return (
    <div style={{ background: C.panel2, border: `1px solid ${C.hair}` }} className="w-full rounded p-3 mt-3">
      <div style={{ color: C.paper }} className="text-sm font-semibold">💾 {t('Save File')}</div>
      <div style={{ color: C.muted }} className="text-xs mt-1 mb-2">
        {game
          ? (L === 'es'
            ? `Tu progreso se guarda solo después de cada acción — mes ${game.month}. Exporta para respaldar o compartir esta partida.`
            : `Progress autosaves after every action — currently month ${game.month}. Export to back this run up or share it.`)
          : (L === 'es'
            ? 'Sin partida activa. Importa un archivo para retomar una.'
            : 'No run in progress. Import a file to pick one up.')}
      </div>
      <div className="flex gap-2">
        <button onClick={exportSave} disabled={!game}
          style={{ background: C.panel3, border: `1px solid ${C.brassDim}`, color: game ? C.brass : C.hair, opacity: game ? 1 : 0.5 }}
          className="rounded px-2 py-1.5 text-[11px] flex-1">
          {L === 'es' ? 'Exportar partida' : 'Export save'}
        </button>
        <button onClick={() => fileRef.current && fileRef.current.click()}
          style={{ background: C.panel3, border: `1px solid ${C.brassDim}`, color: C.brass }}
          className="rounded px-2 py-1.5 text-[11px] flex-1">
          {L === 'es' ? 'Importar partida' : 'Import save'}
        </button>
      </div>
      <input ref={fileRef} type="file" accept="application/json,.json" onChange={importSave} style={{ display: 'none' }} />
      {status && (
        <div style={{ color: C.brassDim }} className="text-[10px] mt-1.5">{status}</div>
      )}
    </div>
  );
}

